function retireAssetProcurementData(data) {
  const retiredTypes = new Set(['资产采购', '设备资产采购']);
  const purchase = data.purchase || {};
  const retiredRequisitionCodes = new Set(
    (purchase.requisitions || [])
      .filter((row) => retiredTypes.has(String(row.purchaseType || '')))
      .map((row) => row.code),
  );
  const retiredOrderCodes = new Set(
    (purchase.orders || [])
      .filter((row) => retiredTypes.has(String(row.purchaseType || '')))
      .map((row) => row.code),
  );
  let changed = retiredRequisitionCodes.size > 0 || retiredOrderCodes.size > 0;

  if (Array.isArray(purchase.requisitions)) {
    purchase.requisitions = purchase.requisitions.filter((row) => !retiredRequisitionCodes.has(row.code));
  }
  if (Array.isArray(purchase.orders)) {
    purchase.orders = purchase.orders.filter((row) => !retiredOrderCodes.has(row.code));
  }
  for (const code of retiredRequisitionCodes) {
    if (purchase.requisitionFlowRecords?.[code]) {
      delete purchase.requisitionFlowRecords[code];
      changed = true;
    }
  }
  for (const code of retiredOrderCodes) {
    if (purchase.orderFlowRecords?.[code]) {
      delete purchase.orderFlowRecords[code];
      changed = true;
    }
  }
  if (Array.isArray(purchase.afterSales)) {
    const nextRows = purchase.afterSales.filter((row) => !retiredOrderCodes.has(row.sourceOrder));
    changed ||= nextRows.length !== purchase.afterSales.length;
    purchase.afterSales = nextRows;
  }
  if (Array.isArray(purchase.commercialFollowUps)) {
    const nextRows = purchase.commercialFollowUps.filter((row) => !retiredOrderCodes.has(row.sourceOrder));
    changed ||= nextRows.length !== purchase.commercialFollowUps.length;
    purchase.commercialFollowUps = nextRows;
  }

  const finance = data.finance || {};
  for (const key of ['purchaseInvoices', 'payables']) {
    if (!Array.isArray(finance[key])) continue;
    const nextRows = finance[key].filter((row) => (
      !retiredOrderCodes.has(row.sourceOrder)
      && !retiredOrderCodes.has(row.sourceDoc)
    ));
    changed ||= nextRows.length !== finance[key].length;
    finance[key] = nextRows;
  }

  if (Array.isArray(data.masterData?.equipment)) {
    data.masterData.equipment.forEach((row) => {
      if (!Object.hasOwn(row, 'sourcePurchase')) return;
      delete row.sourcePurchase;
      changed = true;
    });
  }
  if (Array.isArray(data.system?.menus)) {
    const nextRows = data.system.menus.filter((row) => (
      row.code !== 'MENU-PURCHASE-ASSETS'
      && row.path !== '/purchase/asset-purchases'
    ));
    changed ||= nextRows.length !== data.system.menus.length;
    data.system.menus = nextRows;
  }
  return changed;
}

function hydrateIncomingQualityDueDates(data) {
  const quality = ensureQuality(data);
  const receipts = new Map(
    ensureWarehouse(data).purchaseReceipts.map((receipt) => [receipt.code, receipt]),
  );
  let changed = false;
  quality.incomingDocuments.forEach((task) => {
    const receipt = receipts.get(task.sourceDoc);
    const earliestDueDate = String(task.date || receipt?.date || task.createdAt || '').slice(0, 10);
    if (!earliestDueDate) return;
    if (!task.dueDate || String(task.dueDate).slice(0, 10) < earliestDueDate) {
      task.dueDate = earliestDueDate;
      changed = true;
    }
  });
  return changed;
}

function hydrateCanonicalWarehouseNames(data) {
  const masterNames = new Map(
    ensureMasterRows(data, 'warehouses')
      .map((row) => [String(row.code || '').trim(), String(row.name || '').trim()])
      .filter(([code, name]) => code && name),
  );
  const fieldPairs = [
    ['warehouseCode', 'warehouse'],
    ['warehouseCode', 'warehouseName'],
    ['fromWarehouseCode', 'fromWarehouse'],
    ['toWarehouseCode', 'toWarehouse'],
    ['targetWarehouseCode', 'targetWarehouse'],
    ['destinationWarehouseCode', 'destinationWarehouse'],
    ['sourceWarehouseCode', 'sourceWarehouse'],
    ['sourceWarehouseCode', 'sourceWarehouseName'],
  ];
  let changed = false;

  const visit = (value) => {
    if (!value || typeof value !== 'object') return;
    if (Array.isArray(value)) {
      value.forEach(visit);
      return;
    }
    fieldPairs.forEach(([codeKey, nameKey]) => {
      if (!(nameKey in value)) return;
      const canonicalName = masterNames.get(String(value[codeKey] || '').trim());
      if (canonicalName && value[nameKey] !== canonicalName) {
        value[nameKey] = canonicalName;
        changed = true;
      }
    });
    Object.values(value).forEach(visit);
  };

  visit(data);
  return changed;
}

function hydratePurchaseStagingWarehouse(data) {
  const stagingCode = 'WH-QC-HOLD';
  const stagingName = '采购暂存区';
  let changed = false;

  const visit = (value) => {
    if (!value || typeof value !== 'object') return;
    if (!Array.isArray(value)) {
      const isStagingRecord = value.warehouseCode === stagingCode
        || value.warehouse === '待检暂存区'
        || value.warehouse === '质检暂存区'
        || value.warehouse === stagingName;
      if (isStagingRecord) {
        if ('warehouse' in value && value.warehouse !== stagingName) {
          value.warehouse = stagingName;
          changed = true;
        }
      }
    }
    Object.entries(value).forEach(([key, child]) => {
      if (
        typeof child === 'string'
        && (child.includes('待检暂存区') || child.includes('质检暂存区'))
      ) {
        value[key] = child
          .replaceAll('待检暂存区', stagingName)
          .replaceAll('质检暂存区', stagingName);
        changed = true;
      } else {
        visit(child);
      }
    });
  };

  visit(data);
  const staging = ensureMasterRows(data, 'warehouses').find((row) => row.code === stagingCode);
  if (staging) {
    const next = {
      name: stagingName,
      locationCount: 6,
      binPrefix: 'QC',
      primary: '6 个可用库位',
      secondary: '采购到货按现场库位暂存，不参与可承诺库存',
      note: '采购到货时由仓库选择实际暂存库位；需检物料质检放行、免检物料确认到货后，再转正式入库。',
    };
    Object.entries(next).forEach(([key, value]) => {
      if (staging[key] === value) return;
      staging[key] = value;
      changed = true;
    });
  }
  return changed;
}

function deduplicateInventoryFactRows(data) {
  const warehouse = ensureWarehouse(data);
  const seenKeys = new Set();
  const uniqueRows = [];

  for (const row of warehouse.inventory) {
    const key = String(row?.key || '').trim();
    if (key && seenKeys.has(key)) continue;
    if (key) seenKeys.add(key);
    uniqueRows.push(row);
  }

  if (uniqueRows.length === warehouse.inventory.length) return false;
  warehouse.inventory = uniqueRows;
  return true;
}

function hydratePurchaseReceiptFormalBatchPolicy(data) {
  data.migrations ||= {};
  if (data.migrations.purchaseReceiptFormalBatchV1) return false;
  const warehouse = ensureWarehouse(data);
  const quality = ensureQuality(data);
  let changed = false;
  warehouse.purchaseReceipts
    .filter((receipt) => (
      !['已入库', '已完成'].includes(String(receipt.status || ''))
      && !(receipt.postedQuantities?.lines || []).length
    ))
    .forEach((receipt) => {
      (receipt.products || []).forEach((product) => {
        if (!String(product.batch || '').trim()) return;
        product.stagingBatch = product.stagingBatch ?? product.batch;
        product.batch = '';
        changed = true;
      });
      quality.incomingDocuments
        .filter((task) => task.sourceDoc === receipt.code)
        .forEach((task) => {
          (task.products || []).forEach((product) => {
            if (!String(product.batch || '').trim()) return;
            product.stagingBatch = product.stagingBatch ?? product.batch;
            product.batch = '';
            changed = true;
          });
        });
    });
  data.migrations.purchaseReceiptFormalBatchV1 = true;
  return true;
}

function hydratePurchaseAfterSaleUnifiedInbound(data) {
  data.migrations ||= {};
  if (data.migrations.purchaseAfterSaleUnifiedInboundV1) return false;
  const purchase = ensurePurchase(data);
  purchase.afterSales
    .filter((record) => (
      !['待受理', '已作废'].includes(String(record.status || ''))
      && ['补发', '要求补发', '退货换货', '供应商返工'].includes(String(record.action || ''))
    ))
    .forEach((record) => {
      ensurePurchaseAfterSaleInboundTask(data, record, {
        actor: record.owner || '系统迁移',
        notify: false,
      });
    });
  data.migrations.purchaseAfterSaleUnifiedInboundV1 = true;
  return true;
}

function hydratePurchaseAfterSaleRemedyPlannedQuantities(data) {
  const purchase = ensurePurchase(data);
  let changed = false;
  ensureWarehouse(data).purchaseReceipts
    .filter((receipt) => receipt.sourceType === 'purchase_after_sale' && receipt.sourceAfterSale)
    .forEach((receipt) => {
      const afterSale = purchase.afterSales.find((record) => record.code === receipt.sourceAfterSale);
      if (!afterSale) return;
      const resetLegacyGeneratedActuals = (
        ['草稿', '待收货'].includes(String(receipt.status || ''))
        && !purchaseReceiptTaskExecutionStarted(receipt)
      );
      (receipt.products || []).forEach((product, index) => {
        const source = (afterSale.products || []).find((line) => (
          (line.sourceLineId && line.sourceLineId === product.sourceLineId)
          || (line.materialCode && line.materialCode === product.materialCode)
        )) || afterSale.products?.[index];
        if (!String(product.plannedQty || '').trim()) {
          product.plannedQty = source?.qty || product.arrivalQty || product.acceptedQty || product.qty || '';
          changed = true;
        }
        if (
          resetLegacyGeneratedActuals
          && [
            product.qty,
            product.arrivalQty,
            product.acceptedQty,
            product.refusedQty,
            product.exceptionHeldQty,
          ].some((value) => Math.abs(parseQty(value)) > 0.0001)
        ) {
          const unit = product.uom || qtyUnit(product.plannedQty) || '';
          product.qty = formatQty(0, unit);
          product.arrivalQty = formatQty(0, unit);
          product.acceptedQty = formatQty(0, unit);
          product.refusedQty = formatQty(0, unit);
          product.exceptionHeldQty = formatQty(0, unit);
          changed = true;
        }
      });
    });
  return changed;
}

function migrateSalesReturnStagingWarehouse(data) {
  data.migrations ||= {};
  if (data.migrations.salesReturnStagingV1) return false;
  const rows = ensureMasterRows(data, 'warehouses');
  const seed = createSeedData().masterData?.warehouses?.find((row) => row.code === 'WH-SA-RETURN');
  if (seed && !rows.some((row) => row.code === seed.code)) rows.push(cloneJson(seed, {}));
  data.migrations.salesReturnStagingV1 = true;
  return true;
}

function hydratePurchaseStagingFlow(data) {
  const warehouses = ensureMasterRows(data, 'warehouses');
  const purchase = ensurePurchase(data);
  const warehouse = ensureWarehouse(data);
  let changed = false;
  const stagingForCompany = (company) => (
    warehouses.find((row) => row.status === '启用' && row.allowPurchaseStaging === true && (!company || row.company === company))
  );

  purchase.orders.forEach((order) => {
    const current = warehouseMeta(data, order.warehouseCode, order.warehouse);
    if (current.allowPurchaseStaging === true) return;
    const staging = stagingForCompany(order.company);
    if (!staging) return;
    order.warehouseCode = staging.code;
    order.warehouse = staging.name;
    changed = true;
  });

  warehouse.purchaseReceipts.forEach((receipt) => {
    const sourceOrder = purchase.orders.find((order) => order.code === receipt.sourceDoc);
    if (!sourceOrder) return;
    const current = warehouseMeta(data, receipt.warehouseCode, receipt.warehouse);
    const currentIsValidStaging = current.status === '启用'
      && current.allowPurchaseStaging === true
      && (!receipt.company || !current.company || current.company === receipt.company);
    const staging = currentIsValidStaging
      ? current
      : stagingForCompany(receipt.company || sourceOrder.company);
    if (!staging) return;
    const previousDestination = current.allowPurchaseReceipt === true ? current : undefined;
    const isPendingArrival = ['草稿', '待收货'].includes(receipt.status || '');
    const savedLocation = String(receipt.location || '');
    const previousLocation = isPendingArrival && /-AUTO$/i.test(savedLocation) ? '' : savedLocation;
    const stagingLocations = warehouseLocationOptions(data, staging);
    const normalStagingLocations = stagingLocations.filter((location) => !isPlaceholderWarehouseLocation(location));
    const stagingLocation = previousLocation
      || (normalStagingLocations.length === 1 ? normalStagingLocations[0] : '');
    warehouse.stockLedger.forEach((ledger) => {
      if (ledger.sourceDoc !== receipt.code) return;
      const balanceFact = String(ledger.balanceFact || '');
      const isStagingMovement = ['待检', '待入库', '异常受控'].includes(balanceFact)
        || (!balanceFact && /进入来料质检|质检放行|异常暂存/.test(String(ledger.reason || '')));
      if (!isStagingMovement) return;
      if (
        ledger.warehouseCode !== staging.code
        || ledger.warehouse !== staging.name
        || ledger.location !== stagingLocation
      ) {
        ledger.warehouseCode = staging.code;
        ledger.warehouse = staging.name;
        ledger.location = stagingLocation;
        changed = true;
      }
    });

    (receipt.products || []).forEach((product, index) => {
      const receiptLineId = product.lineId || `L${index + 1}`;
      const stagingBatch = String(product.stagingBatch ?? product.batch ?? '');
      const materialMatches = (row) => (
        product.materialCode
          ? row.materialCode === product.materialCode
          : row.item === product.name
      );
      const stagingKey = `${product.materialCode || product.name}::${staging.code}::${stagingLocation}::${stagingBatch}`;
      let stagingRow = warehouse.inventory.find((row) => row.key === stagingKey);
      let stagingRejectedFactMissing = !stagingRow || (
        !Object.prototype.hasOwnProperty.call(stagingRow, 'rejectedHoldNumber')
        && !Object.prototype.hasOwnProperty.call(stagingRow, 'rejectedHold')
      );
      const legacyRows = warehouse.inventory.filter((row) => (
        row !== stagingRow
        && materialMatches(row)
        && String(row.batch || '') === stagingBatch
        && row.warehouseCode !== staging.code
        && (
          row.sourceDoc === receipt.code
          || (
            product.destinationWarehouseCode
            && row.warehouseCode === product.destinationWarehouseCode
            && (!product.destinationLocation || row.location === product.destinationLocation)
          )
        )
        && inventoryNumber(row, 'qualifiedOnHandNumber', 'qualifiedOnHand') <= 0.0001
        && (
          inventoryNumber(row, 'qcHoldNumber', 'qcHold')
          + inventoryNumber(row, 'pendingInboundNumber', 'pendingInbound')
          + Number(row.rejectedHoldNumber || 0)
          + inventoryNumber(row, 'exceptionHoldNumber', 'exceptionHold')
        ) > 0.0001
      ));

      legacyRows.forEach((legacyRow) => {
        if (!stagingRow) {
          stagingRow = legacyRow;
          stagingRejectedFactMissing = (
            !Object.prototype.hasOwnProperty.call(stagingRow, 'rejectedHoldNumber')
            && !Object.prototype.hasOwnProperty.call(stagingRow, 'rejectedHold')
          );
          stagingRow.warehouseCode = staging.code;
          stagingRow.warehouse = staging.name;
          stagingRow.location = stagingLocation;
          stagingRow.key = stagingKey;
          changed = true;
          return;
        }

        [
          'onHandNumber',
          'qualifiedOnHandNumber',
          'reservedNumber',
          'allocatedNumber',
          'frozenNumber',
          'qcHoldNumber',
          'pendingInboundNumber',
          'rejectedHoldNumber',
          'exceptionHoldNumber',
          'inTransitNumber',
          'outboundPlanNumber',
        ].forEach((field) => {
          stagingRow[field] = Math.max(Number(stagingRow[field] || 0), Number(legacyRow[field] || 0));
        });
        stagingRow.sourceDoc ||= legacyRow.sourceDoc || receipt.code;
        const duplicateIndex = warehouse.inventory.indexOf(legacyRow);
        if (duplicateIndex >= 0) warehouse.inventory.splice(duplicateIndex, 1);
        changed = true;
      });

      if (!stagingRow) return;
      const decisionLine = receipt.qualityDecision?.lines?.find((line) => (
        line.receiptLineId === receiptLineId
        || (product.materialCode && line.materialCode === product.materialCode)
      ));
      if (stagingRejectedFactMissing && Number(decisionLine?.rejectedQty || 0) > 0) {
        stagingRow.rejectedHoldNumber = Number(decisionLine.rejectedQty || 0);
        changed = true;
      }
      refreshInventoryFactRow(stagingRow, inventoryUnit(stagingRow, product.uom || '件'));
    });

    if (current.code === staging.code) {
      if (receipt.location !== stagingLocation) {
        receipt.location = stagingLocation;
        changed = true;
      }
      return;
    }

    receipt.products = (receipt.products || []).map((product) => ({
      ...product,
      destinationWarehouseCode: product.destinationWarehouseCode || previousDestination?.code || '',
      destinationWarehouse: product.destinationWarehouse || previousDestination?.name || '',
      destinationLocation: product.destinationLocation || (previousDestination ? previousLocation : ''),
    }));
    if (Array.isArray(receipt.postedQuantities?.lines)) {
      receipt.postedQuantities.lines = receipt.postedQuantities.lines.map((line) => ({
        ...line,
        warehouseCode: line.warehouseCode || previousDestination?.code || '',
        warehouse: line.warehouse || previousDestination?.name || '',
        location: line.location || (previousDestination ? previousLocation : ''),
      }));
    }
    if (!purchaseReceiptIsPosted(receipt)) {
      (receipt.products || []).forEach((product) => {
        const sourceRow = warehouse.inventory.find((row) => (
          (product.materialCode ? row.materialCode === product.materialCode : row.item === product.name)
          && (current.code ? row.warehouseCode === current.code : row.warehouse === current.name)
          && (!previousLocation || row.location === previousLocation)
          && (!product.batch || row.batch === product.batch)
        ));
        if (!sourceRow) return;
        const qualified = inventoryNumber(sourceRow, 'qualifiedOnHandNumber', 'qualifiedOnHand');
        const pending = inventoryNumber(sourceRow, 'pendingInboundNumber', 'pendingInbound');
        const qcHold = inventoryNumber(sourceRow, 'qcHoldNumber', 'qcHold');
        const rejected = Number(sourceRow.rejectedHoldNumber || 0);
        if (qualified > 0.0001 || pending + qcHold + rejected <= 0.0001) return;
        sourceRow.warehouseCode = staging.code;
        sourceRow.warehouse = staging.name;
        sourceRow.location = stagingLocation;
        sourceRow.key = `${sourceRow.materialCode || sourceRow.item}::${staging.code}::${stagingLocation}::${sourceRow.batch || ''}`;
        refreshInventoryFactRow(sourceRow, inventoryUnit(sourceRow));
      });
      warehouse.stockLedger.forEach((ledger) => {
        if (ledger.sourceDoc !== receipt.code) return;
        ledger.warehouseCode = staging.code;
        ledger.warehouse = staging.name;
        ledger.location = stagingLocation;
      });
    }
    receipt.warehouseCode = staging.code;
    receipt.warehouse = staging.name;
    receipt.location = stagingLocation;
    changed = true;
  });

  purchase.orders.forEach((order) => {
    const generated = ensurePendingPurchaseReceiptTask(data, order, { notify: false, actor: '系统迁移' });
    if (generated.changed) changed = true;
  });

  return changed;
}

function hydratePurchaseReceiptLedgerTransitions(data) {
  const warehouse = ensureWarehouse(data);
  let changed = false;
  const ledgerQuantityNumber = (row) => {
    const explicit = Number(row?.quantityNumber);
    return Number.isFinite(explicit) ? explicit : parseQty(row?.qty);
  };

  warehouse.purchaseReceipts.forEach((receipt) => {
    (receipt.products || []).forEach((product, index) => {
      const receiptLineId = product.lineId || `L${index + 1}`;
      const lineRows = () => warehouse.stockLedger.filter((row) => (
        row.sourceDoc === receipt.code
        && (
          row.documentLineId === receiptLineId
          || (product.materialCode && row.materialCode === product.materialCode)
        )
      ));
      const inventory = receiptInventoryRow(data, receipt, product, receipt.date || shanghaiDateTime());
      const ledgerProduct = { ...product, lineId: receiptLineId };
      const arrivalState = lineRows()
        .filter((row) => ['质检冻结', '到货收货', '异常暂收'].includes(row.movement))
        .sort((left, right) => String(left.time || '').localeCompare(String(right.time || '')))[0];

      if (arrivalState && !lineRows().some((row) => row.movement === '采购到货')) {
        const quantities = purchaseReceiptLineArrivalQuantities(product);
        const physicalQty = quantities.accepted + quantities.exceptionHeld;
        if (physicalQty > 0.0001) {
          const before = Number(arrivalState.beforeBalanceNumber || 0);
          appendStockLedgerFact(
            warehouse,
            inventory.row,
            ledgerProduct,
            physicalQty,
            inventory.unit,
            receipt.code,
            '采购到货进入采购暂存区',
            receipt.owner || arrivalState.operator || '王倩',
            arrivalState.time || receipt.date || shanghaiDateTime(),
            {
              movement: '采购到货',
              balanceFact: '物理在库',
              beforeBalanceNumber: before,
              afterBalanceNumber: before + physicalQty,
            },
          );
          changed = true;
        }
      }

      const decisionLine = receipt.qualityDecision?.lines?.find((line) => (
        line.receiptLineId === receiptLineId
        || (product.materialCode && line.materialCode === product.materialCode)
      ));
      const removedFromHold = Number(decisionLine?.releasedQty || 0) + Number(decisionLine?.rejectedQty || 0);
      const freezeRow = lineRows().find((row) => row.movement === '质检冻结');
      if (
        removedFromHold > 0.0001
        && freezeRow
        && !lineRows().some((row) => row.movement === '质检解冻')
      ) {
        const before = Number(freezeRow.afterBalanceNumber || removedFromHold);
        appendStockLedgerFact(
          warehouse,
          inventory.row,
          ledgerProduct,
          -removedFromHold,
          inventory.unit,
          receipt.code,
          `质检判定释放 ${formatQty(Number(decisionLine.releasedQty || 0), inventory.unit)}`
            + `、隔离 ${formatQty(Number(decisionLine.rejectedQty || 0), inventory.unit)}`,
          receipt.qualityDecision?.actor || '林珊',
          receipt.qualityDecision?.decidedAt || freezeRow.time || shanghaiDateTime(),
          {
            movement: '质检解冻',
            balanceFact: '待检',
            beforeBalanceNumber: before,
            afterBalanceNumber: Math.max(0, before - removedFromHold),
          },
        );
        changed = true;
      }

      const rejectedQty = Number(decisionLine?.rejectedQty || 0);
      if (
        rejectedQty > 0.0001
        && !lineRows().some((row) => row.movement === '不合格隔离')
      ) {
        appendStockLedgerFact(
          warehouse,
          inventory.row,
          ledgerProduct,
          rejectedQty,
          inventory.unit,
          receipt.code,
          `质检判定隔离 ${formatQty(rejectedQty, inventory.unit)}`,
          receipt.qualityDecision?.actor || '林珊',
          receipt.qualityDecision?.decidedAt || shanghaiDateTime(),
          {
            movement: '不合格隔离',
            balanceFact: '不合格隔离',
            beforeBalanceNumber: 0,
            afterBalanceNumber: rejectedQty,
          },
        );
        changed = true;
      }

      const physicalOutboundRows = lineRows()
        .filter((row) => row.movement === '采购入库移出')
        .sort((left, right) => String(left.time || '').localeCompare(String(right.time || '')));
      const existingPendingOutbound = lineRows()
        .filter((row) => row.movement === '待入库转出')
        .sort((left, right) => String(left.time || '').localeCompare(String(right.time || '')));
      const pendingAdds = lineRows()
        .filter((row) => row.balanceFact === '待入库' && ledgerQuantityNumber(row) > 0)
        .reduce((sum, row) => sum + ledgerQuantityNumber(row), 0);
      let pendingBalance = Math.max(
        pendingAdds,
        physicalOutboundRows.reduce((sum, row) => sum + Math.abs(ledgerQuantityNumber(row)), 0),
      );
      physicalOutboundRows.forEach((physicalRow, rowIndex) => {
        const quantity = Math.abs(ledgerQuantityNumber(physicalRow));
        const pendingRow = existingPendingOutbound[rowIndex];
        if (pendingRow && quantity > 0.0001 && Math.abs(ledgerQuantityNumber(pendingRow)) <= 0.0001) {
          pendingRow.quantityNumber = -quantity;
          pendingRow.qty = `-${formatQty(quantity, inventory.unit)}`;
          pendingRow.beforeBalanceNumber = pendingBalance;
          pendingRow.afterBalanceNumber = Math.max(0, pendingBalance - quantity);
          pendingRow.beforeBalance = formatQty(pendingRow.beforeBalanceNumber, inventory.unit);
          pendingRow.afterBalance = formatQty(pendingRow.afterBalanceNumber, inventory.unit);
          pendingRow.balance = pendingRow.afterBalance;
          changed = true;
        }
        pendingBalance = Math.max(0, pendingBalance - quantity);
      });
      if (physicalOutboundRows.length > existingPendingOutbound.length) {
        const existingOutboundTotal = physicalOutboundRows
          .slice(0, existingPendingOutbound.length)
          .reduce((sum, row) => sum + Math.abs(ledgerQuantityNumber(row)), 0);
        pendingBalance = Math.max(0, Math.max(
          pendingAdds,
          physicalOutboundRows.reduce((sum, row) => sum + Math.abs(ledgerQuantityNumber(row)), 0),
        ) - existingOutboundTotal);
        physicalOutboundRows.slice(existingPendingOutbound.length).forEach((physicalRow) => {
          const quantity = Math.abs(ledgerQuantityNumber(physicalRow));
          appendStockLedgerFact(
            warehouse,
            inventory.row,
            { ...ledgerProduct, lineId: physicalRow.documentLineId || receiptLineId },
            -quantity,
            inventory.unit,
            receipt.code,
            `正式入库转出待入库数量：${physicalRow.reason || '采购正式入库'}`,
            physicalRow.operator || receipt.owner || '王倩',
            physicalRow.time || shanghaiDateTime(),
            {
              movement: '待入库转出',
              balanceFact: '待入库',
              beforeBalanceNumber: pendingBalance,
              afterBalanceNumber: Math.max(0, pendingBalance - quantity),
            },
          );
          pendingBalance = Math.max(0, pendingBalance - quantity);
          changed = true;
        });
      }
    });
  });

  return changed;
}

function hydrateSalesIssueExecutionFacts(data) {
  const sales = ensureSales(data);
  const warehouse = ensureWarehouse(data);
  let changed = false;

  warehouse.salesIssues.forEach((issue) => {
    const tracking = sales.outboundRequests.find((row) => row.code === issue.sourceDoc);
    const order = sales.orders.find((row) => row.code === (tracking?.sourceOrder || issue.sourceOrder));
    const address = String(issue.address || tracking?.address || order?.shipAddress || '').trim();
    if (address && issue.address !== address) {
      issue.address = address;
      changed = true;
    }
    const sourceRemark = String(
      tracking?.supplementaryRequirement
        || tracking?.remark
        || issue.supplementaryRequirement
        || issue.sourceRemark
        || '',
    ).trim();
    if (issue.supplementaryRequirement !== sourceRemark) {
      issue.supplementaryRequirement = sourceRemark;
      changed = true;
    }
    if (issue.sourceRemark !== sourceRemark) {
      issue.sourceRemark = sourceRemark;
      changed = true;
    }
    if (
      issue.status === '待拣货'
      && !issue.reviewSubmittedAt
      && !issue.pickingResult
      && sourceRemark
      && String(issue.note || '').trim() === sourceRemark
    ) {
      issue.note = '';
      changed = true;
    }
    if (
      issue.status === '待拣货'
      && !issue.pickingResult
      && (issue.warehouseCode || issue.warehouse)
    ) {
      issue.warehouseCode = '';
      issue.warehouse = '';
      changed = true;
    }
    if (issue.status === '待拣货' && !issue.pickingResult) {
      if (issue.reviewSubmittedAt || issue.reviewSubmittedBy) {
        issue.reviewSubmittedAt = '';
        issue.reviewSubmittedBy = '';
        changed = true;
      }
      if (Array.isArray(issue.actualWarehouses) && issue.actualWarehouses.length) {
        issue.actualWarehouses = [];
        changed = true;
      }
    }

    (issue.products || []).forEach((product) => {
      if (!String(product.taskQty || '').trim()) {
        product.taskQty = product.qty || '';
        changed = true;
      }
      const controls = materialControlSnapshot(data, product);
      if (product.batchControl !== controls.batchControl) {
        product.batchControl = controls.batchControl;
        changed = true;
      }
      if (product.batchTracked !== controls.batchTracked) {
        product.batchTracked = controls.batchTracked;
        changed = true;
      }
    });

    const migratedFromAcceptance = issue.status === '待受理';
    if (migratedFromAcceptance) {
      issue.status = '待拣货';
      changed = true;
      if (issue.owner !== '待分配') {
        issue.owner = '待分配';
        changed = true;
      }
      if (issue.date && issue.date === issue.expectedDate) {
        issue.date = '';
        changed = true;
      }
    }

    const flowRecords = warehouse.salesIssueFlowRecords[issue.code] || [];
    const pickingRecord = flowRecords.find((row) => /开始拣货|受理/.test(String(row.action || '')));
    const pickingStartedAt = issue.pickingStartedAt || issue.acceptedAt || pickingRecord?.time || '';
    const pickingStartedBy = issue.pickingStartedBy || issue.acceptedBy || pickingRecord?.actor || '';
    if (pickingStartedAt && issue.pickingStartedAt !== pickingStartedAt) {
      issue.pickingStartedAt = pickingStartedAt;
      changed = true;
    }
    if (pickingStartedBy && issue.pickingStartedBy !== pickingStartedBy) {
      issue.pickingStartedBy = pickingStartedBy;
      changed = true;
    }
    const reviewRecord = [...flowRecords].reverse().find((row) => (
      /提交复核|拣货复核|重新提交复核/.test(String(row.action || ''))
    ));
    if (reviewRecord && !issue.reviewSubmittedAt && issue.status !== '待拣货') {
      issue.reviewSubmittedAt = reviewRecord.time || '';
      issue.reviewSubmittedBy = reviewRecord.actor || '';
      changed = true;
    }
    const postedRecord = [...flowRecords].reverse().find((row) => String(row.action || '').includes('确认出库'));
    if (postedRecord && !issue.postedAt) {
      issue.postedAt = postedRecord.time || '';
      issue.postedBy = postedRecord.actor || '';
      changed = true;
    }
  });

  sales.outboundRequests.forEach((tracking) => {
    if (['草稿', '已作废', '已取消', '已退回', '已签收', '已完成'].includes(String(tracking.status || ''))) return;
    const fulfillment = shipmentTrackingFulfillment(data, tracking);
    if (fulfillment.isComplete) return;
    const activeIssue = warehouse.salesIssues.find((issue) => (
      issue.sourceDoc === tracking.code
      && !issue.reversalCode
      && !['已出库', '已作废', '已中断', '已取消'].includes(String(issue.status || ''))
    ));
    if (!activeIssue) return;
    const nextStatus = fulfillment.totalDelivered > 0 ? '部分出库' : '待发货';
    if (tracking.status === nextStatus) return;
    tracking.status = nextStatus;
    changed = true;
  });

  return changed;
}

function hydrateWarehouseExecutionActors(data) {
  const warehouse = ensureWarehouse(data);
  const auditLogs = Array.isArray(data.system?.logs) ? data.system.logs : [];
  const invalidActor = (value) => {
    const actor = String(value || '').trim();
    return !actor || actor === '待分配' || /^ACC-/i.test(actor);
  };
  const auditActor = (name, target, reference = '') => {
    const log = auditLogs.find((row) => (
      row.name === name
      && row.target === target
      && (!reference || String(row.remark || '').includes(reference))
    ));
    return String(log?.owner || '').split('/')[0].trim();
  };
  let changed = false;

  warehouse.purchaseReceipts.forEach((receipt) => {
    if (!['草稿', '待收货'].includes(receipt.status || '')) return;
    if (receipt.owner === '待分配') return;
    receipt.owner = '待分配';
    changed = true;
  });

  warehouse.salesIssues.forEach((issue) => {
    if (issue.status !== '已出库' || !invalidActor(issue.owner)) return;
    const actor = auditActor('确认销售出库', issue.code);
    if (!actor) return;
    issue.owner = actor;
    changed = true;
  });

  warehouse.reversals.forEach((reversal) => {
    if (!invalidActor(reversal.actor)) return;
    const actor = auditActor('库存冲销', reversal.sourceDoc, reversal.code);
    if (!actor) return;
    reversal.actor = actor;
    const source = warehouse.salesIssues.find((row) => row.code === reversal.sourceDoc)
      || warehouse.purchaseReceipts.find((row) => row.code === reversal.sourceDoc)
      || warehouse.otherMoves.find((row) => row.code === reversal.sourceDoc)
      || warehouse.transfers.find((row) => row.code === reversal.sourceDoc)
      || warehouse.stocktakes.find((row) => row.code === reversal.sourceDoc);
    if (source && invalidActor(source.reversedBy)) source.reversedBy = actor;
    changed = true;
  });

  const operatorBySource = new Map([
    ...warehouse.salesIssues.map((row) => [row.code, row.owner]),
    ...warehouse.purchaseReceipts.map((row) => [row.code, row.owner]),
    ...warehouse.otherMoves.map((row) => [row.code, row.owner]),
    ...warehouse.transfers.map((row) => [row.code, row.owner]),
    ...warehouse.stocktakes.map((row) => [row.code, row.owner]),
    ...warehouse.reversals.map((row) => [row.code, row.actor]),
  ]);
  warehouse.stockLedger.forEach((ledger) => {
    if (!invalidActor(ledger.operator)) return;
    const actor = String(operatorBySource.get(ledger.sourceDoc) || '').trim();
    if (invalidActor(actor)) return;
    ledger.operator = actor;
    changed = true;
  });

  return changed;
}

function hydratePurchaseDocumentStatuses(data) {
  const requisitions = Array.isArray(data.purchase?.requisitions) ? data.purchase.requisitions : [];
  requisitions.forEach((requisition) => {
    const status = String(requisition.status || '草稿');
    if (['已转采购', '已转物料采购', '已转采购订单'].includes(status)) {
      requisition.status = '待采购受理';
    }
  });

  const orders = Array.isArray(data.purchase?.orders) ? data.purchase.orders : [];
  orders.forEach((order) => {
    const status = String(order.status || '草稿');
    if (['草稿', '已确认', '已关闭', '已作废'].includes(status)) return;
    if (['已完成', '已关闭'].includes(status)) order.status = '已关闭';
    else if (['已作废', '已退回', '已驳回', '已中断', '已取消'].includes(status)) order.status = '已作废';
    else order.status = '已确认';
  });
}

const commercialFollowUpKinds = {
  sales: new Set(['sales_invoice', 'sales_payment']),
  purchase: new Set(['purchase_invoice', 'purchase_payment']),
};

function commercialFollowUpStore(data, module) {
  data[module] ||= {};
  data[module].commercialFollowUps ||= [];
  return data[module].commercialFollowUps;
}

function commercialFollowUpEvents(data, module, sourceOrder) {
  const explicit = commercialFollowUpStore(data, module)
    .filter((event) => event.sourceOrder === sourceOrder && event.status !== 'voided');
  const finance = data.finance || {};
  const legacy = [];

  if (module === 'sales') {
    const invoices = (finance.salesInvoices || []).filter((invoice) => (
      (invoice.sourceOrder === sourceOrder || invoice.sourceDoc === sourceOrder)
      && !['草稿', '待开票', '已作废', '已取消', '已冲销', '红冲', '已红冲'].includes(String(invoice.status || ''))
    ));
    invoices.forEach((invoice) => {
      const amount = parseMoney(invoice.totalAmount || invoice.amount);
      if (amount <= 0) return;
      legacy.push({
        id: `legacy-sales-invoice-${invoice.code}`,
        module,
        sourceOrder,
        kind: 'sales_invoice',
        amount,
        occurredOn: String(invoice.date || invoice.invoiceDate || '').slice(0, 10),
        referenceNo: invoice.invoiceNo || invoice.code,
        note: '由历史演示数据迁移',
        actor: invoice.owner || '历史数据',
        createdAt: invoice.updatedAt || invoice.createdAt || '',
        source: 'legacy',
      });
    });
    const invoiceCodes = new Set(invoices.map((invoice) => invoice.code));
    (finance.receivables || [])
      .filter((record) => (
        !['已作废', '已冲销', '红冲', '已红冲'].includes(String(record.status || ''))
        && (record.sourceOrder === sourceOrder || invoiceCodes.has(record.sourceDoc))
      ))
      .forEach((record) => {
        const amount = parseMoney(record.settledAmount);
        if (amount <= 0) return;
        legacy.push({
          id: `legacy-sales-payment-${record.code}`,
          module,
          sourceOrder,
          kind: 'sales_payment',
          amount,
        occurredOn: String(record.settledAt || record.date || record.updatedAt || record.dueDate || '').slice(0, 10),
          referenceNo: record.code,
          note: '由历史演示数据迁移',
          actor: record.owner || '历史数据',
          createdAt: record.updatedAt || record.createdAt || '',
          source: 'legacy',
        });
      });
  } else {
    const receiptCodes = new Set(
      (data.warehouse?.purchaseReceipts || [])
        .filter((receipt) => receipt.sourceDoc === sourceOrder)
        .map((receipt) => receipt.code),
    );
    const invoices = (finance.purchaseInvoices || []).filter((invoice) => (
      (invoice.sourceOrder === sourceOrder || receiptCodes.has(invoice.sourceDoc))
      && !['草稿', '待收票', '已作废', '已取消', '已冲销'].includes(String(invoice.status || ''))
    ));
    invoices.forEach((invoice) => {
      const amount = parseMoney(invoice.totalAmount || invoice.amount);
      if (amount <= 0) return;
      legacy.push({
        id: `legacy-purchase-invoice-${invoice.code}`,
        module,
        sourceOrder,
        kind: 'purchase_invoice',
        amount,
        occurredOn: String(invoice.date || invoice.invoiceDate || '').slice(0, 10),
        referenceNo: invoice.invoiceNo || invoice.code,
        note: '由历史演示数据迁移',
        actor: invoice.owner || '历史数据',
        createdAt: invoice.updatedAt || invoice.createdAt || '',
        source: 'legacy',
      });
    });
    const invoiceCodes = new Set(invoices.map((invoice) => invoice.code));
    (finance.payables || [])
      .filter((record) => (
        !['已作废', '已取消'].includes(String(record.status || ''))
        && (record.sourceOrder === sourceOrder || invoiceCodes.has(record.sourceDoc))
      ))
      .forEach((record) => {
        const amount = parseMoney(record.settledAmount);
        if (amount <= 0) return;
        legacy.push({
          id: `legacy-purchase-payment-${record.code}`,
          module,
          sourceOrder,
          kind: 'purchase_payment',
          amount,
        occurredOn: String(record.settledAt || record.date || record.updatedAt || record.dueDate || '').slice(0, 10),
          referenceNo: record.code,
          note: '由历史演示数据迁移',
          actor: record.owner || '历史数据',
          createdAt: record.updatedAt || record.createdAt || '',
          source: 'legacy',
        });
      });
  }

  return [...legacy, ...explicit].sort((a, b) => (
    `${b.occurredOn || ''}${b.createdAt || ''}${b.id || ''}`.localeCompare(
      `${a.occurredOn || ''}${a.createdAt || ''}${a.id || ''}`,
    )
  ));
}

function commercialFollowUpTotals(data, module, order) {
  const events = commercialFollowUpEvents(data, module, order.code);
  const invoiceKind = module === 'sales' ? 'sales_invoice' : 'purchase_invoice';
  const paymentKind = module === 'sales' ? 'sales_payment' : 'purchase_payment';
  return {
    events,
    orderAmount: parseMoney(order.amount),
    invoiceAmount: events
      .filter((event) => event.kind === invoiceKind)
      .reduce((sum, event) => sum + Number(event.amount || 0), 0),
    paymentAmount: events
      .filter((event) => event.kind === paymentKind)
      .reduce((sum, event) => sum + Number(event.amount || 0), 0),
  };
}

function createCommercialFollowUp(data, module, order, input, actor) {
  const kind = String(input.kind || '');
  if (!commercialFollowUpKinds[module]?.has(kind)) {
    throw requestError(400, '商务跟进类型不属于当前模块。');
  }
  const idempotencyKey = String(input.idempotencyKey || '').trim();
  if (!idempotencyKey) throw requestError(400, '登记商务跟进必须提供幂等键。');
  const store = commercialFollowUpStore(data, module);
  const repeated = store.find((event) => event.idempotencyKey === idempotencyKey);
  if (repeated) return { event: repeated, repeated: true };

  const amount = parseMoney(input.amount);
  if (amount <= 0) throw requestError(400, '本次金额必须大于 0。');
  const occurredOn = String(input.occurredOn || '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(occurredOn)) throw requestError(400, '请选择有效的业务日期。');
  if (occurredOn > shanghaiDate()) throw requestError(400, '业务日期不能晚于今天。');
  const referenceNo = String(input.referenceNo || '').trim();
  const attachments = Array.isArray(input.attachments) ? input.attachments : [];

  const totals = commercialFollowUpTotals(data, module, order);
  const accumulated = kind.endsWith('_invoice') ? totals.invoiceAmount : totals.paymentAmount;
  if (totals.orderAmount > 0 && accumulated + amount > totals.orderAmount + 0.01) {
    throw requestError(409, `累计登记金额不能超过订单含税总额 ${money(totals.orderAmount)}。`);
  }

  const prefix = module === 'sales' ? 'SCF' : 'PCF';
  const id = nextDocumentCode(
    data,
    `${module}-commercial-follow-ups`,
    store.map((item) => ({ code: item.id })),
    prefix,
  );
  const event = {
    id,
    code: id,
    module,
    sourceOrder: order.code,
    kind,
    amount,
    currency: order.currency || 'CNY',
    occurredOn,
    ...(referenceNo ? { referenceNo } : {}),
    ...(attachments.length ? { attachments } : {}),
    note: String(input.note || '').trim(),
    actor,
    idempotencyKey,
    createdAt: shanghaiDateTime(),
    status: 'active',
    source: 'commercial',
  };
  store.unshift(event);
  return { event, repeated: false };
}

function removeCommercialFollowUp(data, module, order, eventId, actor) {
  const store = commercialFollowUpStore(data, module);
  const event = store.find((item) => item.id === eventId && item.sourceOrder === order.code);
  if (!event) throw requestError(404, '商务跟进记录不存在或属于历史迁移数据。');
  if (event.status === 'voided') return { event, repeated: true };
  event.status = 'voided';
  event.deletedAt = shanghaiDateTime();
  event.deletedBy = actor;
  return { event, repeated: false };
}

function commercialFollowUpEventSummary(event) {
  const note = String(event.note || '').trim();
  return `${event.occurredOn}，本次 ${money(event.amount)}${note ? `，备注：${note}` : ''}。`;
}

const defaultPurchaseOverReceiptTolerancePercent = 5;

function purchaseOrderOverReceiptTolerancePercent(order = {}) {
  const explicit = Number(order.overReceiptTolerancePercent);
  return Number.isFinite(explicit)
    ? Math.min(100, Math.max(0, explicit))
    : defaultPurchaseOverReceiptTolerancePercent;
}

function purchaseOrderLineClosedReceiptQty(order = {}, sourceLineId = '') {
  return (order.receiptClosures || [])
    .filter((closure) => String(closure.sourceLineId || '') === String(sourceLineId || ''))
    .reduce((sum, closure) => sum + Math.max(0, Number(closure.closedQty || 0)), 0);
}

function purchaseOrderLineReceiptLimits(order = {}, orderLine = {}, orderLineIndex = 0) {
  const sourceLineId = orderLine.lineId || `L${orderLineIndex + 1}`;
  const orderedQty = Math.max(0, parseQty(orderLine.qty));
  const closedQty = Math.min(orderedQty, purchaseOrderLineClosedReceiptQty(order, sourceLineId));
  const receiptTargetQty = Math.max(0, orderedQty - closedQty);
  const overReceiptTolerancePercent = purchaseOrderOverReceiptTolerancePercent(order);
  const maxReceivableQty = orderedQty * (1 + overReceiptTolerancePercent / 100);
  return {
    sourceLineId,
    orderedQty,
    closedQty,
    receiptTargetQty,
    overReceiptTolerancePercent,
    maxReceivableQty,
  };
}

function incomingQualityLineResolution(data, receipt, receiptLineId, rejectedQty = 0) {
  const direct = receipt.qualityDispositionQuantities?.[receiptLineId] || {};
  const approvedConcessionQty = Math.max(0, Number(direct.approvedConcessionQty || 0));
  const reinspectionAcceptedQty = Math.max(0, Number(direct.reinspectionAcceptedQty || 0));
  const quality = ensureQuality(data);
  const purchase = ensurePurchase(data);
  const qualityTaskCode = receipt.qualityTaskCode || receipt.qualityDecision?.code || '';
  const returnedQty = (quality.incomingDispositions?.[qualityTaskCode] || [])
    .filter((row) => row.receiptLineId === receiptLineId && row.action === 'return_to_supplier')
    .reduce((sum, row) => {
      const returnDocument = quality.incomingReturnDocuments.find((item) => item.code === row.returnDocumentCode);
      const afterSale = purchase.afterSales.find((item) => item.code === returnDocument?.afterSaleCode);
      return sum + (afterSale?.status === '已关闭' ? Math.max(0, Number(row.quantity || 0)) : 0);
    }, 0);
  const releasedAdjustmentQty = approvedConcessionQty + reinspectionAcceptedQty;
  const resolvedRejectedQty = Math.min(
    Math.max(0, Number(rejectedQty || 0)),
    releasedAdjustmentQty + returnedQty,
  );
  return {
    approvedConcessionQty,
    reinspectionAcceptedQty,
    returnedQty,
    releasedAdjustmentQty,
    unresolvedRejectedQty: Math.max(0, Number(rejectedQty || 0) - resolvedRejectedQty),
  };
}

function purchaseOrderProgressFacts(data, order) {
  const warehouse = ensureWarehouse(data);
  const activeAfterSale = (data.purchase?.afterSales || []).find((record) => (
    record.sourceOrder === order.code && !['已关闭', '已作废'].includes(record.status)
  ));
  const receipts = warehouse.purchaseReceipts.filter((receipt) => (
    receipt.sourceDoc === order.code
    && receipt.sourceType !== 'purchase_after_sale'
    && purchaseReceiptCountsAsArrival(receipt)
  ));
  const orderLines = order.products || [];
  const lineProgress = orderLines.map((orderLine, orderLineIndex) => {
    const limits = purchaseOrderLineReceiptLimits(order, orderLine, orderLineIndex);
    const orderLineId = limits.sourceLineId;
    const matchingReceiptLines = receipts.flatMap((receipt) => (
      (receipt.products || []).flatMap((receiptLine, receiptLineIndex) => {
        const receiptLineId = receiptLine.lineId || `L${receiptLineIndex + 1}`;
        const explicitSourceLineId = receiptLine.sourceLineId || '';
        const sameLine = explicitSourceLineId
          ? explicitSourceLineId === orderLineId
          : receiptLine.lineId && orderLine.lineId
            ? receiptLine.lineId === orderLine.lineId
            : receiptLine.materialCode && orderLine.materialCode
              ? receiptLine.materialCode === orderLine.materialCode
              : receiptLine.name === orderLine.name;
        return sameLine ? [{ receipt, receiptLine, receiptLineIndex, receiptLineId }] : [];
      })
    ));
    const arrivedQty = matchingReceiptLines.reduce(
      (sum, item) => sum + parseQty(item.receiptLine.acceptedQty ?? item.receiptLine.qty),
      0,
    );
    const inboundQty = matchingReceiptLines.reduce(
      (sum, item) => sum + purchaseReceiptPostedQty(item.receipt, item.receiptLine, item.receiptLineIndex),
      0,
    );
    const qualityQuantities = matchingReceiptLines.reduce((result, item) => {
      const decisionLine = item.receipt.qualityDecision?.lines?.find((line) => line.receiptLineId === item.receiptLineId);
      if (decisionLine) {
        const resolution = incomingQualityLineResolution(
          data,
          item.receipt,
          item.receiptLineId,
          decisionLine.rejectedQty,
        );
        result.releasedQty += Number(decisionLine.releasedQty || 0) + resolution.releasedAdjustmentQty;
        result.rejectedQty += resolution.unresolvedRejectedQty;
        result.returnedQty += resolution.returnedQty;
        result.pendingQcQty += Number(decisionLine.pendingQty || 0);
      } else if (item.receiptLine.qcRequired) {
        result.pendingQcQty += parseQty(item.receiptLine.qty);
      } else {
        result.releasedQty += parseQty(item.receiptLine.qty);
      }
      return result;
    }, { releasedQty: 0, rejectedQty: 0, returnedQty: 0, pendingQcQty: 0 });
    return {
      lineId: orderLineId,
      materialCode: orderLine.materialCode || '',
      name: orderLine.name || '',
      uom: orderLine.uom || '',
      orderedQty: limits.orderedQty,
      receiptTargetQty: limits.receiptTargetQty,
      closedQty: limits.closedQty,
      remainingQty: Math.max(0, limits.receiptTargetQty - arrivedQty),
      maxReceivableQty: limits.maxReceivableQty,
      remainingReceivableQty: Math.max(0, limits.maxReceivableQty - arrivedQty),
      overReceivedQty: Math.max(0, arrivedQty - limits.orderedQty),
      overReceiptTolerancePercent: limits.overReceiptTolerancePercent,
      arrivedQty,
      inboundQty,
      ...qualityQuantities,
    };
  });
  const hasArrived = lineProgress.some((line) => line.arrivedQty > 0);
  const arrivalComplete = lineProgress.length > 0
    && lineProgress.every((line) => line.arrivedQty + 0.0001 >= line.receiptTargetQty);
  const hasInbound = lineProgress.some((line) => line.inboundQty > 0);
  const inboundComplete = lineProgress.length > 0
    && lineProgress.every((line) => line.inboundQty + 0.0001 >= line.receiptTargetQty);

  const arrival = !hasArrived
    ? '未到货'
    : arrivalComplete
      ? '已到货'
      : '部分到货';
  const inbound = !hasInbound
    ? '未入库'
    : inboundComplete
      ? '已入库'
      : '部分入库';

  const orderRequiresQuality = (order.products || []).some((line) => (
    incomingQualityRuleRequiresInspection(materialIncomingQualityRule(
      data,
      line.materialCode,
      line.name,
      line.incomingQualityControl,
      Boolean(line.qcRequired),
    ))
  ));
  const requiresQuality = orderRequiresQuality || receipts.some((receipt) => (
    (receipt.products || []).some((line) => (
      Boolean(line.qcRequired) && parseQty(line.acceptedQty ?? line.qty) > 0.0001
    ))
  ));
  let quality = requiresQuality ? '未开始' : '无需质检';
  if (requiresQuality) {
    const decisions = receipts.map((receipt) => receipt.qualityDecision).filter(Boolean);
    const decisionLines = receipts.flatMap((receipt) => (
      (receipt.qualityDecision?.lines || []).map((line) => {
        const resolution = incomingQualityLineResolution(
          data,
          receipt,
          line.receiptLineId,
          line.rejectedQty,
        );
        return {
          ...line,
          effectiveReleasedQty: Number(line.releasedQty || 0) + resolution.releasedAdjustmentQty,
          effectiveRejectedQty: resolution.unresolvedRejectedQty,
          resolvedReturnedQty: resolution.returnedQty,
        };
      })
    ));
    const hasRejected = decisionLines.some((line) => Number(line.effectiveRejectedQty || 0) > 0);
    const hasPending = receipts.some((receipt) => !receipt.qualityDecision)
      || decisionLines.some((line) => Number(line.pendingQty || 0) > 0);
    const hasReleased = decisionLines.some((line) => Number(line.effectiveReleasedQty || 0) > 0);
    const allReleased = decisionLines.length > 0 && decisionLines.every((line) => (
      Number(line.pendingQty || 0) <= 0
      && Number(line.effectiveRejectedQty || 0) <= 0
      && Number(line.effectiveReleasedQty || 0) + Number(line.resolvedReturnedQty || 0) + 0.0001
        >= Number(line.receivedQty || 0)
    ));
    if (!receipts.length) quality = '未开始';
    else if (!decisions.length) quality = '待检';
    else if (hasRejected) quality = '不合格处理中';
    else if (hasPending && hasReleased) quality = '部分放行';
    else if (hasPending) quality = '待检';
    else if (allReleased) quality = '已放行';
  }

  const commercial = commercialFollowUpTotals(data, 'purchase', order);
  const invoiceAmount = commercial.invoiceAmount;
  const orderAmount = commercial.orderAmount;
  const invoice = invoiceAmount <= 0
    ? '未收票'
    : orderAmount > 0 && invoiceAmount + 0.01 < orderAmount
      ? '部分收票'
      : '已收票';

  const payableAmount = orderAmount;
  const settledAmount = commercial.paymentAmount;
  const payment = settledAmount <= 0
    ? '未付款'
    : payableAmount > 0 && settledAmount + 0.01 < payableAmount
      ? '部分付款'
      : '已付款';

  const documentStatus = String(order.status || '草稿');
  const isPaused = documentStatus === '已作废';
  const overdue = order.expectedDate
    && order.expectedDate < shanghaiDate()
    && arrival !== '已到货';
  const attention = isPaused
    ? '已作废'
    : activeAfterSale
      ? '采购售后处理中'
    : quality === '不合格处理中'
      ? '质量异常'
      : overdue
        ? '到货逾期'
        : '正常';
  const attentionTone = isPaused
    ? 'paused'
    : quality === '不合格处理中'
      ? 'danger'
      : overdue
        ? 'warning'
        : 'normal';

  let nextStep = '查看日志';
  if (documentStatus === '草稿') nextStep = '确认采购订单';
  else if (documentStatus === '已作废' || documentStatus === '已关闭') nextStep = '无后续动作';
  else if (activeAfterSale) nextStep = `跟进采购售后 ${activeAfterSale.code}`;
  else if (quality === '不合格处理中') nextStep = '处理来料质量异常';
  else if (arrival !== '已到货') nextStep = '跟进供应商到货';
  else if (!['无需质检', '已放行'].includes(quality)) nextStep = '跟进来料质检';
  else if (inbound !== '已入库') nextStep = '跟进入库过账';
  else if (invoice !== '已收票') nextStep = '跟进供应商开票';
  else if (payment !== '已付款') nextStep = '跟进付款';
  else nextStep = '关闭采购订单';

  return {
    arrival,
    quality,
    inbound,
    invoice,
    payment,
    attention,
    attentionTone,
    nextStep,
    commercial: {
      orderAmount,
      invoicedAmount: invoiceAmount,
      payableAmount,
      settledAmount,
    },
    lines: lineProgress,
  };
}

function salesOrderRelatedDocuments(data, order) {
  const warehouse = ensureWarehouse(data);
  const documents = [];

  warehouse.salesIssues
    .filter((issue) => issue.sourceOrder === order.code && !issue.reversalCode)
    .forEach((issue) => documents.push({
      type: '销售出库',
      code: issue.code,
      status: issue.status || '未记录',
      path: `/warehouse/sales-issues/${encodeURIComponent(issue.code)}`,
    }));

  commercialFollowUpEvents(data, 'sales', order.code).forEach((event) => documents.push({
    type: event.kind === 'sales_invoice' ? '开票记录' : '回款记录',
    code: event.referenceNo || event.id,
    status: money(event.amount),
    path: `/sales/orders/${encodeURIComponent(order.code)}#commercial-follow-up`,
  }));

  return documents;
}

function purchaseOrderRelatedDocuments(data, order) {
  const warehouse = ensureWarehouse(data);
  const quality = ensureQuality(data);
  const purchase = ensurePurchase(data);
  const documents = [];
  const sourceRequisitions = Array.from(new Set([
    ...(Array.isArray(order.sourceRequisitions) ? order.sourceRequisitions : []),
    order.sourceRequisition,
    ...(order.products || []).map((line) => line.sourceRequisition),
  ].filter(Boolean)));

  sourceRequisitions.forEach((code) => {
    const requisition = purchase.requisitions.find((row) => row.code === code);
    documents.push({
      type: '采购申请',
      code,
      status: requisition ? purchaseRequisitionDocumentStatus(requisition, purchaseRequisitionConversionFacts(data, requisition)) : '已关联',
      path: `/purchase/requisitions/${encodeURIComponent(code)}`,
    });
  });

  const receipts = warehouse.purchaseReceipts.filter((receipt) => receipt.sourceDoc === order.code);
  receipts.forEach((receipt) => documents.push({
    type: '采购收货',
    code: receipt.code,
    status: receipt.reversalCode ? `已冲销 · ${receipt.reversalCode}` : receipt.status || '未记录',
    path: `/warehouse/purchase-receipts/${encodeURIComponent(receipt.code)}`,
  }));
  const receiptCodes = new Set(receipts.map((receipt) => receipt.code));

  quality.incomingDocuments
    .filter((record) => receiptCodes.has(record.sourceDoc))
    .forEach((record) => documents.push({
      type: '来料质检',
      code: record.code,
      status: record.status || '未记录',
      path: `/quality/incoming/${encodeURIComponent(record.code)}`,
    }));

  purchase.afterSales
    .filter((record) => record.sourceOrder === order.code)
    .forEach((record) => documents.push({
      type: '采购售后',
      code: record.code,
      status: record.status || '未记录',
      path: `/purchase/after-sales/${encodeURIComponent(record.code)}`,
    }));

  commercialFollowUpEvents(data, 'purchase', order.code).forEach((event) => documents.push({
    type: event.kind === 'purchase_invoice' ? '收票记录' : '付款记录',
    code: event.referenceNo || event.id,
    status: money(event.amount),
    path: `/purchase/orders/${encodeURIComponent(order.code)}#commercial-follow-up`,
  }));

  return documents;
}

function withPurchaseOrderFacts(data, order) {
  const afterSalesOwner = afterSalesOwnerForSource(data, 'purchase', order);
  return {
    ...order,
    overReceiptTolerancePercent: purchaseOrderOverReceiptTolerancePercent(order),
    receiptClosures: cloneJson(order.receiptClosures || [], []),
    afterSalesOwner: afterSalesOwner?.name || '',
    afterSalesOwnerEmployeeCode: afterSalesOwner?.code || '',
    progressFacts: purchaseOrderProgressFacts(data, order),
    commercialFollowUps: commercialFollowUpEvents(data, 'purchase', order.code),
    relatedDocuments: purchaseOrderRelatedDocuments(data, order),
  };
}

function purchaseOrderLineSourceAllocations(orderLine) {
  const allocations = Array.isArray(orderLine?.sourceAllocations)
    ? orderLine.sourceAllocations
      .map((allocation) => ({
        requisitionCode: String(allocation.requisitionCode || allocation.sourceRequisition || '').trim(),
        sourceLineId: String(allocation.sourceLineId || '').trim(),
        quantity: Math.max(0, Number(allocation.quantity ?? allocation.qty ?? 0)),
        unit: String(allocation.unit || orderLine.uom || '').trim(),
        expectedDate: String(allocation.expectedDate || '').trim(),
      }))
      .filter((allocation) => allocation.requisitionCode && allocation.sourceLineId && allocation.quantity > 0)
    : [];
  if (allocations.length) return allocations;
  const requisitionCode = String(orderLine?.sourceRequisition || '').trim();
  const sourceLineId = String(orderLine?.sourceLineId || '').trim();
  if (!requisitionCode || !sourceLineId) return [];
  return [{
    requisitionCode,
    sourceLineId,
    quantity: parseQty(orderLine.qty),
    unit: String(orderLine.uom || '').trim(),
    expectedDate: '',
  }];
}

function purchaseOrderLineBelongsToRequisition(order, orderLine, requisitionCode) {
  return purchaseOrderLineSourceAllocations(orderLine)
    .some((allocation) => allocation.requisitionCode === String(requisitionCode || ''));
}

function purchaseRequisitionConversionFacts(data, requisition) {
  const purchase = ensurePurchase(data);
  const activeOrders = purchase.orders.filter((order) => (
    !['已作废', '已取消'].includes(String(order.status || ''))
    && (order.products || []).some((line) => purchaseOrderLineBelongsToRequisition(order, line, requisition.code))
  ));
  const linkedOrderCodes = activeOrders.map((order) => order.code);
  const lines = (requisition.products || []).map((line, index) => {
        const lineId = line.lineId || `L${index + 1}`;
        const requestedQty = parseQty(line.qty);
        const orderedQty = activeOrders.reduce((total, order) => total + (order.products || []).reduce((sum, orderLine) => {
          const allocatedQty = purchaseOrderLineSourceAllocations(orderLine)
            .filter((allocation) => (
              allocation.requisitionCode === requisition.code
              && allocation.sourceLineId === lineId
            ))
            .reduce((allocationSum, allocation) => allocationSum + allocation.quantity, 0);
          if (allocatedQty > 0) return sum + allocatedQty;
          const sameSource = purchaseOrderLineBelongsToRequisition(order, orderLine, requisition.code);
          const sameLine = !orderLine.sourceAllocations?.length && (orderLine.sourceLineId
            ? orderLine.sourceLineId === lineId
            : (orderLine.materialCode && line.materialCode
                ? orderLine.materialCode === line.materialCode
                : orderLine.name === line.name));
          return sameSource && sameLine ? sum + parseQty(orderLine.qty) : sum;
        }, 0), 0);
        const remainingQty = Math.max(0, requestedQty - orderedQty);
        return {
          lineId,
          materialCode: line.materialCode || '',
          name: line.name || '',
          requestedQty,
          orderedQty,
          remainingQty,
          uom: line.uom || '',
          status: orderedQty <= 0 ? '未承接' : remainingQty > 0 ? '部分承接' : '已承接',
        };
      });

  const demandLines = lines.filter((line) => line.requestedQty > 0);
  const coveredLineCount = demandLines.filter((line) => line.orderedQty > 0).length;
  const completedLineCount = demandLines.filter((line) => line.remainingQty <= 0).length;
  const status = completedLineCount === demandLines.length && demandLines.length
    ? '已转单'
    : coveredLineCount > 0
      ? '部分转单'
      : '未转单';
  const nextStep = requisition.status === '草稿'
    ? '提交采购受理'
    : status === '已转单'
      ? '跟进采购订单'
      : status === '部分转单'
        ? '继续转采购'
        : '生成采购订单';

  return { status, nextStep, linkedOrderCodes, coveredLineCount, completedLineCount, totalLineCount: demandLines.length, lines };
}

function purchaseRequisitionDocumentStatus(requisition, conversionFacts) {
  const persistedStatus = String(requisition.status || '草稿');
  if (persistedStatus === '草稿') return '草稿';
  if (['已作废', '已取消', '已驳回', '已中断'].includes(persistedStatus)) return '已作废';
  if (conversionFacts.status === '已转单') return '已关闭';
  return '已提交';
}

function withPurchaseRequisitionFacts(data, requisition) {
  const conversionFacts = purchaseRequisitionConversionFacts(data, requisition);
  return {
    ...requisition,
    documentStatus: purchaseRequisitionDocumentStatus(requisition, conversionFacts),
    conversionFacts,
  };
}

function purchaseSuggestionMaterials(data) {
  const purchase = ensurePurchase(data);
  const activeSuppliersByCode = new Map(
    ensureMasterRows(data, 'suppliers')
      .filter((supplier) => supplier.status === '启用')
      .map((supplier) => [String(supplier.code || '').trim(), supplier]),
  );
  const relationsByMaterial = new Map();
  ensureMasterRelations(data).materialSuppliers
    .filter((relation) => relation.status === '启用')
    .forEach((relation) => {
      const materialCode = String(relation.materialCode || '').trim();
      const supplierCode = String(relation.supplierCode || '').trim();
      const supplier = activeSuppliersByCode.get(supplierCode);
      if (!materialCode || !supplier) return;
      relationsByMaterial.set(materialCode, [
        ...(relationsByMaterial.get(materialCode) || []),
        {
          supplierCode,
          supplierName: String(supplier.name || relation.supplierName || supplierCode),
          supplierMaterialCode: String(relation.supplierMaterialCode || ''),
          minOrderQty: Number(relation.minOrderQty || 0),
          leadTimeDays: Number(relation.leadTimeDays || 0),
        },
      ]);
    });

  const rows = new Map();
  purchase.requisitions.forEach((requisition) => {
    const requisitionFacts = withPurchaseRequisitionFacts(data, requisition);
    if (requisitionFacts.documentStatus !== '已提交') return;
    const conversionByLine = new Map(
      (requisitionFacts.conversionFacts?.lines || []).map((line) => [String(line.lineId || ''), line]),
    );
    (requisition.products || []).forEach((sourceLine, index) => {
      const sourceLineId = String(sourceLine.lineId || `L${index + 1}`);
      const conversion = conversionByLine.get(sourceLineId);
      const remainingQty = Number(conversion?.remainingQty || 0);
      if (!(remainingQty > 0)) return;
      const material = materialMeta(data, sourceLine.materialCode, sourceLine.name);
      const materialCode = String(material.code || sourceLine.materialCode || '').trim();
      const unit = String(sourceLine.uom || material.uom || qtyUnit(sourceLine.qty) || '').trim();
      const companyCode = String(requisition.companyCode || '').trim();
      const company = String(requisition.company || '').trim();
      const companyKey = companyCode || company || 'UNASSIGNED-COMPANY';
      const key = `${companyKey}::${materialCode || sourceLine.name}::${unit}`;
      if (!rows.has(key)) {
        rows.set(key, {
          key,
          companyCode,
          company,
          materialCode,
          materialName: String(material.name || sourceLine.name || materialCode),
          model: String(material.model || sourceLine.model || ''),
          spec: String(material.spec || sourceLine.spec || ''),
          unit,
          demandQty: 0,
          orderedQty: 0,
          openQty: 0,
          earliestExpectedDate: '',
          sources: [],
        });
      }
      const row = rows.get(key);
      const requestedQty = Number(conversion?.requestedQty || parseQty(sourceLine.qty));
      const orderedQty = Number(conversion?.orderedQty || 0);
      row.demandQty += requestedQty;
      row.orderedQty += orderedQty;
      row.openQty += remainingQty;
      row.earliestExpectedDate = [
        row.earliestExpectedDate,
        String(requisition.expectedDate || ''),
      ].filter(Boolean).sort()[0] || '';
      row.sources.push({
        requisitionCode: requisition.code,
        sourceLineId,
        quantity: remainingQty,
        requestedQty,
        orderedQty,
        remainingQty,
        unit,
        expectedDate: String(requisition.expectedDate || ''),
        department: String(requisition.department || ''),
        requester: String(requisition.requester || ''),
        sourceType: String(requisition.sourceType || '手工需求'),
      });
    });
  });

  return [...rows.values()].map((row) => {
    const sources = [...row.sources].sort((a, b) => (
      String(a.expectedDate || '9999-12-31').localeCompare(String(b.expectedDate || '9999-12-31'))
      || String(a.requisitionCode).localeCompare(String(b.requisitionCode), 'zh-CN')
      || String(a.sourceLineId).localeCompare(String(b.sourceLineId), 'zh-CN')
    ));
    const suppliers = [...(relationsByMaterial.get(row.materialCode) || [])]
      .sort((a, b) => (
        String(a.supplierName).localeCompare(String(b.supplierName), 'zh-CN')
        || String(a.supplierCode).localeCompare(String(b.supplierCode), 'zh-CN')
      ))
      .map((supplier) => {
        const referenceOrderQty = Math.max(row.openQty, Number(supplier.minOrderQty || 0));
        return {
          ...supplier,
          referenceOrderQty,
          referenceSupplementQty: Math.max(0, referenceOrderQty - row.openQty),
        };
      });
    const supplierStatus = suppliers.length ? 'available' : 'no-supplier';
    return {
      ...row,
      sources,
      sourceCount: sources.length,
      supplierCount: suppliers.length,
      suppliers,
      supplierStatus,
      supplierStatusLabel: supplierStatus === 'available' ? '有可选供应商' : '未维护供应关系',
    };
  }).sort((a, b) => (
    String(a.earliestExpectedDate || '9999-12-31').localeCompare(String(b.earliestExpectedDate || '9999-12-31'))
    || String(a.materialCode).localeCompare(String(b.materialCode), 'zh-CN')
  ));
}

function resolveDocumentCompany(data, input = {}, existing = {}) {
  const companies = Array.isArray(data.masterData?.company) ? data.masterData.company : [];
  const requestedCode = String(input.companyCode || existing.companyCode || '').trim();
  const requestedName = String(input.company || existing.company || '').trim();
  const selected = companies.find((row) => row.code === requestedCode || row.name === requestedName)
    || companies.find((row) => row.status !== '停用')
    || companies[0];
  return {
    companyCode: selected?.code || requestedCode,
    company: selected?.name || requestedName,
  };
}

function resolveSalesQuoteCompanyPrintSnapshot(data, companyIdentity = {}, existing = {}) {
  const companies = Array.isArray(data.masterData?.company) ? data.masterData.company : [];
  const selected = companies.find((row) => (
    row.code === companyIdentity.companyCode || row.name === companyIdentity.company
  ));
  const sameCompany = Boolean(
    existing.companyPrintSnapshot
    && (
      existing.companyCode === companyIdentity.companyCode
      || existing.company === companyIdentity.company
    )
  );
  const existingSnapshot = sameCompany ? existing.companyPrintSnapshot : {};

  if (sameCompany) {
    return {
      name: String(existingSnapshot.name || companyIdentity.company || '').trim(),
      address: String(existingSnapshot.address || '').trim(),
      email: String(existingSnapshot.email || '').trim(),
      website: String(existingSnapshot.website || '').trim(),
    };
  }

  return {
    name: String(selected?.name || companyIdentity.company || '').trim(),
    address: String(selected?.address || '').trim(),
    email: String(selected?.email || '').trim(),
    website: String(selected?.website || '').trim(),
  };
}

function hydrateSalesQuoteCompanyPrintSnapshots(data) {
  const quotes = Array.isArray(data.sales?.quotes) ? data.sales.quotes : [];
  let changed = false;
  quotes.forEach((quote) => {
    if (quote.companyPrintSnapshot && typeof quote.companyPrintSnapshot === 'object') return;
    const companyIdentity = resolveDocumentCompany(data, quote, quote);
    Object.assign(quote, companyIdentity);
    quote.companyPrintSnapshot = resolveSalesQuoteCompanyPrintSnapshot(data, companyIdentity);
    changed = true;
  });
  return changed;
}

function resolveSalesOrderSupplierPrintSnapshot(data, ownerIdentity = {}, existing = {}) {
  const employees = Array.isArray(data.masterData?.employees) ? data.masterData.employees : [];
  const selected = employees.find((row) => (
    row.code === ownerIdentity.ownerEmployeeCode || row.name === ownerIdentity.owner
  ));
  const sameOwner = Boolean(
    existing.supplierPrintSnapshot
    && (
      existing.ownerEmployeeCode === ownerIdentity.ownerEmployeeCode
      || existing.owner === ownerIdentity.owner
    )
  );
  const existingSnapshot = sameOwner ? existing.supplierPrintSnapshot : {};
  const legacyContactInfo = String(existingSnapshot.contactInfo || '').trim();
  const legacyPhoneCandidate = legacyContactInfo.split(' · ')[0].trim();
  const legacyPhone = /\d/.test(legacyPhoneCandidate) ? legacyPhoneCandidate : '';

  if (sameOwner) {
    return {
      contact: String(existingSnapshot.contact || ownerIdentity.owner || '').trim(),
      phone: String(existingSnapshot.phone || legacyPhone || selected?.phone || '').trim(),
    };
  }

  return {
    contact: String(selected?.name || ownerIdentity.owner || '').trim(),
    phone: String(selected?.phone || '').trim(),
  };
}

function salesCustomerCompanyAddress(customer = {}) {
  const address = String(customer.address || '').trim();
  if (customer.regionType === '海外') return address;
  return [
    String(customer.province || '').trim(),
    String(customer.city || '').trim(),
    address,
  ].filter(Boolean).join('');
}

function resolveSalesOrderCustomerPrintSnapshot(data, customerIdentity = {}, existing = {}) {
  const customers = Array.isArray(data.masterData?.customers) ? data.masterData.customers : [];
  const selected = customers.find((row) => (
    row.code === customerIdentity.customerCode || row.name === customerIdentity.customer
  ));
  const sameCustomer = Boolean(
    existing.customerPrintSnapshot
    && (
      existing.customerCode === customerIdentity.customerCode
      || existing.customer === customerIdentity.customer
    )
  );
  const existingSnapshot = sameCustomer ? existing.customerPrintSnapshot : {};

  return {
    name: String(selected?.name || customerIdentity.customer || existingSnapshot.name || '').trim(),
    address: String(existingSnapshot.address || salesCustomerCompanyAddress(selected)).trim(),
    contact: String(customerIdentity.contact || existingSnapshot.contact || selected?.contact || '').trim(),
    phone: String(customerIdentity.contactPhone || existingSnapshot.phone || selected?.phone || '').trim(),
  };
}

function hydrateSalesOrderPrintSnapshots(data) {
  const orders = Array.isArray(data.sales?.orders) ? data.sales.orders : [];
  const employees = Array.isArray(data.masterData?.employees) ? data.masterData.employees : [];
  let changed = false;
  orders.forEach((order) => {
    const companyIdentity = resolveDocumentCompany(data, order, order);
    Object.assign(order, companyIdentity);
    if (!order.companyPrintSnapshot || typeof order.companyPrintSnapshot !== 'object') {
      order.companyPrintSnapshot = resolveSalesQuoteCompanyPrintSnapshot(data, companyIdentity);
      changed = true;
    }
    const ownerEmployee = employees.find((row) => (
      row.code === order.ownerEmployeeCode || row.name === order.owner
    ));
    if (!order.ownerEmployeeCode && ownerEmployee?.code) {
      order.ownerEmployeeCode = ownerEmployee.code;
      changed = true;
    }
    const supplierSnapshot = order.supplierPrintSnapshot;
    const needsSupplierSnapshot = (
      !supplierSnapshot
      || typeof supplierSnapshot !== 'object'
      || Object.prototype.hasOwnProperty.call(supplierSnapshot, 'contactInfo')
      || !Object.prototype.hasOwnProperty.call(supplierSnapshot, 'phone')
    );
    if (needsSupplierSnapshot) {
      order.supplierPrintSnapshot = resolveSalesOrderSupplierPrintSnapshot(data, {
        owner: ownerEmployee?.name || order.owner,
        ownerEmployeeCode: ownerEmployee?.code || order.ownerEmployeeCode,
      }, order);
      changed = true;
    }
    const customerSnapshot = order.customerPrintSnapshot;
    const needsCustomerSnapshot = (
      !customerSnapshot
      || typeof customerSnapshot !== 'object'
      || !Object.prototype.hasOwnProperty.call(customerSnapshot, 'address')
    );
    if (needsCustomerSnapshot) {
      order.customerPrintSnapshot = resolveSalesOrderCustomerPrintSnapshot(data, {
        customer: order.customer,
        customerCode: order.customerCode,
        contact: order.contact,
        contactPhone: order.contactPhone,
      }, order);
      changed = true;
    }
  });
  return changed;
}

function resolvePurchaseOrderBuyerPrintSnapshot(data, ownerIdentity = {}, existing = {}) {
  const employees = Array.isArray(data.masterData?.employees) ? data.masterData.employees : [];
  const selected = employees.find((row) => (
    row.code === ownerIdentity.ownerEmployeeCode || row.name === ownerIdentity.owner
  ));
  const sameOwner = Boolean(
    existing.buyerPrintSnapshot
    && (
      existing.ownerEmployeeCode === ownerIdentity.ownerEmployeeCode
      || existing.owner === ownerIdentity.owner
    )
  );
  const existingSnapshot = sameOwner ? existing.buyerPrintSnapshot : {};
  return {
    contact: String(existingSnapshot.contact || selected?.name || ownerIdentity.owner || '').trim(),
    phone: String(existingSnapshot.phone || selected?.phone || '').trim(),
  };
}

function resolvePurchaseOrderSupplierPrintSnapshot(data, supplierIdentity = {}, existing = {}) {
  const suppliers = Array.isArray(data.masterData?.suppliers) ? data.masterData.suppliers : [];
  const selected = suppliers.find((row) => (
    row.code === supplierIdentity.supplierCode || row.name === supplierIdentity.supplier
  ));
  const sameSupplier = Boolean(
    existing.supplierPrintSnapshot
    && (
      existing.supplierCode === supplierIdentity.supplierCode
      || existing.supplier === supplierIdentity.supplier
    )
  );
  const existingSnapshot = sameSupplier ? existing.supplierPrintSnapshot : {};
  return {
    name: String(existingSnapshot.name || selected?.name || supplierIdentity.supplier || '').trim(),
    address: String(existingSnapshot.address || salesCustomerCompanyAddress(selected)).trim(),
    contact: String(supplierIdentity.contact || existingSnapshot.contact || selected?.contact || '').trim(),
    phone: String(supplierIdentity.contactPhone || existingSnapshot.phone || selected?.phone || '').trim(),
  };
}

function hydratePurchaseOrderPrintSnapshots(data) {
  const orders = Array.isArray(data.purchase?.orders) ? data.purchase.orders : [];
  let changed = false;
  orders.forEach((order) => {
    const companyIdentity = resolveDocumentCompany(data, order, order);
    Object.assign(order, companyIdentity);
    if (!order.companyPrintSnapshot || typeof order.companyPrintSnapshot !== 'object') {
      order.companyPrintSnapshot = resolveSalesQuoteCompanyPrintSnapshot(data, companyIdentity);
      changed = true;
    }
    if (!order.buyerPrintSnapshot || typeof order.buyerPrintSnapshot !== 'object') {
      order.buyerPrintSnapshot = resolvePurchaseOrderBuyerPrintSnapshot(data, {
        owner: order.owner,
        ownerEmployeeCode: order.ownerEmployeeCode,
      }, order);
      changed = true;
    }
    if (!order.supplierPrintSnapshot || typeof order.supplierPrintSnapshot !== 'object') {
      order.supplierPrintSnapshot = resolvePurchaseOrderSupplierPrintSnapshot(data, {
        supplier: order.supplier,
        supplierCode: order.supplierCode,
        contact: order.contact,
        contactPhone: order.contactPhone,
      }, order);
      changed = true;
    }
  });
  return changed;
}

function hydrateDocumentCompanies(data) {
  const collections = [
    data.sales?.quotes,
    data.sales?.orders,
    data.sales?.outboundRequests,
    data.purchase?.requisitions,
    data.purchase?.orders,
    data.purchase?.afterSales,
    data.warehouse?.purchaseReceipts,
    data.warehouse?.salesIssues,
    data.finance?.salesInvoices,
    data.finance?.purchaseInvoices,
    data.finance?.receivables,
    data.finance?.payables,
  ];
  collections.forEach((rows) => {
    if (!Array.isArray(rows)) return;
    rows.forEach((row) => Object.assign(row, resolveDocumentCompany(data, row, row)));
  });
}

function wait(ms) {
  return new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
}

async function renameWithRetry(source, target) {
  const retryableCodes = new Set(['EPERM', 'EBUSY', 'EACCES']);
  for (let attempt = 0; attempt < 6; attempt += 1) {
    try {
      await rename(source, target);
      return;
    } catch (error) {
      if (!retryableCodes.has(error?.code) || attempt === 5) throw error;
      await wait(40 * (attempt + 1));
    }
  }
}

async function writeData(data) {
  data.updatedAt = new Date().toISOString();
  await mkdir(dirname(dataFile), { recursive: true });
  const tempFile = `${dataFile}.${process.pid}.${Date.now()}-${randomBytes(4).toString('hex')}.tmp`;
  await writeFile(tempFile, JSON.stringify(data, null, 2), 'utf8');
  await renameWithRetry(tempFile, dataFile);
}

async function readBody(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  if (!chunks.length) return {};

  try {
    return JSON.parse(Buffer.concat(chunks).toString('utf8'));
  } catch {
    const error = new Error('请求体不是有效 JSON');
    error.statusCode = 400;
    throw error;
  }
}

function includesKeyword(row, keyword, fields) {
  if (!keyword) return true;
  const normalized = keyword.toLowerCase();
  return fields.some((field) => String(row[field] ?? '').toLowerCase().includes(normalized));
}

function activeOnly(row, enabled) {
  return !enabled || !['停用', '已作废'].includes(row.status);
}

function normalizeLogisticsMode(value = '') {
  const legacyMap = {
    物流发运: '拼车物流',
    专车配送: '整车货运',
    送货到厂: '本厂配送',
    快递: '快递快运',
  };
  return legacyMap[value] || value || '本厂配送';
}

function referenceResponse(type, rows) {
  return {
    items: rows.map((row) => {
      if (type === 'customers') {
        const address = [row.province, row.city, row.address].filter(Boolean).join('') || row.address || '';
        return {
          id: row.code,
          code: row.code,
          name: row.name,
          primary: `${row.contact || '-'} · ${row.phone || '-'}`,
          secondary: address,
          meta: [],
          status: '',
          raw: row,
        };
      }

      if (type === 'suppliers') {
        return {
          id: row.code,
          code: row.code,
          name: row.name,
          primary: `${row.contact || '-'} · ${row.phone || '-'}`,
          secondary: row.address || row.invoiceTitle || '',
          meta: [row.type, row.paymentMethod, row.bankName].filter(Boolean),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'materials') {
        const available = row.available ? `可用 ${row.available}` : '';
        return {
          id: row.code,
          code: row.code,
          name: row.name,
          primary: [row.model, row.spec || row.category].filter(Boolean).join(' · ') || row.code,
          secondary: [`单位 ${row.uom || '-'}`, available].filter(Boolean).join(' · '),
          meta: [],
          status: '',
          raw: row,
        };
      }

      if (type === 'warehouses') {
        return {
          id: row.code,
          code: row.code,
          name: row.name,
          primary: [row.type, row.company].filter(Boolean).join(' · ') || '-',
          secondary: row.address || row.note || '',
          meta: [
            row.locationCount ? `库位 ${row.locationCount}` : '',
            row.binPrefix ? `前缀 ${row.binPrefix}` : '',
          ].filter(Boolean),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'employees') {
        return {
          id: row.code,
          code: row.code,
          name: row.name,
          primary: [row.englishName, row.owner, row.position].filter(Boolean).join(' · '),
          secondary: [row.phone, row.email].filter(Boolean).join(' · '),
          meta: [row.linkedAccount ? `账号 ${row.linkedAccount}` : ''].filter(Boolean),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'uom') {
        return {
          id: row.code,
          code: row.code,
          name: row.name,
          primary: row.englishAbbreviation ? `英文简称 ${row.englishAbbreviation}` : '',
          secondary: row.note || '',
          meta: [],
          status: row.status,
          raw: row,
        };
      }

      if (type === 'currencies') {
        return {
          id: row.code,
          code: row.code,
          name: row.name,
          primary: [row.symbol, `${row.decimalPlaces ?? 2} 位小数`].filter(Boolean).join(' · '),
          secondary: row.note || '',
          meta: [],
          status: row.status,
          raw: row,
        };
      }

      if (type === 'departments') {
        return {
          id: row.code,
          code: row.code,
          name: row.name,
          primary: row.company || row.owner || '',
          secondary: row.parentDepartment ? `上级 ${row.parentDepartment}` : row.note || '',
          meta: [],
          status: row.status,
          raw: row,
        };
      }

      if (type === 'company') {
        return {
          id: row.code,
          code: row.code,
          name: row.name,
          primary: [row.primary, row.type].filter(Boolean).join(' · '),
          secondary: row.address || '',
          meta: [row.phone, row.email].filter(Boolean).map(String),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'equipment') {
        return {
          id: row.code,
          code: row.code,
          name: row.name,
          primary: [row.brand, row.model].filter(Boolean).join(' · '),
          secondary: [row.owner, row.primary].filter(Boolean).join(' · '),
          meta: [row.serialNumber ? `出厂编号 ${row.serialNumber}` : ''].filter(Boolean),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'productionLines') {
        return {
          id: row.code,
          code: row.code,
          name: row.name,
          primary: [row.type, row.owner].filter(Boolean).join(' · '),
          secondary: [
            row.workshop,
            row.capacityValue ? `${row.capacityValue} ${row.capacityUnit || ''}`.trim() : '',
          ].filter(Boolean).join(' · '),
          meta: [row.processScope].filter(Boolean).map(String),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'purchase-orders') {
        const content = (row.products || []).map((product) => `${product.name} ${product.qty}`).join('，');
        return {
          id: row.code,
          code: row.code,
          name: `${row.code} · ${row.supplier}`,
          primary: `${row.contact || '-'} · ${row.amount || '-'}`,
          secondary: content,
          meta: [row.purchaseType, row.owner, row.expectedDate ? `预计 ${row.expectedDate}` : ''].filter(Boolean),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'purchase-requisitions') {
        const content = (row.products || []).map((product) => `${product.name} ${product.qty}`).join('，');
        return {
          id: row.code,
          code: row.code,
          name: `${row.code} · ${row.department}`,
          primary: `${row.requester || '-'} · ${row.expectedDate || '-'}`,
          secondary: content,
          meta: [row.status, row.purchaseType, row.reason].filter(Boolean),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'purchase-receipts') {
        return {
          id: row.code,
          code: row.code,
          name: `${row.code} · ${row.supplier}`,
          primary: `${row.sourceDoc || '-'} · ${row.date || '-'}`,
          secondary: (row.products || []).map((product) => `${product.name} ${product.qty}`).join('，'),
          meta: [row.status, row.warehouse, row.location].filter(Boolean),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'purchase-invoices') {
        return {
          id: row.code,
          code: row.code,
          name: `${row.code} · ${row.party}`,
          primary: `${row.sourceDoc || '-'} · ${row.totalAmount || '-'}`,
          secondary: (row.lines || []).map((line) => `${line.name} ${line.qty}`).join('，'),
          meta: [row.status, row.owner, row.dueDate ? `到期 ${row.dueDate}` : ''].filter(Boolean),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'sales-orders') {
        return {
          id: row.code,
          code: row.code,
          name: `${row.code} · ${row.customer}`,
          primary: `${row.contact || '-'} · ${row.amount || '-'}`,
          secondary: (row.products || []).map((product) => `${product.name} ${product.qty}`).join('，'),
          meta: [row.status, row.owner, row.delivery ? `交期 ${row.delivery}` : ''].filter(Boolean),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'outbound-requests') {
        return {
          id: row.code,
          code: row.code,
          name: `${row.code} · ${row.customer}`,
          primary: `${row.sourceOrder || '-'} · 交付 ${row.deliveryDate || '-'} · 发货 ${row.expectedDate || '-'}`,
          secondary: (row.products || []).map((product) => `${product.name} ${product.requestQty}`).join('，'),
          meta: [row.applicant, row.deliveryDate ? `交付 ${row.deliveryDate}` : ''].filter(Boolean),
          status: row.status,
          raw: row,
        };
      }

      if (type === 'sales-invoices') {
        return {
          id: row.code,
          code: row.code,
          name: `${row.code} · ${row.party}`,
          primary: `${row.sourceDoc || '-'} · ${row.totalAmount || '-'}`,
          secondary: (row.lines || []).map((line) => `${line.name} ${line.qty}`).join('，'),
          meta: [row.status, row.owner, row.dueDate ? `到期 ${row.dueDate}` : ''].filter(Boolean),
          status: row.status,
          raw: row,
        };
      }

      return {
        id: row.code,
        code: row.code,
        name: `${row.code} · ${row.customer}`,
        primary: `${row.contact || '-'} · ${row.amount || '-'}`,
        secondary: (row.products || []).map((product) => `${product.name} ${product.qty}`).join('；'),
        meta: [row.status, row.owner, row.validUntil ? `有效期 ${row.validUntil}` : ''].filter(Boolean),
        status: row.status,
        raw: row,
      };
    }),
    total: rows.length,
  };
}

function parseQty(value) {
  return Number(String(value ?? '').replace(/,/g, '').match(/-?\d+(\.\d+)?/)?.[0] ?? 0);
}

function parseMoney(value) {
  return Number(String(value ?? '').replace(/[^\d.-]/g, '')) || 0;
}

function money(value) {
  return `￥${Number(value || 0).toLocaleString('zh-CN', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

function isAutoGeneratedCode(value) {
  if (!value) return true;
  const code = String(value).trim();
  return code === '系统自动生成'
    || /^\?+$/.test(code)
    || /^NEW-/i.test(code)
    || /(?:^|[-_])DRAFT(?:[-_]|$)/i.test(code);
}

function qtyUnit(value) {
  return String(value || '').replace(/[\d,.\s-]/g, '').trim();
}

function qtyNumberText(value) {
  return String(value ?? '').replace(/,/g, '').match(/-?\d+(\.\d+)?/)?.[0] || '';
}

function qtyWithUnit(value, unit) {
  const qty = qtyNumberText(value);
  if (!qty) return '';
  return unit ? `${qty} ${unit}` : qty;
}

function enrichProduct(data, product = {}) {
  const material = materialMeta(data, product.materialCode, product.name);
  const uom = material.uom || product.uom || qtyUnit(product.requestQty || product.qty) || '';
  const enriched = {
    ...product,
    materialCode: product.materialCode || material.code || '',
    name: product.name || material.name || '',
    model: product.model || material.model || '',
    spec: product.spec || material.spec || '',
    uom,
    imageLabel: product.imageLabel || material.imageLabel || '',
    imageTone: product.imageTone || material.imageTone || '',
  };

  if (Object.prototype.hasOwnProperty.call(product, 'qty')) {
    enriched.qty = qtyWithUnit(product.qty, uom);
  }
  if (Object.prototype.hasOwnProperty.call(product, 'requestQty')) {
    enriched.requestQty = qtyWithUnit(product.requestQty, uom);
  }

  return enriched;
}

function enrichProducts(data, products) {
  return (Array.isArray(products) ? products : []).map((product) => enrichProduct(data, product));
}

function salesInventoryProjection(data) {
  const groups = new Map();
  ensureWarehouse(data).inventory
    .filter((row) => {
      const material = materialMeta(data, row.materialCode, row.item);
      const identity = `${row.itemType || ''} ${material.type || ''} ${material.category || ''}`.toLowerCase();
      return identity.includes('成品') || identity.includes('finished');
    })
    .forEach((row) => {
      const material = materialMeta(data, row.materialCode, row.item);
      const materialCode = row.materialCode || material.code || '';
      const uom = row.uom || material.uom || inventoryUnit(row);
      const key = `${materialCode || row.item}::${uom}`;
      groups.set(key, [...(groups.get(key) || []), row]);
    });

  return Array.from(groups.entries())
    .map(([key, rows]) => {
      const first = rows[0] || {};
      const material = materialMeta(data, first.materialCode, first.item);
      const materialCode = first.materialCode || material.code || '';
      const item = first.item || material.name || '';
      const uom = first.uom || material.uom || inventoryUnit(first);
      const sum = (numberKey, displayKey) => rows.reduce(
        (total, row) => total + inventoryNumber(row, numberKey, displayKey),
        0,
      );
      const inTransitNumber = sum('inTransitNumber', 'inTransit');
      const availableNumber = sum('availableNumber', 'available');
      const inboundPlanNumber = sum('inboundPlanNumber', 'inboundPlan');
      const outboundPlanNumber = sum('outboundPlanNumber', 'outboundPlan');
      const reservationMap = new Map();
      rows.flatMap((row) => Array.isArray(row.reservationSources) ? row.reservationSources : [])
        .filter((source) => source.type === '销售预留')
        .forEach((source) => {
          const sourceKey = `${source.sourceDoc || ''}::${source.sourceLineId || ''}::${source.status || ''}`;
          const quantityNumber = Number(source.quantityNumber ?? parseQty(source.qty));
          const current = reservationMap.get(sourceKey);
          if (!current || quantityNumber > current.quantityNumber) {
            reservationMap.set(sourceKey, {
              sourceDoc: source.sourceDoc,
              sourceLineId: source.sourceLineId,
              qty: formatQty(quantityNumber, uom),
              quantityNumber,
              status: source.status,
            });
          }
        });
      const updatedAt = rows.map((row) => String(row.updatedAt || '')).sort().at(-1) || '';

      return {
        key,
        materialCode,
        item,
        model: material.model || '',
        spec: material.spec || '',
        itemType: '成品',
        uom,
        available: formatQty(availableNumber, uom),
        inboundPlan: formatQty(inboundPlanNumber, uom),
        outboundPlan: formatQty(outboundPlanNumber, uom),
        inTransit: formatQty(inTransitNumber, uom),
        inTransitNumber,
        availableNumber,
        inboundPlanNumber,
        outboundPlanNumber,
        status: availableNumber > 0 ? '有可用库存' : inTransitNumber > 0 ? '等待在途' : '无可用库存',
        updatedAt,
        salesReservationSources: Array.from(reservationMap.values()),
      };
    })
    .sort((a, b) => `${b.updatedAt || ''}${b.item || ''}`.localeCompare(`${a.updatedAt || ''}${a.item || ''}`));
}

function enrichBusinessData(data) {
  ensureSales(data);
  ensurePurchase(data);
  ensureWarehouse(data);
  ensureFinance(data);
  ensureProduction(data);
  ensureQuality(data);

  data.sales.quotes = data.sales.quotes.map((quote) => ({ ...quote, products: enrichProducts(data, quote.products) }));
  data.sales.orders = data.sales.orders.map((order) => ({ ...order, products: enrichProducts(data, order.products) }));
  data.sales.outboundRequests = data.sales.outboundRequests.map((requestDoc) => ({
    ...requestDoc,
    products: enrichProducts(data, requestDoc.products),
  }));

  data.purchase.requisitions = data.purchase.requisitions.map((requisition) => ({
    ...requisition,
    products: enrichProducts(data, requisition.products),
  }));
  data.purchase.orders = data.purchase.orders.map((order) => ({ ...order, products: enrichProducts(data, order.products) }));

  data.warehouse.purchaseReceipts = data.warehouse.purchaseReceipts.map((receipt) => ({
    ...receipt,
    products: enrichProducts(data, receipt.products),
  }));
  data.warehouse.salesIssues = data.warehouse.salesIssues.map((issue) => ({
    ...issue,
    products: enrichProducts(data, issue.products),
  }));
  data.warehouse.otherMoves = data.warehouse.otherMoves.map((move) => ({
    ...move,
    location: otherMoveLocationProjection(data, move),
    products: enrichProducts(data, move.products),
  }));
  data.warehouse.transfers = data.warehouse.transfers.map((transfer) => ({
    ...transfer,
    toLocation:
      transfer.toLocation
      || (transfer.transitLines || [])
        .map((line) => data.warehouse.inventory.find((row) => row.key === line.targetInventoryKey)?.location)
        .find(Boolean)
      || '',
    products: enrichProducts(data, transfer.products),
  }));

  data.finance.salesInvoices = data.finance.salesInvoices.map((invoice) => ({
    ...invoice,
    lines: enrichProducts(data, invoice.lines),
  }));
  data.finance.purchaseInvoices = data.finance.purchaseInvoices.map((invoice) => ({
    ...invoice,
    lines: enrichProducts(data, invoice.lines),
  }));
  data.finance.receivables = data.finance.receivables.map((record) => ({
    ...record,
    lines: enrichProducts(data, record.lines),
  }));
  data.finance.payables = data.finance.payables.map((record) => ({
    ...record,
    lines: enrichProducts(data, record.lines),
  }));
  data.sales.orders.forEach((order) => recomputeSalesOrderProgress(data, order.code));

  return data;
}

function shanghaiDate() {
  return new Date(Date.now() + 8 * 60 * 60 * 1000).toISOString().slice(0, 10);
}

function shanghaiDateTime() {
  return new Date(Date.now() + 8 * 60 * 60 * 1000).toISOString().slice(0, 16).replace('T', ' ');
}

function requestError(statusCode, message) {
  const error = new Error(message);
  error.statusCode = statusCode;
  return error;
}

function assertRecordRevision(body, record, label) {
  const expectedRevision = Number(body?.revision);
  const currentRevision = Number(record?.revision || 1);
  if (!Number.isInteger(expectedRevision) || expectedRevision !== currentRevision) {
    throw requestError(409, `${label}已被其他用户更新，请刷新后重新操作。`);
  }
  return currentRevision;
}

