function productionQualityCheckpointRequirement(kind, name) {
  return productionQualityCheckpointRequirements[kind]?.[name]
    || `按启用质量标准检查并记录“${name}”`;
}

function ensureProductionQualityCheckpointResults(task) {
  const snapshotRules = Array.isArray(task.qualityStandardSnapshot?.checkpointRules)
    ? task.qualityStandardSnapshot.checkpointRules
    : [];
  const checkpoints = snapshotRules.length
    ? snapshotRules.map((item) => String(item?.name || '').trim()).filter(Boolean)
    : Array.isArray(task.checkpoints) ? task.checkpoints.map((item) => String(item || '').trim()).filter(Boolean) : [];
  const existing = Array.isArray(task.checkpointResults) ? task.checkpointResults : [];
  const completed = !['待检', '检验中'].includes(String(task.status || ''));
  const wholeTaskPassed = String(task.result || task.status || '') === '合格';
  task.checkpointResults = checkpoints.map((name, index) => {
    const stored = existing.find((item) => String(item?.name || '').trim() === name);
    if (stored) {
      return {
        name,
        standard: String(stored.standard || snapshotRules.find((item) => item.name === name)?.requirement || productionQualityCheckpointRequirement(task.kind, name)),
        actual: String(stored.actual || ''),
        result: String(stored.result || '待检验'),
        note: String(stored.note || ''),
      };
    }
    const historicalFailure = completed && !wholeTaskPassed && index === 0;
    return {
      name,
      standard: snapshotRules.find((item) => item.name === name)?.requirement || productionQualityCheckpointRequirement(task.kind, name),
      actual: wholeTaskPassed ? '' : historicalFailure ? String(task.conclusion || task.result || '') : '',
      result: wholeTaskPassed ? '合格' : historicalFailure ? '不合格' : completed ? '历史未逐项记录' : '待检验',
      note: historicalFailure ? String(task.disposition || '') : '',
    };
  });
  return task.checkpointResults;
}

function productionQualityCheckpointDecision(task, body, result) {
  const frozen = ensureProductionQualityCheckpointResults(task);
  const submitted = Array.isArray(body.checkpointResults) ? body.checkpointResults : [];
  if (!submitted.length) {
    // Compatibility for older automation clients. The current web client always submits
    // explicit item results, while legacy callers retain their historical whole-task behavior.
    return frozen.map((item, index) => ({
      ...item,
      actual: String(item.actual || ''),
      result: result === '合格' ? '合格' : index === 0 ? '不合格' : '合格',
      note: result === '合格' || index > 0 ? String(item.note || '') : String(body.conclusion || body.remark || item.note || '整单判定存在异常'),
    }));
  }
  if (submitted.length !== frozen.length) throw requestError(409, '检查项记录数量与冻结的质检标准不一致，请刷新后重试。');
  const records = frozen.map((item) => {
    const input = submitted.find((entry) => String(entry?.name || '').trim() === item.name);
    if (!input) throw requestError(409, `检查项“${item.name}”缺少判定记录，请补齐后提交。`);
    const itemResult = String(input.result || '').trim();
    if (!['合格', '不合格'].includes(itemResult)) throw requestError(409, `检查项“${item.name}”必须判定为合格或不合格。`);
    const actual = String(input.actual || '').trim();
    const note = String(input.note || '').trim();
    if (itemResult === '不合格' && !actual && !note) throw requestError(409, `检查项“${item.name}”不合格时必须填写检查记录或异常说明。`);
    return { ...item, actual, result: itemResult, note };
  });
  const abnormalCount = records.filter((item) => item.result === '不合格').length;
  if (result === '合格' && abnormalCount > 0) throw requestError(409, '存在不合格检查项时，整单不能判定合格。');
  if (result !== '合格' && abnormalCount === 0) throw requestError(409, '整单判定不合格或部分合格时，至少需要标记一个不合格检查项。');
  return records;
}

