function purchaseOrderReceiptStatus(data, orderCode) {
  const purchase = ensurePurchase(data);
  const warehouse = ensureWarehouse(data);
  const order = purchase.orders.find((row) => row.code === orderCode);
  if (!order) return undefined;

  const required = new Map();
  order.products.forEach((product) => {
    const key = product.materialCode || product.name;
    required.set(key, (required.get(key) || 0) + parseQty(product.qty));
  });

  const received = new Map();
  warehouse.purchaseReceipts
    .filter((receipt) => (
      receipt.sourceDoc === orderCode
      && receipt.sourceType !== 'purchase_after_sale'
      && receipt.status === '已入库'
      && !receipt.reversalCode
    ))
    .forEach((receipt) => {
      receipt.products.forEach((product, index) => {
        const key = product.materialCode || product.name;
        received.set(key, (received.get(key) || 0) + purchaseReceiptPostedQty(receipt, product, index));
      });
    });

  const requiredTotal = [...required.values()].reduce((sum, qty) => sum + qty, 0);
  const receivedTotal = [...received.values()].reduce((sum, qty) => sum + qty, 0);
  if (!requiredTotal || !receivedTotal) return '待入库';

  const isComplete = [...required.entries()].every(([key, qty]) => (received.get(key) || 0) >= qty);
  return isComplete ? '已完成' : '部分入库';
}

function quantityMapByProduct(products, quantityField = 'qty') {
  const quantities = new Map();
  (products || []).forEach((product) => {
    const key = product.materialCode || product.name || '';
    if (!key) return;
    quantities.set(key, (quantities.get(key) || 0) + parseQty(product[quantityField] || product.qty));
  });
  return quantities;
}

function purchaseReceiptIsPosted(receipt) {
  return receipt?.stockStage === 'posted'
    || ['已入库', '已完成'].includes(String(receipt?.status || ''));
}

function purchaseReceiptPostedQty(receipt, product, index) {
  const lineId = product.lineId || `L${index + 1}`;
  const postedLines = (receipt.postedQuantities?.lines || [])
    .filter((line) => line.receiptLineId === lineId);
  if (postedLines.length) {
    return postedLines.reduce((sum, line) => sum + Number(line.postedQty || 0), 0);
  }
  if (!purchaseReceiptIsPosted(receipt)) return 0;
  const explicitPosted = Number(product.postedQty ?? product.inboundQty);
  if (Number.isFinite(explicitPosted) && explicitPosted >= 0) return explicitPosted;
  const decisionLine = receipt.qualityDecision?.lines?.find((line) => line.receiptLineId === lineId);
  if (decisionLine) return Number(decisionLine.releasedQty || 0);
  return parseQty(product.qty);
}

function purchaseReceiptProjectionLineFacts(data, receipt, product, index) {
  const receiptLineId = product.lineId || `L${index + 1}`;
  const quantities = purchaseReceiptLineArrivalQuantities(product);
  const decisionLine = receipt.qualityDecision?.lines?.find((line) => (
    (line.receiptLineId || line.lineId) === receiptLineId
    || (line.materialCode && product.materialCode && line.materialCode === product.materialCode)
    || (!line.materialCode && !product.materialCode && line.name && line.name === product.name)
  ));
  const resolution = decisionLine
    ? incomingQualityLineResolution(data, receipt, receiptLineId, decisionLine.rejectedQty)
    : {
        releasedAdjustmentQty: 0,
        unresolvedRejectedQty: 0,
      };
  const qualityAlreadyReleased = (
    ['pending_inbound', 'posted'].includes(String(receipt.stockStage || ''))
    || ['待入库', '部分入库', '已入库'].includes(String(receipt.status || ''))
  );
  const rawReleasedQty = decisionLine
    ? Number(decisionLine.releasedQty || 0) + Number(resolution.releasedAdjustmentQty || 0)
    : !product.qcRequired || qualityAlreadyReleased
      ? quantities.accepted
      : 0;
  const releasedQty = Math.min(quantities.accepted, Math.max(0, rawReleasedQty));
  const rejectedQty = Math.min(
    Math.max(0, quantities.accepted - releasedQty),
    Math.max(0, Number(resolution.unresolvedRejectedQty || decisionLine?.rejectedQty || 0)),
  );
  const qcPendingQty = product.qcRequired
    ? Math.max(
        0,
        decisionLine?.pendingQty !== undefined
          ? Number(decisionLine.pendingQty || 0)
          : quantities.accepted - releasedQty - rejectedQty,
      )
    : 0;
  const postedQty = receipt.reversalCode
    ? 0
    : Math.max(0, purchaseReceiptPostedQty(receipt, product, index));
  const availableQty = Math.max(0, releasedQty - postedQty);
  return {
    receiptLineId,
    sourceLineId: product.sourceLineId || product.lineId || receiptLineId,
    materialCode: product.materialCode || '',
    name: product.name || product.materialCode || '未命名物料',
    model: product.model || '',
    spec: product.spec || '',
    uom: product.uom || '',
    supplierBatch: product.supplierBatch || '',
    ...quantities,
    qcPendingQty,
    releasedQty,
    rejectedQty,
    postedQty,
    availableQty,
  };
}

function purchaseReceiptProjectionScopes(data, selectedReceipt) {
  const warehouse = ensureWarehouse(data);
  const isAfterSale = selectedReceipt.sourceType === 'purchase_after_sale';
  return warehouse.purchaseReceipts.filter((receipt) => (
    receipt.sourceDoc === selectedReceipt.sourceDoc
    && (
      isAfterSale
        ? receipt.sourceType === 'purchase_after_sale'
          && receipt.sourceAfterSale === selectedReceipt.sourceAfterSale
        : receipt.sourceType !== 'purchase_after_sale'
    )
  ));
}

function purchaseInboundDetailProjection(data, selectedReceipt) {
  const isAfterSale = selectedReceipt.sourceType === 'purchase_after_sale';
  const scopeType = isAfterSale ? 'purchase_after_sale' : 'purchase_order';
  const scopeCode = isAfterSale
    ? selectedReceipt.sourceAfterSale || selectedReceipt.code
    : selectedReceipt.sourceDoc;
  const order = ensurePurchase(data).orders.find((row) => row.code === selectedReceipt.sourceDoc);
  const sourceLines = isAfterSale
    ? selectedReceipt.products || []
    : order?.products?.length
      ? order.products
      : selectedReceipt.products || [];
  const aggregateLines = sourceLines.map((product, index) => {
    const sourceLineId = product.sourceLineId || product.lineId || `L${index + 1}`;
    const limits = !isAfterSale && order
      ? purchaseOrderLineReceiptLimits(order, product, index)
      : null;
    return {
      key: sourceLineId,
      sourceLineId,
      materialCode: product.materialCode || '',
      name: product.name || product.materialCode || '未命名物料',
      model: product.model || '',
      spec: product.spec || '',
      uom: product.uom || '',
      plannedQty: limits ? limits.receiptTargetQty : Math.max(0, parseQty(product.plannedQty ?? product.qty)),
      arrivalQty: 0,
      acceptedQty: 0,
      refusedQty: 0,
      exceptionHeldQty: 0,
      qcPendingQty: 0,
      releasedQty: 0,
      rejectedQty: 0,
      postedQty: 0,
      availableQty: 0,
      remainingQty: 0,
    };
  });
  const executedReceipts = purchaseReceiptProjectionScopes(data, selectedReceipt)
    .filter((receipt) => purchaseReceiptCountsAsArrival(receipt));
  const recordFacts = executedReceipts.map((receipt) => ({
    receipt,
    lines: (receipt.products || []).map((product, index) => (
      purchaseReceiptProjectionLineFacts(data, receipt, product, index)
    )),
  }));

  recordFacts.forEach(({ lines }) => {
    lines.forEach((line) => {
      let aggregate = aggregateLines.find((candidate) => (
        candidate.sourceLineId === line.sourceLineId
      ));
      if (!aggregate && line.materialCode) {
        const materialCandidates = aggregateLines.filter((candidate) => (
          candidate.materialCode === line.materialCode
        ));
        if (materialCandidates.length === 1) aggregate = materialCandidates[0];
      }
      if (!aggregate) {
        aggregate = {
          key: line.sourceLineId || line.materialCode || `line-${aggregateLines.length + 1}`,
          sourceLineId: line.sourceLineId,
          materialCode: line.materialCode,
          name: line.name,
          model: line.model,
          spec: line.spec,
          uom: line.uom,
          plannedQty: 0,
          arrivalQty: 0,
          acceptedQty: 0,
          refusedQty: 0,
          exceptionHeldQty: 0,
          qcPendingQty: 0,
          releasedQty: 0,
          rejectedQty: 0,
          postedQty: 0,
          availableQty: 0,
          remainingQty: 0,
        };
        aggregateLines.push(aggregate);
      }
      aggregate.arrivalQty += line.arrival;
      aggregate.acceptedQty += line.accepted;
      aggregate.refusedQty += line.refused;
      aggregate.exceptionHeldQty += line.exceptionHeld;
      aggregate.qcPendingQty += line.qcPendingQty;
      aggregate.releasedQty += line.releasedQty;
      aggregate.rejectedQty += line.rejectedQty;
      aggregate.postedQty += line.postedQty;
      aggregate.availableQty += line.availableQty;
    });
  });

  aggregateLines.forEach((line) => {
    line.remainingQty = Math.max(
      0,
      line.plannedQty - line.acceptedQty - line.exceptionHeldQty,
    );
  });

  const arrivalRecords = recordFacts
    .map(({ receipt, lines }) => ({
      receiptCode: receipt.code,
      date: receipt.date || String(receipt.arrivalResult?.submittedAt || '').slice(0, 10),
      submittedAt: receipt.arrivalResult?.submittedAt || '',
      submittedBy: receipt.arrivalResult?.submittedBy
        || (receipt.owner && receipt.owner !== '待分配' ? receipt.owner : ''),
      warehouse: receipt.warehouse || '',
      location: receipt.location || '',
      sourceType: receipt.sourceType || 'purchase_order',
      sourceAfterSale: receipt.sourceAfterSale || '',
      note: receipt.note || '',
      lines: lines.map((line) => ({
        key: `${receipt.code}-${line.receiptLineId}`,
        receiptLineId: line.receiptLineId,
        sourceLineId: line.sourceLineId,
        materialCode: line.materialCode,
        name: line.name,
        model: line.model,
        spec: line.spec,
        uom: line.uom,
        supplierBatch: line.supplierBatch,
        arrivalQty: line.arrival,
        acceptedQty: line.accepted,
        refusedQty: line.refused,
        exceptionHeldQty: line.exceptionHeld,
        qcPendingQty: line.qcPendingQty,
        releasedQty: line.releasedQty,
        rejectedQty: line.rejectedQty,
        postedQty: line.postedQty,
        availableQty: line.availableQty,
      })),
    }))
    .sort((left, right) => (
      `${right.submittedAt || right.date}${right.receiptCode}`
        .localeCompare(`${left.submittedAt || left.date}${left.receiptCode}`)
    ));

  return {
    scopeType,
    scopeCode,
    sourceOrderReceiving: {
      expectedDate: order?.expectedDate || selectedReceipt.expectedDate || '',
      deliveryMethod: order?.deliveryMethod || '',
      warehouseCode: order?.warehouseCode || '',
      warehouse: order?.warehouse || '',
      receivingAddress: order?.receivingAddress || '',
      receivingContact: order?.receivingContact || '',
      receivingPhone: order?.receivingPhone || '',
    },
    aggregateLines,
    arrivalRecords,
  };
}

function formatMovementQty(data, product, qty) {
  const unit = materialMeta(data, product.materialCode, product.name).uom || product.uom || '';
  return formatQty(qty, unit);
}

function assertPurchaseReceiptWithinOrder(data, receipt) {
  if (!receipt.sourceDoc || receipt.sourceType === 'purchase_after_sale') return;

  const purchase = ensurePurchase(data);
  const warehouse = ensureWarehouse(data);
  const order = purchase.orders.find((row) => row.code === receipt.sourceDoc);
  if (!order) return;

  const ordered = quantityMapByProduct(order.products);
  const received = new Map();
  warehouse.purchaseReceipts
    .filter((row) => (
      row.sourceDoc === receipt.sourceDoc
      && row.sourceType !== 'purchase_after_sale'
      && row.status === '已入库'
      && !row.reversalCode
      && row.code !== receipt.code
    ))
    .forEach((row) => {
      row.products.forEach((product, index) => {
        const key = product.materialCode || product.name || '';
        if (!key) return;
        received.set(key, (received.get(key) || 0) + purchaseReceiptPostedQty(row, product, index));
      });
    });

  (receipt.products || []).forEach((product, index) => {
    const key = product.materialCode || product.name || '';
    if (!key) return;
    if (!ordered.has(key)) {
      throw requestError(409, `${product.name || product.materialCode} 不在采购订单 ${receipt.sourceDoc} 的明细中，不能入库。`);
    }

    const alreadyReceived = received.get(key) || 0;
    const currentQty = purchaseReceiptPostedQty(receipt, product, index);
    const requiredQty = ordered.get(key) || 0;
    const tolerancePercent = purchaseOrderOverReceiptTolerancePercent(order);
    const maximumQty = requiredQty * (1 + tolerancePercent / 100);
    if (alreadyReceived + currentQty > maximumQty + 0.0001) {
      const remainingQty = Math.max(0, maximumQty - alreadyReceived);
      throw requestError(
        409,
        `${product.name || product.materialCode} 入库数量超过采购订单 ${tolerancePercent}% 超收容差，最多还可入库 ${formatMovementQty(data, product, remainingQty)}，本次 ${formatMovementQty(data, product, currentQty)}。`,
      );
    }
  });
}

