function nextSalesIssueCode(data, issues) {
  return nextDocumentCode(data, 'warehouse-sales-issues', issues, 'WS');
}

function businessLineId(line, index) {
  return String(line?.sourceLineId || line?.lineId || `L${index + 1}`).trim();
}

function salesTrackingLines(tracking, order) {
  return (tracking?.products || []).map((line, index) => ({
    ...line,
    sourceLineId: String(
      line.sourceLineId
      || order?.products?.[index]?.lineId
      || order?.products?.[index]?.sourceLineId
      || `L${index + 1}`,
    ).trim(),
  }));
}

function salesIssueSourceLine(lines, product, index) {
  const requestedLineId = String(product?.sourceLineId || '').trim();
  if (requestedLineId) {
    return lines.find((line, lineIndex) => businessLineId(line, lineIndex) === requestedLineId);
  }

  const matches = lines.filter((line) => (
    product?.materialCode && line.materialCode
      ? product.materialCode === line.materialCode
      : product?.name && line.name === product.name
  ));
  if (matches.length === 1) return matches[0];

  const positional = lines[index];
  if (!positional) return undefined;
  const sameProduct = product?.materialCode && positional.materialCode
    ? product.materialCode === positional.materialCode
    : product?.name && positional.name === product.name;
  return sameProduct ? positional : undefined;
}

function normalizeSalesIssue(input, existing, data) {
  const warehouse = ensureWarehouse(data);
  const code =
    !isAutoGeneratedCode(input.code)
      ? String(input.code)
      : existing?.code || nextSalesIssueCode(data, warehouse.salesIssues);
  const sales = ensureSales(data);
  const sourceTrackingCode = existing?.sourceDoc || input.sourceDoc || '';
  const tracking = sales.outboundRequests.find((row) => row.code === sourceTrackingCode);
  const orderCode = tracking?.sourceOrder || input.sourceOrder || existing?.sourceOrder || '';
  const order = sales.orders.find((row) => row.code === orderCode);
  const sourceLines = tracking ? salesTrackingLines(tracking, order) : (order?.products || []);
  const products = Array.isArray(input.products) && input.products.length ? input.products : [];
  const normalizedProducts = products.map((product, index) => {
    const sourceLine = salesIssueSourceLine(sourceLines, product, index);
    if (tracking && String(product.sourceLineId || '').trim() && !sourceLine) {
      throw requestError(
        409,
        `${product.name || product.materialCode || `第 ${index + 1} 行`} 未关联交付追踪 ${tracking.code} 的有效明细行。`,
      );
    }
    const sourceLineIndex = sourceLine ? sourceLines.indexOf(sourceLine) : -1;
    const sourceLineId = sourceLine
      ? businessLineId(sourceLine, sourceLineIndex)
      : String(product.sourceLineId || '').trim();
    const existingProduct = existing?.products?.find((row) => (
      (product.lineId && row.lineId === product.lineId)
      || (sourceLineId && row.sourceLineId === sourceLineId)
    ));
    const enriched = enrichProduct(data, sourceLine || product);
    const controls = materialControlSnapshot(data, enriched, existingProduct);
    return {
      lineId: product.lineId || existingProduct?.lineId || `${code}-L${index + 1}`,
      sourceLineId,
      materialCode: enriched.materialCode,
      name: enriched.name,
      model: enriched.model,
      spec: enriched.spec,
      taskQty: product.taskQty || existingProduct?.taskQty || product.qty || '',
      qty: Object.prototype.hasOwnProperty.call(product, 'qty') ? String(product.qty || '') : existingProduct?.qty || '',
      batch: controls.batchTracked ? product.batch || '' : '',
      ...controls,
      uom: enriched.uom,
      imageLabel: enriched.imageLabel,
      imageTone: enriched.imageTone,
    };
  });
  return {
    ...(existing || {}),
    code,
    ...resolveDocumentCompany(data, {
      companyCode: tracking?.companyCode || order?.companyCode || input.companyCode,
      company: tracking?.company || order?.company || input.company,
    }, existing),
    sourceDoc: tracking?.code || input.sourceDoc || existing?.sourceDoc || '',
    sourceOrder: orderCode,
    customerCode: tracking?.customerCode || order?.customerCode || input.customerCode || '',
    customer: tracking?.customer || order?.customer || input.customer || '',
    contact: tracking?.contact || order?.contact || input.contact || '',
    contactPhone: tracking?.contactPhone || order?.contactPhone || input.contactPhone || '',
    address: tracking?.address || order?.shipAddress || existing?.address || input.address || '',
    products: normalizedProducts,
    // 任务头不限制单一仓库；登记拣货时按实际库存逐行选择仓库、库位和批次。
    warehouseCode: existing?.warehouseCode || '',
    warehouse: existing?.warehouse || '',
    deliveryMethod: tracking?.deliveryMethod || input.deliveryMethod || existing?.deliveryMethod || '',
    supplementaryRequirement: tracking?.supplementaryRequirement || tracking?.remark || existing?.supplementaryRequirement || existing?.sourceRemark || '',
    sourceRemark: tracking?.supplementaryRequirement || tracking?.remark || existing?.supplementaryRequirement || existing?.sourceRemark || '',
    owner: existing?.owner || '待分配',
    status: existing?.status || '待拣货',
    date: Object.prototype.hasOwnProperty.call(input, 'date') ? String(input.date || '') : existing?.date || '',
    expectedDate: tracking?.expectedDate || input.expectedDate || existing?.expectedDate || '',
    note: Object.prototype.hasOwnProperty.call(input, 'note') ? String(input.note || '') : existing?.note || '',
    attachments: Array.isArray(input.attachments) ? input.attachments : existing?.attachments || [],
  };
}

function appendSalesIssueFlow(data, code, action, remark, actor = '待分配') {
  const warehouse = ensureWarehouse(data);
  warehouse.salesIssueFlowRecords[code] = [
    ...(warehouse.salesIssueFlowRecords[code] || []),
    { time: shanghaiDateTime(), actor, action, remark },
  ];
}

function ensureSalesIssueTaskForTracking(data, tracking, actor = tracking?.applicant || '销售交付') {
  if (!tracking?.code || ['草稿', '已出库', '已发完', '按实发完成', '已签收', '已完成', '已作废'].includes(String(tracking.status || ''))) {
    return { task: null, created: false };
  }

  const warehouse = ensureWarehouse(data);
  const existing = warehouse.salesIssues.find((issue) => (
    issue.sourceDoc === tracking.code
    && !issue.reversalCode
    && !['已出库', '已作废', '已中断', '已取消'].includes(String(issue.status || ''))
  ));

  const fulfillment = shipmentTrackingFulfillment(data, tracking);
  if (fulfillment.isComplete || fulfillment.remaining <= 0) return { task: null, created: false };
  const order = ensureSales(data).orders.find((row) => row.code === tracking.sourceOrder);
  const sourceLines = salesTrackingLines(tracking, order);
  const remainingByLine = new Map(fulfillment.rows.map((row) => [row.key, row.remaining]));
  const products = sourceLines
    .map((line, index) => {
      const remaining = Number(remainingByLine.get(businessLineId(line, index)) || 0);
      return {
        ...line,
        sourceLineId: businessLineId(line, index),
        taskQty: remaining > 0 ? formatQty(remaining, line.uom || qtyUnit(line.requestQty || line.qty)) : '',
        qty: remaining > 0 ? formatQty(remaining, line.uom || qtyUnit(line.requestQty || line.qty)) : '',
        batch: '',
      };
    })
    .filter((line) => parseQty(line.qty) > 0);
  if (!products.length) return { task: null, created: false };
  if (existing) {
    let updated = false;
    if (
      existing.status === '待拣货'
      && !existing.pickingStartedAt
      && (!existing.owner || existing.owner === '待分配')
    ) {
      const normalizedProducts = normalizeSalesIssue({
        ...existing,
        products,
      }, existing, data).products;
      if (JSON.stringify(existing.products || []) !== JSON.stringify(normalizedProducts)) {
        existing.products = normalizedProducts;
        updated = true;
      }
    }
    return { task: existing, created: false, updated };
  }

  const task = normalizeSalesIssue({
    code: '系统自动生成',
    sourceDoc: tracking.code,
    sourceOrder: tracking.sourceOrder,
    products,
    warehouseCode: '',
    warehouse: '',
    deliveryMethod: tracking.deliveryMethod,
    address: tracking.address || '',
    owner: '待分配',
    date: '',
    expectedDate: tracking.expectedDate || '',
    supplementaryRequirement: tracking.supplementaryRequirement || tracking.remark || '',
    sourceRemark: tracking.supplementaryRequirement || tracking.remark || '',
    note: '',
    attachments: [],
  }, undefined, data);
  warehouse.salesIssues.unshift(task);
  appendSalesIssueFlow(data, task.code, '生成销售出库任务', `承接交付追踪 ${tracking.code} 的剩余发货数量，进入待拣货。`, actor);
  if (fulfillment.totalDelivered > 0) tracking.status = '部分出库';
  appendOutboundFlow(data, tracking.code, '生成仓库出库任务', `${task.code} 已自动生成，等待仓库登记拣货并复核。`, actor);
  appendBusinessNotification(data, {
    module: '销售',
    action: '交付追踪同步',
    title: '销售出库任务待拣货',
    message: `${tracking.sourceOrder || tracking.code} / ${tracking.code} 已生成 ${task.code}，请登记实际出库数量与批次。`,
    sourceDoc: task.code,
    sourcePath: `/warehouse/sales-issues/${encodeURIComponent(task.code)}`,
    actor,
  });
  return { task, created: true };
}

function ensureSalesIssueTasksForActiveTrackings(data) {
  let changed = false;
  ensureSales(data).outboundRequests.forEach((tracking) => {
    const generated = ensureSalesIssueTaskForTracking(data, tracking, '系统迁移');
    if (generated.created || generated.updated) changed = true;
  });
  return changed;
}

function assertSalesIssueWithinSource(data, issue) {
  const sales = ensureSales(data);
  const warehouse = ensureWarehouse(data);
  const tracking = issue.sourceDoc ? sales.outboundRequests.find((row) => row.code === issue.sourceDoc) : undefined;
  const order = issue.sourceOrder ? sales.orders.find((row) => row.code === issue.sourceOrder) : undefined;
  if (!tracking) throw requestError(409, `来源交付追踪 ${issue.sourceDoc || '未选择'} 不存在，不能确认出库。`);
  if (!order) throw requestError(409, `来源销售订单 ${issue.sourceOrder || tracking.sourceOrder || '未选择'} 不存在，不能确认出库。`);
  if (tracking.sourceOrder !== order.code) {
    throw requestError(409, `交付追踪 ${tracking.code} 不属于销售订单 ${order.code}，不能确认出库。`);
  }
  if (['草稿', '已作废', '已取消', '已退回', '已出库', '按实发完成', '已签收', '已完成'].includes(tracking.status)) {
    throw requestError(409, `交付追踪 ${tracking.code} 当前为${tracking.status}，不能确认新的销售出库。`);
  }

  const sourceLines = salesTrackingLines(tracking, order);
  const planned = new Map(sourceLines.map((line, index) => [
    businessLineId(line, index),
    parseQty(line.requestQty || line.qty),
  ]));
  const shipped = new Map();
  warehouse.salesIssues
    .filter((row) => (
      row.status === '已出库'
      && !row.reversalCode
      && row.code !== issue.code
      && (
        (issue.sourceDoc && row.sourceDoc === issue.sourceDoc)
        || (issue.sourceOrder && row.sourceOrder === issue.sourceOrder)
      )
    ))
    .forEach((row) => {
      row.products.forEach((product, productIndex) => {
        const legacySourceLine = salesIssueSourceLine(sourceLines, product, productIndex);
        const key = product.sourceLineId || (legacySourceLine
          ? businessLineId(legacySourceLine, sourceLines.indexOf(legacySourceLine))
          : '');
        if (!key) return;
        shipped.set(key, (shipped.get(key) || 0) + parseQty(product.qty));
      });
    });

  const seenSourceLines = new Set();
  let selectedLineCount = 0;
  (issue.products || []).forEach((product, index) => {
    const sourceLine = salesIssueSourceLine(sourceLines, product, index);
    const key = product.sourceLineId || (sourceLine
      ? businessLineId(sourceLine, sourceLines.indexOf(sourceLine))
      : '');
    if (!key || !planned.has(key)) {
      throw requestError(409, `${product.name || product.materialCode || `第 ${index + 1} 行`} 未关联交付追踪明细行，不能出库。`);
    }
    if (seenSourceLines.has(key)) {
      throw requestError(400, `交付追踪明细行 ${key} 重复，请合并为一行。`);
    }
    seenSourceLines.add(key);
    if (!planned.has(key)) {
      throw requestError(409, `${product.name || product.materialCode} 不在交付追踪 ${tracking.code} 的明细中，不能出库。`);
    }

    const alreadyShipped = shipped.get(key) || 0;
    const currentQty = parseQty(product.qty);
    const requiredQty = planned.get(key) || 0;
    if (currentQty < 0) {
      throw requestError(400, `${product.name || product.materialCode || `第 ${index + 1} 行`} 的出库数量不能小于 0。`);
    }
    if (currentQty === 0) return;
    selectedLineCount += 1;
    if (alreadyShipped + currentQty > requiredQty + 0.0001) {
      const remainingQty = Math.max(0, requiredQty - alreadyShipped);
      throw requestError(
        409,
        `${product.name || product.materialCode}（${key}）出库数量超过交付追踪剩余数量，剩余 ${formatMovementQty(data, product, remainingQty)}，本次 ${formatMovementQty(data, product, currentQty)}。`,
      );
    }
  });
  if (!selectedLineCount) {
    throw requestError(400, '本次出库至少选择一项物料并填写大于 0 的数量。');
  }
}

function assertSalesIssueHandoffReady(data, issue) {
  const missing = [];
  if (!String(issue.sourceDoc || '').trim()) missing.push('来源交付追踪');
  if (!String(issue.customer || '').trim()) missing.push('客户');
  if (!String(issue.deliveryMethod || '').trim()) missing.push('物流方式');
  if (!String(issue.contact || '').trim()) missing.push('收货人');
  if (!String(issue.contactPhone || '').trim()) missing.push('联系方式');
  if (!String(issue.address || '').trim()) missing.push('收货地址');
  if (!String(issue.expectedDate || '').trim()) missing.push('计划出库日期');
  if (!(issue.products || []).length) missing.push('出库明细');
  if (missing.length) throw requestError(400, `销售出库任务缺少${missing.join('、')}，不能继续流转。`);
}

function assertSalesIssueReadyForReview(data, issue, actionLabel = '提交销售出库复核') {
  assertSalesIssueHandoffReady(data, issue);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(issue.date || '').trim())) {
    throw requestError(400, '提交复核前请填写真实的本次出库日期。');
  }
  if (issue.date > shanghaiDate()) {
    throw requestError(400, '本次出库日期不能晚于今天。');
  }
  assertSalesIssueWithinSource(data, issue);
  assertSalesIssueStockReadyForReview(data, issue, actionLabel);
}

function salesIssueAllocationInventoryRow(warehouse, issue, product, allocation) {
  const inventoryKey = String(allocation?.inventoryKey || '').trim();
  const allocationWarehouseCode = String(allocation?.warehouseCode || '').trim();
  const allocationWarehouseName = String(allocation?.warehouse || '').trim();
  const row = inventoryKey
    ? warehouse.inventory.find((candidate) => String(candidate.key || '') === inventoryKey)
    : warehouse.inventory.find((candidate) => {
        const matchesItem = product.materialCode
          ? candidate.materialCode === product.materialCode
          : candidate.item === product.name;
        const matchesWarehouse = allocationWarehouseCode
          ? candidate.warehouseCode === allocationWarehouseCode
          : allocationWarehouseName
            ? candidate.warehouse === allocationWarehouseName
            : false;
        return matchesItem
          && matchesWarehouse
          && candidate.location === String(allocation?.location || '')
          && String(candidate.batch || '') === String(allocation?.batch || '');
      });
  if (!row) return undefined;
  const matchesItem = product.materialCode
    ? row.materialCode === product.materialCode
    : row.item === product.name;
  const matchesWarehouse = allocationWarehouseCode
    ? row.warehouseCode === allocationWarehouseCode
    : allocationWarehouseName
      ? row.warehouse === allocationWarehouseName
      : true;
  return matchesItem && matchesWarehouse ? row : undefined;
}

function normalizeSalesIssuePickingAllocations(data, issue, product, entered, productIndex) {
  const warehouse = ensureWarehouse(data);
  const rawAllocations = Array.isArray(entered?.allocations) ? entered.allocations : [];
  const allocations = [];
  const seenInventory = new Set();

  rawAllocations.forEach((allocation, allocationIndex) => {
    const quantity = parseQty(allocation?.qty);
    if (quantity <= 0) return;
    const inventoryRow = salesIssueAllocationInventoryRow(warehouse, issue, product, allocation);
    if (!inventoryRow) {
      throw requestError(
        409,
        `${product.name || product.materialCode} 的第 ${allocationIndex + 1} 条拣货位置已失效，请重新打开登记窗口。`,
      );
    }
    const allocationWarehouse = warehouseMeta(data, inventoryRow.warehouseCode, inventoryRow.warehouse);
    if (
      !allocationWarehouse.code
      || allocationWarehouse.status !== '启用'
      || allocationWarehouse.allowSalesIssue !== true
    ) {
      throw requestError(
        409,
        `仓库“${inventoryRow.warehouse || inventoryRow.warehouseCode || '-'}”当前不能承担销售出库。`,
      );
    }
    if (
      String(issue.company || '').trim()
      && String(allocationWarehouse.company || '').trim()
      && allocationWarehouse.company !== issue.company
    ) {
      throw requestError(409, `仓库“${allocationWarehouse.name}”不属于当前销售出库任务公司。`);
    }
    const inventoryIdentity = String(inventoryRow.key || [
      inventoryRow.warehouseCode || inventoryRow.warehouse,
      inventoryRow.location,
      inventoryRow.batch,
      inventoryRow.materialCode || inventoryRow.item,
    ].join('|'));
    if (seenInventory.has(inventoryIdentity)) {
      throw requestError(400, `${product.name || product.materialCode} 的同一库存位置不能重复分配。`);
    }
    seenInventory.add(inventoryIdentity);
    const unit = product.uom || inventoryRow.uom || qtyUnit(product.qty) || '件';
    allocations.push({
      allocationId: String(allocation?.allocationId || `${issue.code}-${product.lineId || product.sourceLineId || `L${productIndex + 1}`}-A${allocations.length + 1}`),
      inventoryKey: String(inventoryRow.key || ''),
      warehouseCode: String(inventoryRow.warehouseCode || ''),
      warehouse: String(inventoryRow.warehouse || ''),
      location: String(inventoryRow.location || ''),
      batch: String(inventoryRow.batch || ''),
      qty: formatQty(quantity, unit),
      uom: unit,
    });
  });

  if (parseQty(entered?.qty) > 0 && !allocations.length) {
    throw requestError(400, `${product.name || product.materialCode} 请按库位和批次填写本次拣货数量。`);
  }
  return allocations;
}

function submitSalesIssuePickingResult(data, existing, req, body = {}) {
  const idempotencyKey = String(body.idempotencyKey || '').trim();
  if (!idempotencyKey) throw requestError(400, '提交拣货结果必须提供幂等键。');
  if (existing.pickingResult?.idempotencyKey === idempotencyKey) {
    return { issue: existing, repeated: true };
  }
  if (existing.status !== '待拣货') {
    throw requestError(409, `销售出库任务 ${existing.code} 当前为${existing.status}，不能登记拣货。`);
  }

  const submittedProducts = Array.isArray(body.products) ? body.products : [];
  const submittedByLine = new Map(submittedProducts.map((product, index) => [
    String(product.sourceLineId || `L${index + 1}`),
    product,
  ]));
  const products = (existing.products || []).map((product, index) => {
    const key = String(product.sourceLineId || `L${index + 1}`);
    const entered = submittedByLine.get(key);
    if (!entered) {
      return {
        ...product,
        qty: formatQty(0, product.uom || qtyUnit(product.qty) || '件'),
        batch: '',
        allocations: [],
      };
    }
    const allocations = normalizeSalesIssuePickingAllocations(data, existing, product, entered, index);
    const quantity = allocations.reduce((sum, allocation) => sum + parseQty(allocation.qty), 0);
    const batches = [...new Set(allocations.map((allocation) => allocation.batch).filter(Boolean))];
    return {
      ...product,
      qty: formatQty(quantity, product.uom || qtyUnit(product.qty) || '件'),
      batch: batches.join(', '),
      allocations,
    };
  });
  if (!products.some((product) => parseQty(product.qty) > 0)) {
    throw requestError(400, '请至少填写一种物料的本次拣货数量。');
  }
  const actor = businessActorName(req, data);
  const submittedAt = shanghaiDateTime();
  const actualWarehouses = [...new Map(
    products
      .flatMap((product) => product.allocations || [])
      .filter((allocation) => parseQty(allocation.qty) > 0)
      .map((allocation) => [
        allocation.warehouseCode || allocation.warehouse,
        { code: allocation.warehouseCode || '', name: allocation.warehouse || '' },
      ]),
  ).values()];
  const issue = {
    ...existing,
    date: String(body.date || ''),
    products,
    actualWarehouses,
    note: String(body.note ?? existing.note ?? ''),
    attachments: Array.isArray(body.attachments) ? body.attachments : existing.attachments || [],
    owner: actor,
    status: '待复核',
    reviewSubmittedAt: submittedAt,
    reviewSubmittedBy: actor,
    pickingResult: {
      idempotencyKey,
      submittedAt,
      submittedBy: actor,
    },
  };
  assertSalesIssueReadyForReview(data, issue);
  appendSalesIssueFlow(
    data,
    issue.code,
    '提交复核',
    `${actor} 已登记本次实际出库数量、批次和作业日期，等待复核。`,
    actor,
  );
  appendBusinessAuditLog(req, data, '提交销售出库拣货结果', issue.code, '拣货结果已登记并提交复核。');
  return { issue, repeated: false };
}

function matchingInventoryRows(warehouse, issue, product) {
  return warehouse.inventory
    .filter((row) => {
      const matchesItem = product.materialCode
        ? row.materialCode === product.materialCode
        : row.item === product.name;
      const matchesWarehouse = issue.warehouseCode
        ? row.warehouseCode === issue.warehouseCode
        : issue.warehouse
          ? row.warehouse === issue.warehouse
          : true;
      const matchesLocation = !String(issue.location || '').trim()
        || row.location === String(issue.location).trim();
      const matchesBatch = !product.batch || row.batch === product.batch;
      return matchesItem && matchesWarehouse && matchesLocation && matchesBatch && parseQty(row.available) > 0;
    })
    .sort((a, b) => `${a.batch || ''}`.localeCompare(`${b.batch || ''}`));
}

function reservationMatchesSalesIssue(source, issue, product) {
  const sourceOrder = String(issue.sourceOrder || '').trim();
  if (!sourceOrder || source.sourceDoc !== sourceOrder) return false;
  if (product.sourceLineId && source.sourceLineId && product.sourceLineId !== source.sourceLineId) return false;
  return !['已释放', '已作废', '已消耗'].includes(source.status);
}

function matchingSalesIssueInventoryRows(warehouse, issue, product) {
  return warehouse.inventory
    .filter((row) => {
      const matchesItem = product.materialCode
        ? row.materialCode === product.materialCode
        : row.item === product.name;
      const matchesWarehouse = issue.warehouseCode
        ? row.warehouseCode === issue.warehouseCode
        : issue.warehouse
          ? row.warehouse === issue.warehouse
          : true;
      const hasExactAllocations = Array.isArray(product.allocations) && product.allocations.length > 0;
      const matchesBatch = hasExactAllocations || !product.batch || row.batch === product.batch;
      if (!matchesItem || !matchesWarehouse || !matchesBatch) return false;
      const reservedForIssue = (row.reservationSources || [])
        .filter((source) => reservationMatchesSalesIssue(source, issue, product))
        .reduce((sum, source) => sum + Number(source.quantityNumber || parseQty(source.qty)), 0);
      return Number(row.availableNumber || parseQty(row.available)) + reservedForIssue > 0;
    })
    .sort((a, b) => {
      const aReserved = (a.reservationSources || []).some((source) => reservationMatchesSalesIssue(source, issue, product));
      const bReserved = (b.reservationSources || []).some((source) => reservationMatchesSalesIssue(source, issue, product));
      if (aReserved !== bReserved) return aReserved ? -1 : 1;
      return `${a.batch || ''}`.localeCompare(`${b.batch || ''}`);
    });
}

function salesIssueDispatchableQuantity(row, issue, product) {
  const reservedForIssue = (row.reservationSources || [])
    .filter((source) => reservationMatchesSalesIssue(source, issue, product))
    .reduce((sum, source) => sum + Number(source.quantityNumber || parseQty(source.qty)), 0);
  const onHand = Number(row.onHandNumber || parseQty(row.onHand));
  return Math.max(0, Math.min(onHand, Number(row.availableNumber || parseQty(row.available)) + reservedForIssue));
}

function assertSalesIssueInventoryWarehouseEligible(data, issue, inventoryRow, actionLabel) {
  const allocationWarehouse = warehouseMeta(data, inventoryRow.warehouseCode, inventoryRow.warehouse);
  if (
    !allocationWarehouse.code
    || allocationWarehouse.status !== '启用'
    || allocationWarehouse.allowSalesIssue !== true
  ) {
    throw requestError(
      409,
      `${actionLabel}失败：仓库“${inventoryRow.warehouse || inventoryRow.warehouseCode || '-'}”当前不能承担销售出库。`,
    );
  }
  if (
    String(issue.company || '').trim()
    && String(allocationWarehouse.company || '').trim()
    && allocationWarehouse.company !== issue.company
  ) {
    throw requestError(409, `${actionLabel}失败：仓库“${allocationWarehouse.name}”不属于当前销售出库任务公司。`);
  }
}

function assertSalesIssueStockReadyForReview(data, issue, actionLabel = '提交销售出库复核') {
  const warehouse = ensureWarehouse(data);
  const allocatedDemandByInventory = new Map();
  (issue.products || []).forEach((product) => {
    const requestedQty = parseQty(product.qty);
    if (requestedQty <= 0) return;
    const allocations = Array.isArray(product.allocations)
      ? product.allocations.filter((allocation) => parseQty(allocation.qty) > 0)
      : [];
    if (allocations.length) {
      const allocatedQty = allocations.reduce((sum, allocation) => {
        const inventoryRow = salesIssueAllocationInventoryRow(warehouse, issue, product, allocation);
        if (!inventoryRow) {
          throw requestError(
            409,
            `${product.name || product.materialCode} 的拣货位置已失效，请退回拣货后重新登记。`,
          );
        }
        assertSalesIssueInventoryWarehouseEligible(data, issue, inventoryRow, actionLabel);
        assertInventoryRowNotStocktakeFrozen(inventoryRow, actionLabel);
        const quantity = parseQty(allocation.qty);
        const dispatchableQty = salesIssueDispatchableQuantity(inventoryRow, issue, product);
        if (quantity > dispatchableQty + 0.0001) {
          throw requestError(
            409,
            `${product.name || product.materialCode} 在 ${inventoryRow.warehouse || '-'} / ${inventoryRow.location || '-'} / ${inventoryRow.batch || '无需批次'} 当前可供 ${formatMovementQty(data, product, dispatchableQty)}，本次分配 ${formatMovementQty(data, product, quantity)}。`,
          );
        }
        const inventoryIdentity = String(inventoryRow.key || [
          inventoryRow.warehouseCode || inventoryRow.warehouse,
          inventoryRow.location,
          inventoryRow.batch,
          inventoryRow.materialCode || inventoryRow.item,
        ].join('|'));
        const demand = allocatedDemandByInventory.get(inventoryIdentity) || {
          row: inventoryRow,
          quantity: 0,
          products: [],
        };
        demand.quantity += quantity;
        demand.products.push(product);
        allocatedDemandByInventory.set(inventoryIdentity, demand);
        return sum + quantity;
      }, 0);
      if (Math.abs(allocatedQty - requestedQty) > 0.0001) {
        throw requestError(
          400,
          `${product.name || product.materialCode} 的拣货分配合计与本次出库数量不一致。`,
        );
      }
      return;
    }
    const candidates = matchingSalesIssueInventoryRows(warehouse, issue, product);
    candidates.forEach((row) => assertSalesIssueInventoryWarehouseEligible(data, issue, row, actionLabel));
    const frozenCandidate = candidates.find((row) => activeStocktakeFreeze(row));
    if (frozenCandidate) assertInventoryRowNotStocktakeFrozen(frozenCandidate, actionLabel);
    const dispatchableQty = candidates.reduce(
      (sum, row) => sum + salesIssueDispatchableQuantity(row, issue, product),
      0,
    );
    if (dispatchableQty + 0.0001 < requestedQty) {
      throw requestError(
        409,
        `${product.name || product.materialCode} 当前可拣 ${formatMovementQty(data, product, dispatchableQty)}，本次登记 ${formatMovementQty(data, product, requestedQty)}，请调整数量后再提交复核。`,
      );
    }
  });
  allocatedDemandByInventory.forEach(({ row, quantity, products }) => {
    const available = Number(row.availableNumber || parseQty(row.available));
    const onHand = Number(row.onHandNumber || parseQty(row.onHand));
    const issueReserved = (row.reservationSources || [])
      .filter((source) => products.some((product) => reservationMatchesSalesIssue(source, issue, product)))
      .reduce((sum, source) => sum + Number(source.quantityNumber || parseQty(source.qty)), 0);
    const dispatchableQty = Math.max(0, Math.min(onHand, available + issueReserved));
    if (quantity > dispatchableQty + 0.0001) {
      throw requestError(
        409,
        `${row.item} 在 ${row.warehouse || '-'} / ${row.location || '-'} / ${row.batch || '无需批次'} 的多行分配合计超过当前可供数量。`,
      );
    }
  });
}

function consumeSalesReservation(row, issue, product, quantity, unit, now) {
  let remaining = quantity;
  row.reservationSources ||= [];
  row.reservationSources.forEach((source) => {
    if (remaining <= 0 || !reservationMatchesSalesIssue(source, issue, product)) return;
    const reservedQty = Number(source.quantityNumber || parseQty(source.qty));
    const consumedQty = Math.min(remaining, reservedQty);
    const remainingReserved = Math.max(0, reservedQty - consumedQty);
    source.originalQuantityNumber ??= reservedQty;
    source.consumedQuantityNumber = Number(source.consumedQuantityNumber || 0) + consumedQty;
    source.quantityNumber = remainingReserved;
    source.qty = formatQty(remainingReserved, unit);
    source.status = remainingReserved > 0 ? '部分消耗' : '已消耗';
    source.consumedBy = issue.code;
    source.consumedAt = now;
    remaining -= consumedQty;
  });
  row.reservedNumber = row.reservationSources
    .filter((source) => !['已释放', '已作废', '已消耗'].includes(source.status))
    .reduce((sum, source) => sum + Number(source.quantityNumber || parseQty(source.qty)), 0);
  return quantity - remaining;
}

function consumeSalesIssueReservationsAcrossInventory(warehouse, issue, product, quantity, unit, now) {
  let remaining = quantity;
  warehouse.inventory
    .filter((row) => (
      product.materialCode
        ? row.materialCode === product.materialCode
        : row.item === product.name
    ))
    .forEach((row) => {
      if (remaining <= 0) return;
      const consumed = consumeSalesReservation(row, issue, product, remaining, unit, now);
      if (consumed <= 0) return;
      remaining -= consumed;
      refreshInventoryFactRow(row, row.uom || unit);
      row.updatedAt = now;
    });
  return quantity - remaining;
}

function applySalesIssueInventoryDeduction(
  warehouse,
  issue,
  product,
  inventoryRow,
  deductQty,
  unit,
  actor,
  now,
) {
  const onHand = Number(inventoryRow.onHandNumber || parseQty(inventoryRow.onHand));
  inventoryRow.onHandNumber = Math.max(0, onHand - deductQty);
  inventoryRow.qualifiedOnHandNumber = Math.max(
    0,
    inventoryNumber(inventoryRow, 'qualifiedOnHandNumber', 'qualifiedOnHand') - deductQty,
  );
  refreshInventoryFactRow(inventoryRow, unit);
  inventoryRow.status = inventoryRow.availableNumber <= 0 ? '不足' : '正常';
  inventoryRow.lastMovement = `销售出库 ${issue.code}`;
  inventoryRow.updatedAt = now;
  appendStockLedgerFact(
    warehouse,
    inventoryRow,
    product,
    -deductQty,
    unit,
    issue.code,
    '销售出库',
    actor,
    now,
    {
      movement: '出库',
      beforeBalanceNumber: onHand,
      afterBalanceNumber: inventoryNumber(inventoryRow, 'onHandNumber', 'onHand'),
    },
  );
}

function applySalesIssueToStock(data, issue, actor) {
  const warehouse = ensureWarehouse(data);
  const now = shanghaiDateTime();
  assertSalesIssueStockReadyForReview(data, issue, '确认销售出库');

  issue.products.forEach((product, index) => {
    product.lineId ||= `${issue.code}-L${index + 1}`;
    let remaining = parseQty(product.qty);
    if (!remaining) return;

    const unit = materialMeta(data, product.materialCode, product.name).uom
      || product.uom
      || String(product.qty || '').replace(/[\d,.\s-]/g, '').trim()
      || '件';
    // Release this sales issue's reservation before reducing qualified stock.
    // Otherwise a fully reserved row is validated in a transient state where
    // stock has already been deducted but the matching reservation still exists.
    consumeSalesIssueReservationsAcrossInventory(
      warehouse,
      issue,
      product,
      remaining,
      unit,
      now,
    );
    const usedBatches = [];
    const allocations = Array.isArray(product.allocations)
      ? product.allocations.filter((allocation) => parseQty(allocation.qty) > 0)
      : [];

    if (allocations.length) {
      allocations.forEach((allocation) => {
        const inventoryRow = salesIssueAllocationInventoryRow(warehouse, issue, product, allocation);
        if (!inventoryRow) {
          throw requestError(409, `${product.name || product.materialCode} 的拣货位置已失效。`);
        }
        const deductQty = parseQty(allocation.qty);
        applySalesIssueInventoryDeduction(
          warehouse,
          issue,
          product,
          inventoryRow,
          deductQty,
          unit,
          actor,
          now,
        );
        remaining -= deductQty;
        if (inventoryRow.batch) usedBatches.push(inventoryRow.batch);
      });
    } else {
      for (const inventoryRow of matchingSalesIssueInventoryRows(warehouse, issue, product)) {
        if (remaining <= 0) break;
        const onHand = Number(inventoryRow.onHandNumber || parseQty(inventoryRow.onHand));
        const available = Number(inventoryRow.availableNumber || parseQty(inventoryRow.available));
        const reservedForIssue = (inventoryRow.reservationSources || [])
          .filter((source) => reservationMatchesSalesIssue(source, issue, product))
          .reduce((sum, source) => sum + Number(source.quantityNumber || parseQty(source.qty)), 0);
        const deductQty = Math.min(remaining, available + reservedForIssue, onHand);
        if (!deductQty) continue;
        applySalesIssueInventoryDeduction(
          warehouse,
          issue,
          product,
          inventoryRow,
          deductQty,
          unit,
          actor,
          now,
        );
        remaining -= deductQty;
        if (inventoryRow.batch) usedBatches.push(inventoryRow.batch);
      }
    }

    issue.products[index] = {
      ...issue.products[index],
      batch: [...new Set(usedBatches)].join(', '),
    };
  });
}

function nextWarehouseDocumentCode(data, rows, prefix) {
  const ruleKey =
    prefix === 'OM'
      ? 'warehouse-other-moves'
      : prefix === 'TR'
        ? 'warehouse-transfers'
        : prefix === 'ST'
          ? 'warehouse-stocktakes'
          : `warehouse-${prefix.toLowerCase()}`;
  return nextDocumentCode(data, ruleKey, rows, prefix);
}

function isSystemGeneratedCode(value, prefix) {
  if (!value) return true;
  const code = String(value);
  return code === '系统自动生成' || /^\?+$/.test(code) || !code.startsWith(`${prefix}-`);
}

function normalizeWarehouseProducts(data, products, documentCode) {
  return (Array.isArray(products) && products.length ? products : []).map((product, index) => {
    const enriched = enrichProduct(data, product);
    const material = materialMeta(data, enriched.materialCode, enriched.name);
    const controls = materialControlSnapshot(data, enriched, product);
    return {
      lineId: product.lineId || `${documentCode}-L${index + 1}`,
      sourceLineId: product.sourceLineId || '',
      materialCode: material.code || enriched.materialCode,
      name: material.name || enriched.name,
      model: material.model || enriched.model,
      spec: material.spec || enriched.spec,
      qty: enriched.qty || '',
      batch: controls.batchTracked ? product.batch || '' : '',
      ...controls,
      uom: material.uom || enriched.uom,
      imageLabel: material.imageLabel || enriched.imageLabel,
      imageTone: material.imageTone || enriched.imageTone,
      inventoryKey: product.inventoryKey || '',
      plannedQty: product.plannedQty == null ? undefined : Number(product.plannedQty),
      postedQty: product.postedQty == null ? undefined : Number(product.postedQty),
    };
  });
}

function normalizeStocktakeLines(lines, existingLines = []) {
  const frozenLines = Array.isArray(existingLines) ? existingLines : [];
  const incomingLines = Array.isArray(lines) ? lines : [];
  return frozenLines.map((existing) => {
    const line = incomingLines.find((row) => row.inventoryKey === existing.inventoryKey) || existing;
    const countedValue = line.countedQty === '' || line.countedQty == null ? null : Number(line.countedQty);
    if (countedValue != null && (!Number.isFinite(countedValue) || countedValue < 0)) {
      throw requestError(400, `${existing.item || existing.materialCode || '盘点行'}的实盘数量必须是大于或等于 0 的数字。`);
    }
    const bookQty = Number(existing.bookQty || 0);
    const countedQty = Number.isFinite(countedValue) ? countedValue : null;
    return {
      ...existing,
      bookQty,
      countedQty,
      differenceQty: countedQty == null ? 0 : countedQty - bookQty,
      frozenQty: Number(existing.frozenQty || 0),
    };
  });
}

function appendOtherMoveFlow(data, code, action, remark, actor = '王倩') {
  const warehouse = ensureWarehouse(data);
  warehouse.otherMoveFlowRecords[code] = [
    ...(warehouse.otherMoveFlowRecords[code] || []),
    { time: shanghaiDateTime(), actor, action, remark },
  ];
}

function appendTransferFlow(data, code, action, remark, actor = '王倩') {
  const warehouse = ensureWarehouse(data);
  warehouse.transferFlowRecords[code] = [
    ...(warehouse.transferFlowRecords[code] || []),
    { time: shanghaiDateTime(), actor, action, remark },
  ];
}

function appendStocktakeFlow(data, code, action, remark, actor = '王倩') {
  const warehouse = ensureWarehouse(data);
  warehouse.stocktakeFlowRecords[code] = [
    ...(warehouse.stocktakeFlowRecords[code] || []),
    { time: shanghaiDateTime(), actor, action, remark },
  ];
}

function warehouseMeta(data, code, name) {
  return ensureMasterRows(data, 'warehouses').find((row) => row.code === code || row.name === name) || {};
}

function warehouseLocationOptions(data, warehouseOrCode, warehouseName = '') {
  const meta = typeof warehouseOrCode === 'object'
    ? warehouseOrCode
    : warehouseMeta(data, warehouseOrCode, warehouseName);
  if (!meta?.code && !meta?.name) return [];
  const matches = (code, name) => (
    (meta.code && code === meta.code)
    || (!meta.code && meta.name && name === meta.name)
  );
  const locations = new Set(
    (Array.isArray(meta.locationOptions) ? meta.locationOptions : [])
      .map((value) => String(value || '').trim())
      .filter(Boolean),
  );
  const warehouse = ensureWarehouse(data);
  [...(warehouse.inventory || []), ...(warehouse.stockLedger || [])].forEach((row) => {
    if (matches(row.warehouseCode, row.warehouse) && String(row.location || '').trim()) {
      locations.add(String(row.location).trim());
    }
  });
  (warehouse.purchaseReceipts || []).forEach((receipt) => {
    if (matches(receipt.warehouseCode, receipt.warehouse) && String(receipt.location || '').trim()) {
      locations.add(String(receipt.location).trim());
    }
    (receipt.products || []).forEach((product) => {
      if (
        matches(product.destinationWarehouseCode, product.destinationWarehouse)
        && String(product.destinationLocation || '').trim()
      ) locations.add(String(product.destinationLocation).trim());
    });
    (receipt.postedQuantities?.lines || []).forEach((line) => {
      if (matches(line.warehouseCode, line.warehouse) && String(line.location || '').trim()) {
        locations.add(String(line.location).trim());
      }
    });
  });

  const locationCount = Math.max(0, Number(meta.locationCount || 0));
  const prefix = String(meta.binPrefix || '').trim().toUpperCase();
  if (locationCount === 1 && prefix) locations.add(`${prefix}-AUTO`);
  if (locationCount > 1 && prefix) {
    for (let index = 1; index <= locationCount; index += 1) {
      locations.add(`${prefix}-${String(index).padStart(2, '0')}`);
    }
  }
  return Array.from(locations).sort((left, right) => left.localeCompare(right, 'zh-CN', { numeric: true }));
}

function isPlaceholderWarehouseLocation(location) {
  const value = String(location || '').trim();
  return value === '默认库位' || /-AUTO$/i.test(value);
}

function productionReceiptLocationOptions(data, warehouseOrCode, warehouseName = '') {
  return warehouseLocationOptions(data, warehouseOrCode, warehouseName)
    .filter((location) => !isPlaceholderWarehouseLocation(location));
}

function assertProductionReceiptDestination(data, receipt) {
  const targetWarehouse = warehouseMeta(data, receipt.targetWarehouseCode, receipt.targetWarehouse);
  if (!targetWarehouse.code) throw requestError(400, '请选择有效的成品入库仓。');
  if (targetWarehouse.status && targetWarehouse.status !== '启用') {
    throw requestError(409, `成品入库仓 ${targetWarehouse.name} 当前未启用。`);
  }
  if (targetWarehouse.allowProductionReceipt !== true) {
    throw requestError(409, `仓库 ${targetWarehouse.name} 不允许办理完工入库。`);
  }
  const location = String(receipt.targetLocation || '').trim();
  if (!location) throw requestError(400, '请选择成品入库仓中的目标库位。');
  if (isPlaceholderWarehouseLocation(location)) {
    throw requestError(400, `完工入库不能使用占位库位 ${location}，请从正式库位列表选择。`);
  }
  const locationOptions = productionReceiptLocationOptions(data, targetWarehouse);
  if (!locationOptions.length) {
    throw requestError(409, `成品入库仓 ${targetWarehouse.name} 尚未维护正式库位，不能办理完工入库。`);
  }
  if (!locationOptions.includes(location)) {
    throw requestError(400, `目标库位 ${location} 不属于成品入库仓 ${targetWarehouse.name}，请从库位列表选择。`);
  }
  return { targetWarehouse, location };
}

function materialMeta(data, code, name) {
  return (data.masterData?.materials || []).find((row) => row.code === code || row.name === name) || {};
}

function materialControlSnapshot(data, product = {}, existing = {}) {
  const material = materialMeta(data, product.materialCode || existing.materialCode, product.name || existing.name);
  const batchControl = String(
    existing.batchControl
    || product.batchControl
    || material.batchControl
    || '不追踪批次',
  ).trim();
  return {
    batchControl,
    batchTracked: typeof existing.batchTracked === 'boolean'
      ? existing.batchTracked
      : typeof product.batchTracked === 'boolean'
        ? product.batchTracked
        : batchControl === '批次管理',
    shelfLife: String(existing.shelfLife || product.shelfLife || material.shelfLife || '无效期要求').trim(),
    incomingQualityControl: String(
      existing.incomingQualityControl
      || product.incomingQualityControl
      || material.incomingQualityControl
      || material.qualityControl
      || '不适用',
    ).trim(),
    inboundQualityControl: String(
      existing.inboundQualityControl
      || product.inboundQualityControl
      || material.inboundQualityControl
      || '不适用',
    ).trim(),
    defaultWarehouse: String(
      existing.defaultWarehouse
      || product.defaultWarehouse
      || material.defaultWarehouse
      || '',
    ).trim(),
  };
}

function materialIncomingQualityRule(data, code, name, fallbackRule = '', fallbackRequired = false) {
  const material = materialMeta(data, code, name);
  const rule = String(
    material.incomingQualityControl
    || material.qualityControl
    || fallbackRule
    || (fallbackRequired ? '需质检' : '免检'),
  ).trim();
  return rule || '免检';
}

function incomingQualityRuleRequiresInspection(rule) {
  return !['免检', '不适用', '无需质检', '无需'].includes(String(rule || '').trim());
}

function productUnit(data, product, fallbackRow) {
  const material = materialMeta(data, product.materialCode, product.name);
  return (
    material.uom ||
    product.uom ||
    String(product.qty || '').replace(/[\d,.\s-]/g, '').trim() ||
    String(fallbackRow?.available || fallbackRow?.onHand || '').replace(/[\d,.\s-]/g, '').trim() ||
    '件'
  );
}

function refreshInventoryRow(row, unit) {
  refreshInventoryFactRow(row, unit);
}

function inventoryTarget(data, code, name, location = '') {
  const meta = warehouseMeta(data, code, name);
  return {
    warehouseCode: code || meta.code || '',
    warehouse: name || meta.name || '',
    location: location || (meta.binPrefix ? `${meta.binPrefix}-AUTO` : '默认库位'),
  };
}

function activeStocktakeFreeze(row) {
  return (row?.freezeSources || []).find((source) => (
    String(source.sourceDoc || '').startsWith('ST-')
    && !['已解除', '已取消', '已作废'].includes(String(source.status || ''))
  ));
}

function normalizeStocktakeScopeValue(value) {
  return String(value || '')
    .replace(/[\s，,、/\\_-]+/g, '')
    .replace(/(库位|抽盘|盘点|范围|专项)/g, '')
    .toLowerCase();
}

function activeStocktakeCoveringTarget(warehouse, target, materialCode, item, batch) {
  const targetWarehouseCode = String(target?.warehouseCode || '').trim();
  const targetWarehouseName = String(target?.warehouse || '').trim();
  const targetLocation = String(target?.location || '').trim();
  const targetMaterialCode = String(materialCode || '').trim();
  const targetBatch = String(batch || '').trim();

  return (warehouse?.stocktakes || []).find((stocktake) => {
    if (!['盘点中', '待复核'].includes(String(stocktake.status || ''))) return false;
    const sameWarehouse = targetWarehouseCode && stocktake.warehouseCode
      ? targetWarehouseCode === stocktake.warehouseCode
      : targetWarehouseName && stocktake.warehouse
        ? targetWarehouseName === stocktake.warehouse
        : false;
    if (!sameWarehouse) return false;

    const scope = String(stocktake.scope || '').trim();
    const scopeMode = String(stocktake.scopeMode || '').trim();
    if (scopeMode === '全仓盘点' || /全仓|全部库位|全库/.test(scope)) return true;
    if (scopeMode === '按库位') return Boolean(targetLocation && targetLocation === scope);
    if (scopeMode === '按物料') return Boolean(targetMaterialCode && targetMaterialCode === scope);
    if (scopeMode === '按批次') return Boolean(targetBatch && targetBatch === scope);

    const scopeKey = normalizeStocktakeScopeValue(scope);
    return [targetLocation, targetMaterialCode, item, targetBatch].some((value) => {
      const valueKey = normalizeStocktakeScopeValue(value);
      return valueKey && scopeKey && (scopeKey.includes(valueKey) || valueKey.includes(scopeKey));
    });
  });
}

function assertTargetNotStocktakeFrozen(warehouse, target, materialCode, item, batch, action = '库存变动') {
  const stocktake = activeStocktakeCoveringTarget(warehouse, target, materialCode, item, batch);
  if (!stocktake) return;
  throw requestError(
    409,
    `${item || materialCode || '该物料'} / ${target?.location || '默认库位'} 属于盘点单 ${stocktake.code} 的盘点范围，完成或取消盘点前不能${action}。`,
  );
}

function assertInventoryRowNotStocktakeFrozen(row, action = '库存变动') {
  const freeze = activeStocktakeFreeze(row);
  if (!freeze) return;
  throw requestError(
    409,
    `${row.item || row.materialCode} / ${row.location || '默认库位'} 正在由盘点单 ${freeze.sourceDoc} 盘点，完成或取消盘点前不能${action}。`,
  );
}

function findOrCreateInventoryRow(data, warehouse, product, target, batch, now, unit) {
  const material = materialMeta(data, product.materialCode, product.name);
  const materialCode = product.materialCode || material.code || '';
  const item = product.name || material.name || '';
  const itemType = material.type || material.category || materialType(data, materialCode, item);
  assertTargetNotStocktakeFrozen(warehouse, target, materialCode, item, batch);
  const key = `${materialCode || item}::${target.warehouseCode || target.warehouse}::${target.location}::${batch}`;
  let inventoryRow = warehouse.inventory.find((row) => row.key === key);

  if (!inventoryRow) {
    inventoryRow = {
      key,
      item,
      itemType,
      materialCode,
      warehouseCode: target.warehouseCode || '',
      warehouse: target.warehouse,
      location: target.location,
      batch,
      batchDate: String(product.batchDate || now).slice(0, 10),
      expiryDate: String(product.expiryDate || ''),
      onHandNumber: 0,
      qualifiedOnHandNumber: 0,
      reservedNumber: 0,
      allocatedNumber: 0,
      frozenNumber: 0,
      availableNumber: 0,
      lockedNumber: 0,
      qcHoldNumber: 0,
      pendingInboundNumber: 0,
      inTransitNumber: 0,
      inboundPlanNumber: 0,
      outboundPlanNumber: 0,
      onHand: formatQty(0, unit),
      available: formatQty(0, unit),
      locked: formatQty(0, unit),
      qcHold: formatQty(0, unit),
      inboundPlan: formatQty(0, unit),
      outboundPlan: formatQty(0, unit),
      status: '正常',
      lastMovement: '',
      updatedAt: now,
    };
    warehouse.inventory.unshift(inventoryRow);
  } else {
    assertInventoryRowNotStocktakeFrozen(inventoryRow);
    if (!inventoryRow.batchDate && product.batchDate) inventoryRow.batchDate = String(product.batchDate).slice(0, 10);
    if (!inventoryRow.expiryDate && product.expiryDate) inventoryRow.expiryDate = String(product.expiryDate);
  }

  return inventoryRow;
}

function appendStockLedgerFact(warehouse, row, product, changeQty, unit, sourceDoc, reason, operator, now, metadata = {}) {
  const afterNumber = Number.isFinite(Number(metadata.afterBalanceNumber))
    ? Number(metadata.afterBalanceNumber)
    : inventoryNumber(row, 'onHandNumber', 'onHand');
  const beforeNumber = Number.isFinite(Number(metadata.beforeBalanceNumber))
    ? Number(metadata.beforeBalanceNumber)
    : afterNumber - changeQty;
  const movement = metadata.movement || (['盘盈', '盘亏'].includes(reason) ? reason : changeQty >= 0 ? '入库' : '出库');
  const movementDirection = metadata.movementDirection
    || (movement === '入库' || movement === '盘盈'
      ? '入库'
      : movement === '出库' || movement === '盘亏'
        ? '出库'
        : '状态变更');
  warehouse.stockLedger.unshift({
    time: now,
    occurredAt: now,
    inventoryKey: row.key || '',
    item: row.item || product.name,
    itemType: row.itemType || materialType({ masterData: { materials: [] } }, product.materialCode, product.name),
    materialCode: row.materialCode || product.materialCode || '',
    batch: row.batch || product.batch || '',
    warehouseCode: row.warehouseCode || '',
    warehouse: row.warehouse,
    location: row.location || '',
    movement,
    movementDirection,
    qty: `${changeQty >= 0 ? '+' : '-'}${formatQty(Math.abs(changeQty), unit)}`,
    quantityNumber: changeQty,
    uom: unit,
    balance: formatQty(afterNumber, unit),
    balanceFact: metadata.balanceFact || '物理在库',
    beforeBalance: formatQty(beforeNumber, unit),
    afterBalance: formatQty(afterNumber, unit),
    beforeBalanceNumber: beforeNumber,
    afterBalanceNumber: afterNumber,
    sourceLineId: product.sourceLineId || '',
    documentLineId: product.lineId || '',
    sourceDoc,
    reason,
    operator: operator || '王倩',
    ...metadata,
  });
}

function appendLedger(warehouse, row, product, changeQty, unit, sourceDoc, reason, operator, now, metadata = {}) {
  appendStockLedgerFact(warehouse, row, product, changeQty, unit, sourceDoc, reason, operator, now, metadata);
}

function warehouseReversalTarget(data, resource, code) {
  const warehouse = ensureWarehouse(data);
  const configByResource = {
    'purchase-receipts': {
      rows: warehouse.purchaseReceipts,
      title: '采购收货单',
      finalStatus: '已入库',
      flowRecords: warehouse.receiptFlowRecords,
      appendFlow: appendReceiptFlow,
    },
    'sales-issues': {
      rows: warehouse.salesIssues,
      title: '销售出库单',
      finalStatus: '已出库',
      flowRecords: warehouse.salesIssueFlowRecords,
      appendFlow: appendSalesIssueFlow,
    },
    'other-moves': {
      rows: warehouse.otherMoves,
      title: '其他出入库单',
      finalStatus: '已过账',
      flowRecords: warehouse.otherMoveFlowRecords,
      appendFlow: appendOtherMoveFlow,
    },
    transfers: {
      rows: warehouse.transfers,
      title: '库存调拨单',
      finalStatus: '已完成',
      flowRecords: warehouse.transferFlowRecords,
      appendFlow: appendTransferFlow,
    },
    stocktakes: {
      rows: warehouse.stocktakes,
      title: '库存盘点单',
      finalStatus: '已完成',
      flowRecords: warehouse.stocktakeFlowRecords,
      appendFlow: appendStocktakeFlow,
    },
  };
  const config = configByResource[resource];
  if (!config) throw requestError(404, '该仓库单据不支持库存冲销。');
  const index = config.rows.findIndex((record) => record.code === code);
  if (index < 0) throw requestError(404, `${config.title}不存在。`);
  return { warehouse, config, index, source: config.rows[index] };
}

function inventoryRowForReversal(warehouse, fact) {
  return warehouse.inventory.find((row) => {
    const sameMaterial = fact.materialCode ? row.materialCode === fact.materialCode : row.item === fact.item;
    const sameWarehouse = fact.warehouseCode ? row.warehouseCode === fact.warehouseCode : row.warehouse === fact.warehouse;
    const sameLocation = fact.location ? row.location === fact.location : true;
    const sameBatch = fact.batch ? row.batch === fact.batch : true;
    return sameMaterial && sameWarehouse && sameLocation && sameBatch;
  });
}

function receiptReversalPlan(data, receipt) {
  const warehouse = ensureWarehouse(data);
  if (receipt.stockStage !== 'posted' || !Array.isArray(receipt.postedQuantities?.lines)) {
    throw requestError(409, `采购收货单 ${receipt.code} 没有已过账的合格库存事实，不能执行库存冲销。`);
  }
  return (receipt.products || []).flatMap((product, index) => {
    const documentLineId = product.lineId || `L${index + 1}`;
    const postedLines = receipt.postedQuantities.lines
      .filter((line) => line.receiptLineId === documentLineId && Number(line.postedQty || 0) > 0);
    const postedQty = postedLines.reduce((sum, line) => sum + Number(line.postedQty || 0), 0);
    if (postedQty <= 0) return [];
    if (Math.abs(postedQty - purchaseReceiptPostableQty(receipt, product, index)) > 0.0001) {
      throw requestError(409, `${product.name || product.materialCode}存在拒收或差异数量，请通过采购退货/差异处理，不允许整单库存冲销。`);
    }
    return postedLines.map((posted) => {
      const fact = {
        materialCode: product.materialCode || '',
        item: product.name || '',
        warehouseCode: posted.warehouseCode || product.destinationWarehouseCode || receipt.warehouseCode || '',
        warehouse: posted.warehouse || product.destinationWarehouse || receipt.warehouse || '',
        location: posted.location || product.destinationLocation || receipt.location || '',
        batch: posted.batch || product.batch || '',
      };
      const row = inventoryRowForReversal(warehouse, fact);
      if (!row) throw requestError(409, `${product.name || product.materialCode}的原入库批次不存在，不能冲销。`);
      return {
        row,
        product: {
          lineId: documentLineId,
          sourceLineId: product.sourceLineId || '',
          materialCode: product.materialCode || '',
          name: product.name || '',
          batch: posted.batch || product.batch || '',
        },
        changeQty: -Number(posted.postedQty || 0),
        unit: posted.unit || product.uom || inventoryUnit(row),
        originalReason: '采购入库',
      };
    });
  });
}

function ledgerReversalPlan(data, source) {
  const warehouse = ensureWarehouse(data);
  const originalRows = warehouse.stockLedger.filter((row) => row.sourceDoc === source.code && !row.reversalOf);
  return originalRows.flatMap((ledgerRow) => {
    const originalQty = parseQty(ledgerRow.qty);
    if (Math.abs(originalQty) <= 0.0001) return [];
    const inventoryRow = inventoryRowForReversal(warehouse, ledgerRow);
    if (!inventoryRow) {
      throw requestError(409, `${ledgerRow.item || ledgerRow.materialCode}的原库存批次不存在，不能冲销。`);
    }
    return [{
      row: inventoryRow,
      product: {
        lineId: ledgerRow.documentLineId || '',
        sourceLineId: ledgerRow.sourceLineId || '',
        materialCode: ledgerRow.materialCode || '',
        name: ledgerRow.item || '',
        batch: ledgerRow.batch || '',
      },
      changeQty: -originalQty,
      unit: inventoryUnit(inventoryRow),
      originalReason: ledgerRow.reason || ledgerRow.movement || '库存过账',
    }];
  });
}

function assertWarehouseReversalInventory(plans, sourceCode) {
  const aggregate = new Map();
  plans.forEach((plan) => {
    const key = plan.row.key || `${plan.row.materialCode}::${plan.row.warehouseCode}::${plan.row.location}::${plan.row.batch}`;
    const current = aggregate.get(key) || { row: plan.row, changeQty: 0, unit: plan.unit };
    current.changeQty += plan.changeQty;
    aggregate.set(key, current);
  });
  aggregate.forEach(({ row, changeQty, unit }) => {
    refreshInventoryFactRow(row, unit);
    if (changeQty >= -0.0001) return;
    const removeQty = Math.abs(changeQty);
    const onHand = inventoryNumber(row, 'onHandNumber', 'onHand');
    const qualified = inventoryNumber(row, 'qualifiedOnHandNumber', 'qualifiedOnHand');
    const available = inventoryNumber(row, 'availableNumber', 'available');
    if (onHand + 0.0001 < removeQty || qualified + 0.0001 < removeQty || available + 0.0001 < removeQty) {
      throw requestError(
        409,
        `${row.item || row.materialCode} / ${row.batch || '无批次'}已有后续占用或出库；当前可用 ${formatQty(available, unit)}，${sourceCode} 需扣回 ${formatQty(removeQty, unit)}。`,
      );
    }
  });
}

function restoreSalesIssueReservations(warehouse, issue) {
  warehouse.inventory.forEach((row) => {
    let changed = false;
    (row.reservationSources || []).forEach((source) => {
      if (source.consumedBy !== issue.code || Number(source.consumedQuantityNumber || 0) <= 0) return;
      const restored = Number(source.consumedQuantityNumber || 0);
      source.quantityNumber = Number(source.quantityNumber || parseQty(source.qty)) + restored;
      source.qty = formatQty(source.quantityNumber, inventoryUnit(row));
      source.consumedQuantityNumber = 0;
      source.consumedBy = '';
      source.consumedAt = '';
      source.status = '有效';
      changed = true;
    });
    if (!changed) return;
    row.reservedNumber = (row.reservationSources || [])
      .filter((source) => !['已释放', '已作废', '已消耗'].includes(source.status))
      .reduce((sum, source) => sum + Number(source.quantityNumber || parseQty(source.qty)), 0);
    refreshInventoryFactRow(row, inventoryUnit(row));
  });
}

function applyWarehouseReversal(data, resource, code, body, actor) {
  const { warehouse, config, index, source } = warehouseReversalTarget(data, resource, code);
  const idempotencyKey = String(body.idempotencyKey || '').trim();
  const reason = String(body.reason || '').trim();
  const authenticatedActor = String(actor || '').trim();
  if (!authenticatedActor) throw requestError(401, '无法识别当前库存冲销操作人。');
  if (!idempotencyKey) throw requestError(400, '库存冲销必须提供幂等键。');
  const repeated = warehouse.reversals.find((record) => record.idempotencyKey === idempotencyKey);
  if (repeated) {
    if (repeated.sourceType !== resource || repeated.sourceDoc !== code) {
      throw requestError(409, '该冲销幂等键已被其他仓库单据使用。');
    }
    return { reversal: repeated, record: source, flowRecords: config.flowRecords[code] || [], repeated: true };
  }
  if (!reason) throw requestError(400, '请填写库存冲销原因。');
  if (source.status !== config.finalStatus) {
    throw requestError(409, `${config.title} ${code} 当前为${source.status || '-'}，只有${config.finalStatus}事实可以冲销。`);
  }
  if (source.reversalCode) throw requestError(409, `${config.title} ${code} 已由 ${source.reversalCode} 冲销，不能重复处理。`);

  const plans = resource === 'purchase-receipts'
    ? receiptReversalPlan(data, source)
    : ledgerReversalPlan(data, source);
  if (!plans.length) throw requestError(409, `${config.title} ${code} 没有可冲销的库存差异。`);
  if (resource === 'transfers' && plans.length < 2) {
    throw requestError(409, `库存调拨单 ${code} 的调出/调入流水不完整，不能自动冲销。`);
  }
  assertWarehouseReversalInventory(plans, code);

  const reversalCode = nextDocumentCode(data, 'warehouse-reversals', warehouse.reversals, 'RV2');
  const now = shanghaiDateTime();
  const sourcePath = `/warehouse/${resource}/${encodeURIComponent(code)}`;
  const reversalLines = [];
  plans.forEach((plan, planIndex) => {
    assertInventoryRowNotStocktakeFrozen(plan.row, '办理库存冲销');
    const beforeNumber = inventoryNumber(plan.row, 'onHandNumber', 'onHand');
    plan.row.onHandNumber = beforeNumber + plan.changeQty;
    plan.row.qualifiedOnHandNumber = inventoryNumber(plan.row, 'qualifiedOnHandNumber', 'qualifiedOnHand') + plan.changeQty;
    refreshInventoryFactRow(plan.row, plan.unit);
    plan.row.lastMovement = `库存冲销 ${reversalCode}`;
    plan.row.updatedAt = now;
    appendLedger(
      warehouse,
      plan.row,
      plan.product,
      plan.changeQty,
      plan.unit,
      reversalCode,
      `冲销 ${code}：${reason}`,
      authenticatedActor,
      now,
      { reversalOf: code, sourcePath },
    );
    reversalLines.push({
      lineId: `${reversalCode}-L${planIndex + 1}`,
      sourceLineId: plan.product.lineId || plan.product.sourceLineId || '',
      inventoryKey: plan.row.key || '',
      materialCode: plan.row.materialCode || plan.product.materialCode || '',
      name: plan.row.item || plan.product.name || '',
      warehouseCode: plan.row.warehouseCode || '',
      warehouse: plan.row.warehouse || '',
      location: plan.row.location || '',
      batch: plan.row.batch || '',
      quantity: plan.changeQty,
      uom: plan.unit,
      beforeBalance: formatQty(beforeNumber, plan.unit),
      afterBalance: plan.row.onHand,
      originalReason: plan.originalReason,
    });
  });

  if (resource === 'purchase-receipts') {
    (source.products || []).forEach((product, productIndex) => {
      const receiptLineId = product.lineId || `L${productIndex + 1}`;
      const restoredQty = plans
        .filter((plan) => plan.product.lineId === receiptLineId)
        .reduce((sum, plan) => sum + Math.abs(Number(plan.changeQty || 0)), 0);
      if (restoredQty <= 0.0001) return;
      const stagingProduct = {
        ...product,
        batch: product.stagingBatch ?? '',
      };
      const { row: stagingRow, unit } = receiptInventoryRow(data, source, stagingProduct, now);
      stagingRow.onHandNumber = inventoryNumber(stagingRow, 'onHandNumber', 'onHand') + restoredQty;
      stagingRow.pendingInboundNumber = inventoryNumber(stagingRow, 'pendingInboundNumber', 'pendingInbound') + restoredQty;
      refreshInventoryFactRow(stagingRow, unit);
      stagingRow.lastMovement = `采购入库冲销恢复 ${reversalCode}`;
      stagingRow.updatedAt = now;
      appendReceiptInventoryLedger(
        warehouse,
        stagingRow,
        stagingProduct,
        source,
        '冲销恢复待入库',
        `冲销 ${code} 后恢复采购暂存待入库数量`,
        restoredQty,
        unit,
        now,
        authenticatedActor,
      );
    });
    source.reversedPostedQuantities = [
      ...(source.reversedPostedQuantities || []),
      {
        reversalCode,
        postedQuantities: cloneJson(source.postedQuantities, {}),
        reversedAt: now,
        reversedBy: authenticatedActor,
      },
    ];
    source.postedQuantities = { lines: [], totalsByUnit: {}, postedAt: '' };
    source.inboundPostings = (source.inboundPostings || []).map((posting) => (
      posting.reversalCode
        ? posting
        : { ...posting, reversalCode, reversedAt: now, reversedBy: authenticatedActor }
    ));
    source.stockStage = 'pending_inbound';
    source.status = '待入库';
  }

  if (resource === 'sales-issues') restoreSalesIssueReservations(warehouse, source);
  const reversal = {
    code: reversalCode,
    companyCode: source.companyCode || '',
    company: source.company || '',
    sourceType: resource,
    sourceDoc: code,
    sourceStatus: source.status,
    sourcePath,
    reason,
    actor: authenticatedActor,
    status: '已完成',
    idempotencyKey,
    lines: reversalLines,
    createdAt: now,
  };
  warehouse.reversals.unshift(reversal);
  const record = {
    ...source,
    reversalCode,
    reversalStatus: '已冲销',
    reversalReason: reason,
    reversedAt: now,
    reversedBy: authenticatedActor,
  };
  config.rows[index] = record;
  config.appendFlow(data, code, '库存冲销', `${reversalCode} 已冲销本单库存影响；原因：${reason}`, authenticatedActor);

  if (resource === 'sales-issues') {
    syncShipmentTrackingFulfillment(data, record);
    const tracking = ensureSales(data).outboundRequests.find((requestDoc) => requestDoc.code === record.sourceDoc);
    if (tracking) ensureSalesIssueTaskForTracking(data, tracking, authenticatedActor);
    recomputeSalesOrderProgress(data, record.sourceOrder);
    appendFlow(data, record.sourceOrder, '库存冲销', `${reversalCode} 已冲销销售出库 ${code}，发货进度已重新计算。`, authenticatedActor);
  }
  if (resource === 'purchase-receipts' && record.sourceDoc) {
    appendPurchaseFlow(data, record.sourceDoc, '库存冲销', `${reversalCode} 已冲销采购入库 ${code}，到货与入库进度已重新计算。`, authenticatedActor);
  }

  return { reversal, record, flowRecords: config.flowRecords[code] || [], repeated: false };
}

function validateStockOut(data, source, products) {
  const warehouse = ensureWarehouse(data);
  products.forEach((product) => {
    const requestedQty = parseQty(product.qty);
    if (!requestedQty) return;

    const candidates = matchingInventoryRows(warehouse, source, product);
    const availableQty = candidates.reduce((sum, row) => sum + parseQty(row.available), 0);
    if (availableQty < requestedQty) {
      const error = new Error(`${product.name} 可用库存不足，当前可用 ${availableQty}，需要 ${requestedQty}`);
      error.statusCode = 409;
      throw error;
    }
  });
}

function applyStockOut(data, source, products, sourceDoc, reason, operator) {
  const warehouse = ensureWarehouse(data);
  const now = shanghaiDateTime();

  validateStockOut(data, source, products);

  products.forEach((product, index) => {
    product.lineId ||= `${sourceDoc}-L${index + 1}`;
    let remaining = parseQty(product.qty);
    if (!remaining) return;

    const usedBatches = [];
    for (const inventoryRow of matchingInventoryRows(warehouse, source, product)) {
      if (remaining <= 0) break;

      const unit = productUnit(data, product, inventoryRow);
      const available = Number(inventoryRow.availableNumber || parseQty(inventoryRow.available));
      const onHand = Number(inventoryRow.onHandNumber || parseQty(inventoryRow.onHand));
      const deductQty = Math.min(remaining, available);
      if (!deductQty) continue;

      inventoryRow.availableNumber = available - deductQty;
      inventoryRow.onHandNumber = Math.max(0, onHand - deductQty);
      inventoryRow.qualifiedOnHandNumber = Math.max(
        0,
        inventoryNumber(inventoryRow, 'qualifiedOnHandNumber', 'qualifiedOnHand') - deductQty,
      );
      refreshInventoryRow(inventoryRow, unit);
      inventoryRow.status = inventoryRow.availableNumber <= 0 ? '不足' : '正常';
      inventoryRow.lastMovement = `${reason} ${sourceDoc}`;
      inventoryRow.updatedAt = now;
      appendLedger(warehouse, inventoryRow, product, -deductQty, unit, sourceDoc, reason, operator, now);

      usedBatches.push(inventoryRow.batch);
      remaining -= deductQty;
    }

    if (usedBatches.length && !products[index].batch) {
      products[index] = { ...products[index], batch: usedBatches.join(', ') };
    }
  });
}

function applyStockIn(data, target, products, sourceDoc, reason, operator) {
  const warehouse = ensureWarehouse(data);
  const now = shanghaiDateTime();
  const targetInfo = inventoryTarget(data, target.warehouseCode, target.warehouse, target.location);

  products.forEach((product, index) => {
    product.lineId ||= `${sourceDoc}-L${index + 1}`;
    const qtyNumber = parseQty(product.qty);
    if (!qtyNumber) return;

    const unit = productUnit(data, product);
    const batchTracked = materialUsesBatchTracking(data, product);
    const batch = batchTracked
      ? product.batch || `${sourceDoc.replace(/[^A-Z0-9]/gi, '')}-${String(index + 1).padStart(2, '0')}`
      : '';
    const inventoryRow = findOrCreateInventoryRow(data, warehouse, product, targetInfo, batch, now, unit);

    inventoryRow.onHandNumber = Number(inventoryRow.onHandNumber || parseQty(inventoryRow.onHand)) + qtyNumber;
    inventoryRow.qualifiedOnHandNumber = inventoryNumber(inventoryRow, 'qualifiedOnHandNumber', 'qualifiedOnHand') + qtyNumber;
    refreshInventoryRow(inventoryRow, unit);
    inventoryRow.status = '正常';
    inventoryRow.lastMovement = `${reason} ${sourceDoc}`;
    inventoryRow.updatedAt = now;
    appendLedger(warehouse, inventoryRow, { ...product, batch }, qtyNumber, unit, sourceDoc, reason, operator, now);

    if (batchTracked && !products[index].batch) {
      products[index] = { ...products[index], batch };
    } else if (!batchTracked && products[index].batch) {
      products[index] = { ...products[index], batch: '' };
    }
  });
}

function normalizeOtherMove(input, existing, data) {
  const warehouse = ensureWarehouse(data);
  const code =
    !isSystemGeneratedCode(input.code, 'OM')
      ? String(input.code)
      : existing?.code || nextWarehouseDocumentCode(data, warehouse.otherMoves, 'OM');
  const requestedMoveType = input.moveType || existing?.moveType || '样品出库';
  const moveType = requestedMoveType === '盘外调整'
    ? '库存调整'
    : requestedMoveType === '研发领料'
      ? '领用出库'
      : requestedMoveType;
  const direction = otherMoveDirection(moveType, input.direction || existing?.direction);
  const requestedWarehouseCode = String(input.warehouseCode ?? existing?.warehouseCode ?? '').trim();
  const requestedWarehouseName = String(input.warehouse ?? existing?.warehouse ?? '').trim();
  const selectedWarehouse = requestedWarehouseCode || requestedWarehouseName
    ? warehouseMeta(data, requestedWarehouseCode, requestedWarehouseName)
    : {};
  if ((requestedWarehouseCode || requestedWarehouseName) && !selectedWarehouse.code) {
    throw requestError(400, `仓库 ${requestedWarehouseCode || requestedWarehouseName} 不存在。`);
  }
  if (selectedWarehouse.status && selectedWarehouse.status !== '启用') {
    throw requestError(409, `仓库 ${selectedWarehouse.name} 当前未启用。`);
  }
  const requestedLocation = String(input.location ?? existing?.location ?? '').trim();
  const availableLocations = selectedWarehouse.code ? warehouseLocationOptions(data, selectedWarehouse) : [];
  const locationExistsInInventory = requestedLocation && warehouse.inventory.some((row) => (
    (selectedWarehouse.code ? row.warehouseCode === selectedWarehouse.code : row.warehouse === selectedWarehouse.name)
    && row.location === requestedLocation
  ));
  if (requestedLocation && availableLocations.length && !availableLocations.includes(requestedLocation) && !locationExistsInInventory) {
    throw requestError(400, `库位 ${requestedLocation} 不属于仓库 ${selectedWarehouse.name}。`);
  }
  const location = requestedLocation || (availableLocations.length === 1 ? availableLocations[0] : '');

  return {
    ...(existing || {}),
    code,
    ...resolveDocumentCompany(data, input, existing),
    moveType,
    direction,
    reason: String(input.reason ?? existing?.reason ?? '').trim(),
    products: normalizeWarehouseProducts(data, input.products, code),
    warehouseCode: selectedWarehouse.code || '',
    warehouse: selectedWarehouse.name || '',
    location,
    targetWarehouse: String(input.targetWarehouse ?? existing?.targetWarehouse ?? '').trim(),
    owner: input.owner || existing?.owner || '王倩',
    status: existing?.status || '草稿',
    date: input.date || shanghaiDate(),
    note: String(input.note ?? existing?.note ?? '').trim(),
    attachments: Array.isArray(input.attachments) ? input.attachments : existing?.attachments || [],
  };
}

function otherMoveLocationProjection(data, move) {
  const explicit = String(move?.location || '').trim();
  if (explicit) return explicit;
  const warehouse = ensureWarehouse(data);
  const matchedLocations = new Set();
  (move?.products || []).forEach((product) => {
    matchingInventoryRows(warehouse, { ...move, location: '' }, product).forEach((row) => {
      const location = String(row.location || '').trim();
      if (location) matchedLocations.add(location);
    });
  });
  if (matchedLocations.size === 1) return [...matchedLocations][0];
  const selectedWarehouse = warehouseMeta(data, move?.warehouseCode, move?.warehouse);
  const configuredLocations = selectedWarehouse.code ? warehouseLocationOptions(data, selectedWarehouse) : [];
  return configuredLocations.length === 1 ? configuredLocations[0] : '';
}

function normalizeTransfer(input, existing, data, actor = '') {
  const warehouse = ensureWarehouse(data);
  const code =
    !isSystemGeneratedCode(input.code, 'TR')
      ? String(input.code)
      : existing?.code || nextWarehouseDocumentCode(data, warehouse.transfers, 'TR');
  const requestedFromCode = String(input.fromWarehouseCode ?? existing?.fromWarehouseCode ?? '').trim();
  const requestedFromName = String(input.fromWarehouse ?? existing?.fromWarehouse ?? '').trim();
  const requestedToCode = String(input.toWarehouseCode ?? existing?.toWarehouseCode ?? '').trim();
  const requestedToName = String(input.toWarehouse ?? existing?.toWarehouse ?? '').trim();
  const fromWarehouse = requestedFromCode || requestedFromName
    ? warehouseMeta(data, requestedFromCode, requestedFromName)
    : {};
  const toWarehouse = requestedToCode || requestedToName
    ? warehouseMeta(data, requestedToCode, requestedToName)
    : {};
  if ((requestedFromCode || requestedFromName) && !fromWarehouse.code) {
    throw requestError(400, `调出仓 ${requestedFromCode || requestedFromName} 不存在。`);
  }
  if ((requestedToCode || requestedToName) && !toWarehouse.code) {
    throw requestError(400, `调入仓 ${requestedToCode || requestedToName} 不存在。`);
  }
  const fromCompany = String(fromWarehouse.company || '').trim();
  const toCompany = String(toWarehouse.company || '').trim();
  const documentCompany = resolveDocumentCompany(
    data,
    {
      ...input,
      company: input.company || existing?.company || fromCompany || toCompany,
    },
    existing,
  );
  if (fromCompany && toCompany && fromCompany !== toCompany) {
    throw requestError(400, '库存调拨只能在同一公司所属仓库之间进行。');
  }
  if (documentCompany.company && ((fromCompany && fromCompany !== documentCompany.company) || (toCompany && toCompany !== documentCompany.company))) {
    throw requestError(400, `调出仓和调入仓必须属于单据公司 ${documentCompany.company}。`);
  }
  if (fromWarehouse.status && fromWarehouse.status !== '启用') throw requestError(409, `调出仓 ${fromWarehouse.name} 当前未启用。`);
  if (toWarehouse.status && toWarehouse.status !== '启用') throw requestError(409, `调入仓 ${toWarehouse.name} 当前未启用。`);
  const requestedToLocation = String(input.toLocation ?? existing?.toLocation ?? '').trim();
  if (requestedToLocation && isPlaceholderWarehouseLocation(requestedToLocation)) {
    throw requestError(400, `库存调拨不能使用占位库位 ${requestedToLocation}，请从调入仓正式库位中选择。`);
  }
  const targetLocationOptions = toWarehouse.code
    ? warehouseLocationOptions(data, toWarehouse).filter((location) => !isPlaceholderWarehouseLocation(location))
    : [];
  if (requestedToLocation && targetLocationOptions.length && !targetLocationOptions.includes(requestedToLocation)) {
    throw requestError(400, `调入库位 ${requestedToLocation} 不属于 ${toWarehouse.name}。`);
  }
  const toLocation = requestedToLocation;

  return {
    ...(existing || {}),
    code,
    ...documentCompany,
    products: normalizeWarehouseProducts(data, input.products, code),
    fromWarehouseCode: fromWarehouse.code || '',
    fromWarehouse: fromWarehouse.name || '',
    toWarehouseCode: toWarehouse.code || '',
    toWarehouse: toWarehouse.name || '',
    toLocation,
    owner: input.owner || existing?.owner || actor,
    status: existing?.status || '草稿',
    date: input.date || shanghaiDate(),
    reason: String(input.reason ?? existing?.reason ?? '').trim(),
    note: String(input.note ?? existing?.note ?? '').trim(),
    attachments: Array.isArray(input.attachments) ? input.attachments : existing?.attachments || [],
    transitLines: Array.isArray(existing?.transitLines) ? existing.transitLines : [],
  };
}

function normalizeStocktake(input, existing, data, actor = '') {
  const warehouse = ensureWarehouse(data);
  const code =
    !isSystemGeneratedCode(input.code, 'ST')
      ? String(input.code)
      : existing?.code || nextWarehouseDocumentCode(data, warehouse.stocktakes, 'ST');

  const isCounting = existing?.status === '盘点中';
  const requestedWarehouseCode = String(input.warehouseCode ?? existing?.warehouseCode ?? '').trim();
  const requestedWarehouseName = String(input.warehouse ?? existing?.warehouse ?? '').trim();
  const selectedWarehouse = isCounting
    ? warehouseMeta(data, existing?.warehouseCode, existing?.warehouse)
    : requestedWarehouseCode || requestedWarehouseName
      ? warehouseMeta(data, requestedWarehouseCode, requestedWarehouseName)
      : {};
  if ((requestedWarehouseCode || requestedWarehouseName) && !selectedWarehouse.code) {
    throw requestError(400, `盘点仓库 ${requestedWarehouseCode || requestedWarehouseName} 不存在。`);
  }
  if (selectedWarehouse.status && selectedWarehouse.status !== '启用') {
    throw requestError(409, `盘点仓库 ${selectedWarehouse.name} 当前未启用。`);
  }
  const scopeModes = new Set(['全仓盘点', '按库位', '按物料', '按批次', '指定范围']);
  const requestedScope = String(input.scope ?? existing?.scope ?? '').trim();
  const requestedScopeMode = String(input.scopeMode ?? existing?.scopeMode ?? '').trim();
  let scopeMode = isCounting
    ? String(existing?.scopeMode || '').trim()
    : requestedScopeMode;
  if (!scopeModes.has(scopeMode)) {
    scopeMode = /全仓|全部库位|全库/.test(requestedScope) ? '全仓盘点' : '指定范围';
  }
  let scope = isCounting ? String(existing?.scope || '').trim() : requestedScope;
  let scopeLabel = isCounting ? String(existing?.scopeLabel || existing?.scope || '').trim() : String(input.scopeLabel || '').trim();
  if (scopeMode === '全仓盘点') {
    scope = '全仓盘点';
    scopeLabel = '全部合格库存';
  } else if (scopeMode === '按物料' && scope) {
    const material = materialMeta(data, scope, scopeLabel || scope);
    if (!material.code) throw requestError(400, `盘点物料 ${scope} 不存在。`);
    scope = material.code;
    scopeLabel = material.name;
  } else {
    scopeLabel ||= scope;
  }
  const lines = isCounting
    ? normalizeStocktakeLines(input.lines, existing?.lines)
    : Array.isArray(existing?.lines)
      ? existing.lines.map((line) => ({ ...line }))
      : [];
  const countedLines = lines.filter((line) => line.countedQty != null);
  const requestedOwnerEmployeeCode = String(input.ownerEmployeeCode ?? existing?.ownerEmployeeCode ?? '').trim();
  const requestedOwnerName = String(input.owner ?? existing?.owner ?? actor).trim();
  const ownerEmployee = isCounting
    ? undefined
    : ensureMasterRows(data, 'employees').find((row) => (
      (requestedOwnerEmployeeCode && row.code === requestedOwnerEmployeeCode)
      || (!requestedOwnerEmployeeCode && requestedOwnerName && row.name === requestedOwnerName)
    ));
  if (!isCounting && (requestedOwnerEmployeeCode || requestedOwnerName) && !ownerEmployee) {
    throw requestError(400, '请选择有效的盘点负责人。');
  }
  if (!isCounting && ownerEmployee?.status && ownerEmployee.status !== '启用') {
    throw requestError(409, `盘点负责人 ${ownerEmployee.name} 当前未启用。`);
  }
  if (!isCounting && ownerEmployee && !employeeHasActiveRole(data, ownerEmployee, 'ROLE-WAREHOUSE')) {
    throw requestError(400, '盘点负责人必须是关联启用仓库角色账号的员工。');
  }
  const stocktakeDate = isCounting
    ? String(existing?.date || '').trim()
    : String(input.date ?? existing?.date ?? shanghaiDate()).trim();
  if (!isCounting && !isValidIsoDate(stocktakeDate)) {
    throw requestError(400, '请填写有效的盘点日期。');
  }
  return {
    ...(existing || {}),
    code,
    ...resolveDocumentCompany(data, input, existing),
    warehouseCode: selectedWarehouse.code || '',
    warehouse: selectedWarehouse.name || '',
    scopeMode,
    scope,
    scopeLabel,
    ownerEmployeeCode: isCounting ? existing.ownerEmployeeCode || '' : ownerEmployee?.code || '',
    owner: isCounting ? existing.owner : ownerEmployee?.name || '',
    status: existing?.status || '待盘点',
    date: stocktakeDate,
    plannedCount: lines.length,
    checkedCount: countedLines.length,
    differenceCount: lines.length
      ? countedLines.filter((line) => Math.abs(Number(line.differenceQty || 0)) > 0.0001).length
      : 0,
    note: String(input.note ?? existing?.note ?? '').trim(),
    attachments: Array.isArray(input.attachments) ? input.attachments : existing?.attachments || [],
    lines,
  };
}

function assertWarehouseProductsReady(data, products, documentLabel) {
  if (!Array.isArray(products) || products.length === 0) {
    throw requestError(400, `${documentLabel}至少需要一条物料明细。`);
  }
  const seen = new Set();
  products.forEach((product, index) => {
    const material = materialMeta(data, product.materialCode, product.name);
    if (!material.code) throw requestError(400, `${documentLabel}第 ${index + 1} 行必须选择有效物料。`);
    const quantity = parseQty(product.qty);
    if (!(quantity > 0)) throw requestError(400, `${product.name || `第 ${index + 1} 行`}的数量必须大于 0。`);
    if (material.uom && product.uom && material.uom !== product.uom) {
      throw requestError(400, `${product.name}必须使用基础单位 ${material.uom}。`);
    }
    const key = `${material.code}::${product.batch || ''}`;
    if (seen.has(key)) throw requestError(400, `${product.name}的相同批次不能重复填写。`);
    seen.add(key);
  });
}

function assertOtherMoveReady(data, move) {
  const allowedMoveTypes = new Set(['样品出库', '领用出库', '报废出库', '借用出库', '借用归还', '库存调整']);
  if (!allowedMoveTypes.has(move.moveType)) throw requestError(400, '请选择有效的其他出入库类型。');
  if (move.direction !== otherMoveDirection(move.moveType, move.direction)) {
    throw requestError(400, '库存方向与业务类型不一致。');
  }
  assertWarehouseProductsReady(data, move.products, '其他出入库单');
  if (!move.warehouseCode && !move.warehouse) throw requestError(400, '请选择发生库存变动的仓库。');
  const selectedWarehouse = warehouseMeta(data, move.warehouseCode, move.warehouse);
  if (!selectedWarehouse.code) throw requestError(400, '请选择有效的业务仓库。');
  if (selectedWarehouse.status && selectedWarehouse.status !== '启用') throw requestError(409, `仓库 ${selectedWarehouse.name} 当前未启用。`);
  const location = otherMoveLocationProjection(data, move);
  if (!location) throw requestError(400, `请选择${move.direction === '入库' ? '入库' : '出库'}库位。`);
  if (isPlaceholderWarehouseLocation(location)) {
    throw requestError(400, `其他出入库不能使用占位库位 ${location}，请从正式库位列表选择。`);
  }
  const locationOptions = warehouseLocationOptions(data, selectedWarehouse);
  const locationExistsInInventory = data.warehouse.inventory.some((row) => (
    row.warehouseCode === selectedWarehouse.code && row.location === location
  ));
  if (locationOptions.length && !locationOptions.includes(location) && !locationExistsInInventory) {
    throw requestError(400, `库位 ${location} 不属于仓库 ${selectedWarehouse.name}。`);
  }
  move.location = location;
  if (move.direction === '出库') {
    (move.products || []).forEach((product) => {
      if (materialUsesBatchTracking(data, product) && !String(product.batch || '').trim()) {
        throw requestError(400, `${product.name || product.materialCode || '物料'}必须选择实际出库批次。`);
      }
    });
  }
  if (move.moveType !== '库存调整' && !String(move.targetWarehouse || '').trim()) {
    throw requestError(400, '请填写本次业务的来源或去向。');
  }
  if (!String(move.reason || '').trim()) throw requestError(400, '请填写其他出入库原因。');
}

function otherMoveDirection(moveType, requestedDirection = '') {
  if (moveType === '借用归还') return '入库';
  if (moveType === '库存调整' || moveType === '盘外调整') return requestedDirection === '入库' ? '入库' : '出库';
  return '出库';
}

function assertTransferReady(data, transfer) {
  assertWarehouseProductsReady(data, transfer.products, '库存调拨单');
  if ((!transfer.fromWarehouseCode && !transfer.fromWarehouse) || (!transfer.toWarehouseCode && !transfer.toWarehouse)) {
    throw requestError(400, '请选择调出仓和调入仓。');
  }
  if (
    (transfer.fromWarehouseCode && transfer.fromWarehouseCode === transfer.toWarehouseCode)
    || (!transfer.fromWarehouseCode && transfer.fromWarehouse === transfer.toWarehouse)
  ) {
    throw requestError(400, '调出仓和调入仓不能相同。');
  }
  const fromWarehouse = warehouseMeta(data, transfer.fromWarehouseCode, transfer.fromWarehouse);
  const toWarehouse = warehouseMeta(data, transfer.toWarehouseCode, transfer.toWarehouse);
  if (!fromWarehouse.code || !toWarehouse.code) throw requestError(400, '请选择有效的调出仓和调入仓。');
  if (fromWarehouse.status && fromWarehouse.status !== '启用') throw requestError(409, `调出仓 ${fromWarehouse.name} 当前未启用。`);
  if (toWarehouse.status && toWarehouse.status !== '启用') throw requestError(409, `调入仓 ${toWarehouse.name} 当前未启用。`);
  if (fromWarehouse.company && toWarehouse.company && fromWarehouse.company !== toWarehouse.company) {
    throw requestError(400, '库存调拨只能在同一公司所属仓库之间进行。');
  }
  if (
    transfer.company
    && ((fromWarehouse.company && fromWarehouse.company !== transfer.company) || (toWarehouse.company && toWarehouse.company !== transfer.company))
  ) {
    throw requestError(400, `调出仓和调入仓必须属于单据公司 ${transfer.company}。`);
  }
  const toLocation = String(transfer.toLocation || '').trim();
  if (!toLocation) throw requestError(400, '请选择调入仓库中的目标库位。');
  if (isPlaceholderWarehouseLocation(toLocation)) {
    throw requestError(400, `库存调拨不能使用占位库位 ${toLocation}，请从调入仓正式库位中选择。`);
  }
  const targetLocationOptions = warehouseLocationOptions(data, toWarehouse)
    .filter((location) => !isPlaceholderWarehouseLocation(location));
  if (!targetLocationOptions.length) {
    throw requestError(409, `调入仓 ${toWarehouse.name} 尚未维护可用库位，不能提交调拨。`);
  }
  if (!targetLocationOptions.includes(toLocation)) {
    throw requestError(400, `调入库位 ${toLocation} 不属于仓库 ${toWarehouse.name}，请从库位列表选择。`);
  }
  const warehouse = ensureWarehouse(data);
  transfer.products.forEach((product) => {
    if (!materialUsesBatchTracking(data, product) || !String(product.batch || '').trim()) return;
    const candidates = matchingInventoryRows(warehouse, {
      warehouseCode: fromWarehouse.code,
      warehouse: fromWarehouse.name,
    }, product);
    if (!candidates.length) {
      throw requestError(400, `${product.name || product.materialCode || '物料'}所选批次 ${product.batch} 在调出仓没有可用库存；可清空后由系统自动分配。`);
    }
  });
  if (!String(transfer.reason || '').trim()) throw requestError(400, '请填写调拨原因。');
}

function assertStocktakeReady(data, stocktake) {
  if (!isValidIsoDate(String(stocktake.date || '').trim())) throw requestError(400, '请填写有效的盘点日期。');
  if (!stocktake.warehouseCode && !stocktake.warehouse) throw requestError(400, '请选择盘点仓库。');
  if (!String(stocktake.scope || '').trim()) throw requestError(400, '请填写盘点范围。');
  const ownerEmployee = ensureMasterRows(data, 'employees').find((row) => (
    (stocktake.ownerEmployeeCode && row.code === stocktake.ownerEmployeeCode)
    || (!stocktake.ownerEmployeeCode && stocktake.owner && row.name === stocktake.owner)
  ));
  if (!ownerEmployee || (ownerEmployee.status && ownerEmployee.status !== '启用')) {
    throw requestError(400, '请选择启用的盘点负责人。');
  }
  if (!employeeHasActiveRole(data, ownerEmployee, 'ROLE-WAREHOUSE')) {
    throw requestError(400, '盘点负责人必须是关联启用仓库角色账号的员工。');
  }
  stocktake.ownerEmployeeCode = ownerEmployee.code;
  stocktake.owner = ownerEmployee.name;
}

function applyOtherMoveToStock(data, move, actor) {
  if (move.direction === '入库') {
    applyStockIn(data, move, move.products, move.code, '其他入库', actor);
  } else {
    applyStockOut(data, move, move.products, move.code, '其他出库', actor);
  }
}

function dispatchTransferToTransit(data, transfer, actor) {
  const source = {
    warehouseCode: transfer.fromWarehouseCode,
    warehouse: transfer.fromWarehouse,
  };
  const target = {
    warehouseCode: transfer.toWarehouseCode,
    warehouse: transfer.toWarehouse,
    location: transfer.toLocation || '',
  };
  const warehouse = ensureWarehouse(data);
  const now = shanghaiDateTime();

  assertTransferReady(data, transfer);
  validateStockOut(data, source, transfer.products);
  const transitLines = [];

  transfer.products.forEach((product, index) => {
    product.lineId ||= `${transfer.code}-L${index + 1}`;
    let remaining = parseQty(product.qty);
    if (!remaining) return;

    const usedBatches = [];
    for (const sourceRow of matchingInventoryRows(warehouse, source, product)) {
      if (remaining <= 0) break;

      const unit = productUnit(data, product, sourceRow);
      const available = Number(sourceRow.availableNumber || parseQty(sourceRow.available));
      const onHand = Number(sourceRow.onHandNumber || parseQty(sourceRow.onHand));
      const moveQty = Math.min(remaining, available);
      if (!moveQty) continue;

      sourceRow.availableNumber = available - moveQty;
      sourceRow.onHandNumber = Math.max(0, onHand - moveQty);
      sourceRow.qualifiedOnHandNumber = Math.max(
        0,
        inventoryNumber(sourceRow, 'qualifiedOnHandNumber', 'qualifiedOnHand') - moveQty,
      );
      refreshInventoryRow(sourceRow, unit);
      sourceRow.status = sourceRow.availableNumber <= 0 ? '不足' : '正常';
      sourceRow.lastMovement = `库存调拨 ${transfer.code}`;
      sourceRow.updatedAt = now;
      appendLedger(warehouse, sourceRow, product, -moveQty, unit, transfer.code, '库存调拨出库', actor, now);

      const targetInfo = inventoryTarget(data, target.warehouseCode, target.warehouse, target.location);
      const targetRow = findOrCreateInventoryRow(data, warehouse, product, targetInfo, sourceRow.batch || product.batch || '', now, unit);
      targetRow.inTransitNumber = inventoryNumber(targetRow, 'inTransitNumber', 'inTransit') + moveQty;
      targetRow.transitSources ||= [];
      const transitSourceLineId = product.lineId || `${transfer.code}-L${index + 1}`;
      const transitSource = targetRow.transitSources.find((source) => (
        source.sourceDoc === transfer.code && source.sourceLineId === transitSourceLineId
      ));
      if (transitSource) {
        transitSource.quantityNumber = Number(transitSource.quantityNumber || parseQty(transitSource.qty)) + moveQty;
        transitSource.qty = formatQty(transitSource.quantityNumber, unit);
        transitSource.status = '调拨中';
      } else {
        targetRow.transitSources.push({
          type: '调拨占用',
          sourceDoc: transfer.code,
          sourceLineId: transitSourceLineId,
          quantityNumber: moveQty,
          qty: formatQty(moveQty, unit),
          status: '调拨中',
          path: `/warehouse/transfers/${encodeURIComponent(transfer.code)}`,
        });
      }
      refreshInventoryRow(targetRow, unit);
      targetRow.status = targetRow.availableNumber <= 0 ? '待入库' : targetRow.status;
      targetRow.lastMovement = `调拨在途 ${transfer.code}`;
      targetRow.updatedAt = now;
      transitLines.push({
        lineId: product.lineId || `${transfer.code}-L${index + 1}`,
        sourceLineId: product.sourceLineId || '',
        inventoryKey: sourceRow.key,
        targetInventoryKey: targetRow.key,
        materialCode: sourceRow.materialCode || product.materialCode || '',
        name: sourceRow.item || product.name || '',
        batch: sourceRow.batch || product.batch || '',
        qty: moveQty,
        uom: unit,
      });

      usedBatches.push(sourceRow.batch);
      remaining -= moveQty;
    }

    if (usedBatches.length && !transfer.products[index].batch) {
      transfer.products[index] = { ...transfer.products[index], batch: usedBatches.join(', ') };
    }
  });
  transfer.transitLines = transitLines;
}

function receiveTransferFromTransit(data, transfer, actor) {
  const warehouse = ensureWarehouse(data);
  const now = shanghaiDateTime();
  if (!Array.isArray(transfer.transitLines) || transfer.transitLines.length === 0) {
    throw requestError(409, `库存调拨单 ${transfer.code} 尚未形成在途库存，请先确认调出。`);
  }

  transfer.transitLines.forEach((line) => {
    const targetRow = warehouse.inventory.find((row) => row.key === line.targetInventoryKey);
    if (!targetRow) throw requestError(409, `${line.name || line.materialCode}的调入库存记录不存在。`);
    assertInventoryRowNotStocktakeFrozen(targetRow, '确认调入');
    const quantity = Number(line.qty || 0);
    const inTransit = inventoryNumber(targetRow, 'inTransitNumber', 'inTransit');
    if (inTransit + 0.0001 < quantity) {
      throw requestError(409, `${line.name || line.materialCode}的在途数量不足，无法确认调入。`);
    }
  });

  transfer.transitLines.forEach((line) => {
    const targetRow = warehouse.inventory.find((row) => row.key === line.targetInventoryKey);
    const quantity = Number(line.qty || 0);
    const unit = line.uom || inventoryUnit(targetRow);
    targetRow.inTransitNumber = Math.max(0, inventoryNumber(targetRow, 'inTransitNumber', 'inTransit') - quantity);
    targetRow.transitSources ||= [];
    const transitSource = targetRow.transitSources.find((source) => (
      source.sourceDoc === transfer.code
      && (!line.lineId || source.sourceLineId === line.lineId)
    ));
    if (transitSource) {
      const remaining = Math.max(0, Number(transitSource.quantityNumber || parseQty(transitSource.qty)) - quantity);
      transitSource.quantityNumber = remaining;
      transitSource.qty = formatQty(remaining, unit);
      transitSource.status = remaining > 0 ? '部分入库' : '已入库';
    }
    targetRow.onHandNumber = inventoryNumber(targetRow, 'onHandNumber', 'onHand') + quantity;
    targetRow.qualifiedOnHandNumber = inventoryNumber(targetRow, 'qualifiedOnHandNumber', 'qualifiedOnHand') + quantity;
    refreshInventoryRow(targetRow, unit);
    targetRow.status = targetRow.availableNumber > 0 ? '正常' : targetRow.status;
    targetRow.lastMovement = `调拨入库 ${transfer.code}`;
    targetRow.updatedAt = now;
    appendLedger(
      warehouse,
      targetRow,
      {
        lineId: line.lineId || '',
        sourceLineId: line.sourceLineId || '',
        materialCode: line.materialCode,
        name: line.name,
        batch: line.batch,
      },
      quantity,
      unit,
      transfer.code,
      '库存调拨入库',
      actor,
      now,
    );
  });
}

function stocktakeInventoryRows(data, stocktake) {
  const warehouse = ensureWarehouse(data);
  const warehouseRows = warehouse.inventory.filter((row) => {
    const matchesWarehouse = stocktake.warehouseCode
      ? row.warehouseCode === stocktake.warehouseCode
      : row.warehouse === stocktake.warehouse;
    return matchesWarehouse && inventoryNumber(row, 'qualifiedOnHandNumber', 'qualifiedOnHand') > 0;
  });
  const scope = String(stocktake.scope || '').trim();
  const scopeMode = String(stocktake.scopeMode || '').trim();
  if (scopeMode === '全仓盘点' || /全仓|全部库位|全库/.test(scope)) return warehouseRows;

  if (scopeMode === '按库位') {
    const scopedRows = warehouseRows.filter((row) => String(row.location || '').trim() === scope);
    if (!scopedRows.length) throw requestError(400, `库位 ${scope || '-'} 没有可盘合格库存。`);
    return scopedRows;
  }
  if (scopeMode === '按物料') {
    const scopedRows = warehouseRows.filter((row) => row.materialCode === scope);
    if (!scopedRows.length) throw requestError(400, `物料 ${stocktake.scopeLabel || scope || '-'} 在当前仓库没有可盘合格库存。`);
    return scopedRows;
  }
  if (scopeMode === '按批次') {
    const scopedRows = warehouseRows.filter((row) => String(row.batch || '').trim() === scope);
    if (!scopedRows.length) throw requestError(400, `批次 ${scope || '-'} 在当前仓库没有可盘合格库存。`);
    return scopedRows;
  }

  const scopeKey = normalizeStocktakeScopeValue(scope);
  const scopedRows = warehouseRows.filter((row) =>
    [row.location, row.materialCode, row.item, row.batch].some((value) => {
      const rowKey = normalizeStocktakeScopeValue(value);
      return rowKey && scopeKey && (scopeKey.includes(rowKey) || rowKey.includes(scopeKey));
    }),
  );
  if (!scopedRows.length) throw requestError(400, '盘点范围未匹配到可盘库存，请填写库位、物料、批次或使用“全仓盘点”。');
  return scopedRows;
}

function stocktakeMaterialIdentityProjection(data, stocktake) {
  return {
    ...stocktake,
    lines: (stocktake.lines || []).map((line) => {
      const material = materialMeta(data, line.materialCode, line.item);
      return {
        ...line,
        model: line.model || material.model || '',
        spec: line.spec || material.spec || '',
        imageLabel: line.imageLabel || material.imageLabel || '',
        imageTone: line.imageTone || material.imageTone || '',
      };
    }),
  };
}

function startStocktakeSnapshot(data, stocktake) {
  assertStocktakeReady(data, stocktake);
  const warehouse = ensureWarehouse(data);
  const rows = stocktakeInventoryRows(data, stocktake);
  const activeStocktakes = warehouse.stocktakes.filter((row) => (
    row.code !== stocktake.code && ['盘点中', '待复核'].includes(row.status)
  ));
  const conflict = rows.find((row) => activeStocktakes.some((active) => (
    (active.lines || []).some((line) => line.inventoryKey === row.key)
  )));
  if (conflict) {
    const active = activeStocktakes.find((candidate) => (
      (candidate.lines || []).some((line) => line.inventoryKey === conflict.key)
    ));
    throw requestError(
      409,
      `${conflict.item || conflict.materialCode} / ${conflict.location || '默认库位'} 已在盘点单 ${active?.code || '-'} 中，不能重复冻结。`,
    );
  }
  stocktake.lines = rows.map((row, index) => {
    const unit = inventoryUnit(row);
    const material = materialMeta(data, row.materialCode, row.item);
    const bookQty = inventoryNumber(row, 'qualifiedOnHandNumber', 'qualifiedOnHand');
    const frozenQty = Number(row.availableNumber || parseQty(row.available));
    row.frozenNumber = inventoryNumber(row, 'frozenNumber', 'frozen') + frozenQty;
    row.freezeSources ||= [];
    row.freezeSources.push({
      type: '手动冻结',
      sourceDoc: stocktake.code,
      sourceLineId: row.key,
      quantityNumber: frozenQty,
      qty: formatQty(frozenQty, unit),
      status: '盘点中',
      path: `/warehouse/stocktakes/${encodeURIComponent(stocktake.code)}`,
    });
    refreshInventoryRow(row, unit);
    row.lastMovement = `盘点冻结 ${stocktake.code}`;
    row.updatedAt = shanghaiDateTime();
    return {
      lineId: `${stocktake.code}-L${index + 1}`,
      inventoryKey: row.key,
      materialCode: row.materialCode || '',
      item: row.item,
      itemType: row.itemType || '',
      model: material.model || '',
      spec: material.spec || '',
      imageLabel: material.imageLabel || '',
      imageTone: material.imageTone || '',
      location: row.location || '',
      batch: row.batch || '',
      uom: unit,
      bookQty,
      countedQty: null,
      differenceQty: 0,
      frozenQty,
    };
  });
  stocktake.plannedCount = stocktake.lines.length;
  stocktake.checkedCount = 0;
  stocktake.differenceCount = 0;
}

function assertStocktakeCounted(stocktake) {
  if (!Array.isArray(stocktake.lines) || stocktake.lines.length === 0) {
    throw requestError(400, '盘点单没有账面快照，不能提交或完成。');
  }
  const missingCount = stocktake.lines.filter((line) => line.countedQty == null).length;
  if (missingCount) throw requestError(400, `还有 ${missingCount} 条库存未填写实盘数量。`);
}

function releaseStocktakeFreeze(data, stocktake, sourceStatus = '已取消') {
  const warehouse = ensureWarehouse(data);
  const now = shanghaiDateTime();
  (stocktake.lines || []).forEach((line) => {
    const row = warehouse.inventory.find((candidate) => candidate.key === line.inventoryKey);
    if (!row) return;
    const unit = line.uom || inventoryUnit(row);
    row.frozenNumber = Math.max(0, inventoryNumber(row, 'frozenNumber', 'frozen') - Number(line.frozenQty || 0));
    row.freezeSources ||= [];
    const freezeSource = row.freezeSources.find((source) => (
      source.sourceDoc === stocktake.code && source.sourceLineId === line.inventoryKey
    ));
    if (freezeSource) {
      freezeSource.quantityNumber = 0;
      freezeSource.qty = formatQty(0, unit);
      freezeSource.status = sourceStatus;
    }
    refreshInventoryRow(row, unit);
    row.lastMovement = `盘点取消 ${stocktake.code}`;
    row.updatedAt = now;
  });
}

function completeStocktakeToStock(data, stocktake, actor) {
  const warehouse = ensureWarehouse(data);
  const now = shanghaiDateTime();
  (stocktake.lines || []).forEach((line) => {
    const row = warehouse.inventory.find((candidate) => candidate.key === line.inventoryKey);
    if (!row) throw requestError(409, `${line.item || line.materialCode}的库存记录不存在，不能完成盘点。`);
    const resultingQualified = Math.max(
      0,
      inventoryNumber(row, 'qualifiedOnHandNumber', 'qualifiedOnHand') + Number(line.differenceQty || 0),
    );
    const occupied = inventoryNumber(row, 'reservedNumber', 'reserved')
      + inventoryNumber(row, 'allocatedNumber', 'allocated');
    if (resultingQualified + 0.0001 < occupied) {
      throw requestError(
        409,
        `${line.item || line.materialCode}实盘后合格库存 ${formatQty(resultingQualified, line.uom)} 低于销售预留和生产分配 ${formatQty(occupied, line.uom)}，请先处理占用或登记库存异常。`,
      );
    }
  });
  (stocktake.lines || []).forEach((line) => {
    const row = warehouse.inventory.find((candidate) => candidate.key === line.inventoryKey);
    if (!row) throw requestError(409, `${line.item || line.materialCode}的库存记录不存在，不能完成盘点。`);
    const unit = line.uom || inventoryUnit(row);
    const difference = Number(line.differenceQty || 0);
    row.frozenNumber = Math.max(0, inventoryNumber(row, 'frozenNumber', 'frozen') - Number(line.frozenQty || 0));
    row.freezeSources ||= [];
    const freezeSource = row.freezeSources.find((source) => (
      source.sourceDoc === stocktake.code && source.sourceLineId === line.inventoryKey
    ));
    if (freezeSource) {
      freezeSource.quantityNumber = 0;
      freezeSource.qty = formatQty(0, unit);
      freezeSource.status = '已解除';
    }
    row.onHandNumber = Math.max(0, inventoryNumber(row, 'onHandNumber', 'onHand') + difference);
    row.qualifiedOnHandNumber = Math.max(
      0,
      inventoryNumber(row, 'qualifiedOnHandNumber', 'qualifiedOnHand') + difference,
    );
    refreshInventoryRow(row, unit);
    row.status = row.availableNumber > 0 ? '正常' : '不足';
    row.lastMovement = `盘点${difference >= 0 ? '盘盈' : '盘亏'} ${stocktake.code}`;
    row.updatedAt = now;
    if (Math.abs(difference) > 0.0001) {
      appendLedger(
        warehouse,
        row,
        {
          lineId: line.lineId || '',
          sourceLineId: '',
          materialCode: line.materialCode,
          name: line.item,
          batch: line.batch,
        },
        difference,
        unit,
        stocktake.code,
        difference > 0 ? '盘盈' : '盘亏',
        actor,
        now,
      );
    }
  });
}

function appendProductionIssueFlow(data, code, action, remark, actor = '仓库主管') {
  const warehouse = ensureWarehouse(data);
  warehouse.productionIssueFlowRecords[code] = [
    ...(warehouse.productionIssueFlowRecords[code] || []),
    { time: shanghaiDateTime(), actor, action, remark },
  ];
}

function appendProductionReturnFlow(data, code, action, remark, actor = '仓库主管') {
  const warehouse = ensureWarehouse(data);
  warehouse.productionReturnFlowRecords[code] = [
    ...(warehouse.productionReturnFlowRecords[code] || []),
    { time: shanghaiDateTime(), actor, action, remark },
  ];
}

function productionReleaseForIssue(data, releaseCode) {
  return ensureProduction(data).workOrderReleases.find((item) => item.code === releaseCode);
}

function productionIssueProducts(data, release) {
  const warehouse = ensureWarehouse(data);
  return (release.materialAllocations || []).map((allocation, index) => {
    const row = warehouse.inventory.find((item) => item.key === allocation.inventoryKey)
      || warehouse.inventory.find((item) => (
        item.materialCode === allocation.materialCode
        && (!allocation.batch || item.batch === allocation.batch)
        && (!allocation.warehouseCode || item.warehouseCode === allocation.warehouseCode)
      ));
    const quantity = Number(allocation.allocatedQty || 0);
    const unit = allocation.unit || inventoryUnit(row);
    const controls = materialControlSnapshot(data, {
      materialCode: allocation.materialCode,
      name: allocation.materialName,
    });
    return {
      lineId: `${release.code}-MAT-${String(index + 1).padStart(2, '0')}`,
      materialCode: allocation.materialCode || '',
      sourceLineId: allocation.lineId || '',
      name: allocation.materialName || allocation.materialCode || '',
      qty: formatQty(quantity, unit),
      batch: allocation.batch || row?.batch || '',
      ...controls,
      uom: unit,
      plannedQty: quantity,
      postedQty: 0,
      inventoryKey: allocation.inventoryKey || row?.key || '',
      warehouseCode: allocation.warehouseCode || row?.warehouseCode || '',
      warehouse: row?.warehouse || '',
    };
  });
}

function normalizeProductionIssue(data, input, existing) {
  const warehouse = ensureWarehouse(data);
  const releaseCode = String(input.releaseBatch || input.releaseBatchCode || existing?.releaseBatch || '').trim();
  const release = productionReleaseForIssue(data, releaseCode);
  if (!release) throw requestError(404, `释放批次 ${releaseCode || '-'} 不存在。`);
  if (release.releaseStatus !== '已释放') throw requestError(409, `释放批次 ${release.code} 尚未释放，不能办理生产领料。`);
  if (release.materialStatus === '已领料') throw requestError(409, `释放批次 ${release.code} 已完成领料，不能重复建单。`);
  if (!Array.isArray(release.materialAllocations) || !release.materialAllocations.length) {
    throw requestError(409, `释放批次 ${release.code} 没有有效生产分配，不能办理领料。`);
  }

  if (existing) {
    if (existing.status !== '草稿') throw requestError(409, `生产领料单 ${existing.code} 已提交，不能覆盖。`);
    const expectedRevision = Number(input.revision);
    if (!Number.isInteger(expectedRevision) || expectedRevision !== Number(existing.revision || 0)) {
      throw requestError(409, `生产领料单 ${existing.code} 已更新，请刷新后重试。`);
    }
  } else {
    const duplicate = warehouse.productionIssues.find((item) => item.releaseBatch === release.code && !['已作废', '已取消'].includes(item.status));
    if (duplicate) throw requestError(409, `释放批次 ${release.code} 已有生产领料单 ${duplicate.code}，请继续处理原单。`);
  }

  const allocations = productionIssueProducts(data, release);
  if (allocations.some((item) => !item.materialCode || !item.uom || item.plannedQty <= 0)) {
    throw requestError(409, `释放批次 ${release.code} 的生产分配不完整，不能生成领料单。`);
  }
  const firstInventory = warehouse.inventory.find((item) => item.key === allocations[0]?.inventoryKey);
  const sourceWarehouses = allocations
    .map((item) => warehouse.inventory.find((row) => row.key === item.inventoryKey))
    .filter(Boolean);
  const sourceWarehouseCodes = [...new Set(sourceWarehouses.map((row) => row.warehouseCode).filter(Boolean))];
  const sourceWarehouseNames = [...new Set(sourceWarehouses.map((row) => row.warehouse).filter(Boolean))];
  sourceWarehouses.forEach((inventoryRow) => {
    const sourceWarehouse = warehouseMeta(data, inventoryRow.warehouseCode, inventoryRow.warehouse);
    if (!sourceWarehouse.code || sourceWarehouse.status !== '启用' || sourceWarehouse.allowProductionIssue !== true) {
      throw requestError(409, `仓库“${inventoryRow.warehouse || inventoryRow.warehouseCode || '-'}”当前不能承担生产领料。`);
    }
  });
  const releaseLine = String(release.line || '生产').trim();
  const targetWarehouse = releaseLine.endsWith('线') ? `${releaseLine}边仓` : `${releaseLine} 线边仓`;
  const code = existing?.code || nextDocumentCode(data, 'warehouse-production-issues', warehouse.productionIssues, 'WM2');
  return {
    ...(existing || {}),
    code,
    moveType: '生产领料',
    direction: '出库',
    reason: '生产领料',
    workOrder: release.workOrderCode,
    releaseBatch: release.code,
    executionCard: existing?.executionCard || '',
    products: allocations,
    warehouseCode: sourceWarehouseCodes.length === 1 ? sourceWarehouseCodes[0] : String(firstInventory?.warehouseCode || ''),
    warehouse: sourceWarehouseNames.length === 1 ? sourceWarehouseNames[0] : sourceWarehouseNames.join('、') || String(firstInventory?.warehouse || '原料仓'),
    targetWarehouse,
    owner: String(input.owner || existing?.owner || '仓库主管'),
    status: existing?.status || '草稿',
    date: String(input.date || existing?.date || shanghaiDate()),
    note: Object.prototype.hasOwnProperty.call(input, 'note')
      ? String(input.note || '')
      : existing?.note || `承接释放批次 ${release.code}，过账后生成现场流转批次。`,
    attachments: Array.isArray(input.attachments) ? input.attachments : existing?.attachments || [],
    revision: Number(existing?.revision || 0) + 1,
    idempotencyKey: String(input.idempotencyKey || existing?.idempotencyKey || `${release.code}:material-issue`),
    createdAt: existing?.createdAt || shanghaiDateTime(),
    updatedAt: shanghaiDateTime(),
  };
}

function ensureProductionIssueTaskForRelease(data, release, options = {}) {
  const warehouse = ensureWarehouse(data);
  const activeIssue = warehouse.productionIssues.find((item) => (
    item.releaseBatch === release.code
    && !['已作废', '已取消'].includes(String(item.status || ''))
  ));
  if (activeIssue) {
    release.materialIssueCodes = [...new Set([...(release.materialIssueCodes || []), activeIssue.code])];
    return { issue: activeIssue, created: false };
  }

  const actor = String(options.actor || release.releasedBy || '系统');
  const issue = normalizeProductionIssue(data, {
    releaseBatch: release.code,
    owner: '仓库主管',
    note: `系统承接释放批次 ${release.code}，仓库核对实物后直接确认领料出库。`,
  }, undefined);
  issue.status = '待出库';
  issue.submittedAt = shanghaiDateTime();
  issue.updatedAt = issue.submittedAt;
  issue.revision = Number(issue.revision || 0) + 1;
  warehouse.productionIssues.unshift(issue);
  release.materialIssueCodes = [...new Set([...(release.materialIssueCodes || []), issue.code])];
  appendProductionIssueFlow(
    data,
    issue.code,
    '系统生成领料任务',
    `生产释放批次 ${release.code} 已形成仓库待出库任务；仓库无需进入生产模块建单。`,
    actor,
  );
  appendBusinessNotification(data, {
    module: '仓库',
    action: '生产领料待出库',
    title: '新的生产领料任务',
    message: `${release.workOrderCode} / ${release.code} 已生成 ${issue.code}，请核对批次与数量后确认出库。`,
    sourceDoc: issue.code,
    sourcePath: `/warehouse/production-issues/${encodeURIComponent(issue.code)}`,
    actor,
  });
  return { issue, created: true };
}

function issueAllocationInventoryRow(data, allocation) {
  const warehouse = ensureWarehouse(data);
  return warehouse.inventory.find((item) => item.key === allocation.inventoryKey)
    || warehouse.inventory.find((item) => (
      item.materialCode === allocation.materialCode
      && item.batch === allocation.batch
      && (!allocation.warehouseCode || item.warehouseCode === allocation.warehouseCode)
    ));
}

function postProductionIssueToStock(data, issue, release, idempotencyKey, actor) {
  const warehouse = ensureWarehouse(data);
  const production = ensureProduction(data);
  if (!idempotencyKey) throw requestError(400, '生产领料过账必须提供幂等键。');
  if (issue.status === '已完成') {
    if (issue.postIdempotencyKey === idempotencyKey) {
      return {
        executionCard: production.executionCards.find((item) => item.code === issue.executionCard),
        repeated: true,
      };
    }
    throw requestError(409, `生产领料单 ${issue.code} 已完成，不能重复过账。`);
  }
  if (issue.status !== '待出库') throw requestError(409, `生产领料单 ${issue.code} 当前状态为${issue.status}，不能过账。`);
  if (release.materialStatus === '已领料') throw requestError(409, `释放批次 ${release.code} 已完成领料。`);

  const allocationFacts = (release.materialAllocations || []).map((allocation) => {
    const row = issueAllocationInventoryRow(data, allocation);
    if (!row) throw requestError(409, `生产分配 ${allocation.materialCode || '-'} 的库存批次不存在。`);
    const quantity = Number(allocation.allocatedQty || 0);
    const unit = allocation.unit || inventoryUnit(row);
    if (inventoryUnit(row) !== unit) throw requestError(409, `${allocation.materialCode} 的库存单位与生产分配单位不一致。`);
    const source = (row.allocationSources || []).find((item) => item.releaseCode === release.code && item.status === '有效');
    if (!source || Number(source.quantityNumber || parseQty(source.qty)) + 0.0001 < quantity) {
      throw requestError(409, `${allocation.materialCode} 的生产分配已失效或数量不足，不能过账。`);
    }
    if (inventoryNumber(row, 'allocatedNumber', 'allocated') + 0.0001 < quantity) {
      throw requestError(409, `${allocation.materialCode} 的已分配库存不足，不能过账。`);
    }
    if (inventoryNumber(row, 'onHandNumber', 'onHand') + 0.0001 < quantity
      || inventoryNumber(row, 'qualifiedOnHandNumber', 'qualifiedOnHand') + 0.0001 < quantity) {
      throw requestError(409, `${allocation.materialCode} 的合格在库不足，不能完成生产领料。`);
    }
    return { allocation, row, source, quantity, unit };
  });

  const now = shanghaiDateTime();
  allocationFacts.forEach(({ allocation, row, source, quantity, unit }) => {
    row.onHandNumber = inventoryNumber(row, 'onHandNumber', 'onHand') - quantity;
    row.qualifiedOnHandNumber = inventoryNumber(row, 'qualifiedOnHandNumber', 'qualifiedOnHand') - quantity;
    row.allocatedNumber = inventoryNumber(row, 'allocatedNumber', 'allocated') - quantity;
    source.status = '已消耗';
    source.consumedBy = issue.code;
    source.consumedAt = now;
    refreshInventoryFactRow(row, unit);
    row.lastMovement = `生产领料 ${issue.code}`;
    row.updatedAt = now;
    appendLedger(
      warehouse,
      row,
      { materialCode: allocation.materialCode, name: allocation.materialName, batch: allocation.batch, uom: unit },
      -quantity,
      unit,
      issue.code,
      `释放批次 ${release.code} 生产领料`,
      actor,
      now,
    );
  });

  issue.products = issue.products.map((item) => ({ ...item, postedQty: Number(item.plannedQty || parseQty(item.qty)) }));
  const workOrder = production.workOrders.find((item) => item.code === release.workOrderCode);
  if (!workOrder) throw requestError(409, `释放批次 ${release.code} 的生产工单不存在。`);
  const executionCard = {
    code: nextDocumentCode(data, 'production-execution-cards', production.executionCards, 'EC2'),
    releaseBatchCode: release.code,
    workOrderCode: workOrder.code,
    productCode: workOrder.productCode || '',
    productName: workOrder.productName || workOrder.productCode || '',
    line: release.line || '待排产',
    lineType: release.lineType || '',
    shift: release.shift || '待排班',
    leader: release.leader || workOrder.owner || '生产主管',
    operator: '',
    planQty: Number(release.releasedQty || 0),
    materialStatus: '已领料',
    reportedQty: 0,
    qualifiedQty: 0,
    packedQty: 0,
    releasedInboundQty: 0,
    inboundQty: 0,
    defectQty: 0,
    unit: release.unit || workOrder.unit || '件',
    node: '待开机',
    status: '待处理',
    nextAction: '生产确认领料与开机条件后开始现场执行',
    processTemplateCode: workOrder.processTemplateCode || '',
    materialIssueCode: issue.code,
    qualityTaskCodes: [],
    reportCodes: [],
    packageRefs: [],
    revision: 0,
    createdAt: now,
    createdBy: actor,
  };
  refreshExecutionCardProcessInstances(data, executionCard);
  production.executionCards.unshift(executionCard);

  issue.status = '已完成';
  issue.executionCard = executionCard.code;
  issue.postIdempotencyKey = idempotencyKey;
  issue.postedAt = now;
  issue.postedBy = actor;
  issue.revision = Number(issue.revision || 0) + 1;
  issue.updatedAt = now;
  release.materialStatus = '已领料';
  release.executionStatus = '待开工';
  release.materialIssueCodes = [...new Set([...(release.materialIssueCodes || []), issue.code])];
  release.executionCardCodes = [...new Set([...(release.executionCardCodes || []), executionCard.code])];
  release.nextAction = '生产确认领料与开机条件后开始现场执行';
  workOrder.status = '生产中';
  workOrder.currentNode = '待开机';
  workOrder.nextStep = `流转批次 ${executionCard.code} 已生成，等待现场开机`;
  workOrder.nextAction = workOrder.nextStep;
  workOrder.updatedAt = now;
  return { executionCard, repeated: false };
}

function productionReturnLineKey(product) {
  return [product.sourceLineId || '', product.materialCode || product.name || '', product.batch || ''].join('::');
}

function productionReturnReservedQty(warehouse, materialIssueCode, product, excludeCode = '') {
  const lineKey = productionReturnLineKey(product);
  return warehouse.productionReturns
    .filter((record) => (
      record.code !== excludeCode
      && record.materialIssue === materialIssueCode
      && !['已作废', '已取消'].includes(record.status)
    ))
    .flatMap((record) => record.products || [])
    .filter((line) => productionReturnLineKey(line) === lineKey)
    .reduce((sum, line) => sum + Number(line.plannedQty || parseQty(line.qty) || 0), 0);
}

function productionIssueForReturn(data, input, existing) {
  const warehouse = ensureWarehouse(data);
  const materialIssueCode = String(
    input.materialIssue
      || input.materialIssueCode
      || existing?.materialIssue
      || '',
  ).trim();
  const issue = warehouse.productionIssues.find((item) => item.code === materialIssueCode);
  if (!issue) throw requestError(404, `原领料单 ${materialIssueCode || '-'} 不存在。`);
  if (issue.status !== '已完成') throw requestError(409, `原领料单 ${issue.code} 尚未完成出库，不能办理退料。`);
  return issue;
}

function normalizeProductionReturn(data, input, existing) {
  const warehouse = ensureWarehouse(data);
  if (existing) {
    if (existing.status !== '草稿') throw requestError(409, `生产退料单 ${existing.code} 当前为${existing.status}，不能修改。`);
    const expectedRevision = Number(input.revision);
    if (!Number.isInteger(expectedRevision) || expectedRevision !== Number(existing.revision || 0)) {
      throw requestError(409, `生产退料单 ${existing.code} 已更新，请刷新后重试。`);
    }
  }

  const issue = productionIssueForReturn(data, input, existing);
  const code = existing?.code || nextDocumentCode(data, 'warehouse-production-returns', warehouse.productionReturns, 'WMR2');
  const requestedProducts = Array.isArray(input.products) ? input.products : [];
  const products = requestedProducts
    .map((requested, index) => {
      const source = (issue.products || []).find((line) => (
        (requested.sourceLineId && line.sourceLineId === requested.sourceLineId)
        || (
          (requested.materialCode || requested.name)
          && (line.materialCode || line.name) === (requested.materialCode || requested.name)
          && (!requested.batch || line.batch === requested.batch)
        )
      ));
      if (!source) throw requestError(409, `${requested.materialCode || requested.name || `第 ${index + 1} 行`} 不属于原领料单 ${issue.code}。`);
      const quantity = Number(requested.plannedQty || parseQty(requested.qty) || 0);
      if (!Number.isFinite(quantity) || quantity <= 0) return null;
      const issuedQty = Number(source.postedQty || source.plannedQty || parseQty(source.qty) || 0);
      const reservedQty = productionReturnReservedQty(warehouse, issue.code, source, code);
      const returnableQty = Math.max(0, issuedQty - reservedQty);
      if (quantity > returnableQty + 0.0001) {
        throw requestError(409, `${source.name || source.materialCode} 最多还可退 ${formatQty(returnableQty, source.uom || '')}。`);
      }
      return {
        ...source,
        lineId: requested.lineId || `${code}-L${index + 1}`,
        sourceLineId: source.sourceLineId || source.lineId || '',
        qty: formatQty(quantity, source.uom || requested.uom || ''),
        plannedQty: quantity,
        postedQty: Number(existing?.products?.find((line) => productionReturnLineKey(line) === productionReturnLineKey(source))?.postedQty || 0),
      };
    })
    .filter(Boolean);
  if (!products.length) throw requestError(400, '请填写至少一项实际退料数量。');

  const now = shanghaiDateTime();
  return {
    ...(existing || {}),
    code,
    moveType: '生产退料',
    direction: '入库',
    reason: '生产余料退回',
    materialIssue: issue.code,
    workOrder: issue.workOrder,
    releaseBatch: issue.releaseBatch,
    executionCard: issue.executionCard || '',
    products,
    warehouseCode: String(issue.targetWarehouseCode || ''),
    warehouse: String(issue.targetWarehouse || '生产线边仓'),
    targetWarehouseCode: String(issue.warehouseCode || ''),
    targetWarehouse: String(issue.warehouse || '原料仓'),
    owner: String(input.owner || existing?.owner || '仓库主管'),
    status: existing?.status || '草稿',
    date: String(input.date || existing?.date || shanghaiDate()),
    note: String(input.note || existing?.note || ''),
    attachments: Array.isArray(input.attachments) ? input.attachments : existing?.attachments || [],
    revision: Number(existing?.revision || 0) + 1,
    createdAt: existing?.createdAt || now,
    updatedAt: now,
  };
}

function postProductionReturnToStock(data, record, idempotencyKey, actor) {
  const warehouse = ensureWarehouse(data);
  const production = ensureProduction(data);
  if (!idempotencyKey) throw requestError(400, '生产退料过账必须提供幂等键。');
  if (record.postIdempotencyKey) {
    if (record.postIdempotencyKey === idempotencyKey && record.status === '已完成') {
      return { record, repeated: true };
    }
    throw requestError(409, `生产退料单 ${record.code} 已使用其他请求完成过账。`);
  }
  if (record.status !== '待入库') throw requestError(409, `生产退料单 ${record.code} 当前为${record.status}，不能过账。`);
  const issue = productionIssueForReturn(data, record, record);
  const now = shanghaiDateTime();
  const postedProducts = record.products.map((product) => {
    const source = (issue.products || []).find((line) => productionReturnLineKey(line) === productionReturnLineKey(product));
    if (!source) throw requestError(409, `${product.name || product.materialCode} 已不在原领料单 ${issue.code} 中。`);
    const quantity = Number(product.plannedQty || parseQty(product.qty) || 0);
    const issuedQty = Number(source.postedQty || source.plannedQty || parseQty(source.qty) || 0);
    const returnedQty = productionReturnReservedQty(warehouse, issue.code, source, record.code);
    if (quantity <= 0 || quantity > Math.max(0, issuedQty - returnedQty) + 0.0001) {
      throw requestError(409, `${source.name || source.materialCode} 的退料数量已超过原领料剩余可退数量。`);
    }
    const unit = source.uom || product.uom || '';
    let row = issueAllocationInventoryRow(data, source);
    if (!row) {
      const target = inventoryTarget(data, record.targetWarehouseCode || issue.warehouseCode, record.targetWarehouse || issue.warehouse, '');
      row = findOrCreateInventoryRow(data, warehouse, source, target, source.batch || '', now, unit);
    }
    assertInventoryRowNotStocktakeFrozen(row, '办理生产退料');
    if (inventoryUnit(row) !== unit) throw requestError(409, `${source.name || source.materialCode} 的库存单位与原领料单不一致。`);
    row.onHandNumber = inventoryNumber(row, 'onHandNumber', 'onHand') + quantity;
    row.qualifiedOnHandNumber = inventoryNumber(row, 'qualifiedOnHandNumber', 'qualifiedOnHand') + quantity;
    refreshInventoryFactRow(row, unit);
    row.lastMovement = `生产退料 ${record.code}`;
    row.updatedAt = now;
    appendLedger(
      warehouse,
      row,
      source,
      quantity,
      unit,
      record.code,
      `原领料单 ${issue.code} 余料退回`,
      actor,
      now,
      { sourceMaterialIssue: issue.code },
    );
    return { ...product, postedQty: quantity };
  });

  record.products = postedProducts;
  record.status = '已完成';
  record.postIdempotencyKey = idempotencyKey;
  record.postedAt = now;
  record.postedBy = actor;
  record.revision = Number(record.revision || 0) + 1;
  record.updatedAt = now;
  issue.productionReturnCodes = [...new Set([...(issue.productionReturnCodes || []), record.code])];
  const card = production.executionCards.find((item) => item.code === record.executionCard);
  if (card) card.productionReturnCodes = [...new Set([...(card.productionReturnCodes || []), record.code])];
  return { record, issue, executionCard: card || null, repeated: false };
}

function productionReceiptReservedQty(warehouse, executionCardCode, excludeCode = '') {
  return warehouse.productionReceipts
    .filter((receipt) => (
      receipt.code !== excludeCode
      && receipt.executionCard === executionCardCode
      && !['已完成', '已作废', '已取消'].includes(receipt.status)
    ))
    .reduce((sum, receipt) => sum + Number(receipt.quantity || 0), 0);
}

function normalizeProductionReceipt(data, input, existing) {
  const warehouse = ensureWarehouse(data);
  const production = ensureProduction(data);
  if (existing && existing.status !== '草稿') {
    throw requestError(409, `完工入库单 ${existing.code} 当前为${existing.status}，不能修改。`);
  }
  const executionCardCode = String(input.executionCard || existing?.executionCard || '').trim();
  const card = production.executionCards.find((item) => item.code === executionCardCode);
  if (!card) throw requestError(409, `流转批次 ${executionCardCode || '-'} 不存在，不能创建完工入库。`);
  const release = productionReleaseForExecutionCard(production, card);
  if (!release) throw requestError(409, `流转批次 ${card.code} 未关联有效释放批次。`);
  if (card.node !== '待入库' || card.status !== '待仓库') {
    throw requestError(409, `流转批次 ${card.code} 当前为${card.node}/${card.status}，尚未通过入库抽检。`);
  }
  const code = existing?.code || nextDocumentCode(data, 'warehouse-production-receipts', warehouse.productionReceipts, 'WPR2');
  const releasedInboundQty = Number(card.releasedInboundQty || 0);
  const alreadyInboundQty = Number(card.inboundQty || 0);
  const reservedQty = productionReceiptReservedQty(warehouse, card.code, code);
  const availableQty = Math.max(0, releasedInboundQty - alreadyInboundQty - reservedQty);
  const productInput = Array.isArray(input.products) ? input.products[0] : undefined;
  const quantity = Number(parseQty(productInput?.qty) || productInput?.plannedQty || input.quantity || existing?.quantity || availableQty);
  if (!Number.isFinite(quantity) || quantity <= 0) throw requestError(400, '完工入库数量必须大于 0。');
  if (quantity > availableQty + 0.0001) {
    throw requestError(409, `流转批次 ${card.code} 当前可办理完工入库 ${formatQty(availableQty, card.unit)}。`);
  }
  if (!existing) {
    const duplicate = warehouse.productionReceipts.find((item) => (
      item.executionCard === card.code
      && !['已完成', '已作废', '已取消'].includes(String(item.status || ''))
    ));
    if (duplicate) throw requestError(409, `流转批次 ${card.code} 已有待处理完工入库单 ${duplicate.code}。`);
  }
  const controls = materialControlSnapshot(data, {
    materialCode: card.productCode || '',
    name: card.productName || card.productCode || '',
  }, existing?.products?.[0]);
  const defaultTarget = warehouseMeta(data, controls.defaultWarehouse, controls.defaultWarehouse);
  const requestedTargetCode = String(input.targetWarehouseCode || existing?.targetWarehouseCode || defaultTarget.code || 'WH-FG');
  const requestedTargetName = String(input.targetWarehouse || existing?.targetWarehouse || defaultTarget.name || '成品仓');
  const targetMeta = warehouseMeta(data, requestedTargetCode, requestedTargetName);
  if (!targetMeta.code) throw requestError(409, `成品入库仓 ${requestedTargetCode || requestedTargetName || '-'} 不存在。`);
  if (targetMeta.status && targetMeta.status !== '启用') throw requestError(409, `成品入库仓 ${targetMeta.name} 当前未启用。`);
  if (targetMeta.allowProductionReceipt !== true) throw requestError(409, `仓库 ${targetMeta.name} 不允许办理完工入库。`);
  const requestedTargetLocation = String(input.targetLocation || existing?.targetLocation || '').trim();
  if (requestedTargetLocation) {
    assertProductionReceiptDestination(data, {
      targetWarehouseCode: targetMeta.code,
      targetWarehouse: targetMeta.name,
      targetLocation: requestedTargetLocation,
    });
  }
  const productionLine = String(card.line || '').trim();
  const sourceWarehouse = productionLine
    ? productionLine.endsWith('线') ? `${productionLine}边仓` : `${productionLine}线边仓`
    : '生产线边仓';
  const now = shanghaiDateTime();
  return {
    ...(existing || {}),
    code,
    moveType: '完工入库',
    workOrder: card.workOrderCode,
    releaseBatch: card.releaseBatchCode,
    executionCard: card.code,
    qualityTaskCodes: (card.qualityTaskCodes || []).filter((taskCode) => {
      const task = production.qualityTasks.find((item) => item.code === taskCode);
      return task?.kind === '入库抽检' && ['合格', '部分合格'].includes(task.status);
    }),
    quantity,
    unit: card.unit,
    products: [{
      lineId: `${code}-L1`,
      materialCode: card.productCode || '',
      name: card.productName || card.productCode || '',
      qty: formatQty(quantity, card.unit),
      plannedQty: quantity,
      postedQty: Number(existing?.products?.[0]?.postedQty || 0),
      batch: controls.batchTracked ? card.code : '',
      ...controls,
      uom: card.unit,
    }],
    warehouseCode: '',
    warehouse: sourceWarehouse,
    targetWarehouseCode: targetMeta.code,
    targetWarehouse: targetMeta.name,
    targetLocation: requestedTargetLocation,
    owner: String(input.owner || existing?.owner || '仓库主管'),
    status: existing?.status || '草稿',
    date: String(input.date || existing?.date || shanghaiDate()),
    note: String(input.note || existing?.note || ''),
    attachments: Array.isArray(input.attachments) ? input.attachments : existing?.attachments || [],
    revision: Number(existing?.revision || 0) + 1,
    createdAt: existing?.createdAt || now,
    updatedAt: now,
  };
}

function updatePendingProductionReceiptDestination(data, input, existing) {
  if (existing.status !== '待入库') {
    throw requestError(409, `完工入库单 ${existing.code} 当前为${existing.status}，不能修改入库去向。`);
  }
  const requestedTargetCode = String(input.targetWarehouseCode || existing.targetWarehouseCode || '').trim();
  const requestedTargetName = String(input.targetWarehouse || existing.targetWarehouse || '').trim();
  const targetMeta = warehouseMeta(data, requestedTargetCode, requestedTargetName);
  const targetLocation = String(input.targetLocation || '').trim();
  const destination = {
    targetWarehouseCode: targetMeta.code || requestedTargetCode,
    targetWarehouse: targetMeta.name || requestedTargetName,
    targetLocation,
  };
  assertProductionReceiptDestination(data, destination);
  const now = shanghaiDateTime();
  return {
    ...existing,
    ...destination,
    note: String(input.note ?? existing.note ?? ''),
    attachments: Array.isArray(input.attachments) ? input.attachments : existing.attachments || [],
    revision: Number(existing.revision || 0) + 1,
    updatedAt: now,
  };
}

function ensureProductionReceiptTaskForCard(data, card, options = {}) {
  const warehouse = ensureWarehouse(data);
  const availableQty = Math.max(
    0,
    Number(card.releasedInboundQty || 0)
      - Number(card.inboundQty || 0)
      - productionReceiptReservedQty(warehouse, card.code),
  );
  const activeReceipt = warehouse.productionReceipts.find((item) => (
    item.executionCard === card.code
    && !['已完成', '已作废', '已取消'].includes(String(item.status || ''))
  ));
  if (activeReceipt) return { receipt: activeReceipt, created: false };
  if (availableQty <= 0.0001 || card.node !== '待入库' || card.status !== '待仓库') {
    return { receipt: null, created: false };
  }

  const actor = String(options.actor || '系统');
  const receipt = normalizeProductionReceipt(data, {
    executionCard: card.code,
    quantity: availableQty,
    owner: '仓库主管',
    note: `系统承接生产批次 ${card.code} 的质检放行量，仓库核对实物后直接确认入库。`,
  }, undefined);
  receipt.status = '待入库';
  receipt.submittedAt = shanghaiDateTime();
  receipt.updatedAt = receipt.submittedAt;
  receipt.revision = Number(receipt.revision || 0) + 1;
  warehouse.productionReceipts.unshift(receipt);
  card.productionReceiptCodes = [...new Set([...(card.productionReceiptCodes || []), receipt.code])];
  const release = productionReleaseForExecutionCard(ensureProduction(data), card);
  if (release) {
    release.productionReceiptCodes = [...new Set([...(release.productionReceiptCodes || []), receipt.code])];
  }
  appendProductionReceiptFlow(
    data,
    receipt.code,
    '系统生成完工入库任务',
    `生产批次 ${card.code} 已放行 ${formatQty(availableQty, card.unit)}，仓库无需进入生产或质检模块建单。`,
    actor,
  );
  appendBusinessNotification(data, {
    module: '仓库',
    action: '完工入库待确认',
    title: '新的完工入库任务',
    message: `${card.workOrderCode} / ${card.code} 已生成 ${receipt.code}，请核对实物后确认入库。`,
    sourceDoc: receipt.code,
    sourcePath: `/warehouse/production-receipts/${encodeURIComponent(receipt.code)}`,
    actor,
  });
  return { receipt, created: true };
}

function postProductionReceiptToStock(data, receipt, idempotencyKey, actor) {
  const warehouse = ensureWarehouse(data);
  const production = ensureProduction(data);
  if (!idempotencyKey) throw requestError(400, '完工入库过账必须提供幂等键。');
  if (receipt.postIdempotencyKey) {
    if (receipt.postIdempotencyKey === idempotencyKey && receipt.status === '已完成') {
      const card = production.executionCards.find((item) => item.code === receipt.executionCard);
      return { receipt, card, repeated: true };
    }
    throw requestError(409, `完工入库单 ${receipt.code} 已使用其他请求完成过账。`);
  }
  if (receipt.status !== '待入库') {
    throw requestError(409, `完工入库单 ${receipt.code} 当前为${receipt.status}，不能过账。`);
  }
  assertProductionReceiptDestination(data, receipt);
  const card = production.executionCards.find((item) => item.code === receipt.executionCard);
  if (!card) throw requestError(409, `完工入库单 ${receipt.code} 的流转批次不存在。`);
  const quantity = Number(receipt.quantity || 0);
  const availableQty = Math.max(0, Number(card.releasedInboundQty || 0) - Number(card.inboundQty || 0));
  if (quantity <= 0 || quantity > availableQty + 0.0001) {
    throw requestError(409, `流转批次 ${card.code} 当前可入库 ${formatQty(availableQty, card.unit)}。`);
  }
  const product = receipt.products[0];
  const now = shanghaiDateTime();
  const target = inventoryTarget(data, receipt.targetWarehouseCode, receipt.targetWarehouse, receipt.targetLocation);
  const batch = materialUsesBatchTracking(data, product) ? String(product.batch || card.code) : '';
  product.batch = batch;
  const row = findOrCreateInventoryRow(data, warehouse, product, target, batch, now, card.unit);
  row.onHandNumber = inventoryNumber(row, 'onHandNumber', 'onHand') + quantity;
  row.qualifiedOnHandNumber = inventoryNumber(row, 'qualifiedOnHandNumber', 'qualifiedOnHand') + quantity;
  refreshInventoryFactRow(row, card.unit);
  row.lastMovement = `完工入库 ${receipt.code}`;
  row.updatedAt = now;
  appendLedger(warehouse, row, product, quantity, card.unit, receipt.code, `流转批次 ${card.code} 完工入库`, actor, now);

  receipt.products = receipt.products.map((item) => ({ ...item, postedQty: Number(item.plannedQty || quantity) }));
  receipt.status = '已完成';
  receipt.postIdempotencyKey = idempotencyKey;
  receipt.postedAt = now;
  receipt.postedBy = actor;
  receipt.revision = Number(receipt.revision || 0) + 1;
  receipt.updatedAt = now;

  card.inboundQty = Number(card.inboundQty || 0) + quantity;
  const postprocess = executionCardPostprocessQuantityFacts(production, card);
  const executionComplete = executionCardReportingComplete(card)
    && postprocess.pendingPackagingQty <= 0.0001
    && postprocess.pendingInboundInspectionQty <= 0.0001
    && postprocess.inboundHoldQty <= 0.0001
    && postprocess.pendingInboundQty <= 0.0001;
  if (postprocess.pendingInboundQty > 0.0001) {
    card.node = '待入库';
    card.status = '待仓库';
    card.nextAction = `继续入库 ${formatQty(postprocess.pendingInboundQty, card.unit)}`;
  } else if (postprocess.inboundHoldQty > 0.0001) {
    card.node = '待抽检';
    card.status = '异常';
    card.nextAction = `继续处置入库检冻结 ${formatQty(postprocess.inboundHoldQty, card.unit)}`;
  } else if (postprocess.pendingInboundInspectionQty > 0.0001) {
    card.node = '待抽检';
    card.status = '待质检';
    card.nextAction = `完成入库抽检 ${formatQty(postprocess.pendingInboundInspectionQty, card.unit)}`;
  } else if (postprocess.pendingPackagingQty > 0.0001) {
    card.node = '待包装';
    card.status = '进行中';
    card.nextAction = `继续包装 ${formatQty(postprocess.pendingPackagingQty, card.unit)}`;
  } else {
    card.node = executionComplete ? '已入库' : '待包装';
    card.status = executionComplete ? '已完成' : '进行中';
    card.nextAction = executionComplete ? '本批次后处理与入库完成' : '继续完成本批次后处理';
  }
  card.productionReceiptCodes = [...new Set([...(card.productionReceiptCodes || []), receipt.code])];
  card.revision = Number(card.revision || 0) + 1;
  card.updatedAt = now;

  const release = productionReleaseForExecutionCard(production, card);
  if (release) {
    release.productionReceiptCodes = [...new Set([...(release.productionReceiptCodes || []), receipt.code])];
    release.inboundStatus = executionComplete
      ? '已入库'
      : postprocess.pendingInboundQty > 0.0001
        ? Number(card.inboundQty || 0) > 0 ? '部分入库' : '待入库'
        : '待放行';
    release.executionStatus = executionComplete
      ? '已完成'
      : card.status === '待仓库'
        ? '待入库'
        : card.status === '待质检'
          ? '待质检'
          : card.status === '异常'
            ? '异常'
            : '执行中';
    release.nextAction = card.nextAction;
  }
  const workOrder = production.workOrders.find((item) => item.code === card.workOrderCode);
  if (workOrder) {
    const cards = production.executionCards.filter((item) => item.workOrderCode === workOrder.code);
    const effectivePlanQty = workOrderEffectivePlanQty(workOrder, cards);
    workOrder.completedQty = cards.reduce((sum, item) => sum + Number(item.qualifiedQty || 0), 0);
    workOrder.inboundQty = cards.reduce((sum, item) => sum + Number(item.inboundQty || 0), 0);
    workOrder.acceptedShortageQty = Math.max(0, Number(workOrder.planQty || 0) - effectivePlanQty);
    workOrder.status = Number(workOrder.inboundQty || 0) + 0.0001 >= effectivePlanQty ? '已完成' : '部分入库';
    workOrder.currentNode = workOrder.status === '已完成' ? '已入库' : card.node;
    workOrder.nextStep = workOrder.status === '已完成' ? '生产工单已完成入库' : card.nextAction;
    workOrder.nextAction = workOrder.nextStep;
    workOrder.updatedAt = now;
    if (workOrder.sourceDocument) recomputeSalesOrderProgress(data, workOrder.sourceDocument);
  }
  refreshExecutionCardProcessInstances(data, card);
  return { receipt, card, repeated: false };
}

function financeInvoiceDocumentStatus(record, type) {
  if (record?.documentStatus) return String(record.documentStatus);
  const legacy = String(record?.status || '');
  if (['已作废', '已冲销', '红冲', '已红冲'].includes(legacy)) return type === 'sales' ? '已红冲' : '已冲销';
  if (type === 'sales') return ['待开票', '草稿', ''].includes(legacy) ? '待开票' : '已开票';
  return ['待收票', '草稿', ''].includes(legacy) ? '待收票' : '已收票';
}

function financeInvoiceSettlementStatus(record, type, settledAmount = parseMoney(record?.settledAmount), totalAmount = parseMoney(record?.totalAmount)) {
  const documentStatus = financeInvoiceDocumentStatus(record, type);
  if (['已红冲', '已冲销'].includes(documentStatus)) return '已冲销';
  if (settledAmount <= 0) return type === 'sales' ? '未收款' : '未付款';
  if (totalAmount > 0 && settledAmount + 0.01 >= totalAmount) return type === 'sales' ? '已收款' : '已付款';
  return type === 'sales' ? '部分收款' : '部分付款';
}

function ensureFinance(data) {
  data.finance ||= {};
  data.finance.salesInvoices ||= [];
  data.finance.purchaseInvoices ||= [];
  data.finance.receivables ||= [];
  data.finance.payables ||= [];
  data.finance.salesInvoiceFlowRecords ||= {};
  data.finance.invoiceFlowRecords ||= {};
  data.finance.receivableFlowRecords ||= {};
  data.finance.payableFlowRecords ||= {};
  data.finance.receivablePayments ||= {};
  data.finance.payablePayments ||= {};
  data.finance.salesInvoiceReversals ||= [];
  data.finance.salesRedInvoices ||= [];
  data.finance.salesRefunds ||= [];
  data.finance.afterSalesTasks ||= [];
  data.finance.salesAfterSalesAdjustments ||= [];
  data.finance.purchaseAfterSalesAdjustments ||= [];
  data.finance.supplierRefunds ||= [];
  data.finance.salesRefundFlowRecords ||= {};
  data.finance.salesInvoices.forEach((invoice) => {
    const sourceOrder = ensureSales(data).orders.find((order) => (
      order.code === (invoice.sourceOrder || invoice.sourceDoc)
    ));
    if (sourceOrder) {
      invoice.companyCode ||= sourceOrder.companyCode || '';
      invoice.company ||= sourceOrder.company || '';
      invoice.taxMode ||= sourceOrder.taxMode || '含税';
    }
    const documentStatus = financeInvoiceDocumentStatus(invoice, 'sales');
    const linked = data.finance.receivables.filter((record) => record.sourceDoc === invoice.code && record.status !== '已作废');
    const settledAmount = linked.length
      ? linked.reduce((sum, record) => sum + parseMoney(record.settledAmount), 0)
      : documentStatus === '待开票' ? 0 : parseMoney(invoice.settledAmount);
    invoice.documentStatus = documentStatus;
    invoice.settlementStatus = financeInvoiceSettlementStatus(invoice, 'sales', settledAmount, parseMoney(invoice.totalAmount));
    invoice.status = documentStatus;
    invoice.settledAmount = money(Math.min(settledAmount, parseMoney(invoice.totalAmount)));
  });
  data.finance.purchaseInvoices.forEach((invoice) => {
    const sourceReceipt = ensureWarehouse(data).purchaseReceipts.find((receipt) => receipt.code === invoice.sourceDoc);
    const sourceOrder = ensurePurchase(data).orders.find((order) => (
      order.code === (invoice.sourceOrder || sourceReceipt?.sourceDoc)
    ));
    if (sourceOrder) {
      invoice.companyCode ||= sourceReceipt?.companyCode || sourceOrder.companyCode || '';
      invoice.company ||= sourceReceipt?.company || sourceOrder.company || '';
      invoice.taxMode ||= sourceOrder.taxMode || '含税';
    }
    const documentStatus = financeInvoiceDocumentStatus(invoice, 'purchase');
    const linked = data.finance.payables.filter((record) => record.sourceDoc === invoice.code && record.status !== '已作废');
    const settledAmount = linked.length
      ? linked.reduce((sum, record) => sum + parseMoney(record.settledAmount), 0)
      : documentStatus === '待收票' ? 0 : parseMoney(invoice.settledAmount);
    invoice.documentStatus = documentStatus;
    invoice.settlementStatus = financeInvoiceSettlementStatus(invoice, 'purchase', settledAmount, parseMoney(invoice.totalAmount));
    invoice.status = documentStatus;
    invoice.settledAmount = money(Math.min(settledAmount, parseMoney(invoice.totalAmount)));
  });
  data.finance.receivables.forEach((record) => {
    const invoice = data.finance.salesInvoices.find((item) => item.code === record.sourceDoc);
    if (!invoice) return;
    record.companyCode ||= invoice.companyCode || '';
    record.company ||= invoice.company || '';
    record.taxMode ||= invoice.taxMode || '';
    record.refundCode ||= invoice.refundCode || '';
    record.refundStatus ||= invoice.refundStatus || '';
    if (!['已作废', '已取消', '已冲销', '红冲', '已红冲'].includes(record.status)) {
      const effectiveTotal = financeEffectiveTotal(record);
      const settledAmount = parseMoney(record.settledAmount);
      record.status = settledAmount + 0.01 >= effectiveTotal
        ? '已收款'
        : settledAmount > 0 ? '部分收款' : '待收款';
    }
  });
  data.finance.payables.forEach((record) => {
    const invoice = data.finance.purchaseInvoices.find((item) => item.code === record.sourceDoc);
    if (invoice) {
      record.companyCode ||= invoice.companyCode || '';
      record.company ||= invoice.company || '';
      record.taxMode ||= invoice.taxMode || '';
    }
    if (record.status === '暂缓付款') {
      record.status = parseMoney(record.settledAmount) > 0 ? '部分付款' : '待付款';
      record.holdStatus = '已暂缓';
      record.holdReason ||= '历史暂缓记录，请在恢复付款前核对原因。';
    }
    record.holdStatus ||= '正常';
    if (!['已作废', '已取消', '已冲销'].includes(record.status)) {
      const effectiveTotal = financeEffectiveTotal(record);
      const settledAmount = parseMoney(record.settledAmount);
      record.status = settledAmount + 0.01 >= effectiveTotal
        ? '已付款'
        : settledAmount > 0 ? '部分付款' : '待付款';
    }
  });
  return data.finance;
}

function nextFinanceCode(data, rows, prefix) {
  const ruleKey =
    prefix === 'PI'
      ? 'finance-purchase-invoices'
      : prefix === 'SI'
        ? 'finance-sales-invoices'
        : prefix === 'AP'
          ? 'finance-payables'
          : prefix === 'AR'
            ? 'finance-receivables'
            : `finance-${prefix.toLowerCase()}`;
  return nextDocumentCode(data, ruleKey, rows, prefix);
}

function parseTaxRate(value) {
  const numeric = Number(String(value || '13').replace(/[^\d.-]/g, ''));
  return Number.isFinite(numeric) ? numeric / 100 : 0.13;
}

function normalizeFinanceLines(data, lines) {
  return (Array.isArray(lines) && lines.length ? lines : []).map((line, index) => {
    const enriched = enrichProduct(data, line);
    const qty = enriched.qty || '';
    const unitPrice = line.unitPrice || '';
    const amountNumber = parseQty(qty) * parseMoney(unitPrice);
    return {
      lineId: String(line.lineId || `L${index + 1}`),
      sourceOrder: String(line.sourceOrder || ''),
      sourceLineId: String(line.sourceLineId || line.orderLineId || ''),
      sourceReceiptLineId: String(line.sourceReceiptLineId || line.receiptLineId || ''),
      materialCode: enriched.materialCode,
      name: enriched.name,
      model: enriched.model,
      spec: enriched.spec,
      qty,
      unitPrice,
      amount: line.amount || money(amountNumber),
      taxRate: line.taxRate || '13%',
      uom: enriched.uom,
      imageLabel: enriched.imageLabel,
      imageTone: enriched.imageTone,
    };
  });
}

function salesInvoiceExcludedStatus(status) {
  return ['已作废', '已冲销', '红冲', '已红冲'].includes(String(status || ''));
}

function resolveOrderLineForInvoiceLine(order, line, index) {
  const orderLines = Array.isArray(order?.products) ? order.products : [];
  const sourceLineId = String(line.sourceLineId || line.orderLineId || '').trim();
  if (sourceLineId) return orderLines.find((item, lineIndex) => (item.lineId || `L${lineIndex + 1}`) === sourceLineId);

  const materialCode = String(line.materialCode || '').trim();
  const name = String(line.name || '').trim();
  const candidates = orderLines.filter((item) => (
    (materialCode && item.materialCode === materialCode)
    || (!materialCode && name && item.name === name)
  ));
  if (candidates.length === 1) return candidates[0];

  const positional = orderLines[index];
  if (
    positional
    && ((materialCode && positional.materialCode === materialCode) || (!materialCode && name && positional.name === name))
  ) return positional;
  return undefined;
}

function bindSalesInvoiceLinesToOrder(lines, order) {
  if (!order) return lines;
  return lines.map((line, index) => {
    const orderLine = resolveOrderLineForInvoiceLine(order, line, index);
    if (!orderLine) return { ...line, sourceOrder: order.code };
    const sourceLineId = orderLine.lineId || `L${order.products.indexOf(orderLine) + 1}`;
    return {
      ...line,
      sourceOrder: order.code,
      sourceLineId,
      orderQty: orderLine.qty || '',
      orderAmount: orderLine.amount || '',
    };
  });
}

function salesInvoiceAllocationSummary(data, orderCode, excludeInvoiceCode = '') {
  const sales = ensureSales(data);
  const finance = ensureFinance(data);
  const order = sales.orders.find((item) => item.code === orderCode);
  if (!order) return { order: undefined, lines: [] };

  const allocatedByLine = new Map();
  finance.salesInvoices
    .filter((invoice) => (
      invoice.code !== excludeInvoiceCode
      && !salesInvoiceExcludedStatus(invoice.status)
      && (invoice.sourceOrder === order.code || invoice.sourceDoc === order.code)
    ))
    .forEach((invoice) => {
      bindSalesInvoiceLinesToOrder(invoice.lines || [], order).forEach((line) => {
        const sourceLineId = String(line.sourceLineId || '').trim();
        if (!sourceLineId) return;
        const current = allocatedByLine.get(sourceLineId) || { qty: 0, amount: 0 };
        current.qty += parseQty(line.qty);
        current.amount += parseMoney(line.amount);
        allocatedByLine.set(sourceLineId, current);
      });
    });

  return {
    order,
    lines: (order.products || []).map((line, index) => {
      const sourceLineId = line.lineId || `L${index + 1}`;
      const allocated = allocatedByLine.get(sourceLineId) || { qty: 0, amount: 0 };
      const orderQty = parseQty(line.qty);
      const orderAmount = parseMoney(line.grossAmount || line.amount)
        || orderQty * parseMoney(line.grossUnitPrice || line.unitPrice);
      return {
        sourceOrder: order.code,
        sourceLineId,
        materialCode: line.materialCode || '',
        name: line.name || '',
        unit: line.uom || qtyUnit(line.qty) || '',
        orderQty,
        orderAmount,
        invoicedQty: allocated.qty,
        invoicedAmount: allocated.amount,
        remainingQty: Math.max(0, orderQty - allocated.qty),
        remainingAmount: Math.max(0, orderAmount - allocated.amount),
      };
    }),
  };
}

function financeTotalsByTaxMode(lines, taxMode = '含税') {
  const lineAmount = lines.reduce((sum, line) => sum + parseMoney(line.amount), 0);
  const amountNumber = taxMode === '含税'
    ? lines.reduce((sum, line) => sum + parseMoney(line.amount) / (1 + parseTaxRate(line.taxRate)), 0)
    : lineAmount;
  const taxAmountNumber = taxMode === '含税'
    ? lineAmount - amountNumber
    : lines.reduce((sum, line) => sum + parseMoney(line.amount) * parseTaxRate(line.taxRate), 0);
  const totalNumber = taxMode === '含税' ? lineAmount : amountNumber + taxAmountNumber;

  return {
    amount: money(amountNumber),
    taxAmount: money(taxAmountNumber),
    totalAmount: money(totalNumber),
  };
}

function purchaseInvoiceExcludedStatus(status) {
  return ['待收票', '草稿', '已作废', '已取消', '已冲销', '红冲', '已红冲'].includes(String(status || ''));
}

function purchaseReceiptPostedQuantity(receipt, receiptLine) {
  if (!receipt) return 0;
  const lineIndex = Math.max(0, (receipt.products || []).indexOf(receiptLine));
  return purchaseReceiptPostedQty(receipt, receiptLine, lineIndex);
}

function resolvePurchaseOrderLine(order, receiptLine, index) {
  const orderLines = Array.isArray(order?.products) ? order.products : [];
  const sourceLineId = String(receiptLine.sourceLineId || receiptLine.orderLineId || '').trim();
  if (sourceLineId) return orderLines.find((line, lineIndex) => (line.lineId || `L${lineIndex + 1}`) === sourceLineId);
  const materialCode = String(receiptLine.materialCode || '').trim();
  const name = String(receiptLine.name || '').trim();
  const candidates = orderLines.filter((line) => (
    (materialCode && line.materialCode === materialCode)
    || (!materialCode && name && line.name === name)
  ));
  if (candidates.length === 1) return candidates[0];
  const positional = orderLines[index];
  if (positional && ((materialCode && positional.materialCode === materialCode) || (!materialCode && name && positional.name === name))) {
    return positional;
  }
  return undefined;
}

function bindPurchaseInvoiceLinesToSources(lines, receipt, order) {
  if (!receipt || !order) return lines;
  return lines.map((line, index) => {
    const explicitReceiptLineId = String(line.sourceReceiptLineId || line.receiptLineId || '').trim();
    const receiptLine = explicitReceiptLineId
      ? receipt.products?.find((item, lineIndex) => (item.lineId || `L${lineIndex + 1}`) === explicitReceiptLineId)
      : receipt.products?.find((item) => item.materialCode && item.materialCode === line.materialCode)
        || receipt.products?.find((item) => item.name && item.name === line.name)
        || receipt.products?.[index];
    const receiptLineIndex = receiptLine ? receipt.products.indexOf(receiptLine) : -1;
    const orderLine = receiptLine ? resolvePurchaseOrderLine(order, receiptLine, receiptLineIndex) : undefined;
    const orderLineIndex = orderLine ? order.products.indexOf(orderLine) : -1;
    return {
      ...line,
      sourceOrder: order.code,
      sourceLineId: orderLine ? orderLine.lineId || `L${orderLineIndex + 1}` : line.sourceLineId || '',
      sourceReceiptLineId: receiptLine ? receiptLine.lineId || `L${receiptLineIndex + 1}` : line.sourceReceiptLineId || '',
      orderQty: orderLine?.qty || line.orderQty || '',
      orderAmount: orderLine?.grossAmount || orderLine?.amount || line.orderAmount || '',
      unitPrice: orderLine?.grossUnitPrice || orderLine?.unitPrice || line.unitPrice || '',
      taxRate: orderLine?.taxRate || line.taxRate || '13%',
    };
  });
}

function purchaseInvoiceMatchingSummary(data, receiptCode, excludeInvoiceCode = '') {
  const finance = ensureFinance(data);
  const receipt = ensureWarehouse(data).purchaseReceipts.find((item) => item.code === receiptCode);
  const orderCode = String(receipt?.sourceDoc || '').trim();
  const order = ensurePurchase(data).orders.find((item) => item.code === orderCode);
  const blockedReasons = [];
  const warnings = [];

  if (!receipt) blockedReasons.push(`来源采购收货 ${receiptCode || '-'} 不存在。`);
  const receiptPostedQty = receipt
    ? (receipt.products || []).reduce(
        (sum, receiptLine) => sum + purchaseReceiptPostedQuantity(receipt, receiptLine),
        0,
      )
    : 0;
  if (receipt && receiptPostedQty <= 0.0001) {
    blockedReasons.push(`采购收货 ${receipt.code} 尚未正式入库，不能确认采购发票。`);
  }
  if (receipt && !order) blockedReasons.push(`采购收货 ${receipt.code} 未关联有效采购订单。`);

  const invoicedByLine = new Map();
  if (order && receipt) {
    finance.purchaseInvoices
      .filter((invoice) => invoice.code !== excludeInvoiceCode && !purchaseInvoiceExcludedStatus(invoice.status))
      .filter((invoice) => invoice.sourceDoc === receipt.code)
      .forEach((invoice) => {
        bindPurchaseInvoiceLinesToSources(invoice.lines || [], receipt, order).forEach((line) => {
          const sourceLineId = String(line.sourceLineId || '').trim();
          if (!sourceLineId) return;
          const current = invoicedByLine.get(sourceLineId) || { qty: 0, amount: 0 };
          current.qty += parseQty(line.qty);
          current.amount += parseMoney(line.amount);
          invoicedByLine.set(sourceLineId, current);
        });
      });
  }

  const lines = order && receipt
    ? (receipt.products || []).map((receiptLine, index) => {
      const orderLine = resolvePurchaseOrderLine(order, receiptLine, index);
      const sourceLineId = orderLine?.lineId || (orderLine ? `L${order.products.indexOf(orderLine) + 1}` : '');
      const invoiced = invoicedByLine.get(sourceLineId) || { qty: 0, amount: 0 };
      const orderedQty = parseQty(orderLine?.qty || '');
      const postedQty = purchaseReceiptPostedQuantity(receipt, receiptLine);
      const orderAmount = parseMoney(orderLine?.grossAmount || orderLine?.amount)
        || orderedQty * parseMoney(orderLine?.grossUnitPrice || orderLine?.unitPrice);
      const invoiceableQty = Math.max(0, Math.min(orderedQty || postedQty, postedQty));
      const invoiceableAmount = orderedQty > 0
        ? orderAmount * (invoiceableQty / orderedQty)
        : invoiceableQty > 0 ? orderAmount : 0;
      if (!orderLine) blockedReasons.push(`收货行 ${receiptLine.materialCode || receiptLine.name || index + 1} 无法匹配采购订单明细。`);
      if (postedQty <= 0) warnings.push(`${receiptLine.name || receiptLine.materialCode || `第 ${index + 1} 行`}没有可开票的正式入库数量。`);
      return {
        sourceLineId,
        materialCode: receiptLine.materialCode || orderLine?.materialCode || '',
        name: receiptLine.name || orderLine?.name || '',
        unit: receiptLine.uom || orderLine?.uom || qtyUnit(receiptLine.qty) || '',
        orderedQty,
        postedQty,
        previouslyInvoicedQty: invoiced.qty,
        remainingQty: Math.max(0, invoiceableQty - invoiced.qty),
        unitPrice: parseMoney(orderLine?.grossUnitPrice || orderLine?.unitPrice),
        taxRate: orderLine?.taxRate || '13%',
        orderAmount,
        previouslyInvoicedAmount: invoiced.amount,
        remainingAmount: Math.max(0, invoiceableAmount - invoiced.amount),
      };
    })
    : [];

  return {
    sourceType: 'purchase-receipt',
    sourceReceipt: receipt?.code || receiptCode || '',
    sourceOrder: order?.code || orderCode,
    receiptStatus: receipt?.status || '',
    lines,
    blockedReasons: Array.from(new Set(blockedReasons)),
    warnings: Array.from(new Set(warnings)),
    matched: blockedReasons.length === 0,
  };
}

function assertPurchaseInvoiceMatch(data, invoice) {
  const matching = purchaseInvoiceMatchingSummary(data, invoice.sourceDoc, invoice.code);
  if (matching.blockedReasons.length) throw requestError(409, matching.blockedReasons[0]);
  const lineAvailability = new Map(matching.lines.map((line) => [line.sourceLineId, line]));
  const currentByLine = new Map();
  const receipt = ensureWarehouse(data).purchaseReceipts.find((item) => item.code === matching.sourceReceipt);
  const order = ensurePurchase(data).orders.find((item) => item.code === matching.sourceOrder);
  const boundLines = bindPurchaseInvoiceLinesToSources(invoice.lines || [], receipt, order);
  if (!boundLines.length) throw requestError(400, '采购发票至少需要一条有效明细。');

  boundLines.forEach((line, index) => {
    const sourceLineId = String(line.sourceLineId || '').trim();
    const available = lineAvailability.get(sourceLineId);
    if (!sourceLineId || !available) throw requestError(409, `采购发票第 ${index + 1} 行未关联有效采购与入库明细。`);
    const unit = qtyUnit(line.qty) || line.uom || '';
    if (available.unit && unit && available.unit !== unit) {
      throw requestError(409, `采购明细 ${sourceLineId} 的基础单位为 ${available.unit}，本次发票单位 ${unit} 无法核销。`);
    }
    const current = currentByLine.get(sourceLineId) || { qty: 0, amount: 0 };
    current.qty += parseQty(line.qty);
    current.amount += parseMoney(line.amount);
    currentByLine.set(sourceLineId, current);
  });

  currentByLine.forEach((current, sourceLineId) => {
    const available = lineAvailability.get(sourceLineId);
    if (current.qty <= 0 || current.amount <= 0) throw requestError(400, `采购明细 ${sourceLineId} 的本次收票数量和金额必须大于 0。`);
    if (current.qty > available.remainingQty + 0.0001) {
      throw requestError(409, `采购明细 ${sourceLineId} 正式入库后剩余可收票 ${available.remainingQty}${available.unit || ''}，本次 ${current.qty}${available.unit || ''} 超出可收票数量。`);
    }
    if (available.remainingAmount > 0 && current.amount > available.remainingAmount + 0.01) {
      throw requestError(409, `采购明细 ${sourceLineId} 剩余可收票金额 ${money(available.remainingAmount)}，本次 ${money(current.amount)} 超出采购金额。`);
    }
  });
  invoice.sourceOrder = matching.sourceOrder;
  invoice.lines = boundLines;
  return matching;
}

function normalizePurchaseInvoice(input, existing, data) {
  const finance = ensureFinance(data);
  const code =
    !isAutoGeneratedCode(input.code)
      ? String(input.code)
      : existing?.code || nextFinanceCode(data, finance.purchaseInvoices, 'PI');
  const sourceReference = String(input.sourceDoc || existing?.sourceDoc || '').trim();
  if (!sourceReference) throw requestError(400, '采购发票必须关联来源采购收货。');
  const receipt = ensureWarehouse(data).purchaseReceipts.find((row) => row.code === sourceReference);
  if (!receipt) {
    throw requestError(409, `采购发票来源 ${sourceReference} 不是有效采购收货。`);
  }
  const purchaseOrder = ensurePurchase(data).orders.find((row) => row.code === receipt?.sourceDoc);
  if (!purchaseOrder) throw requestError(409, `采购来源 ${sourceReference} 未关联有效采购订单。`);
  const supplier = ensureMasterRows(data, 'suppliers').find((row) => (
    row.code === (receipt?.supplierCode || purchaseOrder.supplierCode)
    || row.name === (receipt?.supplier || purchaseOrder.supplier)
  ));
  const invoiceDate = String(input.date || existing?.date || shanghaiDate()).trim();
  const dueDate = String(input.dueDate || existing?.dueDate || '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(invoiceDate)) throw requestError(400, '采购发票必须填写有效收票日期。');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) throw requestError(400, '采购发票必须填写有效到期日期。');
  if (dueDate < invoiceDate) throw requestError(400, '采购发票到期日期不能早于收票日期。');
  const normalizedLines = normalizeFinanceLines(data, input.lines);
  const lines = bindPurchaseInvoiceLinesToSources(normalizedLines, receipt, purchaseOrder);
  const totals = financeTotalsByTaxMode(lines, purchaseOrder?.taxMode || '含税');

  return {
    ...(existing || {}),
    code,
    ...resolveDocumentCompany(data, {
      companyCode: receipt?.companyCode || purchaseOrder.companyCode,
      company: receipt?.company || purchaseOrder.company,
    }, existing),
    sourceDoc: receipt?.code || sourceReference,
    sourceOrder: purchaseOrder.code,
    partyCode: receipt?.supplierCode || purchaseOrder.supplierCode || '',
    party: receipt?.supplier || purchaseOrder.supplier || '',
    contact: receipt?.contact || purchaseOrder.contact || '',
    contactPhone: receipt?.contactPhone || purchaseOrder.contactPhone || '',
    ...totals,
    settledAmount: existing?.settledAmount || '￥0.00',
    owner: input.owner || existing?.owner || '赵敏',
    status: financeInvoiceDocumentStatus(existing, 'purchase') || '待收票',
    documentStatus: financeInvoiceDocumentStatus(existing, 'purchase') || '待收票',
    settlementStatus: financeInvoiceSettlementStatus(existing || { status: '待收票' }, 'purchase'),
    date: invoiceDate,
    dueDate,
    invoiceType: input.invoiceType || existing?.invoiceType || '增值税专用发票',
    taxMode: purchaseOrder.taxMode || '含税',
    paymentMethod: input.paymentMethod || existing?.paymentMethod || '验收后付款',
    bankAccount: input.bankAccount || existing?.bankAccount || supplier?.bankAccount || '',
    lines,
    note: input.note || '',
  };
}

function normalizeSalesInvoice(input, existing, data) {
  const finance = ensureFinance(data);
  const code =
    !isAutoGeneratedCode(input.code)
      ? String(input.code)
      : existing?.code || nextFinanceCode(data, finance.salesInvoices, 'SI');
  const sourceOrder = String(input.sourceOrder || input.sourceDoc || existing?.sourceOrder || existing?.sourceDoc || '').trim();
  if (!sourceOrder) throw requestError(400, '销售发票必须关联来源销售订单。');
  const sourceOrderRecord = ensureSales(data).orders.find((order) => order.code === sourceOrder);
  if (!sourceOrderRecord) throw requestError(409, `销售发票来源销售订单 ${sourceOrder} 不存在。`);
  const company = ensureMasterRows(data, 'company').find((row) => (
    row.code === sourceOrderRecord.companyCode || row.name === sourceOrderRecord.company
  ))
    || ensureMasterRows(data, 'company')[0];
  const invoiceDate = String(input.date || existing?.date || shanghaiDate()).trim();
  const dueDate = String(input.dueDate || existing?.dueDate || '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(invoiceDate)) throw requestError(400, '销售发票必须填写有效开票日期。');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) throw requestError(400, '销售发票必须填写有效到期日期。');
  if (dueDate < invoiceDate) throw requestError(400, '销售发票到期日期不能早于开票日期。');
  const lines = bindSalesInvoiceLinesToOrder(normalizeFinanceLines(data, input.lines), sourceOrderRecord);
  const totals = financeTotalsByTaxMode(lines, sourceOrderRecord.taxMode || '含税');

  return {
    ...(existing || {}),
    code,
    ...resolveDocumentCompany(data, {
      companyCode: sourceOrderRecord.companyCode,
      company: sourceOrderRecord.company,
    }, existing),
    sourceDoc: sourceOrderRecord.code,
    sourceOrder,
    partyCode: sourceOrderRecord.customerCode || '',
    party: sourceOrderRecord.customer || '',
    contact: input.contact || sourceOrderRecord.contact || existing?.contact || '',
    contactPhone: input.contactPhone || sourceOrderRecord.contactPhone || existing?.contactPhone || '',
    ...totals,
    settledAmount: existing?.settledAmount || '￥0.00',
    owner: input.owner || existing?.owner || '赵敏',
    status: financeInvoiceDocumentStatus(existing, 'sales') || '待开票',
    documentStatus: financeInvoiceDocumentStatus(existing, 'sales') || '待开票',
    settlementStatus: financeInvoiceSettlementStatus(existing || { status: '待开票' }, 'sales'),
    date: invoiceDate,
    dueDate,
    invoiceType: input.invoiceType || existing?.invoiceType || '增值税专用发票',
    taxMode: sourceOrderRecord.taxMode || '含税',
    paymentMethod: input.paymentMethod || existing?.paymentMethod || '月结 30 天',
    bankAccount: input.bankAccount || existing?.bankAccount || company?.bankAccount || '',
    lines,
    note: input.note || '',
  };
}

function assertSalesInvoiceWithinOrder(data, invoice) {
  const sales = ensureSales(data);
  const finance = ensureFinance(data);
  const orderCode = String(invoice.sourceOrder || invoice.sourceDoc || '').trim();
  const order = sales.orders.find((item) => item.code === orderCode);
  if (!order) {
    throw requestError(409, `销售发票 ${invoice.code} 必须关联有效销售订单，当前来源 ${orderCode || '-'} 不存在。`);
  }
  if (salesDocumentStatus(order) !== '已确认') {
    throw requestError(409, `销售订单 ${order.code} 当前单据状态为${salesDocumentStatus(order)}，不能继续确认开票。`);
  }

  const invoiceAmount = parseMoney(invoice.totalAmount);
  if (!Number.isFinite(invoiceAmount) || invoiceAmount <= 0) {
    throw requestError(400, '销售发票价税合计必须大于 0。');
  }
  const otherInvoicedAmount = finance.salesInvoices
    .filter((item) => (
      item.code !== invoice.code
      && !salesInvoiceExcludedStatus(item.status)
      && (item.sourceOrder === order.code || item.sourceDoc === order.code)
    ))
    .reduce((sum, item) => sum + parseMoney(item.totalAmount), 0);
  const orderAmount = parseMoney(order.amount);
  if (orderAmount > 0 && otherInvoicedAmount + invoiceAmount > orderAmount + 0.01) {
    throw requestError(
      409,
      `销售订单 ${order.code} 含税金额 ${money(orderAmount)}，已开票 ${money(otherInvoicedAmount)}，本次 ${money(invoiceAmount)} 将导致超额开票。`,
    );
  }

  const availability = salesInvoiceAllocationSummary(data, order.code, invoice.code);
  const availabilityByLine = new Map(availability.lines.map((line) => [line.sourceLineId, line]));
  const currentByLine = new Map();
  bindSalesInvoiceLinesToOrder(invoice.lines || [], order).forEach((line, index) => {
    const sourceLineId = String(line.sourceLineId || '').trim();
    if (!sourceLineId || !availabilityByLine.has(sourceLineId)) {
      throw requestError(409, `销售发票第 ${index + 1} 行必须关联销售订单 ${order.code} 的有效明细行。`);
    }
    const available = availabilityByLine.get(sourceLineId);
    const lineUnit = qtyUnit(line.qty) || line.uom || '';
    if (available.unit && lineUnit && available.unit !== lineUnit) {
      throw requestError(409, `销售订单行 ${sourceLineId} 的单位为 ${available.unit}，本次开票单位 ${lineUnit} 无法直接核销。`);
    }
    const current = currentByLine.get(sourceLineId) || { qty: 0, amount: 0 };
    current.qty += parseQty(line.qty);
    current.amount += parseMoney(line.amount);
    currentByLine.set(sourceLineId, current);
  });

  currentByLine.forEach((current, sourceLineId) => {
    const available = availabilityByLine.get(sourceLineId);
    if (current.qty <= 0 || current.amount <= 0) {
      throw requestError(400, `销售订单行 ${sourceLineId} 的本次开票数量和金额必须大于 0。`);
    }
    if (current.qty > available.remainingQty + 0.0001) {
      throw requestError(
        409,
        `销售订单行 ${sourceLineId} 剩余可开 ${available.remainingQty}${available.unit || ''}，本次 ${current.qty}${available.unit || ''} 将导致超量开票。`,
      );
    }
    if (current.amount > available.remainingAmount + 0.01) {
      throw requestError(
        409,
        `销售订单行 ${sourceLineId} 剩余可开金额 ${money(available.remainingAmount)}，本次 ${money(current.amount)} 将导致超额开票。`,
      );
    }
  });
  return order;
}

function normalizePayableFromInvoice(invoice, existing, data) {
  const finance = ensureFinance(data);
  const code = existing?.code || nextFinanceCode(data, finance.payables, 'AP');
  const sourceOrder = ensurePurchase(data).orders.find((order) => order.code === invoice.sourceOrder);
  const orderPaymentHeld = sourceOrder?.paymentHoldStatus === '已暂缓';

  return {
    ...(existing || {}),
    code,
    companyCode: invoice.companyCode || '',
    company: invoice.company || '',
    sourceDoc: invoice.code,
    sourceOrder: invoice.sourceOrder || '',
    partyCode: invoice.partyCode || '',
    party: invoice.party,
    contact: invoice.contact,
    contactPhone: invoice.contactPhone || '',
    amount: invoice.amount,
    taxAmount: invoice.taxAmount,
    totalAmount: invoice.totalAmount,
    settledAmount: existing?.settledAmount || '￥0.00',
    owner: invoice.owner || existing?.owner || '赵敏',
    status: existing?.status || '待付款',
    holdStatus: existing?.holdStatus === '已暂缓' || orderPaymentHeld ? '已暂缓' : '正常',
    holdReason: existing?.holdReason || sourceOrder?.paymentHoldReason || '',
    holdAfterSaleCode: existing?.holdAfterSaleCode || sourceOrder?.paymentHoldAfterSaleCode || '',
    heldAt: existing?.heldAt || '',
    heldBy: existing?.heldBy || '',
    date: invoice.date || shanghaiDate(),
    dueDate: invoice.dueDate || '',
    invoiceType: '应付账款',
    taxMode: invoice.taxMode || '',
    paymentMethod: invoice.paymentMethod || '',
    bankAccount: invoice.bankAccount || '',
    lines: invoice.lines || [],
    note: existing?.note || `由采购发票 ${invoice.code} 生成。`,
  };
}

function normalizeReceivableFromInvoice(invoice, existing, data) {
  const finance = ensureFinance(data);
  const code = existing?.code || nextFinanceCode(data, finance.receivables, 'AR');

  return {
    ...(existing || {}),
    code,
    companyCode: invoice.companyCode || '',
    company: invoice.company || '',
    sourceDoc: invoice.code,
    sourceOrder: invoice.sourceOrder || invoice.sourceDoc || '',
    partyCode: invoice.partyCode || '',
    party: invoice.party,
    contact: invoice.contact,
    contactPhone: invoice.contactPhone || '',
    amount: invoice.amount,
    taxAmount: invoice.taxAmount,
    totalAmount: invoice.totalAmount,
    settledAmount: existing?.settledAmount || '￥0.00',
    owner: invoice.owner || existing?.owner || '赵敏',
    status: existing?.status || '待收款',
    date: invoice.date || shanghaiDate(),
    dueDate: invoice.dueDate || '',
    invoiceType: '应收账款',
    taxMode: invoice.taxMode || '',
    paymentMethod: invoice.paymentMethod || '',
    bankAccount: invoice.bankAccount || '',
    lines: invoice.lines || [],
    note: existing?.note || `由销售发票 ${invoice.code} 生成。`,
  };
}

function appendFinanceFlow(data, group, code, action, remark, actor = '系统') {
  const finance = ensureFinance(data);
  const key =
    group === 'payables'
      ? 'payableFlowRecords'
      : group === 'receivables'
        ? 'receivableFlowRecords'
        : group === 'sales-invoices'
          ? 'salesInvoiceFlowRecords'
          : 'invoiceFlowRecords';
  finance[key][code] = [
    ...(finance[key][code] || []),
    { time: shanghaiDateTime(), actor, action, remark },
  ];
}

function financeSettlementEventView(record, direction, sourceCode, index = 0) {
  const isReceipt = direction === '收款';
  return {
    code: String(record.code || `${isReceipt ? 'RCV' : 'PAY'}-HISTORY-${index + 1}`),
    ...(isReceipt ? { receivableCode: sourceCode } : { payableCode: sourceCode }),
    sourceInvoice: String(record.sourceInvoice || ''),
    sourceOrder: String(record.sourceOrder || ''),
    direction,
    amount: typeof record.amount === 'string' ? record.amount : money(Number(record.amount || 0)),
    transactionDate: String(record.transactionDate || record.date || record.receivedAt || record.paidAt || record.createdAt || '').slice(0, 10),
    method: String(record.method || record.paymentMethod || '银行转账'),
    account: String(record.account || record.bankAccount || ''),
    reference: String(record.reference || record.paymentReference || record.transactionRef || ''),
    note: String(record.note || ''),
    actor: String(record.actor || record.owner || '财务'),
    idempotencyKey: String(record.idempotencyKey || ''),
    createdAt: String(record.createdAt || record.receivedAt || record.paidAt || ''),
  };
}

function financeSettlementPayload(body, direction) {
  const transactionDate = String(body.transactionDate || '').trim().slice(0, 10);
  const method = String(body.method || body.paymentMethod || '').trim();
  const account = String(body.account || body.bankAccount || '').trim();
  const reference = String(body.reference || body.paymentReference || '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(transactionDate)) throw requestError(400, `登记${direction}必须填写有效日期。`);
  if (!method) throw requestError(400, `登记${direction}必须选择${direction}方式。`);
  if (!account) throw requestError(400, `登记${direction}必须填写${direction}账户。`);
  if (!reference) throw requestError(400, `登记${direction}必须填写银行流水号或${direction}凭证号。`);
  return {
    transactionDate,
    method,
    account,
    reference,
    note: String(body.note || '').trim(),
  };
}

function reverseSalesInvoiceFact(data, invoice, body, authenticatedActor) {
  const finance = ensureFinance(data);
  const idempotencyKey = String(body.idempotencyKey || '').trim();
  if (!idempotencyKey) throw requestError(400, '销售发票红冲必须提供幂等键。');
  const repeated = finance.salesInvoiceReversals.find((item) => item.idempotencyKey === idempotencyKey);
  if (repeated) {
    if (repeated.sourceInvoice !== invoice.code) throw requestError(409, '该红冲幂等键已被其他销售发票使用。');
    return {
      reversal: repeated,
      redInvoice: finance.salesRedInvoices.find((item) => item.code === repeated.redInvoiceCode),
      refund: finance.salesRefunds.find((item) => item.code === repeated.refundCode),
      repeated: true,
    };
  }
  if (financeInvoiceDocumentStatus(invoice, 'sales') !== '已开票') {
    throw requestError(409, `销售发票 ${invoice.code} 当前单据状态为${financeInvoiceDocumentStatus(invoice, 'sales') || '-'}，只有已确认发票可以红冲。`);
  }
  if (finance.salesInvoiceReversals.some((item) => item.sourceInvoice === invoice.code)) {
    throw requestError(409, `销售发票 ${invoice.code} 已存在红冲凭证，不能重复红冲。`);
  }
  const reason = String(body.reason || '').trim();
  if (!reason) throw requestError(400, '销售发票红冲必须填写原因。');
  const actor = authenticatedActor || '系统';
  const now = shanghaiDateTime();
  const redInvoice = {
    code: nextDocumentCode(data, 'finance-sales-red-invoices', finance.salesRedInvoices, 'CRN2'),
    sourceInvoice: invoice.code,
    sourceOrder: invoice.sourceOrder || invoice.sourceDoc || '',
    partyCode: invoice.partyCode || '',
    party: invoice.party || '',
    amount: money(-parseMoney(invoice.amount)),
    taxAmount: money(-parseMoney(invoice.taxAmount)),
    totalAmount: money(-parseMoney(invoice.totalAmount)),
    lines: (invoice.lines || []).map((line) => ({
      ...cloneJson(line, {}),
      reversalOfLineId: line.lineId || '',
      reversedQty: parseQty(line.qty),
      reversedAmount: parseMoney(line.amount),
    })),
    reason,
    status: '已生效',
    actor,
    createdAt: now,
  };
  finance.salesRedInvoices.unshift(redInvoice);

  const receivable = finance.receivables.find((item) => item.sourceDoc === invoice.code);
  const settledAmount = parseMoney(receivable?.settledAmount || invoice.settledAmount);
  let refund;
  if (settledAmount > 0) {
    refund = {
      code: nextDocumentCode(data, 'finance-sales-refunds', finance.salesRefunds, 'RF2'),
      sourceInvoice: invoice.code,
      redInvoiceCode: redInvoice.code,
      receivableCode: receivable?.code || '',
      sourceOrder: invoice.sourceOrder || invoice.sourceDoc || '',
      partyCode: invoice.partyCode || '',
      party: invoice.party || '',
      amount: money(settledAmount),
      status: '待退款',
      reason,
      owner: actor,
      createdAt: now,
    };
    finance.salesRefunds.unshift(refund);
    finance.salesRefundFlowRecords[refund.code] = [
      { time: now, actor, action: '生成退款义务', remark: `销售发票 ${invoice.code} 红冲后待退款 ${refund.amount}。` },
    ];
  }

  const reversal = {
    code: `${invoice.code}-REV-01`,
    sourceInvoice: invoice.code,
    sourceOrder: invoice.sourceOrder || invoice.sourceDoc || '',
    redInvoiceCode: redInvoice.code,
    refundCode: refund?.code || '',
    reason,
    actor,
    status: '已生效',
    idempotencyKey,
    createdAt: now,
  };
  finance.salesInvoiceReversals.unshift(reversal);
  invoice.status = '已红冲';
  invoice.documentStatus = '已红冲';
  invoice.settlementStatus = '已冲销';
  invoice.reversalCode = reversal.code;
  invoice.redInvoiceCode = redInvoice.code;
  invoice.refundCode = refund?.code || '';
  invoice.refundStatus = refund ? '待退款' : '无需退款';
  invoice.reversedAt = now;
  invoice.reversedBy = actor;
  if (receivable) {
    receivable.status = '已冲销';
    receivable.reversalCode = reversal.code;
    receivable.refundCode = refund?.code || '';
    receivable.refundStatus = refund ? '待退款' : '无需退款';
  }
  return { reversal, redInvoice, refund, repeated: false };
}

function completeSalesRefundFact(data, refund, body, authenticatedActor) {
  const idempotencyKey = String(body.idempotencyKey || '').trim();
  if (!idempotencyKey) throw requestError(400, '登记退款必须提供幂等键。');
  if (refund.status === '已退款') {
    if (refund.completionIdempotencyKey === idempotencyKey) return { refund, repeated: true };
    throw requestError(409, `退款义务 ${refund.code} 已完成，不能重复登记。`);
  }
  if (refund.status !== '待退款') throw requestError(409, `退款义务 ${refund.code} 当前状态为${refund.status}，不能登记退款。`);
  const paymentMethod = String(body.paymentMethod || '').trim();
  const transactionRef = String(body.transactionRef || '').trim();
  if (!paymentMethod) throw requestError(400, '登记退款必须填写退款方式。');
  if (!transactionRef) throw requestError(400, '登记退款必须填写外部交易流水号。');
  const actor = authenticatedActor || '系统';
  const now = shanghaiDateTime();
  refund.status = '已退款';
  refund.paymentMethod = paymentMethod;
  refund.transactionRef = transactionRef;
  refund.completionIdempotencyKey = idempotencyKey;
  refund.completedAt = now;
  refund.completedBy = actor;
  const finance = ensureFinance(data);
  const invoice = finance.salesInvoices.find((item) => item.code === refund.sourceInvoice);
  if (invoice) invoice.refundStatus = '已退款';
  const receivable = finance.receivables.find((item) => item.code === refund.receivableCode);
  if (receivable) receivable.refundStatus = '已退款';
  finance.salesRefundFlowRecords[refund.code] = [
    ...(finance.salesRefundFlowRecords[refund.code] || []),
    { time: now, actor, action: '完成退款', remark: `${paymentMethod}，外部流水 ${transactionRef}，金额 ${refund.amount}。` },
  ];
  return { refund, repeated: false };
}

function salesDocumentStatus(order) {
  if (order.documentStatus) return order.documentStatus;
  if (order.status === '草稿') return '草稿';
  if (order.status === '已作废') return '已作废';
  if (order.status === '已中断') return '已中断';
  if (order.status === '已关闭') return '已关闭';
  return '已确认';
}

function salesProductionLineStatus(line, hasQualityDispositionBlocker = false, hasPendingQualityTask = false) {
  if (line.productionDemandQty <= 0 && line.plannedQty <= 0) return '无需生产';
  const targetQty = line.productionDemandQty > 0 ? line.productionDemandQty : line.plannedQty;
  if (targetQty > 0 && line.inboundQty + 0.0001 >= targetQty) return '已入库';
  if (hasQualityDispositionBlocker) return '质量待处置';
  if (hasPendingQualityTask || line.reportedQty > line.qualifiedQty + 0.0001) return '待质检';
  if (line.inboundQty > 0) return '部分入库';
  if (line.releasedInboundQty > line.inboundQty + 0.0001) return '待入库';
  if (line.qualifiedQty > line.releasedInboundQty + 0.0001) return '待入库放行';
  if (line.reportedQty > 0 || line.releasedQty > 0) return '生产中';
  if (line.plannedQty > 0) return '待释放';
  return '待建工单';
}

function salesProductionProgressFacts(data, order) {
  const production = ensureProduction(data);
  const activeWorkOrders = production.workOrders.filter((workOrder) => (
    workOrderSourceAllocations(workOrder).some((allocation) => allocation.sourceDocument === order.code)
    && !['已作废', '已取消'].includes(workOrder.documentStatus)
  ));
  const lines = (order.products || []).map((product, index) => {
    const sourceLineId = String(product.lineId || product.sourceLineId || `L${index + 1}`);
    const legacyLinks = (product.fulfillmentLinks || []).filter((link) => (
      link.type === '生产任务' && !['已作废', '已取消'].includes(link.status)
    ));
    const workOrderProjections = activeWorkOrders.flatMap((workOrder) => {
      const allocations = workOrderSourceAllocations(workOrder).filter((allocation) => (
        allocation.sourceDocument === order.code
        && allocation.sourceLineId === sourceLineId
      ));
      const allocationQty = allocations.reduce((sum, allocation) => sum + allocation.quantity, 0);
      return allocationQty > 0 ? [{ workOrder, allocationQty }] : [];
    });
    const workOrders = workOrderProjections.map((projection) => projection.workOrder);
    const workOrderCodes = workOrders.map((workOrder) => workOrder.code);
    const releases = production.workOrderReleases.filter((release) => (
      workOrderCodes.includes(release.workOrderCode)
      && !['已取消', '已作废'].includes(release.status)
    ));
    const cards = production.executionCards.filter((card) => workOrderCodes.includes(card.workOrderCode));
    const cardCodes = new Set(cards.map((card) => card.code));
    const hasQualityDispositionBlocker = production.qualityTasks.some((task) => (
      cardCodes.has(task.sourceCard)
      && task.dispositionStatus === '待处置'
    ));
    const hasPendingQualityTask = production.qualityTasks.some((task) => (
      cardCodes.has(task.sourceCard) && ['待检', '检验中'].includes(task.status)
    ));
    const legacyCompletedQty = legacyLinks
      .filter((link) => ['已完成', '已完工', '已入库'].includes(link.status))
      .reduce((sum, link) => sum + parseQty(link.qty), 0);
    const projectedWorkOrderMetric = (workOrder, value) => {
      const projection = workOrderProjections.find((candidate) => candidate.workOrder.code === workOrder.code);
      return workOrderAllocationMetric(workOrder, { quantity: projection?.allocationQty || 0 }, value);
    };
    const productionDemandQty = legacyLinks.length
      ? legacyLinks.reduce((sum, link) => sum + parseQty(link.qty), 0)
      : workOrderProjections.reduce((sum, projection) => sum + projection.allocationQty, 0);
    const plannedQty = workOrderProjections.reduce((sum, projection) => sum + projection.allocationQty, 0);
    const releasedQty = releases.length
      ? releases.reduce((sum, release) => {
          const workOrder = workOrders.find((candidate) => candidate.code === release.workOrderCode);
          return sum + (workOrder ? projectedWorkOrderMetric(workOrder, release.releasedQty) : 0);
        }, 0)
      : 0;
    const reportedQty = cards.length
      ? cards.reduce((sum, card) => {
          const workOrder = workOrders.find((candidate) => candidate.code === card.workOrderCode);
          return sum + (workOrder ? projectedWorkOrderMetric(workOrder, card.reportedQty) : 0);
        }, 0)
      : workOrders.reduce((sum, workOrder) => sum + projectedWorkOrderMetric(workOrder, workOrder.reportedQty), 0);
    const qualifiedQty = cards.length
      ? cards.reduce((sum, card) => {
          const workOrder = workOrders.find((candidate) => candidate.code === card.workOrderCode);
          return sum + (workOrder ? projectedWorkOrderMetric(workOrder, card.qualifiedQty) : 0);
        }, 0)
      : workOrders.length
        ? workOrders.reduce((sum, workOrder) => sum + projectedWorkOrderMetric(workOrder, workOrder.completedQty), 0)
        : legacyCompletedQty;
    const releasedInboundQty = cards.length
      ? cards.reduce((sum, card) => {
          const workOrder = workOrders.find((candidate) => candidate.code === card.workOrderCode);
          return sum + (workOrder ? projectedWorkOrderMetric(workOrder, card.releasedInboundQty) : 0);
        }, 0)
      : legacyCompletedQty;
    const inboundQty = cards.length
      ? cards.reduce((sum, card) => {
          const workOrder = workOrders.find((candidate) => candidate.code === card.workOrderCode);
          return sum + (workOrder ? projectedWorkOrderMetric(workOrder, card.inboundQty) : 0);
        }, 0)
      : workOrders.length
        ? workOrders.reduce((sum, workOrder) => sum + projectedWorkOrderMetric(workOrder, workOrder.inboundQty), 0)
        : legacyCompletedQty;
    const unit = String(product.uom || qtyUnit(product.qty) || workOrders[0]?.unit || '件');
    const line = {
      sourceLineId,
      materialCode: String(product.materialCode || workOrders[0]?.productCode || ''),
      name: String(product.name || workOrders[0]?.productName || ''),
      unit,
      orderQty: parseQty(product.qty),
      productionDemandQty,
      plannedQty,
      releasedQty,
      reportedQty,
      qualifiedQty,
      releasedInboundQty,
      inboundQty,
      workOrderCodes,
      status: '',
    };
    line.status = salesProductionLineStatus(line, hasQualityDispositionBlocker, hasPendingQualityTask);
    return line;
  });
  const activeLines = lines.filter((line) => line.productionDemandQty > 0 || line.plannedQty > 0);
  let status = '无需生产';
  if (activeLines.length && activeLines.every((line) => line.status === '已入库')) status = '已入库';
  else if (activeLines.some((line) => line.status === '质量待处置')) status = '质量待处置';
  else if (activeLines.some((line) => line.status === '待质检')) status = '待质检';
  else if (activeLines.some((line) => line.inboundQty > 0)) status = '部分入库';
  else if (activeLines.some((line) => line.status === '待入库')) status = '待入库';
  else if (activeLines.some((line) => line.status === '待入库放行')) status = '待入库放行';
  else if (activeLines.some((line) => line.status === '生产中')) status = '生产中';
  else if (activeLines.some((line) => line.status === '待释放')) status = '待释放';
  else if (activeLines.length) status = '待建工单';

  const units = [...new Set(activeLines.map((line) => line.unit).filter(Boolean))];
  const sameUnit = units.length <= 1;
  const totals = sameUnit
    ? activeLines.reduce((result, line) => ({
        productionDemandQty: result.productionDemandQty + line.productionDemandQty,
        plannedQty: result.plannedQty + line.plannedQty,
        releasedQty: result.releasedQty + line.releasedQty,
        reportedQty: result.reportedQty + line.reportedQty,
        qualifiedQty: result.qualifiedQty + line.qualifiedQty,
        releasedInboundQty: result.releasedInboundQty + line.releasedInboundQty,
        inboundQty: result.inboundQty + line.inboundQty,
      }), { productionDemandQty: 0, plannedQty: 0, releasedQty: 0, reportedQty: 0, qualifiedQty: 0, releasedInboundQty: 0, inboundQty: 0 })
    : {};
  return {
    status,
    ...totals,
    ...(sameUnit && units[0] ? { unit: units[0] } : {}),
    completedQty: sameUnit ? totals.qualifiedQty : undefined,
    mixedUnits: !sameUnit,
    lineCount: activeLines.length,
    lines,
  };
}

function recomputeSalesOrderProgress(data, orderCode) {
  if (!orderCode) return;
  const sales = ensureSales(data);
  const warehouse = ensureWarehouse(data);
  const orderIndex = sales.orders.findIndex((order) => order.code === orderCode);
  if (orderIndex < 0) return;
  const order = sales.orders[orderIndex];
  const deliveryLines = salesOrderDeliveryLineFacts(data, order);
  const orderedQty = deliveryLines.reduce((sum, line) => sum + line.orderedQty, 0);
  const deliveryTargetQty = deliveryLines.reduce((sum, line) => sum + line.deliveryTargetQty, 0);
  const closedQty = deliveryLines.reduce((sum, line) => sum + line.closedQty, 0);
  const productionProgress = salesProductionProgressFacts(data, order);
  const issues = warehouse.salesIssues.filter((issue) => (
    issue.sourceOrder === orderCode && issue.status !== '已作废' && !issue.reversalCode
  ));
  const outboundQty = deliveryLines.reduce((sum, line) => sum + line.outboundQty, 0);
  const tracking = sales.outboundRequests.filter((request) => request.sourceOrder === orderCode && request.status !== '已作废');
  const activeAfterSale = sales.afterSales.find((record) => (
    record.sourceOrder === orderCode && !['已关闭', '已作废'].includes(record.status)
  ));
  const signed = tracking.length > 0 && tracking.every((request) => ['已签收', '已完成'].includes(request.status));
  const commercial = commercialFollowUpTotals(data, 'sales', order);
  const orderAmount = commercial.orderAmount;
  const invoicedAmount = commercial.invoiceAmount;
  const receivableAmount = orderAmount;
  const settledAmount = commercial.paymentAmount;
  let productionStatus = productionProgress.status;
  let deliveryStatus = outboundQty <= 0
    ? tracking.length ? '待出库' : '待分配'
    : outboundQty + 0.0001 < deliveryTargetQty
      ? '部分出库'
      : signed ? '已签收' : '待签收';
  let invoiceStatus = invoicedAmount <= 0
    ? '未开票'
    : orderAmount > 0 && invoicedAmount + 0.01 < orderAmount ? '部分开票' : '已开票';
  let paymentStatus = settledAmount <= 0
    ? '未收款'
    : receivableAmount > 0 && settledAmount + 0.01 < receivableAmount ? '部分收款' : '已收款';
  const documentStatus = salesDocumentStatus(order);
  if (documentStatus === '已关闭') {
    if (productionProgress.lineCount <= 0 && order.productionProgress?.status) {
      productionStatus = order.productionProgress.status;
    }
    if (!issues.length && !tracking.length && order.deliveryProgress?.status) {
      deliveryStatus = order.deliveryProgress.status;
    }
    if (!commercial.events.some((event) => event.kind === 'sales_invoice') && order.invoiceProgress?.status) {
      invoiceStatus = order.invoiceProgress.status;
    }
    if (!commercial.events.some((event) => event.kind === 'sales_payment') && order.paymentProgress?.status) {
      paymentStatus = order.paymentProgress.status;
    }
  }
  const today = shanghaiDate();
  const activeOrder = !['已作废', '已中断', '已关闭'].includes(documentStatus);
  const deliveryDue = String(order.delivery || '').slice(0, 10);
  const shipmentDue = String(order.plannedShipDate || '').slice(0, 10);
  const deliveryDays = deliveryDue ? Math.ceil((Date.parse(`${deliveryDue}T00:00:00+08:00`) - Date.parse(`${today}T00:00:00+08:00`)) / 86400000) : undefined;
  const shipmentDays = shipmentDue ? Math.ceil((Date.parse(`${shipmentDue}T00:00:00+08:00`) - Date.parse(`${today}T00:00:00+08:00`)) / 86400000) : undefined;
  const attentionStatus = ['已作废', '已中断'].includes(documentStatus)
    ? documentStatus
    : activeAfterSale
      ? '售后处理中'
    : order.status === '退货处理中'
      ? '售后处理中'
      : activeOrder && !signed && deliveryDays !== undefined && deliveryDays < 0
        ? '交付逾期'
        : activeOrder && outboundQty + 0.0001 < deliveryTargetQty && shipmentDays !== undefined && shipmentDays < 0
          ? '发货逾期'
          : activeOrder && !signed && deliveryDays !== undefined && deliveryDays <= 3
            ? '交付临近'
            : activeOrder && outboundQty + 0.0001 < deliveryTargetQty && shipmentDays !== undefined && shipmentDays <= 3
              ? '发货临近'
              : '正常';

  const progressFacts = {
    production: { ...productionProgress, status: productionStatus },
    delivery: {
      status: deliveryStatus,
      orderedQty,
      deliveryTargetQty,
      closedQty,
      outboundQty,
      signedQty: signed ? outboundQty : 0,
      lines: deliveryLines,
    },
    invoice: { status: invoiceStatus, orderAmount, invoicedAmount },
    payment: { status: paymentStatus, receivableAmount, settledAmount },
    attention: { status: attentionStatus },
  };
  sales.orders[orderIndex] = {
    ...order,
    documentStatus,
    productionProgress: progressFacts.production,
    deliveryProgress: progressFacts.delivery,
    invoiceProgress: progressFacts.invoice,
    paymentProgress: progressFacts.payment,
    attentionFlags: progressFacts.attention,
    progressFacts,
    commercialSummary: {
      eventIds: commercial.events.map((event) => event.id),
      invoicedAmount,
      receivableAmount,
      settledAmount,
    },
  };
  return sales.orders[orderIndex];
}

function syncSalesOrderFromFinance(data, orderCode, _status, action, remark, actor = '王倩') {
  const order = recomputeSalesOrderProgress(data, orderCode);
  if (!order) return;
  appendFlow(data, orderCode, action, remark, actor || order.owner);
}

function listFromText(value) {
  if (Array.isArray(value)) return value.map((item) => String(item).trim()).filter(Boolean);
  return String(value || '')
    .split(/[,，、/]/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function hashPassword(password) {
  const salt = randomBytes(16).toString('hex');
  const iterations = 120000;
  const updatedMs = Date.now();
  const hash = pbkdf2Sync(password, salt, iterations, 32, 'sha256').toString('hex');
  return {
    passwordSalt: salt,
    passwordHash: `pbkdf2_sha256$${iterations}$${hash}`,
    passwordUpdatedAt: shanghaiDateTime(),
    passwordUpdatedMs: updatedMs,
  };
}

function accountPasswordUpdate(input) {
  const passwordInput = String(input?.passwordInput || '');
  const passwordConfirm = String(input?.passwordConfirm || '');
  if (!passwordInput && !passwordConfirm) return undefined;
  if (passwordInput !== passwordConfirm) {
    throw requestError(400, '两次输入的密码不一致');
  }
  if (passwordInput.length < 6) {
    throw requestError(400, '密码至少需要 6 位');
  }
  return hashPassword(passwordInput);
}

function verifyPassword(password, account) {
  const passwordHash = String(account?.passwordHash || '');
  const passwordSalt = String(account?.passwordSalt || '');
  const [, iterationsText, expectedHash] = passwordHash.split('$');
  const iterations = Number(iterationsText);

  if (!passwordSalt || !expectedHash || !Number.isFinite(iterations)) return false;

  const actualHash = pbkdf2Sync(String(password || ''), passwordSalt, iterations, 32, 'sha256');
  const expectedBuffer = Buffer.from(expectedHash, 'hex');
  return actualHash.length === expectedBuffer.length && timingSafeEqual(actualHash, expectedBuffer);
}

function hasAccountPassword(account) {
  return Boolean(account?.passwordHash);
}

function tokenDigest(token) {
  return createHash('sha256').update(String(token || '')).digest('hex');
}

function numericTimestamp(value) {
  const timestamp = Number(value);
  return Number.isFinite(timestamp) && timestamp > 0 ? timestamp : 0;
}

function normalizedDateTimeText(value) {
  return String(value || '').trim().replace('T', ' ');
}

function dateTimeSortValue(value) {
  const text = normalizedDateTimeText(value);
  if (!text) return 0;
  const parsed = Date.parse(text.includes('T') ? text : text.replace(' ', 'T'));
  return Number.isFinite(parsed) ? parsed : 0;
}

function compareUpdatedRows(a, b) {
  return dateTimeSortValue(b?.updatedAt) - dateTimeSortValue(a?.updatedAt) || String(b?.code || '').localeCompare(String(a?.code || ''));
}

function sessionCreatedBeforePasswordUpdate(session, account) {
  const passwordUpdatedMs = numericTimestamp(account?.passwordUpdatedMs);
  const sessionCreatedMs = numericTimestamp(session?.createdMs);
  if (passwordUpdatedMs && sessionCreatedMs) return sessionCreatedMs < passwordUpdatedMs;

  const passwordUpdatedAt = normalizedDateTimeText(account?.passwordUpdatedAt);
  const sessionCreatedAt = normalizedDateTimeText(session?.createdAt);
  return Boolean(passwordUpdatedAt && sessionCreatedAt && sessionCreatedAt < passwordUpdatedAt);
}

function sanitizeSystemRecord(page, record) {
  if (page !== 'accounts') return { ...record };
  const {
    passwordHash,
    passwordSalt,
    passwordUpdatedMs,
    passwordInput,
    passwordConfirm,
    ...safeRecord
  } = record;
  return {
    ...safeRecord,
    passwordSet: hasAccountPassword(record),
    passwordUpdatedAt: record.passwordUpdatedAt || '',
  };
}

function sanitizeSystemRows(page, rows) {
  return rows.map((row) => sanitizeSystemRecord(page, row));
}

function findAccountEmployee(data, account) {
  const employeeRows = ensureMasterRows(data, 'employees');
  const employeeCode = String(account?.employeeCode || '').trim();
  if (employeeCode) {
    const byCode = employeeRows.find((employee) => employee.code === employeeCode);
    if (byCode) return byCode;
  }

  const accountName = String(account?.name || '').trim();
  if (accountName) {
    return employeeRows.find((employee) => employee.name === accountName);
  }

  return undefined;
}

function hydrateAccountFromEmployee(data, account) {
  const employee = findAccountEmployee(data, account);
  if (!employee) return account;

  return {
    ...account,
    employeeCode: employee.code,
    name: employee.name || account.name,
    department: employee.owner || account.department || '',
    phone: employee.contact || employee.phone || account.phone || '',
    email: employee.email || account.email || '',
  };
}

function resolveRoleCodes(data, value) {
  const roleRows = [
    ...(Array.isArray(data.system?.roles) ? data.system.roles : []),
    ...systemPageDefaults.roles,
  ];
  const codes = listFromText(value)
    .map((item) => {
      const normalizedItem = normalizedLoginName(item);
      const matchedRole = roleRows.find(
        (role) =>
          normalizedLoginName(role.code) === normalizedItem ||
          normalizedLoginName(role.name) === normalizedItem,
      );
      const aliasCode = roleDefaultAliasPairs.find(([alias]) => normalizedLoginName(alias) === normalizedItem)?.[1];
      return matchedRole?.code || aliasCode || item;
    })
    .filter(Boolean);
  return Array.from(new Set(codes)).join(',');
}

function hydrateAccountRoles(data, account) {
  return {
    ...account,
    roles: resolveRoleCodes(data, account.roles),
  };
}

