function parseLogDescription(description) {
  const text = String(description || '').trim();
  const parts = text.split(/[:：]/);
  if (parts.length > 1) {
    return {
      target: parts[0].trim(),
      remark: parts.slice(1).join('：').trim(),
    };
  }
  return {
    target: '',
    remark: text,
  };
}

const legacySystemLogPrefixLabels = [
  ['ACC-', '账号'],
  ['PERM-', '权限'],
  ['ROLE-', '角色'],
  ['MENU-', '菜单'],
  ['RULE-', '编码规则'],
  ['OPT-', '选项字典'],
  ['NOTICE-', '通知规则'],
  ['APP-', '应用'],
  ['MCP-', 'MCP 工具'],
];

function normalizeLegacySystemLogAction(name, target) {
  const action = String(name || '').trim();
  if (!['更新系统配置', '新建系统配置'].includes(action)) return action;
  const targetText = String(target || '').trim().toUpperCase();
  const label = legacySystemLogPrefixLabels.find(([prefix]) => targetText.startsWith(prefix))?.[1];
  return label ? action.replace('系统配置', label) : action;
}

function normalizeAliyunDeploymentPlanStatus(row) {
  if (row?.code !== 'APP-ALIYUN-DEPLOY' || row.status === '停用') return row;
  if (!appRequiredMissingFields(row).length) return row;
  return {
    ...row,
    status: '停用',
    healthStatus: row.healthStatus || '未检查',
    healthMessage: row.healthMessage || '请先替换真实阿里云访问入口后再启用。',
  };
}

function syncSystemMenuRows(existingRows) {
  const existingByCode = new Map(existingRows.map((row) => [row.code, row]));
  return flattenedMenuDefaults.map((defaultMenu) => {
    const existing = existingByCode.get(defaultMenu.code);
    return {
      ...defaultMenu,
      ...existing,
      name: defaultMenu.name,
      description: defaultMenu.description,
      menuKey: defaultMenu.menuKey || '',
      parentCode: defaultMenu.parentCode || '',
      path: defaultMenu.path || '',
      permissionCode: existing?.permissionCode || defaultMenu.permissionCode || '',
      sortOrder: defaultMenu.sortOrder,
      status: existing?.status || defaultMenu.status,
      updatedAt: existing?.updatedAt || shanghaiDate(),
    };
  });
}

function withoutRetiredFinanceRecipient(value, retiredCode) {
  return listFromText(value)
    .filter((code) => code !== retiredCode)
    .join(',');
}

function legacyFinanceAfterSalesCode(row) {
  const sourceText = [row?.sourceDoc, row?.message]
    .map((value) => String(value || '').trim())
    .filter(Boolean)
    .join(' ');
  return sourceText.match(/(?<![A-Z0-9])(SA|PA)-\d{8}-\d+(?![A-Z0-9-])/i)?.[0]?.toUpperCase() || '';
}

function legacyFinanceAfterSalesTarget(data, row) {
  const code = legacyFinanceAfterSalesCode(row);
  if (!code) return undefined;
  const isSales = code.startsWith('SA-');
  const records = isSales ? data.sales?.afterSales : data.purchase?.afterSales;
  if (!Array.isArray(records) || !records.some((record) => record.code === code)) return undefined;
  return {
    code,
    module: isSales ? '销售' : '采购',
    roleCode: isSales ? 'ROLE-SALES' : 'ROLE-PURCHASE',
    path: `/${isSales ? 'sales' : 'purchase'}/after-sales/${encodeURIComponent(code)}`,
  };
}

function notificationAccountCodesForRoleSnapshot(data, roleCode) {
  const accounts = Array.isArray(data.system?.accounts) ? data.system.accounts : [];
  return accounts
    .filter((account) => account.status !== '停用' && account.code !== 'ACC-FINANCE')
    .filter((account) => listFromText(resolveRoleCodes(data, account.roles)).includes(roleCode))
    .map((account) => account.code);
}

function normalizeLegacyFinanceAfterSalesNotification(data, row) {
  const sanitized = { ...row };
  if (Object.prototype.hasOwnProperty.call(row, 'targetRoles')) {
    sanitized.targetRoles = withoutRetiredFinanceRecipient(row.targetRoles, 'ROLE-FINANCE');
  }
  if (Object.prototype.hasOwnProperty.call(row, 'targetAccounts')) {
    sanitized.targetAccounts = withoutRetiredFinanceRecipient(row.targetAccounts, 'ACC-FINANCE');
  }
  if (Object.prototype.hasOwnProperty.call(row, 'readBy')) {
    sanitized.readBy = withoutRetiredFinanceRecipient(row.readBy, 'ACC-FINANCE');
  }
  if (!String(row.sourcePath || '').startsWith('/finance/after-sales/')) return sanitized;

  const target = legacyFinanceAfterSalesTarget(data, row);
  const activeAccountCodes = (data.system?.accounts || [])
    .filter((account) => account.status !== '停用' && account.code !== 'ACC-FINANCE')
    .map((account) => account.code);
  const readBy = Array.from(new Set([...listFromText(sanitized.readBy), ...activeAccountCodes])).join(',');

  if (!target) {
    return {
      ...sanitized,
      module: '系统',
      action: '历史通知归档',
      title: '历史售后处理记录',
      message: '旧财务模块通知已归档，当前没有可安全定位的业务单据。',
      sourcePath: '',
      targetRoles: '',
      targetAccounts: '',
      readBy,
      historical: true,
    };
  }

  return {
    ...sanitized,
    module: target.module,
    action: '历史售后处理结果',
    title: `${target.module}售后历史处理结果`,
    message: `${target.code} 的旧财务处理记录已归档；如需继续跟进，请在${target.module}售后中查看当前处理结果。`,
    sourceDoc: target.code,
    sourcePath: target.path,
    targetRoles: target.roleCode,
    targetAccounts: notificationAccountCodesForRoleSnapshot(data, target.roleCode).join(','),
    readBy,
    historical: true,
  };
}

function ensureSystem(data) {
  data.system ||= {};
  for (const [page, rows] of Object.entries(systemPageDefaults)) {
    const existingRows = Array.isArray(data.system[page]) ? data.system[page] : [];
    rows.forEach((row) => {
      const index = existingRows.findIndex((existing) => existing.code === row.code);
      if (index >= 0) {
        existingRows[index] = { ...row, ...existingRows[index], updatedAt: existingRows[index].updatedAt || shanghaiDate() };
      } else {
        existingRows.push({ ...row, updatedAt: shanghaiDate() });
      }
    });
    if (page === 'menus') {
      data.system[page] = syncSystemMenuRows(existingRows);
      continue;
    }
    if (page === 'naming-rules') {
      data.system[page] = existingRows.map((row) => {
        const isLegacyWarehouseRule = row.code === 'RULE-WH';
        const defaultRule =
          namingRuleDefaults.find((rule) => rule.code === row.code) ||
          namingRuleDefaults.find((rule) => rule.ruleKey === row.ruleKey);
        const prefix = isLegacyWarehouseRule ? 'WH' : normalizeCodePrefix(row.prefix, defaultRule?.prefix || 'DOC');
        const dateFormat = normalizeDateFormat(row.dateFormat || defaultRule?.dateFormat);
        const sequenceLength = normalizeSequenceLength(row.sequenceLength ?? defaultRule?.sequenceLength);
        return {
          ...row,
          name: isLegacyWarehouseRule ? '仓库单据（旧规则）' : row.name,
          status: isLegacyWarehouseRule ? '停用' : row.status,
          description: isLegacyWarehouseRule
            ? '旧版通用仓库编码规则已拆分为采购入库、销售出库、其他出入库、调拨和盘点规则。'
            : row.description,
          ruleKey: isLegacyWarehouseRule
            ? 'warehouse-legacy'
            : row.ruleKey || defaultRule?.ruleKey || row.code.toLowerCase().replace(/^rule-/, ''),
          prefix,
          dateFormat,
          sequenceLength,
          sampleCode: sampleNamingCode({ prefix, dateFormat, sequenceLength }),
        };
      });
      continue;
    }
    if (page === 'accounts') {
      data.system[page] = existingRows
        .filter((row) => row.code !== 'ACC-FINANCE')
        .map((row) => hydrateAccountRoles(data, hydrateAccountFromEmployee(data, row)));
      continue;
    }
    if (page === 'apps') {
      data.system[page] = existingRows.map((row) => normalizeAliyunDeploymentPlanStatus(row));
      continue;
    }
    if (page === 'notifications') {
      data.system[page] = existingRows.map((row) => {
        const normalized = row.code === 'NOTICE-STOCK-POSTED'
          ? {
              ...row,
              receiverRoles: 'ROLE-WAREHOUSE',
              description: '库存过账按来源单据定向提醒对应岗位；内部调拨和其他出入库只提醒仓库。',
            }
          : row;
        return {
          ...normalized,
          receiverRoles: withoutRetiredFinanceRecipient(normalized.receiverRoles, 'ROLE-FINANCE'),
        };
      });
      continue;
    }
    data.system[page] = existingRows;
  }
  const supportedPermissionCodes = new Set(permissionDefaults.map((permission) => permission.code));
  if (Array.isArray(data.system.permissions)) {
    data.system.permissions = permissionDefaults.map((defaultPermission) => {
      const existing = data.system.permissions.find((permission) => permission.code === defaultPermission.code);
      const status =
        defaultPermission.code === systemPermissionCode
          ? '启用'
          : existing?.status === '停用'
            ? '停用'
            : defaultPermission.status;
      return {
        ...defaultPermission,
        name: existing?.name || defaultPermission.name,
        owner: existing?.owner || defaultPermission.owner,
        description: existing?.description || defaultPermission.description,
        status,
        updatedAt: existing?.updatedAt || shanghaiDate(),
      };
    });
  }
  if (Array.isArray(data.system.roles)) {
    data.system.roles = data.system.roles
      .filter((role) => role.code !== 'ROLE-FINANCE')
      .map((role) => ({
        ...role,
        permissions: listFromText(role.permissions)
          .filter((permissionCode) => supportedPermissionCodes.has(permissionCode))
          .join(','),
      }));
  }
  if (Array.isArray(data.system.logs)) {
    data.system.logs = data.system.logs.map((row) => {
      const legacy = parseLogDescription(row.description);
      const target = row.target || legacy.target || row.code || '';
      return {
        ...row,
        name: normalizeLegacySystemLogAction(row.name, target),
        target,
        remark: row.remark || legacy.remark || row.description || '',
        sourceAccount: row.sourceAccount || row.owner || '',
        sourceIp: row.sourceIp || '',
      };
    }).slice(0, 500);
  }
  const currentPermissionSchemaVersion = Number(data.system.permissionSchemaVersion || 0);
  if (currentPermissionSchemaVersion < 3 && Array.isArray(data.system.menus)) {
    data.system.menus = data.system.menus.map((menu) => {
      if ((menu.code?.startsWith('MENU-WAREHOUSE') || menu.path?.startsWith('/warehouse')) && menu.permissionCode === 'PERM-WAREHOUSE-POST') {
        return { ...menu, permissionCode: 'PERM-WAREHOUSE-VIEW' };
      }
      return menu;
    });
  }
  if (currentPermissionSchemaVersion < systemPermissionSchemaVersion) {
    if (Array.isArray(data.system.permissions)) {
      const defaultPermissionByCode = new Map(permissionDefaults.map((permission) => [permission.code, permission]));
      data.system.permissions = data.system.permissions.map((permission) => {
        const defaultPermission = defaultPermissionByCode.get(permission.code);
        if (!defaultPermission) return permission;
        return {
          ...permission,
          module: defaultPermission.module,
          description: defaultPermission.description,
        };
      });
    }
    if (Array.isArray(data.system.notifications)) {
      data.system.notifications = data.system.notifications.map((notification) => (
        notification.triggerModule === '电商'
          ? { ...notification, status: '停用' }
          : notification
      ));
    }
    if (Array.isArray(data.system.menus)) {
      const defaultMenuByCode = new Map(flattenedMenuDefaults.map((menu) => [menu.code, menu]));
      data.system.menus = data.system.menus.map((menu) => {
        const defaultMenu = defaultMenuByCode.get(menu.code);
        return defaultMenu
          ? {
              ...menu,
              sortOrder: defaultMenu.sortOrder,
              status: defaultMenu.status === '停用' ? '停用' : menu.status,
            }
          : menu;
      });
    }
    if (currentPermissionSchemaVersion < rolePermissionUpgradeSchemaVersion) {
      data.system.roles = (data.system.roles || []).map((role) => {
        const upgradePermissions = defaultRolePermissionUpgrades[role.code];
        if (!upgradePermissions) return role;

        const mergedPermissions = new Set(listFromText(role.permissions));
        upgradePermissions.forEach((permission) => mergedPermissions.add(permission));
        return {
          ...role,
          permissions: Array.from(mergedPermissions).join(','),
        };
      });
    }
    data.system.permissionSchemaVersion = systemPermissionSchemaVersion;
  }
  if (!Array.isArray(data.system.notificationInbox)) {
    data.system.notificationInbox = [];
  }
  data.system.notificationInbox = data.system.notificationInbox
    .map((row) => normalizeLegacyFinanceAfterSalesNotification(data, row));
  if (!Array.isArray(data.system.sessions)) {
    data.system.sessions = [];
  }
  return data.system;
}

function requestAccountKey(req) {
  return String(req.headers['x-filatrix-account'] || '').trim();
}

function requestSessionToken(req) {
  const header = String(req.headers.authorization || '').trim();
  const matched = header.match(/^Bearer\s+(.+)$/i);
  return matched?.[1]?.trim() || '';
}

function passwordLoginRequired(data) {
  const activeAccounts = (Array.isArray(data?.system?.accounts) ? data.system.accounts : []).filter((row) => row.status !== '停用');
  return activeAccounts.some((row) => hasAccountPassword(row));
}

function pruneExpiredSessions(system) {
  const now = Date.now();
  system.sessions = (system.sessions || []).filter((session) => !session.expiresAt || Date.parse(session.expiresAt) > now);
}

function accountForSessionToken(req, data) {
  const token = requestSessionToken(req);
  if (!token) return undefined;

  const system = ensureSystem(data);
  pruneExpiredSessions(system);
  const digest = tokenDigest(token);
  const session = system.sessions.find((row) => row.tokenHash === digest);
  if (!session) return undefined;

  const account = system.accounts.find((row) => row.code === session.accountCode && row.status !== '停用');
  if (!account || sessionCreatedBeforePasswordUpdate(session, account)) return undefined;

  return account;
}

function createAccountSession(data, account) {
  const system = ensureSystem(data);
  pruneExpiredSessions(system);
  const token = randomBytes(32).toString('hex');
  const nowMs = Date.now();
  const now = shanghaiDateTime();
  account.lastLogin = now;
  system.sessions.unshift({
    tokenHash: tokenDigest(token),
    accountCode: account.code,
    createdAt: now,
    createdMs: nowMs,
    expiresAt: new Date(nowMs + 1000 * 60 * 60 * 12).toISOString(),
  });
  system.sessions = system.sessions.slice(0, 100);
  return token;
}

function clearAccountSession(req, data) {
  const token = requestSessionToken(req);
  if (!token) return;

  const system = ensureSystem(data);
  const digest = tokenDigest(token);
  system.sessions = (system.sessions || []).filter((row) => row.tokenHash !== digest);
}

function clearSessionsForAccount(data, accountCode) {
  const code = String(accountCode || '').trim();
  if (!code) return 0;

  const system = ensureSystem(data);
  const before = (system.sessions || []).length;
  system.sessions = (system.sessions || []).filter((row) => row.accountCode !== code);
  return before - system.sessions.length;
}

function activeAccountForRequest(req, data) {
  const system = ensureSystem(data);
  const token = requestSessionToken(req);
  if (token) return accountForSessionToken(req, data);

  const accountKey = requestAccountKey(req);
  const requestedAccount = accountKey
    ? system.accounts.find(
        (account) =>
          account.status !== '停用' &&
          accountIdentityMatches(account, accountKey),
      )
    : undefined;

  if (accountKey && (!passwordLoginRequired(data) || process.env.FILATRIX_ALLOW_ACCOUNT_HEADER === 'true')) {
    return requestedAccount;
  }

  if (passwordLoginRequired(data)) return undefined;

  return (
    system.accounts.find((account) => account.code === defaultAdminAccountCode && account.status !== '停用') ||
    system.accounts.find((account) => account.username === 'zhangsan' && account.status !== '停用') ||
    system.accounts.find((account) => account.status !== '停用')
  );
}

function requestSourceIp(req) {
  return String(req.headers['x-forwarded-for'] || req.socket?.remoteAddress || '')
    .split(',')[0]
    .trim();
}

function accountAuditName(account) {
  if (!account) return '系统';
  return [account.name, account.code].filter(Boolean).join(' / ');
}

function businessActorDisplayName(value, fallback = '') {
  return String(value || '')
    .replace(/\s*\/\s*ACC-[A-Z0-9-]+\s*$/i, '')
    .trim() || fallback;
}

function businessActorName(req, data) {
  const account = activeAccountForRequest(req, data);
  return account?.name || account?.code || '系统';
}

function permissionUsageSummary(data, permissionCode) {
  const system = ensureSystem(data);
  return {
    roles: system.roles
      .filter((role) => role.status !== '停用' && role.code !== adminRoleCode && listFromText(role.permissions).includes(permissionCode))
      .map((role) => role.name || role.code),
    menus: system.menus
      .filter((menu) => menu.status !== '停用' && menu.permissionCode === permissionCode)
      .map((menu) => menu.name || menu.code),
  };
}

function summarizedNameList(names, limit = 5) {
  const visibleNames = names.slice(0, limit);
  return names.length > visibleNames.length ? `${visibleNames.join('、')} 等 ${names.length} 个` : visibleNames.join('、');
}

function permissionStopReferenceSummary(data, usage, dependentOperationCodes) {
  return [
    usage.roles.length ? `启用角色：${summarizedNameList(usage.roles)}` : '',
    usage.menus.length ? `启用菜单：${summarizedNameList(usage.menus)}` : '',
    dependentOperationCodes.length
      ? `启用操作权限：${summarizedNameList(dependentOperationCodes.map((code) => permissionDisplayName(data, code)))}`
      : '',
  ].filter(Boolean).join('；');
}

function roleStopReferenceSummary(usage) {
  return [
    usage.accounts.length ? `启用账号：${summarizedNameList(usage.accounts)}` : '',
    usage.notifications.length ? `启用通知规则：${summarizedNameList(usage.notifications)}` : '',
  ].filter(Boolean).join('；');
}

function roleUsageSummary(data, roleCode) {
  const system = ensureSystem(data);
  return {
    accounts: system.accounts
      .filter((account) => account.status !== '停用')
      .filter((account) => listFromText(resolveRoleCodes(data, account.roles)).includes(roleCode))
      .map((account) => account.name || account.code),
    notifications: system.notifications
      .filter((notification) => notification.status !== '停用')
      .filter((notification) => listFromText(resolveRoleCodes(data, notification.receiverRoles)).includes(roleCode))
      .map((notification) => notification.name || notification.code),
  };
}

function activeAccountsLinkedToEmployee(data, employeeCode, employeeName = '') {
  const system = ensureSystem(data);
  const normalizedEmployeeCode = String(employeeCode || '').trim();
  const normalizedEmployeeName = String(employeeName || '').trim();
  return system.accounts.filter((account) => {
    if (account.status === '停用') return false;
    if (normalizedEmployeeCode && String(account.employeeCode || '').trim() === normalizedEmployeeCode) return true;
    return !account.employeeCode && normalizedEmployeeName && String(account.name || '').trim() === normalizedEmployeeName;
  });
}

function employeeHasActiveRole(data, employee, roleCode) {
  return activeAccountsLinkedToEmployee(data, employee?.code, employee?.name)
    .some((account) => listFromText(resolveRoleCodes(data, account.roles)).includes(roleCode));
}

function employeeHasActivePermission(data, employee, permissionCode) {
  return activeAccountsLinkedToEmployee(data, employee?.code, employee?.name)
    .some((account) => accountPermissionCodesForAccount(data, account).has(permissionCode));
}

function normalizeAfterSalesOwnerAssignment(data, kind, record) {
  const roleCode = kind === 'sales' ? 'ROLE-SALES' : 'ROLE-PURCHASE';
  const employees = ensureMasterRows(data, 'employees');
  const findEmployee = (employeeCode, employeeName) => employees.find((employee) => (
    (employeeCode && employee.code === employeeCode)
    || (employeeName && employee.name === employeeName)
  ));
  const eligible = (employee) => (
    employee
    && employee.status !== '停用'
    && employeeHasActiveRole(data, employee, roleCode)
  );
  const current = findEmployee(record.ownerEmployeeCode, record.owner);
  if (eligible(current)) {
    record.owner = current.name;
    record.ownerEmployeeCode = current.code;
    return;
  }

  const orders = kind === 'sales' ? data.sales?.orders || [] : data.purchase?.orders || [];
  const sourceOrder = orders.find((order) => order.code === record.sourceOrder);
  const replacement = afterSalesOwnerForSource(data, kind, sourceOrder);
  if (!replacement) return;
  record.owner = replacement.name;
  record.ownerEmployeeCode = replacement.code;
}

function afterSalesOwnerForSource(data, kind, sourceOrder = {}) {
  const roleCode = kind === 'sales' ? 'ROLE-SALES' : 'ROLE-PURCHASE';
  const employees = ensureMasterRows(data, 'employees');
  const sourceOwner = employees.find((employee) => (
    (sourceOrder.ownerEmployeeCode && employee.code === sourceOrder.ownerEmployeeCode)
    || (sourceOrder.owner && employee.name === sourceOrder.owner)
  ));
  if (sourceOwner && sourceOwner.status !== '停用' && employeeHasActiveRole(data, sourceOwner, roleCode)) {
    return sourceOwner;
  }
  return employees
    .filter((employee) => employee.status !== '停用' && employeeHasActiveRole(data, employee, roleCode))
    .sort((left, right) => {
      const roleAccountRank = (employee) => {
        const accounts = activeAccountsLinkedToEmployee(data, employee.code, employee.name)
          .filter((account) => listFromText(resolveRoleCodes(data, account.roles)).includes(roleCode));
        return accounts.some((account) => !listFromText(resolveRoleCodes(data, account.roles)).includes(adminRoleCode)) ? 0 : 1;
      };
      return roleAccountRank(left) - roleAccountRank(right) || String(left.code).localeCompare(String(right.code));
    })[0];
}

function normalizedLoginName(value) {
  return String(value || '').trim().toLowerCase();
}

function canonicalLoginUsername(value) {
  return normalizedLoginName(value);
}

function validateLoginUsernameFormat(username) {
  if (/^[a-z0-9._-]+$/.test(username)) return;
  throw requestError(400, '登录账号只能使用字母、数字、点、下划线和短横线。');
}

function accountIdentityMatches(account, identifier) {
  const key = String(identifier || '').trim();
  if (!account || !key) return false;
  return account.code === key || normalizedLoginName(account.username) === normalizedLoginName(key);
}

function accountUniquenessConflict(rows, code, username, employeeCode) {
  const normalizedUsername = normalizedLoginName(username);
  const normalizedCode = normalizedLoginName(code);
  const normalizedEmployeeCode = String(employeeCode || '').trim();
  const duplicateUsername = rows.find(
    (row) => row.code !== code && normalizedLoginName(row.username) === normalizedUsername,
  );
  if (duplicateUsername) {
    return `登录账号 ${username} 已被 ${duplicateUsername.name || duplicateUsername.code} 使用。`;
  }

  const duplicateIdentityCode = rows.find(
    (row) => row.code !== code && normalizedLoginName(row.code) === normalizedUsername,
  );
  if (duplicateIdentityCode) {
    return `登录账号 ${username} 与账号编码 ${duplicateIdentityCode.code} 冲突，请换一个登录账号。`;
  }

  const duplicateCodeUsername = rows.find(
    (row) => row.code !== code && normalizedLoginName(row.username) === normalizedCode,
  );
  if (duplicateCodeUsername) {
    return `账号编码 ${code} 与登录账号 ${duplicateCodeUsername.username} 冲突，请换一个账号编码。`;
  }

  if (normalizedEmployeeCode) {
    const duplicateEmployee = rows.find(
      (row) => row.code !== code && String(row.employeeCode || '').trim() === normalizedEmployeeCode,
    );
    if (duplicateEmployee) {
      return `员工 ${normalizedEmployeeCode} 已关联账号 ${duplicateEmployee.name || duplicateEmployee.code}。`;
    }
  }

  return '';
}

function accountPermissionCodesForAccount(data, account) {
  const system = ensureSystem(data);
  if (!account) return new Set();

  const activeRoles = activeRoleRowsForAccount(data, account);
  const activePermissionCodes = new Set(
    system.permissions.filter((permission) => permission.status !== '停用').map((permission) => permission.code),
  );
  const permissionCandidates = new Set();

  activeRoles.forEach((role) => {
    listFromText(role.permissions).forEach((permission) => {
      if (activePermissionCodes.has(permission)) permissionCandidates.add(permission);
    });
  });

  if (activeRoles.some((role) => role.code === adminRoleCode)) {
    activePermissionCodes.forEach((permission) => permissionCandidates.add(permission));
  }

  return effectivePermissionCodeSet(Array.from(permissionCandidates), activePermissionCodes);
}

function accountPermissionCodes(req, data) {
  return accountPermissionCodesForAccount(data, activeAccountForRequest(req, data));
}

function menuRowsForRequest(data, rows, actor) {
  if (!actor && passwordLoginRequired(data)) return [];

  const permissions = accountPermissionCodesForAccount(data, actor);
  if (permissions.has(systemPermissionCode)) return rows;

  function canSeeMenuRow(row, trail = new Set()) {
    if (!row || row.status === '停用') return false;
    const requiredPermissions = menuRequiredPermissionCodesForRow(rows, row);
    if (requiredPermissions.some((permissionCode) => !permissions.has(permissionCode))) return false;
    if (!row.parentCode) return true;
    if (trail.has(row.code)) return false;
    const parent = rows.find((candidate) => candidate.code === row.parentCode);
    return canSeeMenuRow(parent, new Set([...trail, row.code]));
  }

  return rows.filter((row) => {
    if (row.status === '停用') return false;
    return canSeeMenuRow(row);
  });
}

function menuRequiredPermissionCodesForRow(rows, row) {
  const parentPermissionCode = row.parentCode
    ? rows.find((parent) => parent.code === row.parentCode)?.permissionCode
    : '';
  return Array.from(
    new Set([
      menuRequiredPermissionForPath(row.path),
      parentPermissionCode,
      row.permissionCode,
    ].filter(Boolean)),
  );
}

function apiMenuPathForParts(parts) {
  const moduleKey = parts[1];
  if (!routeMenuModuleKeys.has(moduleKey)) return '';
  if (moduleKey === 'system' && parts[2] === 'menus') return '';
  if (!parts[2]) return `/${moduleKey}`;
  return `/${moduleKey}/${parts[2]}`;
}

function closestMenuRecordForPath(rows, path) {
  const normalizedPath = String(path || '').replace(/\/$/, '') || '/';
  return [...rows]
    .filter((row) => row.path && (normalizedPath === row.path || normalizedPath.startsWith(`${row.path}/`)))
    .sort((a, b) => {
      const pathLengthDiff = String(b.path || '').length - String(a.path || '').length;
      if (pathLengthDiff) return pathLengthDiff;
      return menuDepth(rows, b) - menuDepth(rows, a);
    })[0];
}

function menuDepth(rows, row, trail = new Set()) {
  if (!row?.parentCode || trail.has(row.code)) return 0;
  const parent = rows.find((candidate) => candidate.code === row.parentCode);
  return parent ? 1 + menuDepth(rows, parent, new Set([...trail, row.code])) : 0;
}

function disabledMenuInPath(rows, row, trail = new Set()) {
  if (!row) return undefined;
  if (row.status === '停用') return row;
  if (!row.parentCode || trail.has(row.code)) return undefined;
  const parent = rows.find((candidate) => candidate.code === row.parentCode);
  return disabledMenuInPath(rows, parent, new Set([...trail, row.code]));
}

function activeChildMenusForMenu(rows, code) {
  return rows.filter((row) => row.code !== code && row.parentCode === code && row.status !== '停用');
}

function activeChildMenuSummaryForMenu(rows) {
  const names = rows.slice(0, 5).map((row) => row.name || row.code);
  return rows.length > names.length ? `${names.join('、')} 等 ${rows.length} 个` : names.join('、');
}

async function requireEnabledMenuPathAudited(req, data, parts) {
  if (['OPTIONS'].includes(req.method)) return;
  if (isPublicReadPath(parts)) return;

  const menuPath = apiMenuPathForParts(parts);
  if (!menuPath) return;

  const system = ensureSystem(data);
  const row = closestMenuRecordForPath(system.menus, menuPath);
  const disabledMenu = disabledMenuInPath(system.menus, row);
  if (!disabledMenu) return;

  const message = `菜单 ${disabledMenu.name || disabledMenu.code} 已停用，不能直接访问 ${menuPath}。`;
  await auditPermissionDenied(req, data, disabledMenu.code, message);
  throw requestError(403, message);
}

function dataWithProposedSystemRecord(data, page, record, index) {
  const system = ensureSystem(data);
  const rows = Array.isArray(system[page]) ? system[page] : [];
  return {
    ...data,
    system: {
      ...system,
      [page]: rows.map((row, rowIndex) => (rowIndex === index ? record : row)),
    },
  };
}

function dataWithSystemRows(data, page, rows) {
  const system = ensureSystem(data);
  return {
    ...data,
    system: {
      ...system,
      [page]: rows,
    },
  };
}

function assertEnabledAccountsHaveEffectivePermissions(data, accounts) {
  const proposedData = dataWithSystemRows(data, 'accounts', accounts);
  const brokenAccounts = accounts.filter(
    (account) => account.status !== '停用' && !accountPermissionCodesForAccount(proposedData, account).size,
  );
  if (brokenAccounts.length) {
    throw requestError(
      400,
      `以下启用账号必须至少拥有一个有效权限：${summarizedNameList(
        brokenAccounts.map((account) => account.name || account.code),
      )}。请先调整角色权限或账号角色后再保存。`,
    );
  }
}

function passwordLoginRequiredForAccounts(accounts) {
  return accounts.some((account) => account.status !== '停用' && hasAccountPassword(account));
}

function assertPasswordLoginHasSystemManager(data, accounts) {
  const proposedData = dataWithSystemRows(data, 'accounts', accounts);
  if (!passwordLoginRequiredForAccounts(accounts)) return;

  const manager = accounts.find(
    (account) =>
      account.status !== '停用' &&
      hasAccountPassword(account) &&
      accountPermissionCodesForAccount(proposedData, account).has(systemPermissionCode),
  );
  if (!manager) {
    throw requestError(400, '启用密码登录后必须至少保留一个已设置密码且拥有系统配置维护权限的账号。');
  }
}

function assertActorKeepsSystemConfig(data, page, record, index, actor) {
  if (!actor?.code) return;
  if (!['accounts', 'roles', 'permissions'].includes(page)) return;
  if (!accountPermissionCodesForAccount(data, actor).has(systemPermissionCode)) return;

  const proposedData = dataWithProposedSystemRecord(data, page, record, index);
  const proposedSystem = ensureSystem(proposedData);
  const proposedActor = proposedSystem.accounts.find((account) => account.code === actor.code);
  const keepsSystemConfig =
    proposedActor &&
    proposedActor.status !== '停用' &&
    accountPermissionCodesForAccount(proposedData, proposedActor).has(systemPermissionCode);

  if (!keepsSystemConfig) {
    throw requestError(400, '不能移除当前账号的系统配置维护权限，请先保留另一个可用管理员账号后再调整。');
  }
}

function systemPermissionRows(data) {
  return data?.system?.permissions || permissionDefaults;
}

function activeSystemPermissionCodes(data) {
  return new Set(systemPermissionRows(data).filter((permission) => permission.status !== '停用').map((permission) => permission.code));
}

function validateActivePermissionCodes(data, permissionCodes, contextLabel) {
  const permissionRows = systemPermissionRows(data);
  const knownPermissionCodes = new Set(permissionRows.map((permission) => permission.code));
  const activePermissionCodes = activeSystemPermissionCodes(data);
  const invalidPermissionCodes = permissionCodes.filter((permissionCode) => !knownPermissionCodes.has(permissionCode));
  if (invalidPermissionCodes.length) {
    throw requestError(400, `${contextLabel}包含不存在的权限点：${invalidPermissionCodes.join('、')}。`);
  }

  const disabledPermissionCodes = permissionCodes.filter((permissionCode) => !activePermissionCodes.has(permissionCode));
  if (disabledPermissionCodes.length) {
    throw requestError(400, `${contextLabel}不能绑定已停用的权限点：${disabledPermissionCodes.join('、')}。`);
  }
}

const operationPermissionCodeSet = new Set(Object.keys(operationPermissionDependencies));

function isOperationPermissionCode(permissionCode) {
  return operationPermissionCodeSet.has(String(permissionCode || ''));
}

function effectivePermissionCodeSet(permissionCodes, activePermissionCodes) {
  const selectedPermissionCodes = new Set(permissionCodes.filter((permissionCode) => activePermissionCodes.has(permissionCode)));
  return new Set(
    Array.from(selectedPermissionCodes).filter((permissionCode) =>
      (operationPermissionDependencies[permissionCode] || []).every((dependency) => selectedPermissionCodes.has(dependency)),
    ),
  );
}

function permissionDisplayName(data, permissionCode) {
  return systemPermissionRows(data).find((permission) => permission.code === permissionCode)?.name || permissionCode;
}

function permissionDisplayLabel(data, permissionCodeOrCodes) {
  return listFromText(permissionCodeOrCodes)
    .map((permissionCode) => `${permissionDisplayName(data, permissionCode)}（${permissionCode}）`)
    .join('、');
}

function validateOperationPermissionDependencies(data, permissionCodes, contextLabel) {
  const selectedPermissionCodes = new Set(permissionCodes);
  const missingDependencies = Object.entries(operationPermissionDependencies)
    .filter(([operationPermission]) => selectedPermissionCodes.has(operationPermission))
    .map(([operationPermission, dependencies]) => ({
      operationPermission,
      dependencies: dependencies.filter((dependency) => !selectedPermissionCodes.has(dependency)),
    }))
    .filter((item) => item.dependencies.length);

  if (!missingDependencies.length) return;

  const message = missingDependencies
    .map(
      (item) =>
        `${permissionDisplayName(data, item.operationPermission)} 需要 ${item.dependencies
          .map((dependency) => permissionDisplayName(data, dependency))
          .join('、')}`,
    )
    .join('；');
  throw requestError(400, `${contextLabel}操作权限缺少基础权限：${message}。`);
}

function activeDependentOperationPermissions(data, permissionCode) {
  const activePermissionCodes = activeSystemPermissionCodes(data);
  return Object.entries(operationPermissionDependencies)
    .filter(([operationPermission, dependencies]) => (
      activePermissionCodes.has(operationPermission) &&
      dependencies.includes(permissionCode)
    ))
    .map(([operationPermission]) => operationPermission);
}

function systemRoleRows(data) {
  const rows = data?.system?.roles;
  return Array.isArray(rows) && rows.length ? rows : systemPageDefaults.roles;
}

function activeSystemRoleCodes(data) {
  return new Set(systemRoleRows(data).filter((role) => role.status !== '停用').map((role) => role.code));
}

function systemRoleDisplayName(data, roleCode) {
  return systemRoleRows(data).find((role) => role.code === roleCode)?.name || roleCode;
}

function notificationNoTargetAccountMessage(data, receiverRoles) {
  const roleNames = receiverRoles.map((roleCode) => systemRoleDisplayName(data, roleCode));
  return `接收角色 ${summarizedNameList(roleNames)} 当前没有匹配启用账号，请先为这些角色分配启用账号或调整接收角色。`;
}

function validateActiveRoleCodes(data, roleCodes, contextLabel) {
  const roleRows = systemRoleRows(data);
  const knownRoleCodes = new Set(roleRows.map((role) => role.code));
  const activeRoleCodes = activeSystemRoleCodes(data);
  const invalidRoleCodes = roleCodes.filter((roleCode) => !knownRoleCodes.has(roleCode));
  if (invalidRoleCodes.length) {
    throw requestError(400, `${contextLabel}包含不存在的角色：${invalidRoleCodes.join('、')}。`);
  }

  const disabledRoleCodes = roleCodes.filter((roleCode) => !activeRoleCodes.has(roleCode));
  if (disabledRoleCodes.length) {
    throw requestError(400, `${contextLabel}不能绑定已停用的角色：${disabledRoleCodes.join('、')}。`);
  }
}

function validateSupportedNotificationTrigger(triggerModule, triggerAction) {
  const actions = notificationActionOptionsByModule[triggerModule] || [];
  if (!actions.includes(triggerAction)) {
    throw requestError(400, `通知规则只能选择当前系统已接通的触发动作：${triggerModule || '-'} / ${triggerAction || '-'}。`);
  }
}

function notificationChannelUnsupportedMessage() {
  return `当前系统只支持${notificationChannelOptions.join('、')}通知，邮件和企业微信通道暂未接通。`;
}

function isSupportedNotificationChannel(channel) {
  return notificationChannelOptions.includes(channel);
}

function activeRoleRowsForAccount(data, account) {
  const system = ensureSystem(data);
  if (!account) return [];
  const assignedRoleCodes = new Set(listFromText(resolveRoleCodes(data, account.roles)));
  return system.roles.filter((role) => role.status !== '停用' && assignedRoleCodes.has(role.code));
}

function accountRoleContext(data, account) {
  const roleRows = activeRoleRowsForAccount(data, account);
  return {
    roleCodes: roleRows.map((role) => role.code),
    roleRows,
    roleNames: roleRows.map((role) => role.name),
  };
}

function notificationTargetAccountsFromRows(data, accounts, targetRoles) {
  const targetRoleSet = new Set(listFromText(targetRoles));
  if (!targetRoleSet.size) return [];

  return accounts
    .filter((account) => account.status !== '停用')
    .filter((account) => {
      const { roleCodes } = accountRoleContext(data, account);
      return roleCodes.some((roleCode) => targetRoleSet.has(roleCode));
    })
    .map((account) => account.code);
}

function assertEnabledNotificationsHaveRecipients(data, accounts) {
  const system = ensureSystem(data);
  const brokenRules = system.notifications.filter(
    (notification) =>
      notification.status !== '停用' &&
      !notificationTargetAccountsFromRows(data, accounts, notification.receiverRoles).length,
  );
  if (brokenRules.length) {
    throw requestError(
      400,
      `以下启用通知规则必须至少匹配一个启用账号：${summarizedNameList(brokenRules.map((rule) => rule.name || rule.code))}。请先调整接收角色或账号角色后再保存。`,
    );
  }
}

function sessionAccountSummary(account) {
  return {
    code: account.code,
    employeeCode: account.employeeCode || '',
    username: account.username || '',
    name: account.name || '',
    department: account.department || '',
    status: account.status || '',
    passwordSet: hasAccountPassword(account),
    passwordUpdatedAt: account.passwordUpdatedAt || '',
  };
}

function sessionContext(req, data, accountOverride) {
  const system = ensureSystem(data);
  const account = accountOverride || activeAccountForRequest(req, data);
  if (!account) {
    throw requestError(passwordLoginRequired(data) ? 401 : 403, passwordLoginRequired(data) ? '请先登录。' : '当前账号不存在或已停用。');
  }

  const permissions = Array.from(accountPermissionCodesForAccount(data, account));
  const { roleCodes, roleNames } = accountRoleContext(data, account);
  const activeAccounts = system.accounts.filter((row) => row.status !== '停用');
  const setupMode = activeAccounts.length > 0 && activeAccounts.every((row) => !hasAccountPassword(row));
  const canManageSystem = permissions.includes(systemPermissionCode);
  const accountOptions = (setupMode || canManageSystem ? activeAccounts : [account]).map(sessionAccountSummary);
  const permissionLabels = Object.fromEntries(system.permissions.map((permission) => [permission.code, permission.name || permission.code]));

  return {
    account: sessionAccountSummary(account),
    accountOptions,
    setupMode,
    roles: roleNames,
    roleCodes,
    permissions,
    permissionLabels,
  };
}

function modulePermissionForPath(parts, access = 'read') {
  const moduleKey = parts[1];
  const permissions = access === 'write' ? routeModuleWritePermissionCodes : routeModuleReadPermissionCodes;
  return permissions[moduleKey] || '';
}

function isPublicReadPath(parts) {
  if (parts[1] === 'health' || parts[1] === 'session') return true;
  if (parts[1] === 'reference') return true;
  if (parts[1] === 'system' && parts[2] === 'menus') return true;
  return false;
}

function operationPermissionForPath(req, parts) {
  if (req.method !== 'POST') return '';

  const moduleKey = parts[1];
  const action = parts.at(-1);
  if (!action) return '';

  const rule = operationPermissionRouteRules.find(
    (candidate) =>
      candidate?.module === moduleKey &&
      Array.isArray(candidate.actions) &&
      candidate.actions.includes(action),
  );
  return rule ? operationPermissionCodes[rule.permissionKey] || rule.permissionCode || '' : '';
}

function referencePermissionCodesForType(type) {
  const permissions = referencePermissionCodes[type];
  return Array.isArray(permissions) ? permissions : [];
}

async function requireReferencePermissionAudited(req, data, type, account) {
  const allowedPermissions = referencePermissionCodesForType(type);
  if (!allowedPermissions.length) return;

  const permissions = accountPermissionCodesForAccount(data, account);
  if (allowedPermissions.some((permissionCode) => permissions.has(permissionCode))) return;

  const permissionLabel = permissionDisplayLabel(data, allowedPermissions);
  const message = `当前账号没有 ${permissionLabel} 权限，不能读取 ${type} 候选列表。`;
  await auditPermissionDenied(req, data, permissionLabel, message);
  throw requestError(403, message);
}

function menuRequiredPermissionForPath(path) {
  const normalizedPath = String(path || '').trim();
  if (!normalizedPath.startsWith('/')) return '';
  return modulePermissionForPath(['api', ...normalizedPath.split('/').filter(Boolean)], 'read');
}

function validateMenuPermissionMatchesPath(data, record) {
  if (record.status === '停用') return;
  const requiredPermission = menuRequiredPermissionForPath(record.path);
  if (!requiredPermission || record.permissionCode === requiredPermission) return;
  const requiredPermissionLabel = permissionDisplayLabel(data, requiredPermission);
  const currentPermissionLabel = record.permissionCode ? permissionDisplayLabel(data, record.permissionCode) : '空权限';
  throw requestError(
    400,
    `菜单路径 ${record.path || '-'} 必须绑定 ${requiredPermissionLabel} 权限，不能绑定 ${currentPermissionLabel}。`,
  );
}

function validateMenuPermissionIsNotOperation(data, record) {
  if (!record.permissionCode || !isOperationPermissionCode(record.permissionCode)) return;
  throw requestError(
    400,
    `菜单入口不能绑定操作权限：${permissionDisplayLabel(data, record.permissionCode)}。请在角色权限中配置确认、过账或收付款。`,
  );
}

async function requireReadPermissionAudited(req, data, parts) {
  if (req.method !== 'GET') return;
  if (isPublicReadPath(parts)) return;

  const permissionCode = modulePermissionForPath(parts, 'read');
  if (!permissionCode) return;
  if (accountPermissionCodes(req, data).has(permissionCode)) return;

  const permissionLabel = permissionDisplayLabel(data, permissionCode);
  const message = `当前账号没有 ${permissionLabel} 权限，不能查看该数据。`;
  await auditPermissionDenied(req, data, permissionLabel, message);
  throw requestError(403, message);
}

async function requireWritePermissionAudited(req, data, parts) {
  if (['GET', 'OPTIONS'].includes(req.method)) return;

  const permissionCode = modulePermissionForPath(parts, 'write');
  if (!permissionCode) return;
  if (accountPermissionCodes(req, data).has(permissionCode)) return;

  const permissionLabel = permissionDisplayLabel(data, permissionCode);
  const message = `当前账号没有 ${permissionLabel} 权限，不能执行该操作。`;
  await auditPermissionDenied(req, data, permissionLabel, message);
  throw requestError(403, message);
}

async function requireOperationPermissionAudited(req, data, parts) {
  const permissionCode = operationPermissionForPath(req, parts);
  if (!permissionCode) return;
  if (accountPermissionCodes(req, data).has(permissionCode)) return;

  const permissionLabel = permissionDisplayLabel(data, permissionCode);
  const message = `当前账号没有 ${permissionLabel} 操作权限，不能执行该动作。`;
  await auditPermissionDenied(req, data, permissionLabel, message);
  throw requestError(403, message);
}

const systemMenuPageKeys = (menuDefaults.find((menu) => menu.menuKey === 'system')?.children || [])
  .map((child) => String(child.path || '').split('/').filter(Boolean)[1])
  .filter(Boolean);
const readOnlySystemPages = new Set(
  Array.isArray(systemPageBehavior.readOnlyPages) ? systemPageBehavior.readOnlyPages : ['logs'],
);
const nonCreatableSystemPages = new Set(
  Array.isArray(systemPageBehavior.nonCreatablePages) ? systemPageBehavior.nonCreatablePages : [],
);
const systemApiPages = new Set(systemMenuPageKeys);
const systemLifecyclePages = new Set(systemMenuPageKeys.filter((page) => !readOnlySystemPages.has(page)));

function normalizeSystemStatus(page, inputStatus, existingStatus) {
  const fallback = systemLifecyclePages.has(page) ? '启用' : '正常';
  const status = inputStatus ?? existingStatus ?? fallback;
  if (systemLifecyclePages.has(page) && !['启用', '停用'].includes(status)) {
    throw requestError(400, '系统配置状态只能选择启用或停用。');
  }
  return status;
}

function canonicalSystemCode(value) {
  return String(value || '').trim().toUpperCase();
}

function systemCodePrefixForPage(page) {
  return systemCodePrefixes[page] || page
    .split('-')
    .map((part) => part.slice(0, 3).toUpperCase())
    .join('-');
}

function nextSystemRecordCode(page, rows) {
  const prefix = systemCodePrefixForPage(page);
  const matchPrefix = `${prefix}-`;
  const maxSequence = rows.reduce((max, row) => {
    const code = String(row.code || '').trim().toUpperCase();
    if (!code.startsWith(matchPrefix)) return max;
    const sequence = Number(code.slice(matchPrefix.length));
    return Number.isInteger(sequence) && sequence > max ? sequence : max;
  }, 0);
  return `${prefix}-${String(maxSequence + 1).padStart(4, '0')}`;
}

function validateSystemCodeFormat(page, code) {
  if (/^[A-Z0-9]+(?:-[A-Z0-9]+)*$/.test(code)) return;
  throw requestError(400, `${systemPageLogLabel(page)}编码只能使用大写字母、数字和短横线，且不能以短横线开头或结尾。`);
}

function isPlaceholderSystemConfigValue(value) {
  return /<[^>]+>|待填写|请填写|TBD/i.test(String(value || '').trim());
}

function appRequiredMissingFields(record) {
  const runtimeMode = String(record.runtimeMode || '').trim();
  const publicUrl = String(record.publicUrl || '').trim();
  const apiBase = String(record.apiBase || '').trim();
  const healthPath = String(record.healthPath || '').trim();
  const dataStore = String(record.dataStore || '').trim();
  const missing = [];
  if (!runtimeMode) missing.push('运行方式');
  if (!publicUrl && !apiBase) {
    missing.push('访问入口或 API 地址');
  } else {
    if (publicUrl && isPlaceholderSystemConfigValue(publicUrl)) missing.push('真实访问入口');
    if (apiBase && isPlaceholderSystemConfigValue(apiBase)) missing.push('真实 API 地址');
  }
  if (!healthPath) {
    missing.push('健康检查路径');
  } else if (isPlaceholderSystemConfigValue(healthPath)) {
    missing.push('真实健康检查路径');
  }
  if (!dataStore) {
    missing.push('数据位置');
  } else if (isPlaceholderSystemConfigValue(dataStore)) {
    missing.push('真实数据位置');
  }
  return missing;
}

function appUrlFormatIssues(record) {
  const publicUrl = String(record.publicUrl || '').trim();
  const apiBase = String(record.apiBase || '').trim();
  const healthPath = String(record.healthPath || '').trim();
  const issues = [];

  if (publicUrl && !parseHttpUrl(publicUrl)) {
    issues.push('访问入口必须是有效的 HTTP/HTTPS 地址');
  }
  if (apiBase && !apiBase.startsWith('/') && !parseHttpUrl(apiBase)) {
    issues.push('API 地址必须是 / 开头的相对路径或有效的 HTTP/HTTPS 地址');
  }
  if (healthPath) {
    const hasUnsupportedProtocol = /^[a-z][a-z0-9+.-]*:\/\//i.test(healthPath) && !parseHttpUrl(healthPath);
    if (/\s/.test(healthPath) || hasUnsupportedProtocol) {
      issues.push('健康检查路径必须是相对路径或有效的 HTTP/HTTPS 地址');
    }
  }

  return issues;
}

function mcpToolRequiredMissingFields(record) {
  return [
    ['适用范围', record.useScope],
    ['调用入口', record.entryPoint],
    ['验证方式', record.verifyMethod],
  ]
    .filter(([, value]) => !String(value || '').trim())
    .map(([label]) => label);
}

function validateUniqueSystemName(page, record, rows, fieldLabel) {
  const name = String(record.name || '').trim();
  if (!name) return;
  const duplicate = rows.find(
    (row) => row.code !== record.code && normalizedLoginName(row.name) === normalizedLoginName(name),
  );
  if (duplicate) {
    throw requestError(400, `${fieldLabel} ${name} 已被 ${duplicate.code} 使用，不能重复。`);
  }
}

function validateUniqueSystemCode(page, record, rows) {
  const code = String(record.code || '').trim();
  if (!code) return;
  const duplicate = rows.find(
    (row) => row.code !== record.code && normalizedLoginName(row.code) === normalizedLoginName(code),
  );
  if (duplicate) {
    throw requestError(400, `${systemPageLogLabel(page)}编码 ${code} 已被 ${duplicate.code} 使用，不能重复。`);
  }
}

function validateUniqueMenuSortOrder(record, rows) {
  const sortOrder = Number(record.sortOrder);
  if (!Number.isFinite(sortOrder)) return;

  const duplicate = rows.find(
    (row) =>
      row.code !== record.code &&
      String(row.parentCode || '') === String(record.parentCode || '') &&
      Number(row.sortOrder) === sortOrder,
  );
  if (duplicate) {
    const scope = record.parentCode || '一级菜单';
    throw requestError(400, `同级菜单排序号 ${sortOrder} 已被 ${duplicate.name || duplicate.code} 使用，请调整 ${scope} 下的排序。`);
  }
}

function normalizeSystemMenuSortOrder(value, fallback) {
  const sortOrder = Number(value ?? fallback);
  if (!Number.isFinite(sortOrder) || !Number.isInteger(sortOrder) || sortOrder < 1) {
    throw requestError(400, '菜单排序号必须是大于 0 的整数。');
  }
  return sortOrder;
}

function systemInputText(input, existing, field, fallback = '') {
  if (Object.prototype.hasOwnProperty.call(input, field)) {
    return String(input[field] ?? '').trim();
  }
  return String(existing?.[field] ?? fallback).trim();
}

function normalizeSystemRecord(page, input, existing, rows, data) {
  const explicitCode = canonicalSystemCode(input.code || existing?.code || '');
  const code = explicitCode || nextSystemRecordCode(page, rows);
  const record = {
    ...(existing || {}),
    code,
    name: systemInputText(input, existing, 'name'),
    owner: systemInputText(input, existing, 'owner', '系统管理员') || '系统管理员',
    status: normalizeSystemStatus(page, input.status, existing?.status),
    description: systemInputText(input, existing, 'description'),
    updatedAt: shanghaiDateTime(),
  };
  validateSystemCodeFormat(page, code);
  validateUniqueSystemCode(page, record, rows);
  if (page !== 'accounts' && !record.name) {
    throw requestError(400, `${systemPageLogLabel(page)}名称不能为空。`);
  }

  if (page === 'permissions' && code === systemPermissionCode && record.status === '停用') {
    throw requestError(400, '系统配置维护权限不能停用。');
  }
  if (page === 'permissions') {
    validateUniqueSystemName(page, record, rows, '权限名称');
  }
  if (page === 'permissions' && record.status === '停用') {
    const usage = permissionUsageSummary(data, code);
    const dependentOperations = activeDependentOperationPermissions(data, code);
    if (usage.roles.length || usage.menus.length || dependentOperations.length) {
      throw requestError(
        400,
        `该权限仍被引用：${permissionStopReferenceSummary(data, usage, dependentOperations)}。请先调整角色、菜单或依赖权限后再停用。`,
      );
    }
  }

  if (page === 'naming-rules') {
    const defaultRule =
      namingRuleDefaults.find((rule) => rule.code === code) ||
      namingRuleDefaults.find((rule) => rule.ruleKey === input.ruleKey || rule.ruleKey === existing?.ruleKey);
    const prefixValue = normalizeCodePrefix(input.prefix || existing?.prefix, defaultRule?.prefix || 'DOC');
    const dateFormat = normalizeDateFormat(input.dateFormat || existing?.dateFormat || defaultRule?.dateFormat);
    const sequenceLength = normalizeSequenceLength(input.sequenceLength ?? existing?.sequenceLength ?? defaultRule?.sequenceLength);
    Object.assign(record, {
      ruleKey: input.ruleKey || existing?.ruleKey || defaultRule?.ruleKey || code.toLowerCase().replace(/^rule-/, ''),
      prefix: prefixValue,
      dateFormat,
      sequenceLength,
      sampleCode: sampleNamingCode({ prefix: prefixValue, dateFormat, sequenceLength }),
    });
    validateNamingRuleRecord(record, rows, existing);
  }

  if (page === 'menus') {
    const defaultMenu = flattenedMenuDefaults.find((menu) => menu.code === code);
    if (!defaultMenu) {
      throw requestError(400, '菜单由当前系统路由生成，不能维护未接入菜单。');
    }
    Object.assign(record, {
      menuKey: defaultMenu.menuKey || '',
      parentCode: defaultMenu.parentCode || '',
      path: defaultMenu.path || '',
      permissionCode: input.permissionCode || existing?.permissionCode || defaultMenu.permissionCode || '',
      sortOrder: normalizeSystemMenuSortOrder(input.sortOrder ?? existing?.sortOrder, defaultMenu.sortOrder),
    });
    validateUniqueMenuSortOrder(record, rows);
    validateMenuPermissionIsNotOperation(data, record);
    if (record.permissionCode && record.status !== '停用') {
      validateActivePermissionCodes(data, [record.permissionCode], '启用菜单');
    }
    if (record.status !== '停用' && record.parentCode) {
      const parent = rows.find((row) => row.code === record.parentCode);
      if (!parent) {
        throw requestError(400, `上级菜单不存在：${record.parentCode}。`);
      }
      if (parent.status === '停用') {
        throw requestError(400, `请先启用上级菜单 ${parent.name || parent.code} 后再启用该菜单。`);
      }
    }
    if (record.status === '停用') {
      const activeChildMenus = activeChildMenusForMenu(rows, code);
      if (activeChildMenus.length) {
        throw requestError(
          400,
          `该菜单下仍有启用下级菜单：${activeChildMenuSummaryForMenu(activeChildMenus)}，请先停用下级菜单后再停用该菜单。`,
        );
      }
    }
    validateMenuPermissionMatchesPath(data, record);
    if (protectedMenuCodes.has(code)) {
      if (record.status !== '启用') {
        throw requestError(400, '系统核心菜单必须保持启用。');
      }
      if (record.permissionCode !== systemPermissionCode) {
        throw requestError(400, '系统核心菜单必须绑定系统配置维护权限。');
      }
    }
  }

  if (page === 'roles') {
    const rawPermissions = input.permissions ?? existing?.permissions ?? '';
    let permissionCodes = listFromText(rawPermissions);
    validateUniqueSystemName(page, record, rows, '角色名称');
    if (code === adminRoleCode && record.status === '停用') {
      throw requestError(400, '管理员角色不能停用。');
    }
    if (code !== adminRoleCode && record.status === '停用') {
      const usage = roleUsageSummary(data, code);
      if (usage.accounts.length || usage.notifications.length) {
        throw requestError(
          400,
          `该角色仍被引用：${roleStopReferenceSummary(usage)}。请先从账号和通知规则中移除后再停用。`,
        );
      }
    }
    if (code === adminRoleCode) {
      permissionCodes = systemPermissionRows(data)
        .filter((permission) => permission.status !== '停用')
        .map((permission) => permission.code);
    }
    if (code !== adminRoleCode) {
      if (record.status !== '停用' && !permissionCodes.length) {
        throw requestError(400, '启用角色必须至少选择一个权限点。');
      }
      validateActivePermissionCodes(data, permissionCodes, '角色');
      validateOperationPermissionDependencies(data, permissionCodes, '角色');
    }
    Object.assign(record, {
      permissions: permissionCodes.join(','),
      description: record.description,
    });

    if (data) {
      const proposedRoles = existing
        ? rows.map((row) => (row.code === code ? record : row))
        : [...rows, record];
      const proposedData = dataWithSystemRows(data, 'roles', proposedRoles);
      assertEnabledAccountsHaveEffectivePermissions(proposedData, proposedData.system.accounts || []);
      assertPasswordLoginHasSystemManager(proposedData, proposedData.system.accounts || []);
    }
  }

  if (page === 'notifications') {
    const triggerModule = input.triggerModule || existing?.triggerModule || '销售';
    const triggerAction = input.triggerAction || existing?.triggerAction || '';
    const receiverRoles = listFromText(resolveRoleCodes(data, input.receiverRoles ?? existing?.receiverRoles ?? ''));
    const channel = input.channel || existing?.channel || '站内';
    if (record.status !== '停用') {
      validateSupportedNotificationTrigger(triggerModule, triggerAction);
      if (!isSupportedNotificationChannel(channel)) {
        throw requestError(400, notificationChannelUnsupportedMessage());
      }
      if (!receiverRoles.length) {
        throw requestError(400, '启用通知规则必须选择接收角色。');
      }
      validateActiveRoleCodes(data, receiverRoles, '通知规则');
      if (!notificationTargetAccounts(data, receiverRoles).length) {
        throw requestError(400, notificationNoTargetAccountMessage(data, receiverRoles));
      }
    }

    Object.assign(record, {
      triggerModule,
      triggerAction,
      receiverRoles: receiverRoles.join(','),
      channel,
      description: record.description,
    });
  }

  if (page === 'option-dictionaries') {
    const optionModule = systemInputText(input, existing, 'optionModule', '通用');
    const optionField = systemInputText(input, existing, 'optionField');
    const optionValues = listFromText(input.optionValues ?? existing?.optionValues ?? '').join(',');
    const useScope = systemInputText(input, existing, 'useScope');
    if (record.status !== '停用') {
      if (!optionModule) throw requestError(400, '启用选项字典必须填写所属模块。');
      if (!optionField) throw requestError(400, '启用选项字典必须填写字段/用途。');
      if (!optionValues) throw requestError(400, '启用选项字典必须至少维护一个选项值。');
    }

    Object.assign(record, {
      optionModule,
      optionField,
      optionValues,
      useScope,
      description: record.description,
    });
  }

  if (page === 'apps') {
    const appType = String(input.appType ?? existing?.appType ?? '业务前端').trim();
    const deployTarget = String(input.deployTarget ?? existing?.deployTarget ?? '本地开发').trim();
    const runtimeMode = String(input.runtimeMode ?? existing?.runtimeMode ?? 'Vite + Node API').trim();
    const publicUrl = String(input.publicUrl ?? existing?.publicUrl ?? '').trim();
    const apiBase = String(input.apiBase ?? existing?.apiBase ?? '').trim();
    const healthPath = String(input.healthPath ?? existing?.healthPath ?? '').trim();
    const dataStore = String(input.dataStore ?? existing?.dataStore ?? '').trim();
    if (!appTypeOptions.includes(appType)) {
      throw requestError(400, '应用类型只能选择当前系统支持的类型。');
    }
    if (!deployTargetOptions.includes(deployTarget)) {
      throw requestError(400, '部署目标只能选择当前系统支持的目标。');
    }
    if (record.status !== '停用') {
      if (!runtimeMode) throw requestError(400, '启用应用必须填写运行方式。');
      if (!publicUrl && !apiBase) throw requestError(400, '启用应用必须填写访问入口或 API 地址。');
      if (!healthPath) throw requestError(400, '启用应用必须填写健康检查路径。');
      if (!dataStore) throw requestError(400, '启用应用必须填写数据位置。');
      const placeholderFields = [
        ['运行方式', runtimeMode],
        ['访问入口', publicUrl],
        ['API 地址', apiBase],
        ['健康检查路径', healthPath],
        ['数据位置', dataStore],
      ]
        .filter(([, value]) => value && isPlaceholderSystemConfigValue(value))
        .map(([label]) => label);
      if (placeholderFields.length) {
        throw requestError(400, `启用应用不能使用占位配置，请替换${placeholderFields.join('、')}。`);
      }
      const urlIssues = appUrlFormatIssues({ publicUrl, apiBase, healthPath });
      if (urlIssues.length) {
        throw requestError(400, `启用应用地址配置不正确：${urlIssues.join('、')}。`);
      }
    }

    Object.assign(record, {
      appType,
      deployTarget,
      runtimeMode,
      publicUrl,
      apiBase,
      healthPath,
      dataStore,
      versionTag: String(input.versionTag ?? existing?.versionTag ?? '').trim(),
      healthStatus: existing?.healthStatus || '未检查',
      healthCheckedAt: existing?.healthCheckedAt || '',
      healthMessage: existing?.healthMessage || '',
      healthLatencyMs: Number(existing?.healthLatencyMs ?? 0),
      healthTarget: existing?.healthTarget || '',
      description: record.description,
    });
  }

  if (page === 'mcp-tools') {
    const toolType = input.toolType || existing?.toolType || '终端';
    const riskLevel = input.riskLevel || existing?.riskLevel || '中';
    const useScope = systemInputText(input, existing, 'useScope');
    const entryPoint = systemInputText(input, existing, 'entryPoint');
    const verifyMethod = systemInputText(input, existing, 'verifyMethod');
    if (!mcpToolTypeOptions.includes(toolType)) {
      throw requestError(400, '工具类型只能选择当前系统支持的类型。');
    }
    if (!riskLevelOptions.includes(riskLevel)) {
      throw requestError(400, '风险级别只能选择低、中或高。');
    }

    Object.assign(record, {
      toolType,
      useScope,
      entryPoint,
      verifyMethod,
      riskLevel,
      lastVerifiedAt: existing?.lastVerifiedAt || '',
      lastVerificationRemark: existing?.lastVerificationRemark || '',
      description: record.description,
    });
    if (record.status !== '停用') {
      if (!record.useScope) throw requestError(400, '启用工具必须填写适用范围。');
      if (!record.entryPoint) throw requestError(400, '启用工具必须填写调用入口。');
      if (!record.verifyMethod) throw requestError(400, '启用工具必须填写验证方式。');
    }
  }

  if (page === 'accounts') {
    const requestedEmployeeCode = String(input.employeeCode ?? existing?.employeeCode ?? '').trim();
    const employeeRows = data ? ensureMasterRows(data, 'employees') : [];
    const employee = requestedEmployeeCode
      ? employeeRows.find((row) => row.code === requestedEmployeeCode)
      : data
        ? findAccountEmployee(data, { ...existing, ...input })
        : undefined;
    const username = canonicalLoginUsername(input.username ?? existing?.username ?? '');
    const resolvedRoles = resolveRoleCodes(data, input.roles ?? existing?.roles ?? '');
    const resolvedRoleCodes = listFromText(resolvedRoles);
    const passwordUpdate = accountPasswordUpdate(input);
    const finalEmployeeCode = requestedEmployeeCode || employee?.code || '';
    const displayName = employee?.name || systemInputText(input, existing, 'name');

    if (!username) {
      throw requestError(400, '请填写登录账号。');
    }
    validateLoginUsernameFormat(username);
    if (requestedEmployeeCode && !employee) {
      throw requestError(400, '关联员工不存在，请重新选择员工。');
    }
    if (requestedEmployeeCode && employee?.status === '停用' && record.status !== '停用') {
      throw requestError(400, '启用账号不能关联已停用员工，请先启用员工或停用账号。');
    }
    if (record.status !== '停用' && !displayName) {
      throw requestError(400, '启用账号必须填写姓名或关联员工。');
    }
    const duplicateMessage = accountUniquenessConflict(rows, code, username, finalEmployeeCode);
    if (duplicateMessage) {
      throw requestError(400, duplicateMessage);
    }

    if (code === defaultAdminAccountCode) {
      if (record.status === '停用') {
        throw requestError(400, '默认管理员账号不能停用。');
      }
      if (!listFromText(resolvedRoles).includes(adminRoleCode)) {
        throw requestError(400, '默认管理员账号必须保留管理员角色。');
      }
    }

    if (record.status !== '停用') {
      if (!resolvedRoleCodes.length) {
        throw requestError(400, '启用账号必须至少选择一个角色。');
      }
      validateActiveRoleCodes(data, resolvedRoleCodes, '账号');
    }

    const passwordState = passwordUpdate
      ? passwordUpdate
      : {
          passwordHash: existing?.passwordHash || '',
          passwordSalt: existing?.passwordSalt || '',
          passwordUpdatedAt: existing?.passwordUpdatedAt || '',
          passwordUpdatedMs: existing?.passwordUpdatedMs || 0,
        };
    if (record.status !== '停用' && passwordLoginRequired(data) && !passwordState.passwordHash) {
      throw requestError(400, '系统已启用密码登录，启用账号必须设置登录密码。');
    }

    Object.assign(record, {
      username,
      employeeCode: finalEmployeeCode,
      name: displayName,
      department: employee?.owner || systemInputText(input, existing, 'department'),
      roles: resolvedRoles,
      phone: employee?.contact || employee?.phone || systemInputText(input, existing, 'phone'),
      email: employee?.email || systemInputText(input, existing, 'email'),
      lastLogin: existing?.lastLogin || '',
      ...passwordState,
      description: record.description,
    });

    if (data) {
      const proposedAccounts = existing
        ? rows.map((row) => (row.code === code ? record : row))
        : [...rows, record];
      assertEnabledAccountsHaveEffectivePermissions(data, proposedAccounts);
      assertPasswordLoginHasSystemManager(data, proposedAccounts);
      assertEnabledNotificationsHaveRecipients(data, proposedAccounts);
    }
  }

  return record;
}

function appendSystemLog(system, action, target, remark, options = {}) {
  system.logs ||= [];
  const targetText = String(target || '').trim();
  const remarkText = String(remark || '').trim();
  const now = shanghaiDateTime();
  system.logs.unshift({
    code: `LOG-${Date.now()}-${randomBytes(2).toString('hex').toUpperCase()}`,
    name: action,
    owner: options.owner || '系统',
    status: options.status || '正常',
    target: targetText,
    remark: remarkText,
    sourceAccount: options.sourceAccount || options.owner || '系统',
    sourceIp: options.sourceIp || '',
    description: `${targetText}：${remarkText}`,
    updatedAt: now,
  });
  system.logs = system.logs.slice(0, 500);
}

