function normalizeAuditFieldValue(field, value) {
  if (['roles', 'permissions', 'receiverRoles'].includes(field)) {
    const values = listFromText(value).sort((a, b) => a.localeCompare(b));
    return values.length ? values.join(',') : '空';
  }

  const text = String(value ?? '').trim();
  return text || '空';
}

function systemConfigChangeSummary(page, before, after) {
  const fields = systemAuditFieldsByPage[page] || ['name', 'owner', 'status', 'description'];
  const changes = fields
    .map((field) => {
      const oldValue = normalizeAuditFieldValue(field, before?.[field]);
      const newValue = normalizeAuditFieldValue(field, after?.[field]);
      if (oldValue === newValue) return '';
      return `${systemAuditFieldLabels[field] || field}：${oldValue} -> ${newValue}`;
    })
    .filter(Boolean);

  if (!changes.length) return '关键字段未变化';
  const visibleChanges = changes.slice(0, 8).join('；');
  return changes.length > 8 ? `变更：${visibleChanges}；另 ${changes.length - 8} 项` : `变更：${visibleChanges}`;
}

async function auditPermissionDenied(req, data, permissionCode, reason) {
  const system = ensureSystem(data);
  const account = activeAccountForRequest(req, data);
  const path = String(req.url || '').replace(/^\/api/, '') || '/';
  appendSystemLog(system, '权限拒绝', permissionCode, `${req.method} ${path}：${reason}`, {
    owner: accountAuditName(account),
    sourceAccount: account?.code || '',
    sourceIp: requestSourceIp(req),
    status: '异常',
  });
  await writeData(data);
}

function appendBusinessAuditLog(req, data, action, target, remark, options = {}) {
  const system = ensureSystem(data);
  const account = activeAccountForRequest(req, data);
  appendSystemLog(system, action, target, remark, {
    owner: options.owner || accountAuditName(account),
    sourceAccount: account?.code || '',
    sourceIp: requestSourceIp(req),
    status: options.status || '正常',
  });
}

