const supplierDeliveryMethods = ['送货到厂', '本厂自提', '供应商直送', '物流到厂', '快递快运', '供应商送货安装'];
const supplierTaxRates = ['13%', '9%', '6%', '3%', '1%', '0%', '免税'];
const masterRegionTypes = ['国内', '海外'];
const materialRelationUnsupportedSupplierTypes = new Set(['设备供应商', '物流服务']);
const replenishmentUnsupportedWarehouseTypes = new Set(['暂存仓', '隔离仓']);

function normalizedWarehouseType(value) {
  const type = normalizedMasterText(value);
  return warehouseTypeAliases.get(type) || type;
}

function supplierSupportsMaterialRelations(type) {
  return !materialRelationUnsupportedSupplierTypes.has(normalizedMasterText(type));
}

function warehouseSupportsReplenishment(warehouseOrType) {
  if (warehouseOrType && typeof warehouseOrType === 'object') {
    const functions = normalizeWarehouseFunctions(
      warehouseOrType.warehouseFunctions,
      warehouseOrType.type,
      warehouseOrType,
    );
    return !functions.some((item) => ['采购暂存', '销售退货暂存', '不合格隔离'].includes(item));
  }
  return !replenishmentUnsupportedWarehouseTypes.has(normalizedWarehouseType(warehouseOrType));
}

function normalizedMasterText(value) {
  return String(value ?? '').trim();
}

function normalizedMasterStatus(value, label) {
  const status = normalizedMasterText(value);
  if (!masterStatuses.includes(status)) throw requestError(400, `请选择有效的${label}使用状态。`);
  return status;
}

function normalizedOptionalEmail(value, label = '邮箱') {
  const email = normalizedMasterText(value).toLowerCase();
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw requestError(400, `请填写有效的${label}。`);
  }
  return email;
}

function normalizedNonNegativeNumber(value, label) {
  const number = Number(value);
  if (!Number.isFinite(number) || number < 0) throw requestError(400, `${label}必须是大于或等于 0 的数值。`);
  return number;
}

function normalizedNonNegativeInteger(value, label) {
  const number = Number(value);
  if (!Number.isInteger(number) || number < 0) throw requestError(400, `${label}必须是大于或等于 0 的整数。`);
  return number;
}

function normalizedOptionalDomesticTaxNumber(value, regionType, label) {
  const taxNumber = normalizedMasterText(value).replace(/\s+/g, '').toUpperCase();
  if (regionType === '国内' && taxNumber && !/^[0-9A-Z]{18}$/.test(taxNumber)) {
    throw requestError(400, `${label}必须是 18 位数字或大写字母。`);
  }
  return taxNumber;
}

function sameMasterText(left, right) {
  return normalizedMasterText(left).toLocaleLowerCase('zh-CN') === normalizedMasterText(right).toLocaleLowerCase('zh-CN');
}

function isValidIsoDate(value) {
  const text = normalizedMasterText(value);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) return false;
  const parsed = new Date(`${text}T00:00:00Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === text;
}

function resolveMasterDepartment(data, reference, subjectLabel) {
  const departmentRef = normalizedMasterText(reference);
  const departments = ensureMasterRows(data, 'departments');
  const byCode = departments.find((row) => row.code === departmentRef);
  if (byCode) return byCode;
  const byName = departments.filter((row) => row.name === departmentRef);
  if (byName.length > 1) {
    throw requestError(400, `${subjectLabel}所属部门名称不唯一，请重新从部门选择器选择。`);
  }
  return byName[0];
}

function resolveMasterDepartmentFields(data, departmentCode, departmentName, subjectLabel, mismatchMessage) {
  const codeRef = normalizedMasterText(departmentCode);
  const nameRef = normalizedMasterText(departmentName);
  const department = resolveMasterDepartment(data, codeRef || nameRef, subjectLabel);
  if (department && codeRef && nameRef && ![department.code, department.name].includes(nameRef)) {
    throw requestError(400, mismatchMessage);
  }
  return department;
}

function inventoryFactHasOutstandingQuantity(row) {
  const numericFields = [
    'onHandNumber',
    'qualifiedOnHandNumber',
    'availableNumber',
    'reservedNumber',
    'allocatedNumber',
    'frozenNumber',
    'lockedNumber',
    'qcHoldNumber',
    'pendingInboundNumber',
    'rejectedHoldNumber',
    'exceptionHoldNumber',
    'inTransitNumber',
    'inboundPlanNumber',
    'outboundPlanNumber',
  ];
  if (numericFields.some((field) => Math.abs(Number(row?.[field]) || 0) > 0.0001)) return true;
  return ['onHand', 'locked', 'qcHold', 'pendingInbound', 'rejectedHold', 'exceptionHold', 'inTransit', 'inboundPlan', 'outboundPlan']
    .some((field) => Math.abs(parseQty(row?.[field])) > 0.0001);
}

function outstandingInventoryFacts(data, predicate) {
  return ensureWarehouse(data).inventory.filter((row) => predicate(row) && inventoryFactHasOutstandingQuantity(row));
}

function legacyWarehouseFunctions(type, source = {}) {
  const rawType = String(type || '');
  const legacy = warehouseTypeCapabilities[normalizedWarehouseType(rawType)] || {};
  const functions = [];
  if (source.allowQualityHold === true || rawType === '质检暂存') functions.push('采购暂存');
  if (source.allowSalesReturnStaging === true) functions.push('销售退货暂存');
  if (source.allowPurchaseReceipt === true || legacy.allowPurchaseReceipt === true) functions.push('可采购入库');
  if (source.allowSalesIssue === true || legacy.allowSalesIssue === true) functions.push('可销售出库');
  if (source.allowProductionIssue === true || legacy.allowProductionIssue === true) functions.push('可生产领料');
  if (source.allowProductionReceipt === true || legacy.allowProductionReceipt === true) functions.push('可生产入库');
  if (source.allowQuarantine === true || legacy.allowQuarantine === true) functions.push('不合格隔离');
  return functions;
}

function normalizeWarehouseFunctions(value, type, source = {}) {
  const requested = Array.isArray(value) ? value : legacyWarehouseFunctions(type, source);
  return [...new Set(requested.map((item) => normalizedMasterText(item)).filter((item) => warehouseFunctionOptions.includes(item)))];
}

function warehouseCapabilities(type, functions, source = {}) {
  const warehouseType = normalizedWarehouseType(type);
  if (!warehouseTypes.includes(warehouseType)) return null;
  const selected = normalizeWarehouseFunctions(functions, type, source);
  return {
    warehouseFunctions: selected,
    allowPurchaseStaging: selected.includes('采购暂存'),
    allowSalesReturnStaging: selected.includes('销售退货暂存'),
    allowPurchaseReceipt: selected.includes('可采购入库'),
    allowSalesIssue: selected.includes('可销售出库'),
    allowProductionIssue: selected.includes('可生产领料'),
    allowProductionReceipt: selected.includes('可生产入库'),
    allowQualityHold: selected.includes('采购暂存'),
    allowQuarantine: selected.includes('不合格隔离'),
  };
}

function masterType(rawType) {
  return masterTypeAliases[rawType] || '';
}

function ensureMasterRows(data, type) {
  data.masterData ||= {};
  const seedRows = createSeedData().masterData?.[type] || [];
  if (!Array.isArray(data.masterData[type]) || (data.masterData[type].length === 0 && seedRows.length > 0)) {
    data.masterData[type] = seedRows.map((row) => ({ ...row }));
  }
  const rows = data.masterData[type];
  rows.forEach((row) => {
    const revision = Number(row.revision);
    row.revision = Number.isInteger(revision) && revision > 0 ? revision : 1;
  });
  if (type === 'materials') {
    const defaultMaterialEnglishFacts = {
      'M-FG-PETG-175-BLK': {
        englishName: 'PETG 1.75mm Black Filament 1kg',
        englishModel: 'PETG-175-BLK-1KG',
        englishSpec: 'Diameter 1.75mm, net weight 1kg, black',
      },
      'M-FG-PLA-175-WHT': {
        englishName: 'PLA 1.75mm Pearl White Filament 1kg',
        englishModel: 'PLA-175-WHT-1KG',
        englishSpec: 'Diameter 1.75mm, net weight 1kg, pearl white',
      },
    };
    rows.forEach((row) => {
      const englishFacts = defaultMaterialEnglishFacts[row.code];
      if (englishFacts && !String(row.englishName || '').trim()) row.englishName = englishFacts.englishName;
      if (englishFacts && !String(row.englishModel || '').trim()) row.englishModel = englishFacts.englishModel;
      if (englishFacts && !String(row.englishSpec || '').trim()) row.englishSpec = englishFacts.englishSpec;
      delete row.owner;
      delete row.primary;
      delete row.secondary;
      delete row.salesUom;
      delete row.salesUomConversionRate;
      delete row.purchaseUom;
      delete row.purchaseUomConversionRate;
      delete row.purchaseLeadTimeDays;
      delete row.productionLeadTimeDays;
      delete row.safetyStock;
      delete row.reorderPoint;
    });
  }
  if (type === 'customers') {
    rows.forEach((row) => {
      delete row.owner;
      delete row.manager;
      delete row.primary;
      delete row.secondary;
    });
  }
  if (type === 'suppliers') {
    rows.forEach((row) => {
      delete row.owner;
      delete row.manager;
      delete row.primary;
      delete row.secondary;
      delete row.supplyScope;
      delete row.incomingQualityRule;
      delete row.qualificationRequired;
      delete row.qualificationStatus;
      delete row.supplyMaterialCount;
      delete row.purchaseLeadTimeDays;
    });
  }
  if (type === 'warehouses') {
    rows.forEach((row) => {
      row.type = normalizedWarehouseType(row.type);
      delete row.owner;
      delete row.manager;
      delete row.phone;
      delete row.warehouseScope;
      delete row.primary;
      delete row.secondary;
      Object.assign(row, warehouseCapabilities(row.type, row.warehouseFunctions, row) || {});
    });
  }
  if (type === 'uom') {
    const defaultEnglishAbbreviations = {
      'UOM-ROLL': 'roll',
      'UOM-KG': 'kg',
      'UOM-G': 'g',
      'UOM-EA': 'pcs',
      'UOM-CTN': 'ctn',
    };
    rows.forEach((row) => {
      if (row.code === 'UOM-KG' && row.name === '千克') row.name = 'kg';
      if (row.code === 'UOM-G' && row.name === '克') row.name = 'g';
      if (!String(row.englishAbbreviation || '').trim()) {
        row.englishAbbreviation = defaultEnglishAbbreviations[row.code] || String(row.englishName || '').trim();
      }
      delete row.englishName;
      delete row.symbol;
      delete row.type;
      delete row.baseUom;
      delete row.conversionRate;
      delete row.decimalPrecision;
      delete row.owner;
      delete row.primary;
      delete row.secondary;
    });
  }
  if (type === 'currencies') {
    const retiredStarterCurrencies = new Set(['USD', 'EUR', 'GBP', 'JPY']);
    for (let index = rows.length - 1; index >= 0; index -= 1) {
      if (retiredStarterCurrencies.has(String(rows[index]?.code || '').trim().toUpperCase())) rows.splice(index, 1);
    }
    rows.forEach((row) => {
      row.code = String(row.code || '').trim().toUpperCase();
      row.decimalPlaces = Number.isInteger(Number(row.decimalPlaces)) ? Number(row.decimalPlaces) : 2;
      delete row.englishName;
      delete row.type;
      delete row.owner;
      delete row.primary;
      delete row.secondary;
    });
  }
  if (type === 'departments') {
    rows.forEach((row) => {
      delete row.type;
      delete row.manager;
      delete row.primary;
      delete row.secondary;
    });
  }
  if (type === 'equipment') {
    const departmentRows = Array.isArray(data.masterData.departments) ? data.masterData.departments : [];
    rows.forEach((row) => {
      delete row.type;
      delete row.manager;
      delete row.operatingState;
      delete row.maintenanceCycleWeeks;
      delete row.secondary;
      if (!row.departmentCode && row.owner) {
        const matches = departmentRows.filter((department) => department.name === row.owner);
        if (matches.length === 1) row.departmentCode = matches[0].code;
      }
    });
  }
  if (type === 'productionLines') {
    const departmentRows = Array.isArray(data.masterData.departments) ? data.masterData.departments : [];
    rows.forEach((row) => {
      delete row.manager;
      delete row.operatingState;
      delete row.primary;
      delete row.secondary;
      if (!row.departmentCode && row.owner) {
        const matches = departmentRows.filter((department) => department.name === row.owner);
        if (matches.length === 1) row.departmentCode = matches[0].code;
      }
    });
  }
  if (type === 'employees') {
    const departmentRows = Array.isArray(data.masterData.departments) ? data.masterData.departments : [];
    const defaultEnglishNames = {
      'EMP-ZS': 'Zhang San',
      'EMP-LM': 'Li Ming',
      'EMP-WQ': 'Wang Qian',
      'EMP-ZM': 'Zhao Min',
      'EMP-ZN': 'Zhou Ning',
      'EMP-LS': 'Lin Shan',
      'EMP-ZY': 'Zhao Yun',
    };
    rows.forEach((row) => {
      delete row.type;
      delete row.supervisor;
      delete row.employmentStatus;
      delete row.contact;
      delete row.primary;
      delete row.secondary;
      delete row.birthDate;
      delete row.homeAddress;
      delete row.emergencyContactName;
      delete row.emergencyContactPhone;
      if (!String(row.englishName || '').trim() && defaultEnglishNames[row.code]) {
        row.englishName = defaultEnglishNames[row.code];
      }
      if (!row.departmentCode && row.owner) {
        const matches = departmentRows.filter((department) => department.name === row.owner);
        if (matches.length === 1) row.departmentCode = matches[0].code;
      }
    });
  }
  if (type === 'company') {
    rows.forEach((row) => {
      delete row.owner;
      delete row.manager;
    });
  }
  return rows;
}

function ensureMasterRelations(data) {
  data.masterRelations ||= {};
  const seedRelations = createSeedData().masterRelations || {};
  for (const key of ['materialSuppliers', 'warehouseMaterials']) {
    if (!Array.isArray(data.masterRelations[key]) || (!data.masterRelations[key].length && seedRelations[key]?.length)) {
      data.masterRelations[key] = (seedRelations[key] || []).map((row) => ({ ...row }));
    }
  }
  data.masterRelations.materialSuppliers.forEach((row) => {
    delete row.purchaseUom;
  });
  const supplierByCode = new Map(ensureMasterRows(data, 'suppliers').map((row) => [row.code, row]));
  const warehouseByCode = new Map(ensureMasterRows(data, 'warehouses').map((row) => [row.code, row]));
  const materialByCode = new Map(ensureMasterRows(data, 'materials').map((row) => [row.code, row]));
  data.masterRelations.materialSuppliers.forEach((row) => {
    const supplier = supplierByCode.get(row.supplierCode);
    const material = materialByCode.get(row.materialCode);
    if (
      !supplier
      || supplier.status === '停用'
      || !supplierSupportsMaterialRelations(supplier.type)
      || !material
      || material.status === '停用'
      || !isPurchasableMaterial(material)
      || row.status !== '启用'
    ) {
      row.status = '停用';
      row.isDefault = false;
    }
  });
  data.masterRelations.warehouseMaterials.forEach((row) => {
    const warehouse = warehouseByCode.get(row.warehouseCode);
    const material = materialByCode.get(row.materialCode);
    if (
      !warehouse
      || warehouse.status === '停用'
      || !warehouseSupportsReplenishment(warehouse)
      || !material
      || material.status === '停用'
      || row.status !== '启用'
    ) {
      row.status = '停用';
    }
  });
  return data.masterRelations;
}

const masterCodePrefixes = {
  customers: 'CUS',
  suppliers: 'SUP',
  warehouses: 'WH',
  uom: 'UOM',
  departments: 'DEP',
  employees: 'EMP',
  company: 'COM',
  equipment: 'EQ',
  productionLines: 'LINE',
  currencies: '',
};

const materialCodePrefixes = {
  成品: 'M-FG',
  半成品: 'M-SF',
  原料: 'M-RM',
  色母: 'M-CM',
  色粉: 'M-CP',
  辅料: 'M-AM',
  包材: 'M-PKG',
  回料: 'M-RG',
  不良品: 'M-DF',
};

function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function masterCodePrefix(type, input = {}) {
  if (type === 'materials') {
    return materialCodePrefixes[input.category || input.type] || 'M';
  }
  return masterCodePrefixes[type] || 'MD';
}

function isSaleableMaterial(row = {}) {
  if (Object.prototype.hasOwnProperty.call(row, 'isSaleable')) {
    return Boolean(row.isSaleable);
  }

  return row.category === '成品' || row.type === '成品';
}

function isPurchasableMaterial(row = {}) {
  if (Object.prototype.hasOwnProperty.call(row, 'isPurchasable')) {
    return Boolean(row.isPurchasable);
  }
  return ['采购', '采购+自制'].includes(row.supplyStrategy || '');
}

function isProducibleMaterial(row = {}) {
  if (Object.prototype.hasOwnProperty.call(row, 'isProducible')) {
    return Boolean(row.isProducible);
  }
  return ['自制', '采购+自制', '委外'].includes(row.supplyStrategy || '');
}

function isProductionOutputMaterial(row = {}) {
  return isProducibleMaterial(row) && [row.type, row.category].some((value) => ['成品', '半成品'].includes(value));
}

function replenishmentDocumentIsTerminal(status) {
  return ['已完成', '已关闭', '已作废', '已取消', '已冲销'].includes(String(status || ''));
}

function replenishmentLinkedDocument(data, relationCode) {
  const purchase = ensurePurchase(data);
  const production = ensureProduction(data);
  const requisitions = [...purchase.requisitions]
    .filter((row) => row.sourceReplenishmentCode === relationCode)
    .sort((a, b) => `${b.date || ''}${b.code}`.localeCompare(`${a.date || ''}${a.code}`));

  for (const requisition of requisitions) {
    const linkedOrders = purchase.orders.filter((order) => (
      order.sourceRequisition === requisition.code
      || order.sourceRequisitions?.includes(requisition.code)
      || order.products?.some((line) => line.sourceRequisition === requisition.code)
    ));
    const activeOrder = linkedOrders.find((order) => !replenishmentDocumentIsTerminal(order.status));
    if (activeOrder) {
      return {
        type: '采购订单',
        code: activeOrder.code,
        status: activeOrder.status,
        path: `/purchase/orders/${encodeURIComponent(activeOrder.code)}`,
      };
    }
    if (!linkedOrders.length && !replenishmentDocumentIsTerminal(requisition.status)) {
      return {
        type: '采购申请',
        code: requisition.code,
        status: requisition.status,
        path: `/purchase/requisitions/${encodeURIComponent(requisition.code)}`,
      };
    }
  }

  const task = [...production.tasks]
    .filter((row) => row.sourceReplenishmentCode === relationCode && !replenishmentDocumentIsTerminal(row.status))
    .sort((a, b) => `${b.updatedAt || b.createdAt || ''}${b.code}`.localeCompare(`${a.updatedAt || a.createdAt || ''}${a.code}`))[0];
  if (!task) return null;
  return {
    type: '生产任务',
    code: task.code,
    status: task.status,
    path: `/production/tasks/${encodeURIComponent(task.code)}`,
  };
}

function cleanReplenishmentQty(value) {
  return Number(Math.max(0, Number(value) || 0).toFixed(4));
}

function purchasePendingInboundQtyForWarehouse(data, warehouseCode, materialCode) {
  const receipts = ensureWarehouse(data).purchaseReceipts;
  return receipts.reduce((receiptSum, receipt) => {
    return receiptSum + (receipt.products || []).reduce((lineSum, product, index) => {
      if (product.materialCode !== materialCode) return lineSum;
      const receiptLineId = product.lineId || `L${index + 1}`;
      const postedForTarget = (receipt.postedQuantities?.lines || [])
        .filter((line) => line.receiptLineId === receiptLineId && line.warehouseCode === warehouseCode)
        .reduce((sum, line) => sum + Number(line.postedQty || 0), 0);
      const allocations = (receipt.inboundAllocations || []).filter((line) => (
        line.receiptLineId === receiptLineId && line.warehouseCode === warehouseCode
      ));
      if (allocations.length) {
        const allocatedForTarget = allocations.reduce((sum, line) => sum + parseQty(line.quantity), 0);
        return lineSum + Math.max(0, allocatedForTarget - postedForTarget);
      }

      const decisionLine = receipt.qualityDecision?.lines?.find((line) => (
        line.receiptLineId === receiptLineId
        || (line.materialCode && line.materialCode === product.materialCode)
      ));
      const disposition = receipt.qualityDispositionQuantities?.[receiptLineId] || {};
      const releasedQty = product.qcRequired
        ? Number(decisionLine?.releasedQty || 0)
          + Number(disposition.approvedConcessionQty || 0)
          + Number(disposition.reinspectionAcceptedQty || 0)
        : purchaseReceiptLineArrivalQuantities(product).accepted;
      const postedTotal = (receipt.postedQuantities?.lines || [])
        .filter((line) => line.receiptLineId === receiptLineId)
        .reduce((sum, line) => sum + Number(line.postedQty || 0), 0);
      const remaining = Math.max(0, releasedQty - postedTotal);
      if (remaining <= 0.0001) return lineSum;

      const destination = warehouseMeta(
        data,
        product.destinationWarehouseCode,
        product.destinationWarehouse || materialMeta(data, product.materialCode, product.name).defaultWarehouse,
      );
      return destination.code === warehouseCode ? lineSum + remaining : lineSum;
    }, 0);
  }, 0);
}

function warehouseReplenishmentSignals(data) {
  const relations = ensureMasterRelations(data).warehouseMaterials
    .filter((row) => row.status === '启用');
  const inventory = ensureWarehouse(data).inventory;
  const materials = ensureMasterRows(data, 'materials');
  const warehouses = ensureMasterRows(data, 'warehouses');

  return relations.map((relation) => {
    const rows = inventory.filter((row) => (
      row.warehouseCode === relation.warehouseCode
      && row.materialCode === relation.materialCode
    ));
    const availableQty = rows.reduce(
      (sum, row) => sum + inventoryNumber(row, 'availableNumber', 'available'),
      0,
    );
    const warehousePendingInboundQty = rows.reduce(
      (sum, row) => sum + inventoryNumber(row, 'pendingInboundNumber', 'pendingInbound'),
      0,
    );
    const stagingPendingInboundQty = purchasePendingInboundQtyForWarehouse(
      data,
      relation.warehouseCode,
      relation.materialCode,
    );
    const pendingInboundQty = warehousePendingInboundQty + stagingPendingInboundQty;
    const inTransitQty = rows.reduce(
      (sum, row) => sum + inventoryNumber(row, 'inTransitNumber', 'inTransit'),
      0,
    );
    const projectedQty = availableQty + pendingInboundQty + inTransitQty;
    const safetyStock = Number(relation.safetyStock || 0);
    const reorderPoint = Number(relation.reorderPoint || 0);
    const maxStock = Number(relation.maxStock || 0);
    const replenishmentLot = Number(relation.replenishmentLot || 0);
    const targetQty = Math.min(maxStock, reorderPoint + replenishmentLot);
    const suggestedQty = cleanReplenishmentQty(targetQty - projectedQty);
    const thresholdStatus = projectedQty <= safetyStock
      ? '库存告急'
      : projectedQty <= reorderPoint
        ? '需补货'
        : availableQty <= reorderPoint && pendingInboundQty + inTransitQty > 0
          ? '在途覆盖'
          : '正常';
    const linkedDocument = replenishmentLinkedDocument(data, relation.code);
    const status = linkedDocument && availableQty <= reorderPoint
      ? '补货处理中'
      : thresholdStatus;
    const material = materials.find((row) => row.code === relation.materialCode) || {};
    const warehouse = warehouses.find((row) => row.code === relation.warehouseCode) || {};
    const availableRoutes = [
      ...(isPurchasableMaterial(material) ? ['采购申请'] : []),
      ...(isProductionOutputMaterial(material) ? ['生产任务'] : []),
    ];
    const actionRequired = ['库存告急', '需补货'].includes(thresholdStatus) && !linkedDocument;
    const updatedAt = [...rows]
      .sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')))[0]?.updatedAt
      || shanghaiDate();

    return {
      code: relation.code,
      warehouseCode: relation.warehouseCode,
      warehouseName: relation.warehouseName || warehouse.name || relation.warehouseCode,
      materialCode: relation.materialCode,
      materialName: relation.materialName || material.name || relation.materialCode,
      uom: relation.uom || material.uom || '件',
      availableQty: cleanReplenishmentQty(availableQty),
      pendingInboundQty: cleanReplenishmentQty(pendingInboundQty),
      inTransitQty: cleanReplenishmentQty(inTransitQty),
      projectedQty: cleanReplenishmentQty(projectedQty),
      safetyStock,
      reorderPoint,
      maxStock,
      replenishmentLot,
      suggestedQty,
      thresholdStatus,
      status,
      actionRequired,
      availableRoutes,
      linkedDocument,
      updatedAt,
      sourcePath: `/warehouse/inventory?view=item&keyword=${encodeURIComponent(relation.materialCode)}`,
      message: status === '补货处理中'
        ? `${linkedDocument.type} ${linkedDocument.code} 正在处理`
        : thresholdStatus === '库存告急'
          ? `预计可用 ${formatQty(projectedQty, relation.uom)}，已低于安全库存 ${formatQty(safetyStock, relation.uom)}`
          : thresholdStatus === '需补货'
            ? `预计可用 ${formatQty(projectedQty, relation.uom)}，已触及补货点 ${formatQty(reorderPoint, relation.uom)}`
            : thresholdStatus === '在途覆盖'
              ? `当前可用已触及补货点，在途与待入库可覆盖至 ${formatQty(projectedQty, relation.uom)}`
              : `预计可用高于补货点 ${formatQty(reorderPoint, relation.uom)}`,
    };
  }).sort((a, b) => {
    const rank = { 库存告急: 1, 需补货: 2, 补货处理中: 3, 在途覆盖: 4, 正常: 5 };
    return (rank[a.status] || 9) - (rank[b.status] || 9)
      || a.warehouseName.localeCompare(b.warehouseName)
      || a.materialName.localeCompare(b.materialName);
  });
}

function startWarehouseReplenishment(data, relationCode, routeType, actor = '仓库主管') {
  const signal = warehouseReplenishmentSignals(data).find((row) => row.code === relationCode);
  if (!signal) throw requestError(404, '仓库补货设置不存在或已停用。');
  if (signal.linkedDocument) {
    return { signal, document: signal.linkedDocument, repeated: true };
  }
  if (!signal.actionRequired) {
    throw requestError(409, `${signal.materialName}当前不需要发起新的补货。`);
  }
  if (!signal.availableRoutes.includes(routeType)) {
    throw requestError(409, `${signal.materialName}不支持${routeType}补货，请检查物料业务属性。`);
  }

  const material = materialMeta(data, signal.materialCode, signal.materialName);
  const warehouse = warehouseMeta(data, signal.warehouseCode, signal.warehouseName);
  const snapshot = {
    relationCode: signal.code,
    warehouseCode: signal.warehouseCode,
    warehouseName: signal.warehouseName,
    materialCode: signal.materialCode,
    materialName: signal.materialName,
    uom: signal.uom,
    availableQty: signal.availableQty,
    pendingInboundQty: signal.pendingInboundQty,
    inTransitQty: signal.inTransitQty,
    projectedQty: signal.projectedQty,
    safetyStock: signal.safetyStock,
    reorderPoint: signal.reorderPoint,
    maxStock: signal.maxStock,
    replenishmentLot: signal.replenishmentLot,
    suggestedQty: signal.suggestedQty,
    triggeredAt: shanghaiDateTime(),
  };

  if (routeType === '采购申请') {
    const purchase = ensurePurchase(data);
    const requisition = normalizePurchaseRequisition({
      code: '系统自动生成',
      companyCode: warehouse.companyCode || '',
      company: warehouse.company || '',
      purchaseType: '物料采购',
      department: warehouse.department || '仓储部',
      requester: actor,
      reason: `库存补货：${signal.warehouseName} / ${signal.materialName}`,
      date: shanghaiDate(),
      expectedDate: shanghaiDate(),
      products: [{
        lineId: `${signal.code}-L1`,
        materialCode: signal.materialCode,
        name: signal.materialName,
        model: material.model || '',
        spec: material.spec || '',
        qty: String(signal.suggestedQty),
        uom: signal.uom,
      }],
      attachments: [],
    }, undefined, data);
    Object.assign(requisition, {
      status: '待采购受理',
      sourceType: '库存补货',
      sourceReplenishmentCode: signal.code,
      sourceWarehouseCode: signal.warehouseCode,
      sourceWarehouseName: signal.warehouseName,
      replenishmentSnapshot: snapshot,
    });
    purchase.requisitions.unshift(requisition);
    appendPurchaseRequisitionFlow(
      data,
      requisition.code,
      '仓库发起补货',
      `${signal.code} 触发采购补货 ${formatQty(signal.suggestedQty, signal.uom)}，等待采购受理。`,
      actor,
    );
    return {
      signal,
      document: {
        type: '采购申请',
        code: requisition.code,
        status: requisition.status,
        path: `/purchase/requisitions/${encodeURIComponent(requisition.code)}`,
      },
      repeated: false,
    };
  }

  const production = ensureProduction(data);
  const task = normalizeProductionTask({
    code: '系统自动生成',
    command: 'save',
    sourceType: '安全库存补货',
    sourceCode: signal.code,
    products: [{
      lineId: `${signal.code}-L1`,
      productCode: signal.materialCode,
      productName: signal.materialName,
      model: material.model || '',
      spec: material.spec || '',
      demandQty: signal.suggestedQty,
      unit: signal.uom,
      recipeCode: '',
    }],
    deliveryDate: shanghaiDate(),
    priority: signal.thresholdStatus === '库存告急' ? '紧急' : '正常',
    owner: '生产主管',
    note: `由${signal.warehouseName}库存预警发起，预计可用 ${formatQty(signal.projectedQty, signal.uom)}。`,
  }, undefined, data);
  Object.assign(task, {
    sourceReplenishmentCode: signal.code,
    sourceWarehouseCode: signal.warehouseCode,
    sourceWarehouseName: signal.warehouseName,
    replenishmentSnapshot: snapshot,
  });
  production.tasks.unshift(task);
  appendProductionTaskFlow(
    data,
    task.code,
    '仓库发起安全库存补货',
    `${signal.code} 触发生产补货 ${formatQty(signal.suggestedQty, signal.uom)}，等待生产计划确认。`,
    actor,
  );
  return {
    signal,
    document: {
      type: '生产任务',
      code: task.code,
      status: task.status,
      path: `/production/tasks/${encodeURIComponent(task.code)}`,
    },
    repeated: false,
  };
}

function nextMasterCode(type, rows, input = {}) {
  const prefix = masterCodePrefix(type, input);
  const maxSequence = rows.reduce((max, row) => {
    const match = new RegExp(`^${escapeRegExp(prefix)}-(\\d{5})$`).exec(String(row.code || ''));
    return Math.max(max, Number(match?.[1]) || 0);
  }, 0);
  return `${prefix}-${String(maxSequence + 1).padStart(5, '0')}`;
}

function isAutoMasterCode(type, value, input = {}) {
  if (!value) return true;
  const code = String(value).trim().toUpperCase();
  if (type === 'currencies' && /^[A-Z]{3}$/.test(code)) return false;
  const prefix = masterCodePrefix(type, input);
  return code === '系统自动生成' || code === 'AUTO' || /^\?+$/.test(code) || !code.startsWith(`${prefix}-`);
}

function normalizeMasterRecord(type, input, existing, rows, data) {
  const code = isAutoMasterCode(type, input.code, input)
    ? existing?.code || nextMasterCode(type, rows, input)
    : normalizedMasterText(input.code);
  const base = {
    ...(existing || {}),
    ...input,
    code,
    name: input.name ?? existing?.name ?? '',
    type: input.type ?? existing?.type ?? '',
    owner: input.owner ?? existing?.owner ?? '',
    status: input.status ?? existing?.status ?? '启用',
    updatedAt: shanghaiDate(),
    revision: existing ? Number(existing.revision || 1) + 1 : 1,
    attachments: Number(input.attachments ?? existing?.attachments ?? 0),
    note: input.note ?? existing?.note ?? '',
  };

  if (type === 'customers') {
    const customerName = normalizedMasterText(base.name);
    const contact = normalizedMasterText(base.contact);
    const phone = normalizedMasterText(base.phone);
    const customerType = normalizedMasterText(base.type);
    const regionType = normalizedMasterText(base.regionType || '国内');
    const status = normalizedMasterStatus(base.status, '客户');
    if (!customerName) throw requestError(400, '客户名称不能为空。');
    if (!contact) throw requestError(400, '客户联系人不能为空。');
    if (!phone) throw requestError(400, '客户联系方式不能为空。');
    if (!customerMasterTypes.includes(customerType)) throw requestError(400, '请选择有效的客户类型。');
    if (!masterRegionTypes.includes(regionType)) throw requestError(400, '请选择有效的客户地区类型。');

    const duplicateName = rows.find((row) => row.code !== code && sameMasterText(row.name, customerName));
    if (duplicateName) throw requestError(400, `客户名称已存在：${duplicateName.code}。`);

    const taxNumber = normalizedOptionalDomesticTaxNumber(base.taxNumber, regionType, '客户税号');
    const duplicateTaxNumber = taxNumber && rows.find((row) => (
      row.code !== code
      && normalizedMasterText(row.taxNumber).replace(/\s+/g, '').toUpperCase() === taxNumber
    ));
    if (duplicateTaxNumber) throw requestError(400, `客户税号已被 ${duplicateTaxNumber.code} 使用。`);

    const paymentMethod = normalizedMasterText(base.paymentMethod || '款到发货');
    if (!customerPaymentMethods.includes(paymentMethod)) throw requestError(400, '请选择有效的客户付款方式。');
    const paymentTermDays = normalizedNonNegativeInteger(base.paymentTermDays ?? 0, '客户付款期限');
    const creditLimit = normalizedNonNegativeNumber(base.creditLimit ?? 0, '客户信用额度');
    const currency = normalizedMasterText(base.currency || 'CNY').toUpperCase();
    const currencyMaster = ensureMasterRows(data, 'currencies').find((row) => row.code === currency);
    if (!currencyMaster || currencyMaster.status === '停用') throw requestError(400, '请选择有效且启用的客户结算币种。');
    const defaultLogisticsMode = normalizeLogisticsMode(base.defaultLogisticsMode || base.deliveryMethod || '');
    if (!customerLogisticsModes.includes(defaultLogisticsMode)) throw requestError(400, '请选择有效的客户默认物流方式。');

    delete base.owner;
    delete base.manager;
    delete base.primary;
    delete base.secondary;
    return {
      ...base,
      name: customerName,
      type: customerType,
      contact,
      phone,
      email: normalizedOptionalEmail(base.email, '客户邮箱'),
      regionType,
      taxNumber,
      paymentMethod,
      paymentTermDays,
      creditLimit: String(creditLimit),
      currency,
      status,
      address: normalizedMasterText(base.address),
      defaultLogisticsMode,
      defaultShipContact: normalizedMasterText(base.defaultShipContact),
      defaultShipPhone: normalizedMasterText(base.defaultShipPhone),
      defaultShipAddress: normalizedMasterText(base.defaultShipAddress),
      note: normalizedMasterText(base.note),
    };
  }

  if (type === 'suppliers') {
    const supplierName = normalizedMasterText(base.name);
    const contact = normalizedMasterText(base.contact);
    const phone = normalizedMasterText(base.phone);
    const supplierType = normalizedMasterText(base.type);
    const regionType = normalizedMasterText(base.regionType || '国内');
    const status = normalizedMasterStatus(base.status, '供应商');
    if (!supplierName) throw requestError(400, '供应商名称不能为空。');
    if (!contact) throw requestError(400, '供应商联系人不能为空。');
    if (!phone) throw requestError(400, '供应商联系方式不能为空。');
    if (!supplierMasterTypes.includes(supplierType)) throw requestError(400, '请选择有效的供应商类型。');
    if (!masterRegionTypes.includes(regionType)) throw requestError(400, '请选择有效的供应商地区类型。');

    const duplicateName = rows.find((row) => row.code !== code && sameMasterText(row.name, supplierName));
    if (duplicateName) throw requestError(400, `供应商名称已存在：${duplicateName.code}。`);

    const taxNumber = normalizedOptionalDomesticTaxNumber(base.taxNumber, regionType, '供应商税号');
    const duplicateTaxNumber = taxNumber && rows.find((row) => (
      row.code !== code
      && normalizedMasterText(row.taxNumber).replace(/\s+/g, '').toUpperCase() === taxNumber
    ));
    if (duplicateTaxNumber) throw requestError(400, `供应商税号已被 ${duplicateTaxNumber.code} 使用。`);

    const paymentMethod = normalizedMasterText(base.paymentMethod || '月结');
    const deliveryMethod = normalizedMasterText(base.deliveryMethod || '送货到厂');
    const taxRate = normalizedMasterText(base.taxRate || '13%');
    const currency = normalizedMasterText(base.currency || 'CNY').toUpperCase();
    if (!supplierPaymentMethods.includes(paymentMethod)) throw requestError(400, '请选择有效的供应商付款方式。');
    if (!supplierDeliveryMethods.includes(deliveryMethod)) throw requestError(400, '请选择有效的供应商交付方式。');
    if (!supplierTaxRates.includes(taxRate)) throw requestError(400, '请选择有效的供应商税率。');
    const currencyMaster = ensureMasterRows(data, 'currencies').find((row) => row.code === currency);
    if (!currencyMaster || currencyMaster.status === '停用') throw requestError(400, '请选择有效且启用的供应商结算币种。');
    const paymentTermDays = normalizedNonNegativeInteger(base.paymentTermDays ?? 0, '供应商付款期限');

    delete base.owner;
    delete base.manager;
    delete base.primary;
    delete base.secondary;
    delete base.supplyScope;
    delete base.incomingQualityRule;
    delete base.qualificationRequired;
    delete base.qualificationStatus;
    delete base.supplyMaterialCount;
    delete base.purchaseLeadTimeDays;
    return {
      ...base,
      name: supplierName,
      type: supplierType,
      contact,
      phone,
      email: normalizedOptionalEmail(base.email, '供应商邮箱'),
      regionType,
      taxNumber,
      paymentMethod,
      paymentTermDays,
      deliveryMethod,
      taxRate,
      currency,
      status,
      address: normalizedMasterText(base.address),
      note: normalizedMasterText(base.note),
    };
  }

  if (type === 'warehouses') {
    delete base.owner;
    delete base.manager;
    delete base.phone;
    delete base.warehouseScope;
    delete base.primary;
    delete base.secondary;

    const warehouseName = String(base.name || '').trim();
    const warehouseType = normalizedWarehouseType(base.type);
    if (!warehouseName) throw requestError(400, '仓库名称不能为空。');
    if (!warehouseTypes.includes(warehouseType)) throw requestError(400, '请选择有效的仓库类型。');
    const status = normalizedMasterStatus(base.status, '仓库');
    const warehouseFunctions = normalizeWarehouseFunctions(
      base.warehouseFunctions,
      warehouseType,
      existing || base,
    );
    const controlledFunctions = warehouseFunctions.filter((item) => ['采购暂存', '销售退货暂存', '不合格隔离'].includes(item));
    if (controlledFunctions.length && warehouseFunctions.length > 1) {
      throw requestError(400, `“${controlledFunctions[0]}”属于受控职能，不能与其他仓库职能同时配置。`);
    }
    if (rows.some((row) => row.code !== code && sameMasterText(row.name, warehouseName))) {
      throw requestError(400, '仓库名称已存在。');
    }

    const companyRef = String(base.company || '').trim();
    const company = ensureMasterRows(data, 'company').find((row) => row.code === companyRef || row.name === companyRef);
    if (!company) throw requestError(400, '请选择有效的所属公司。');
    if (status !== '停用' && company.status === '停用') {
      throw requestError(400, '启用仓库不能归属已停用公司。');
    }
    if (existing) {
      if (String(existing.type || '').trim() !== warehouseType) {
        throw requestError(400, '仓库类型属于库存分类基础，已有仓库不能直接修改；请新建仓库。');
      }
      const previousCompany = ensureMasterRows(data, 'company').find(
        (row) => row.code === existing.company || row.name === existing.company,
      );
      if (previousCompany && previousCompany.code !== company.code) {
        throw requestError(400, '所属公司决定库存责任主体，已有仓库不能直接修改；请新建仓库。');
      }

      const previousFunctions = normalizeWarehouseFunctions(existing.warehouseFunctions, existing.type, existing);
      const removedFunctions = previousFunctions.filter((item) => !warehouseFunctions.includes(item));
      if (removedFunctions.length) {
        const warehouseReferences = [code, existing.code, warehouseName, existing.name].filter(Boolean);
        const inventoryFacts = outstandingInventoryFacts(
          data,
          (row) => warehouseReferences.includes(row.warehouseCode) || warehouseReferences.includes(row.warehouse),
        );
        if (inventoryFacts.length) {
          throw requestError(
            409,
            `仓库仍有 ${inventoryFacts.length} 条非零库存、待检、待入库或占用事实，不能取消“${removedFunctions.join('、')}”职能。`,
          );
        }
        if (removedFunctions.includes('采购暂存')) {
          const openOrders = ensurePurchase(data).orders.filter((order) => (
            !['已关闭', '已作废', '已取消'].includes(String(order.status || ''))
            && warehouseReferences.includes(order.warehouseCode || order.warehouse)
          ));
          const openReceipts = ensureWarehouse(data).purchaseReceipts.filter((receipt) => (
            !['已入库', '已作废', '已取消'].includes(String(receipt.status || ''))
            && warehouseReferences.includes(receipt.warehouseCode || receipt.warehouse)
          ));
          if (openOrders.length || openReceipts.length) {
            throw requestError(
              409,
              `仓库仍被 ${openOrders.length} 张未关闭采购订单和 ${openReceipts.length} 张未完成采购收货引用，不能取消“采购暂存”职能。`,
            );
          }
        }
        if (removedFunctions.includes('销售退货暂存')) {
          const allOpenTasks = ensureWarehouse(data).afterSalesTasks.filter((task) => (
            !['已完成', '已取消'].includes(String(task.status || ''))
            && task.afterSaleKind === 'sales'
          ));
          const referencedTasks = allOpenTasks.filter((task) => warehouseReferences.includes(task.warehouseCode || task.warehouse));
          const alternativeExists = rows.some((row) => (
            row.code !== code
            && row.status === '启用'
            && row.company === company.name
            && normalizeWarehouseFunctions(row.warehouseFunctions, row.type, row).includes('销售退货暂存')
          ));
          if (referencedTasks.length || (allOpenTasks.length && !alternativeExists)) {
            throw requestError(409, `当前存在 ${allOpenTasks.length} 张未完成销售退货任务，且不能失去可用的“销售退货暂存”仓库。`);
          }
        }
        if (removedFunctions.includes('可销售出库')) {
          const openIssues = ensureWarehouse(data).salesIssues.filter((issue) => (
            !['已出库', '已作废', '已取消'].includes(String(issue.status || ''))
            && warehouseReferences.includes(issue.warehouseCode || issue.warehouse)
          ));
          if (openIssues.length) throw requestError(409, `仓库仍被 ${openIssues.length} 张未完成销售出库引用，不能取消“可销售出库”职能。`);
        }
        if (removedFunctions.includes('可生产领料')) {
          const openIssues = ensureWarehouse(data).productionIssues.filter((issue) => (
            !['已完成', '已作废', '已取消'].includes(String(issue.status || ''))
            && warehouseReferences.includes(issue.warehouseCode || issue.warehouse)
          ));
          if (openIssues.length) throw requestError(409, `仓库仍被 ${openIssues.length} 张未完成生产领料引用，不能取消“可生产领料”职能。`);
        }
      }
    }

    const locationCount = Number(base.locationCount ?? 0);
    if (!Number.isInteger(locationCount) || locationCount < 0) {
      throw requestError(400, '库位数量必须是大于或等于 0 的整数。');
    }
    const binPrefix = locationCount > 0 ? String(base.binPrefix || '').trim().toUpperCase() : '';
    if (locationCount > 0 && !binPrefix) throw requestError(400, '设置库位数量后必须填写库位前缀。');
    if (binPrefix && !/^[A-Z0-9-]+$/.test(binPrefix)) {
      throw requestError(400, '库位前缀只能使用大写字母、数字或短横线。');
    }

    if (existing && status === '停用') {
      const warehouseReferences = [code, existing.code, warehouseName, existing.name].filter(Boolean);
      const inventoryFacts = outstandingInventoryFacts(
        data,
        (row) => warehouseReferences.includes(row.warehouseCode) || warehouseReferences.includes(row.warehouse),
      );
      if (inventoryFacts.length) {
        throw requestError(400, `仓库仍有 ${inventoryFacts.length} 条非零库存、占用、待入库或在途事实，清理完成后才能停用。`);
      }
      const defaultMaterials = ensureMasterRows(data, 'materials').filter((material) => (
        material.status !== '停用'
        && warehouseReferences.includes(String(material.defaultWarehouse || '').trim())
      ));
      if (defaultMaterials.length) {
        throw requestError(400, `仓库仍是 ${defaultMaterials.length} 项启用物料的常用仓库，请先调整物料后再停用。`);
      }
      const previousFunctions = normalizeWarehouseFunctions(existing.warehouseFunctions, existing.type, existing);
      if (previousFunctions.includes('采购暂存')) {
        const openPurchaseFacts = [
          ...ensurePurchase(data).orders.filter((order) => (
            !['已关闭', '已作废', '已取消'].includes(String(order.status || ''))
            && warehouseReferences.includes(order.warehouseCode || order.warehouse)
          )),
          ...ensureWarehouse(data).purchaseReceipts.filter((receipt) => (
            !['已入库', '已作废', '已取消'].includes(String(receipt.status || ''))
            && warehouseReferences.includes(receipt.warehouseCode || receipt.warehouse)
          )),
        ];
        if (openPurchaseFacts.length) throw requestError(409, `仓库仍承接 ${openPurchaseFacts.length} 项未完成采购收货事实，不能停用。`);
      }
      if (previousFunctions.includes('销售退货暂存')) {
        const openSalesReturnTasks = ensureWarehouse(data).afterSalesTasks.filter((task) => (
          !['已完成', '已取消'].includes(String(task.status || ''))
          && task.afterSaleKind === 'sales'
        ));
        const alternativeExists = rows.some((row) => (
          row.code !== code
          && row.status === '启用'
          && row.company === company.name
          && normalizeWarehouseFunctions(row.warehouseFunctions, row.type, row).includes('销售退货暂存')
        ));
        if (openSalesReturnTasks.some((task) => warehouseReferences.includes(task.warehouseCode || task.warehouse))
          || (openSalesReturnTasks.length && !alternativeExists)) {
          throw requestError(409, `当前存在 ${openSalesReturnTasks.length} 张未完成销售退货任务，且不能失去可用的“销售退货暂存”仓库。`);
        }
      }
    }

    const warehouseRules = warehouseCapabilities(warehouseType, warehouseFunctions, base);

    return {
      ...base,
      ...warehouseRules,
      name: warehouseName,
      type: warehouseType,
      status,
      company: company.name,
      locationCount,
      binPrefix,
      address: normalizedMasterText(base.address),
      note: normalizedMasterText(base.note),
    };
  }

  if (type === 'materials') {
    delete base.owner;
    delete base.primary;
    delete base.secondary;
    delete base.isFinishedProduct;
    delete base.shelfLifeApplicable;
    delete base.shelfLifeMonths;
    delete base.purchaseLeadTimeDays;
    delete base.productionLeadTimeDays;
    delete base.safetyStock;
    delete base.reorderPoint;

    const materialName = normalizedMasterText(base.name);
    const category = normalizedMasterText(base.category || base.type);
    const uomRef = normalizedMasterText(base.uom);
    const status = normalizedMasterStatus(base.status, '物料');
    if (!materialName) throw requestError(400, '物料名称不能为空。');
    if (!materialCategories.includes(category)) throw requestError(400, '请选择有效的物料分类。');

    const uom = ensureMasterRows(data, 'uom').find((row) => row.code === uomRef || row.name === uomRef);
    if (!uom) throw requestError(400, '请选择有效的基础单位。');
    if (status !== '停用' && uom.status === '停用') throw requestError(400, '启用物料不能使用已停用的基础单位。');

    if (existing) {
      const previousCategory = normalizedMasterText(existing.category || existing.type);
      const previousUom = normalizedMasterText(existing.uom);
      if (previousCategory && previousCategory !== category) {
        throw requestError(400, '物料分类决定编码前缀，已有物料不能直接改分类；请新建物料。');
      }
      if (previousUom && previousUom !== uom.name) {
        throw requestError(400, '基础单位决定库存和单据数量口径，已有物料不能直接修改；请新建物料。');
      }
      if (status === '停用') {
        const materialReferences = [code, existing.code, materialName, existing.name].filter(Boolean);
        const inventoryFacts = outstandingInventoryFacts(
          data,
          (row) => materialReferences.includes(row.materialCode) || materialReferences.includes(row.item),
        );
        if (inventoryFacts.length) {
          throw requestError(400, `物料仍有 ${inventoryFacts.length} 条非零库存、占用、待入库或在途事实，清理完成后才能停用。`);
        }
      }
    }

    const isPurchasable = Boolean(
      input.isPurchasable
      ?? base.isPurchasable
      ?? ['采购', '采购+自制'].includes(base.supplyStrategy || ''),
    );
    const isProducible = Boolean(
      input.isProducible
      ?? base.isProducible
      ?? ['自制', '采购+自制', '委外'].includes(base.supplyStrategy || ''),
    );
    const isSaleable = Boolean(input.isSaleable ?? base.isSaleable ?? category === '成品');
    if (!isSaleable && !isPurchasable && !isProducible) throw requestError(400, '物料至少需要一个业务属性。');

    const batchControl = normalizedMasterText(base.batchControl || '批次管理');
    if (!['批次管理', '不追踪批次'].includes(batchControl)) throw requestError(400, '请选择有效的物料批次追踪方式。');
    const shelfLife = normalizedMasterText(base.shelfLife || '无效期要求');
    const shelfLifeMatch = /^(\d+)个月$/.exec(shelfLife);
    if (shelfLife !== '无效期要求' && (!shelfLifeMatch || Number(shelfLifeMatch[1]) <= 0)) {
      throw requestError(400, '物料效期必须为无效期要求或大于 0 的整月数。');
    }
    const incomingQualityControl = normalizedMasterText(base.incomingQualityControl || base.qualityControl || '不适用');
    const inboundQualityControl = normalizedMasterText(base.inboundQualityControl || '不适用');
    if (!materialQualityRules.includes(incomingQualityControl) || !materialQualityRules.includes(inboundQualityControl)) {
      throw requestError(400, '请选择有效的物料检验规则。');
    }

    const warehouseRef = normalizedMasterText(base.defaultWarehouse);
    let defaultWarehouse = '';
    if (warehouseRef) {
      const warehouse = ensureMasterRows(data, 'warehouses').find((row) => row.code === warehouseRef || row.name === warehouseRef);
      if (!warehouse) throw requestError(400, '请选择有效的常用仓库。');
      if (status !== '停用' && warehouse.status === '停用') throw requestError(400, '启用物料不能使用已停用的常用仓库。');
      defaultWarehouse = warehouse.name;
    }

    return {
      ...base,
      name: materialName,
      englishName: normalizedMasterText(base.englishName),
      englishModel: normalizedMasterText(base.englishModel),
      englishSpec: normalizedMasterText(base.englishSpec),
      type: category,
      category,
      uom: uom.name,
      status,
      isSaleable,
      isPurchasable,
      isProducible,
      supplyStrategy: isPurchasable && isProducible ? '采购+自制' : isPurchasable ? '采购' : isProducible ? '自制' : '',
      defaultWarehouse,
      batchControl,
      shelfLife,
      incomingQualityControl,
      inboundQualityControl,
      qualityControl: incomingQualityControl,
      note: normalizedMasterText(base.note),
    };
  }

  if (type === 'employees') {
    delete base.type;
    delete base.supervisor;
    delete base.employmentStatus;
    delete base.contact;
    delete base.primary;
    delete base.secondary;
    delete base.birthDate;
    delete base.homeAddress;
    delete base.emergencyContactName;
    delete base.emergencyContactPhone;
    delete base.linkedAccount;
    delete base.linkedAccountStatus;
    const employeeName = normalizedMasterText(base.name);
    const position = normalizedMasterText(base.position);
    const departmentCode = normalizedMasterText(base.departmentCode);
    const departmentName = normalizedMasterText(base.owner);
    const departmentRef = departmentCode || departmentName;
    const status = normalizedMasterStatus(base.status, '员工');
    if (!employeeName) throw requestError(400, '员工姓名不能为空。');
    if (!position) throw requestError(400, '员工岗位/职务不能为空。');
    if (!departmentRef) throw requestError(400, '员工必须选择所属部门。');

    const department = resolveMasterDepartmentFields(
      data,
      departmentCode,
      departmentName,
      '员工',
      '员工必须选择有效的所属部门；部门编码与名称不一致，请重新选择。',
    );
    if (!department) throw requestError(400, '员工必须选择有效的所属部门。');
    if (status !== '停用' && department.status === '停用') {
        throw requestError(400, '启用员工必须选择有效的所属部门，且该部门必须处于启用状态。');
    }

    const gender = normalizedMasterText(base.gender);
    if (gender && !['男', '女', '未说明'].includes(gender)) throw requestError(400, '请选择有效的员工性别。');
    const hireDate = normalizedMasterText(base.hireDate);
    if (hireDate && !isValidIsoDate(hireDate)) throw requestError(400, '请填写有效的员工入职日期。');

    if (status === '停用' && existing?.status !== '停用' && data) {
      assertEmployeeHasNoOpenEquipmentInspectionResponsibility(data, { ...existing, ...base, code, name: employeeName });
      const linkedAccounts = activeAccountsLinkedToEmployee(data, code, employeeName);
      if (linkedAccounts.length) {
        throw requestError(
          400,
          `员工 ${employeeName || code} 已关联 ${linkedAccounts.length} 个启用账号，请先停用或解绑账号后再停用员工。`,
        );
      }
    }
    const linkedAccount = ensureSystem(data).accounts.find((account) => (
      String(account.employeeCode || '').trim() === code
      || (!account.employeeCode && String(account.name || '').trim() === employeeName)
    ));
    return {
      ...base,
      name: employeeName,
      englishName: normalizedMasterText(base.englishName),
      position,
      owner: department.name,
      departmentCode: department.code,
      phone: normalizedMasterText(input.phone ?? existing?.phone ?? ''),
      email: normalizedOptionalEmail(base.email, '员工邮箱'),
      gender,
      hireDate,
      status,
      note: normalizedMasterText(base.note),
      linkedAccount: linkedAccount?.username || linkedAccount?.code || '',
      linkedAccountStatus: linkedAccount?.status || '未分配',
    };
  }

  if (type === 'uom') {
    const unitName = String(base.name || '').trim();
    const englishAbbreviation = String(base.englishAbbreviation || base.englishName || '').trim();
    if (!unitName || !englishAbbreviation) throw requestError(400, '单位和英文简称不能为空。');
    if (!/^[A-Za-z0-9./-]{1,16}$/.test(englishAbbreviation)) {
      throw requestError(400, '英文简称只能使用 1 到 16 位英文字母、数字、点、斜线或短横线。');
    }
    const status = normalizedMasterStatus(base.status, '计量单位');
    const duplicateUnit = rows.find((row) => (
      row.code !== code
      && (
        String(row.name || '').trim().toLowerCase() === unitName.toLowerCase()
        || String(row.englishAbbreviation || '').trim().toLowerCase() === englishAbbreviation.toLowerCase()
      )
    ));
    if (duplicateUnit) throw requestError(400, '单位或英文简称已存在。');

    if (existing && data) {
      const previousRefs = [existing.code, existing.name].map((value) => String(value || '').trim()).filter(Boolean);
      const materialReferences = ensureMasterRows(data, 'materials').filter((material) => previousRefs.includes(String(material.uom || '').trim()));
      const definitionChanged = String(existing.name || '').trim() !== unitName;
      if (definitionChanged && materialReferences.length) {
        throw requestError(400, `该单位已被 ${materialReferences.length} 项物料引用，不能修改；请新建单位。`);
      }
      const activeMaterialReferences = materialReferences.filter((material) => material.status !== '停用');
      if (status === '停用' && activeMaterialReferences.length) {
        throw requestError(400, `该单位仍被 ${activeMaterialReferences.length} 项启用物料引用，不能停用。`);
      }
    }

    delete base.symbol;
    delete base.type;
    delete base.baseUom;
    delete base.conversionRate;
    delete base.decimalPrecision;
    delete base.englishName;
    delete base.owner;
    delete base.primary;
    delete base.secondary;
    return {
      ...base,
      name: unitName,
      englishAbbreviation,
      status,
      note: normalizedMasterText(base.note),
    };
  }

  if (type === 'currencies') {
    delete base.englishName;
    delete base.type;
    delete base.owner;
    delete base.primary;
    delete base.secondary;
    const currencyCode = String(code || '').trim().toUpperCase();
    const currencyName = normalizedMasterText(base.name);
    const symbol = normalizedMasterText(base.symbol);
    const decimalPlaces = Number(base.decimalPlaces);
    const status = normalizedMasterStatus(base.status, '币种');
    if (!/^[A-Z]{3}$/.test(currencyCode)) throw requestError(400, '币种代码必须是 3 位大写英文字母。');
    if (!currencyName || !symbol) throw requestError(400, '币种名称和货币符号不能为空。');
    if (!Number.isInteger(decimalPlaces) || decimalPlaces < 0 || decimalPlaces > 4) {
      throw requestError(400, '金额小数位必须是 0 到 4 的整数。');
    }
    if (existing && String(existing.code || '').trim().toUpperCase() !== currencyCode) {
      throw requestError(400, '币种代码是全局引用标识，已有币种不能修改代码。');
    }
    const duplicateCurrency = rows.find((row) => row.code !== currencyCode && sameMasterText(row.name, currencyName));
    if (duplicateCurrency) throw requestError(400, `币种名称已被 ${duplicateCurrency.code} 使用。`);
    if (status === '停用') {
      const activeCustomerCount = ensureMasterRows(data, 'customers')
        .filter((row) => row.status !== '停用' && row.currency === currencyCode).length;
      const activeSupplierCount = ensureMasterRows(data, 'suppliers')
        .filter((row) => row.status !== '停用' && row.currency === currencyCode).length;
      if (activeCustomerCount || activeSupplierCount) {
        throw requestError(
          400,
          `币种仍被 ${activeCustomerCount} 个启用客户和 ${activeSupplierCount} 个启用供应商引用，不能停用。`,
        );
      }
    }
    return {
      ...base,
      code: currencyCode,
      name: currencyName,
      symbol,
      decimalPlaces,
      status,
      note: normalizedMasterText(base.note),
    };
  }

  if (type === 'departments') {
    delete base.type;
    delete base.manager;
    delete base.primary;
    delete base.secondary;
    const departmentName = normalizedMasterText(base.name);
    const status = normalizedMasterStatus(base.status, '部门');
    if (!departmentName) throw requestError(400, '部门名称不能为空。');
    const companyRef = String(base.owner || '').trim();
    if (!companyRef) throw requestError(400, '部门必须选择所属公司。');
    const company = ensureMasterRows(data, 'company').find((row) => row.code === companyRef || row.name === companyRef);
    if (!company || company.status === '停用') throw requestError(400, '部门必须归属已启用的公司。');

    const duplicateDepartment = rows.find((row) => (
      row.code !== code
      && sameMasterText(row.name, departmentName)
      && String(row.owner || '').trim() === company.name
    ));
    if (duplicateDepartment) throw requestError(400, '同一公司内不能存在同名部门。');

    const parentRef = String(base.parentDepartment || '').trim();
    if (parentRef) {
      const parent = rows.find((row) => row.code === parentRef)
        || rows.find((row) => row.name === parentRef && String(row.owner || '').trim() === company.name);
      if (!parent) throw requestError(400, '请选择有效的上级部门。');
      if (parent.code === code) throw requestError(400, '上级部门不能选择当前部门自身。');
      if (String(parent.owner || '').trim() !== company.name) throw requestError(400, '上级部门必须属于同一公司。');
      if (base.status !== '停用' && parent.status === '停用') {
        throw requestError(400, '启用部门不能归属已停用部门。');
      }
      base.parentDepartment = parent.name;

      const visited = new Set([code]);
      let cursor = parent;
      while (cursor) {
        if (visited.has(cursor.code)) throw requestError(400, '部门上下级关系不能形成循环。');
        visited.add(cursor.code);
        const nextRef = String(cursor.parentDepartment || '').trim();
        cursor = nextRef ? rows.find((row) => row.code === nextRef || row.name === nextRef) : undefined;
      }
    }
    base.name = departmentName;
    base.status = status;
  }

  if (type === 'departments' && base.status === '停用' && data) {
    const employeeRows = ensureMasterRows(data, 'employees');
    const linkedEmployees = employeeRows.filter(
      (employee) =>
        employee.status !== '停用' &&
        [base.name, code, existing?.name, existing?.code].filter(Boolean).includes(employee.owner),
    );
    if (linkedEmployees.length) {
      throw requestError(
        400,
        `部门 ${base.name || code} 仍被 ${linkedEmployees.length} 个启用员工引用，请先调整员工所属部门或停用员工后再停用部门。`,
      );
    }
    const linkedChildren = rows.filter(
      (department) => department.code !== code
        && department.status !== '停用'
        && [base.name, code, existing?.name, existing?.code].filter(Boolean).includes(department.parentDepartment),
    );
    if (linkedChildren.length) {
      throw requestError(
        400,
        `部门 ${base.name || code} 仍有 ${linkedChildren.length} 个启用下级部门，请先调整或停用下级部门。`,
      );
    }
    const references = [base.name, code, existing?.name, existing?.code].filter(Boolean);
    const linkedResources = [
      ['设备', ensureMasterRows(data, 'equipment').filter((row) => row.status !== '停用' && references.includes(row.owner))],
      ['产线', ensureMasterRows(data, 'productionLines').filter((row) => row.status !== '停用' && references.includes(row.owner))],
    ].filter(([, linkedRows]) => linkedRows.length > 0);
    if (linkedResources.length) {
      const summary = linkedResources.map(([label, linkedRows]) => `${linkedRows.length} 个${label}`).join('、');
      throw requestError(400, `部门 ${base.name || code} 仍被${summary}引用，请先调整或停用相关资源。`);
    }
  }

  if (type === 'departments' && existing && data && String(existing.name || '').trim() !== String(base.name || '').trim()) {
    const linkedEmployees = ensureMasterRows(data, 'employees').filter(
      (employee) => [existing.name, existing.code].filter(Boolean).includes(employee.owner),
    );
    const linkedChildren = rows.filter(
      (department) => department.code !== code
        && [existing.name, existing.code].filter(Boolean).includes(department.parentDepartment),
    );
    const references = [existing.name, existing.code].filter(Boolean);
    const linkedResources = ['equipment', 'productionLines'].flatMap((masterType) => (
      ensureMasterRows(data, masterType).filter((row) => references.includes(row.owner))
    ));
    if (linkedEmployees.length || linkedChildren.length || linkedResources.length) {
      throw requestError(400, '部门已被员工、下级部门或业务资源引用，不能直接改名；请先调整引用关系。');
    }
  }

  if (type === 'departments') {
    return {
      ...base,
      owner: ensureMasterRows(data, 'company').find((row) => row.code === base.owner || row.name === base.owner)?.name || base.owner,
      note: normalizedMasterText(base.note),
      employeeCount: ensureMasterRows(data, 'employees').filter(
        (employee) => employee.status !== '停用' && [base.name, code].filter(Boolean).includes(employee.owner),
      ).length,
    };
  }

  if (type === 'equipment') {
    delete base.type;
    delete base.manager;
    delete base.operatingState;
    delete base.maintenanceCycleWeeks;
    delete base.sourcePurchase;
    const equipmentName = String(base.name || '').trim();
    if (!equipmentName) throw requestError(400, '设备名称不能为空。');
    const equipmentModel = String(base.model || '').trim();
    if (!equipmentModel) throw requestError(400, '设备型号不能为空。');
    const status = normalizedMasterStatus(base.status, '设备');
    const location = normalizedMasterText(base.primary);
    if (!location) throw requestError(400, '设备使用位置不能为空。');
    if (existing) {
      const equipmentManagement = ensureEquipmentManagement(data);
      const activeInspectionPlan = equipmentManagement.plans.find((plan) => (
        plan.equipmentCode === code && plan.status === '启用'
      ));
      const openInspectionTask = equipmentManagement.tasks.find((task) => (
        task.equipmentCode === code && equipmentInspectionTaskIsOpen(task)
      ));
      if (activeInspectionPlan && equipmentModel !== String(existing.model || '').trim()) {
        throw requestError(400, `设备正被启用巡检计划 ${activeInspectionPlan.code} 引用，不能修改型号；请先停用或调整该计划。`);
      }
      if (openInspectionTask && equipmentModel !== String(existing.model || '').trim()) {
        throw requestError(400, `设备仍有未完成巡检任务 ${openInspectionTask.code}，不能修改型号；请先完成或取消该任务。`);
      }
      if (activeInspectionPlan && status === '停用') {
        throw requestError(400, `设备正被启用巡检计划 ${activeInspectionPlan.code} 引用，不能停用；请先停用该计划。`);
      }
      if (openInspectionTask && status === '停用') {
        throw requestError(400, `设备仍有未完成巡检任务 ${openInspectionTask.code}，不能停用；请先完成或取消该任务。`);
      }
    }

    const serialNumber = String(base.serialNumber || '').trim();
    const duplicateSerial = serialNumber && rows.find((row) => (
      row.code !== code
      && String(row.serialNumber || '').trim().toLowerCase() === serialNumber.toLowerCase()
    ));
    if (duplicateSerial) throw requestError(400, '设备出厂编号已存在。');

    const startDate = String(base.startDate || '').trim();
    if (startDate && (!isValidIsoDate(startDate) || startDate > shanghaiDate())) {
      throw requestError(400, '启用日期必须是今天或更早的有效日期。');
    }

    const departmentCode = normalizedMasterText(base.departmentCode);
    const departmentName = normalizedMasterText(base.owner);
    const departmentRef = departmentCode || departmentName;
    if (!departmentRef) throw requestError(400, '设备必须选择所属部门。');
    const department = resolveMasterDepartmentFields(
      data,
      departmentCode,
      departmentName,
      '设备',
      '启用设备必须归属有效且启用的部门；部门编码与名称不一致，请重新选择。',
    );
    if (!department) throw requestError(400, '设备必须归属有效部门。');
    if (status !== '停用' && department.status === '停用') throw requestError(400, '启用设备必须归属有效且启用的部门。');

    return {
      ...base,
      name: equipmentName,
      model: equipmentModel,
      serialNumber,
      owner: department.name,
      departmentCode: department.code,
      primary: location,
      startDate,
      status,
      note: normalizedMasterText(base.note),
    };
  }

  if (type === 'productionLines') {
    delete base.manager;
    delete base.operatingState;
    delete base.primary;
    delete base.secondary;
    const lineName = String(base.name || '').trim();
    const lineType = String(base.type || '').trim();
    const capacityUnit = String(base.capacityUnit || '').trim();
    const capacityValue = Number(base.capacityValue);
    if (!lineName) throw requestError(400, '产线名称不能为空。');
    if (!['挤出产线', '复绕产线', '包装产线', '试验产线'].includes(lineType)) {
      throw requestError(400, '请选择有效的产线类型。');
    }
    const status = normalizedMasterStatus(base.status, '产线');
    if (rows.some((row) => row.code !== code && String(row.name || '').trim().toLowerCase() === lineName.toLowerCase())) {
      throw requestError(400, '产线名称已存在。');
    }
    if (!Number.isFinite(capacityValue) || capacityValue <= 0) throw requestError(400, '标准产能必须大于 0。');
    if (['挤出产线', '试验产线'].includes(lineType) && capacityUnit !== 'kg/小时') {
      throw requestError(400, `${lineType}的标准产能统一使用 kg/小时。`);
    }
    if (['复绕产线', '包装产线'].includes(lineType) && !['卷/班', '卷/小时'].includes(capacityUnit)) {
      throw requestError(400, `${lineType}的标准产能请使用卷/班或卷/小时。`);
    }
    const workshop = String(base.workshop || '').trim();
    const processScope = String(base.processScope || '').trim();
    if (!workshop) throw requestError(400, '车间或区域不能为空。');
    if (!processScope) throw requestError(400, '适用工艺或产品不能为空。');

    const departmentCode = normalizedMasterText(base.departmentCode);
    const departmentName = normalizedMasterText(base.owner);
    const departmentRef = departmentCode || departmentName;
    if (!departmentRef) throw requestError(400, '产线必须选择所属部门。');
    const department = resolveMasterDepartmentFields(
      data,
      departmentCode,
      departmentName,
      '产线',
      '启用产线必须归属有效且启用的部门；部门编码与名称不一致，请重新选择。',
    );
    if (!department) throw requestError(400, '产线必须归属有效部门。');
    if (status !== '停用' && department.status === '停用') throw requestError(400, '启用产线必须归属有效且启用的部门。');

    const referencedLineNames = [code, existing?.code, lineName, existing?.name].filter(Boolean);
    const relatedJobs = ensureProduction(data).executionCards.flatMap((card) => (
      ensureExecutionCardOperationJobs(data, card).filter((job) => (
        referencedLineNames.includes(job.assignedLine) || referencedLineNames.includes(job.recommendedLine)
      ))
    ));
    if (existing && status === '停用') {
      const openJobs = relatedJobs.filter((job) => !['已完成', '已取消', '已关闭'].includes(String(job.status || '')));
      if (openJobs.length) throw requestError(400, `产线仍有 ${openJobs.length} 个未结束设备作业，请先改线或结束作业。`);
    }
    if (existing && String(existing.name || '').trim() !== lineName && relatedJobs.length) {
      throw requestError(400, '产线已被生产设备作业引用，不能直接改名；请先处理关联作业。');
    }

    return {
      ...base,
      name: lineName,
      type: lineType,
      workshop,
      processScope,
      capacityValue,
      capacityUnit,
      owner: department.name,
      departmentCode: department.code,
      status,
      note: normalizedMasterText(base.note),
    };
  }

  if (type === 'company') {
    delete base.owner;
    delete base.manager;
    const companyName = String(base.name || '').trim();
    const taxNumber = String(base.taxNumber || '').replace(/\s+/g, '').toUpperCase();
    const companyType = normalizedMasterText(base.type);
    const status = normalizedMasterStatus(base.status, '公司');
    if (!companyName) throw requestError(400, '公司名称不能为空。');
    if (!taxNumber) throw requestError(400, '统一社会信用代码不能为空。');
    if (!['总公司', '分支机构'].includes(companyType)) throw requestError(400, '请选择有效的公司类型。');
    if (!/^[0-9A-Z]{18}$/.test(taxNumber)) {
      throw requestError(400, '统一社会信用代码必须是 18 位数字或大写字母。');
    }

    const duplicateCompany = rows.find((row) => (
      row.code !== code
      && (
        String(row.name || '').trim().toLowerCase() === companyName.toLowerCase()
        || String(row.taxNumber || '').replace(/\s+/g, '').toUpperCase() === taxNumber
      )
    ));
    if (duplicateCompany) throw requestError(400, '公司名称或统一社会信用代码已存在。');

    const taxRateNumber = Number(String(base.secondary || '').replace('%', '').trim());
    if (!Number.isFinite(taxRateNumber) || taxRateNumber < 0 || taxRateNumber > 100) {
      throw requestError(400, '默认税率必须是 0% 到 100% 之间的数值。');
    }
    const normalizedTaxRate = `${Number(taxRateNumber.toFixed(4))}%`;

    let website = String(base.website || '').trim();
    if (website && !/^https?:\/\//i.test(website)) website = `https://${website}`;
    if (website) {
      let parsedWebsite;
      try {
        parsedWebsite = new URL(website);
      } catch {
        throw requestError(400, '请填写有效的公司官网地址。');
      }
      if (!['http:', 'https:'].includes(parsedWebsite.protocol) || !parsedWebsite.hostname.includes('.')) {
        throw requestError(400, '公司官网只支持有效的 HTTP 或 HTTPS 地址。');
      }
      website = parsedWebsite.toString().replace(/\/$/, '');
    }

    if (existing && data) {
      const previousReferences = [existing.code, existing.name].map((value) => String(value || '').trim()).filter(Boolean);
      const linkedDepartments = ensureMasterRows(data, 'departments').filter((department) =>
        previousReferences.includes(String(department.owner || '').trim()),
      );
      const linkedWarehouses = ensureMasterRows(data, 'warehouses').filter((warehouse) =>
        previousReferences.includes(String(warehouse.company || '').trim()),
      );
      if (String(existing.name || '').trim() !== companyName && (linkedDepartments.length || linkedWarehouses.length)) {
        throw requestError(400, '公司已被部门或仓库引用，不能直接改名；请先调整引用关系。');
      }
      const activeDepartments = linkedDepartments.filter((department) => department.status !== '停用');
      const activeWarehouses = linkedWarehouses.filter((warehouse) => warehouse.status !== '停用');
      if (status === '停用' && (activeDepartments.length || activeWarehouses.length)) {
        throw requestError(
          400,
          `公司仍被 ${activeDepartments.length} 个启用部门和 ${activeWarehouses.length} 个启用仓库引用，请先调整或停用这些资料。`,
        );
      }
    }

    return {
      ...base,
      name: companyName,
      type: companyType,
      englishName: String(base.englishName || '').trim(),
      taxNumber,
      invoiceTitle: String(base.invoiceTitle || '').trim() || companyName,
      secondary: normalizedTaxRate,
      website,
      email: normalizedOptionalEmail(base.email, '公司邮箱'),
      address: String(base.address || '').trim(),
      englishAddress: String(base.englishAddress || '').trim(),
      seal: Math.min(3, Math.max(0, Number(base.seal) || 0)),
      primary: String(base.primary || '').trim(),
      status,
      note: normalizedMasterText(base.note),
    };
  }

  return {
    ...base,
    primary: base.primary || base.manager || base.contact || '',
    secondary: base.secondary || base.address || base.note || '',
  };
}

function syncMasterReferenceProjections(data, type, previous, record) {
  const relations = ensureMasterRelations(data);
  const previousName = String(previous?.name || '').trim();
  const nameChanged = previousName && previousName !== String(record.name || '').trim();

  if (type === 'suppliers') {
    relations.materialSuppliers
      .filter((row) => row.supplierCode === record.code)
      .forEach((row) => {
        row.supplierName = record.name;
        if (record.status === '停用' || !supplierSupportsMaterialRelations(record.type)) {
          row.status = '停用';
          row.isDefault = false;
        }
      });
  }

  if (type === 'materials') {
    relations.materialSuppliers
      .filter((row) => row.materialCode === record.code)
      .forEach((row) => {
        row.materialName = record.name;
        if (record.status === '停用' || !isPurchasableMaterial(record)) {
          row.status = '停用';
          row.isDefault = false;
        }
      });
    relations.warehouseMaterials
      .filter((row) => row.materialCode === record.code)
      .forEach((row) => {
        row.materialName = record.name;
        row.uom = record.uom || row.uom;
        if (record.status === '停用') {
          row.status = '停用';
        }
      });
    if (nameChanged) {
      ensureWarehouse(data).inventory
        .filter((row) => row.materialCode === record.code || row.item === previousName)
        .forEach((row) => { row.item = record.name; });
    }
  }

  if (type === 'warehouses') {
    relations.warehouseMaterials
      .filter((row) => row.warehouseCode === record.code)
      .forEach((row) => {
        row.warehouseName = record.name;
        if (record.status === '停用' || !warehouseSupportsReplenishment(record)) row.status = '停用';
      });
    if (nameChanged) {
      ensureMasterRows(data, 'materials')
        .filter((material) => [previous?.code, previousName].filter(Boolean).includes(material.defaultWarehouse))
        .forEach((material) => { material.defaultWarehouse = record.name; });
      ensureWarehouse(data).inventory
        .filter((row) => row.warehouseCode === record.code || row.warehouse === previousName)
        .forEach((row) => { row.warehouse = record.name; });
    }
  }

  if (type === 'equipment') {
    ensureEquipmentManagement(data).plans
      .filter((plan) => plan.equipmentCode === record.code)
      .forEach((plan) => {
        plan.equipmentName = record.name;
        plan.equipmentModel = record.model;
        plan.location = record.primary;
      });
  }
}

