function equipmentInspectionTaskIsOpen(task) {
  return ['待巡检', '巡检中', '异常处理中'].includes(String(task?.status || ''));
}

function ensureEquipmentManagement(data) {
  data.equipmentManagement ||= {};
  const equipment = data.equipmentManagement;
  for (const key of ['standards', 'plans', 'tasks']) {
    if (!Array.isArray(equipment[key]) || equipment[key].length === 0) {
      equipment[key] = cloneJson(equipmentInspectionSeed[key]);
    }
  }
  if (!equipment.flowRecords || typeof equipment.flowRecords !== 'object') equipment.flowRecords = {};
  if (!Array.isArray(equipment.commands)) equipment.commands = [];
  const employees = ensureMasterRows(data, 'employees');
  const eligibleOwner = (row) => row.status !== '停用' && employeeHasActivePermission(data, row, 'PERM-EQUIPMENT-OPERATE');
  const defaultOwner = employees.find((row) => row.code === 'EMP-ZN' && eligibleOwner(row))
    || employees.find(eligibleOwner);
  const masterEquipment = ensureMasterRows(data, 'equipment');
  equipment.standards.forEach((standard) => {
    if (!standard.equipmentModel) {
      const legacyScope = String(standard.equipmentScope || '').trim();
      const matchedEquipment = masterEquipment.find((row) => {
        const equipmentName = String(row.name || '').replace(/\s+\d+\s*$/, '');
        return legacyScope && (
          legacyScope === String(row.model || '').trim()
          || legacyScope === String(row.name || '').trim()
          || legacyScope === equipmentName
        );
      });
      standard.equipmentModel = matchedEquipment?.model
        || ({ 'EIS-EXT-DAILY-V1': 'JWS45', 'EIS-WIND-SHIFT-V1': 'FW-2S' }[standard.code] || '');
    }
    delete standard.equipmentScope;
    delete standard.inspectionMethod;
    delete standard.owner;
    if (standard.note === '每班开机前完成。') standard.note = '每日开机前完成。';
    if (standard.updatedBy === '设备主管' && defaultOwner) standard.updatedBy = defaultOwner.name;
  });
  equipment.plans.forEach((plan) => {
    const referencedStandard = equipment.standards.find((standard) => standard.code === plan.standardCode);
    if (referencedStandard) {
      plan.standardName = referencedStandard.name;
      plan.standardRevision = Number(referencedStandard.revision || 1);
    }
    try {
      plan.executionWindow = normalizeEquipmentInspectionWindow(plan.executionWindow);
    } catch {
      plan.executionWindow = '08:00-17:00';
    }
    if (plan.frequency === '每班') plan.frequency = '每日';
    const ownerEmployee = employees.find((row) => (
      (plan.ownerEmployeeCode && row.code === plan.ownerEmployeeCode)
      || (!plan.ownerEmployeeCode && row.name === plan.owner)
    ));
    if (ownerEmployee) {
      plan.owner = ownerEmployee.name;
      plan.ownerEmployeeCode = ownerEmployee.code;
    }
    if (plan.status !== '启用') return;
    const nextOpenTask = equipment.tasks
      .filter((task) => task.planCode === plan.code && equipmentInspectionTaskIsOpen(task))
      .sort((left, right) => String(left.scheduledDate || '').localeCompare(String(right.scheduledDate || '')))[0];
    if (nextOpenTask) plan.nextDueDate = nextOpenTask.scheduledDate;
  });
  equipment.tasks.forEach((task) => {
    delete task.note;
    task.cancelReason ||= '';
    task.cancelledAt ||= '';
    const plan = equipment.plans.find((candidate) => candidate.code === task.planCode);
    const taskStandard = equipment.standards.find((standard) => standard.code === task.standardCode);
    if (!Number.isInteger(Number(task.standardRevision)) || Number(task.standardRevision) < 1) {
      task.standardRevision = Number(taskStandard?.revision || 1);
    }
    if (!task.dueAt && plan) {
      task.dueAt = equipmentInspectionDueAt(task.scheduledDate, plan.executionWindow);
    }
    const assignee = employees.find((row) => (
      (task.assigneeEmployeeCode && row.code === task.assigneeEmployeeCode)
      || (!task.assigneeEmployeeCode && row.name === task.assignee)
    ));
    if (assignee) {
      if (!task.assignee) task.assignee = assignee.name;
      if (!task.assigneeEmployeeCode) task.assigneeEmployeeCode = assignee.code;
      if (task.updatedBy === '设备主管') task.updatedBy = assignee.name;
    }
  });
  return equipment;
}

function equipmentInspectionResponsibilityUsage(data, employee) {
  const equipment = ensureEquipmentManagement(data);
  const employeeCode = String(employee?.code || '').trim();
  const employeeName = String(employee?.name || '').trim();
  const matches = (code, name) => (
    (employeeCode && String(code || '').trim() === employeeCode)
    || (!code && employeeName && String(name || '').trim() === employeeName)
  );
  return {
    plans: equipment.plans.filter((plan) => (
      plan.status === '启用' && matches(plan.ownerEmployeeCode, plan.owner)
    )),
    tasks: equipment.tasks.filter((task) => (
      equipmentInspectionTaskIsOpen(task) && matches(task.assigneeEmployeeCode, task.assignee)
    )),
  };
}

function equipmentInspectionResponsibilitySummary(usage) {
  return [
    usage.plans.length ? `${usage.plans.length} 个启用巡检计划` : '',
    usage.tasks.length ? `${usage.tasks.length} 个未完成巡检任务` : '',
  ].filter(Boolean).join('、');
}

function assertEmployeeHasNoOpenEquipmentInspectionResponsibility(data, employee) {
  const usage = equipmentInspectionResponsibilityUsage(data, employee);
  if (!usage.plans.length && !usage.tasks.length) return;
  throw requestError(
    400,
    `员工 ${employee.name || employee.code} 仍负责${equipmentInspectionResponsibilitySummary(usage)}；请先调整巡检计划负责人，并完成或承接已开始的巡检任务后再停用。`,
  );
}

function assertEquipmentInspectionResponsibilityContinuity(data, proposedData) {
  const currentEmployees = ensureMasterRows(data, 'employees');
  const proposedEmployees = ensureMasterRows(proposedData, 'employees');
  for (const currentEmployee of currentEmployees) {
    const usage = equipmentInspectionResponsibilityUsage(data, currentEmployee);
    if (!usage.plans.length && !usage.tasks.length) continue;
    if (currentEmployee.status === '停用' || !employeeHasActivePermission(data, currentEmployee, 'PERM-EQUIPMENT-OPERATE')) continue;
    const proposedEmployee = proposedEmployees.find((employee) => employee.code === currentEmployee.code);
    const keepsResponsibility =
      proposedEmployee
      && proposedEmployee.status !== '停用'
      && employeeHasActivePermission(proposedData, proposedEmployee, 'PERM-EQUIPMENT-OPERATE');
    if (keepsResponsibility) continue;
    throw requestError(
      400,
      `员工 ${currentEmployee.name || currentEmployee.code} 仍负责${equipmentInspectionResponsibilitySummary(usage)}，不能停用账号或移除设备巡检操作权限；请先调整巡检计划负责人，并完成或承接已开始的巡检任务。`,
    );
  }
}

function appendEquipmentInspectionFlow(data, code, action, remark, actor = '系统') {
  const equipment = ensureEquipmentManagement(data);
  equipment.flowRecords[code] = [
    ...(equipment.flowRecords[code] || []),
    { time: shanghaiDateTime(), actor, action, remark },
  ];
}

function reassignPendingEquipmentInspectionTasks(data, previousPlan, updatedPlan, actor) {
  const previousOwnerCode = String(previousPlan?.ownerEmployeeCode || '').trim();
  const updatedOwnerCode = String(updatedPlan?.ownerEmployeeCode || '').trim();
  const previousOwnerName = String(previousPlan?.owner || '').trim();
  const updatedOwnerName = String(updatedPlan?.owner || '').trim();
  if (previousOwnerCode === updatedOwnerCode && previousOwnerName === updatedOwnerName) return 0;

  const equipment = ensureEquipmentManagement(data);
  const pendingTasks = equipment.tasks.filter((task) => task.planCode === updatedPlan.code && task.status === '待巡检');
  pendingTasks.forEach((task) => {
    const formerAssignee = task.assignee || previousOwnerName || '原负责人';
    task.assignee = updatedOwnerName;
    task.assigneeEmployeeCode = updatedOwnerCode;
    task.revision = Number(task.revision || 0) + 1;
    task.updatedAt = shanghaiDateTime();
    task.updatedBy = actor;
    appendEquipmentInspectionFlow(
      data,
      task.code,
      '改派巡检任务',
      `${formerAssignee} → ${updatedOwnerName}；来源计划 ${updatedPlan.code} 负责人调整。`,
      actor,
    );
  });
  return pendingTasks.length;
}

function equipmentInspectionResponse(data, record, generatedTask = null, extra = {}) {
  const equipment = ensureEquipmentManagement(data);
  return {
    record,
    flowRecords: equipment.flowRecords[record.code] || [],
    generatedTask,
    ...extra,
  };
}

function normalizeEquipmentInspectionItems(items, { task = false, allowIncomplete = false } = {}) {
  if (!Array.isArray(items) || items.length === 0) {
    if (allowIncomplete) return [];
    throw requestError(400, '至少需要一条巡检项目。');
  }
  const normalized = items.map((item, index) => {
    const name = String(item.name || '').trim();
    const method = String(item.method || '').trim();
    const requirement = String(item.requirement || '').trim();
    if (!allowIncomplete && (!name || !method || !requirement)) {
      throw requestError(400, `第 ${index + 1} 条巡检项目的名称、方法和判定要求不能为空。`);
    }
    if (allowIncomplete && !name && !method && !requirement) return null;
    return {
      lineId: String(item.lineId || `I${index + 1}`).trim(),
      name,
      method,
      requirement,
      ...(task
        ? {
            result: ['正常', '异常'].includes(item.result) ? item.result : '待检查',
            actual: String(item.actual || '').trim(),
            note: String(item.note || '').trim(),
          }
        : {}),
    };
  }).filter(Boolean);
  const duplicateLineId = normalized.find((item, index) => (
    normalized.findIndex((candidate) => candidate.lineId === item.lineId) !== index
  ));
  if (duplicateLineId) throw requestError(400, `巡检项目行号 ${duplicateLineId.lineId} 重复，请删除重复项后重试。`);
  const duplicateName = normalized.find((item, index) => (
    item.name
    && normalized.findIndex((candidate) => (
      candidate.name && candidate.name.toLowerCase() === item.name.toLowerCase()
    )) !== index
  ));
  if (duplicateName) throw requestError(400, `巡检项目“${duplicateName.name}”重复，请合并后保存。`);
  return normalized;
}

function normalizeEquipmentInspectionTaskResults(inputItems, frozenItems) {
  const submitted = normalizeEquipmentInspectionItems(inputItems, { task: true });
  if (submitted.length !== frozenItems.length) {
    throw requestError(409, '巡检项目数量与任务生成时冻结的标准不一致，请刷新后重试。');
  }
  return frozenItems.map((frozen, index) => {
    const input = submitted.find((item) => item.lineId === frozen.lineId);
    if (!input) {
      throw requestError(409, `第 ${index + 1} 项“${frozen.name}”与冻结标准不一致，请刷新后重试。`);
    }
    const changedField = [
      ['name', '检查项目'],
      ['method', '检查方法'],
      ['requirement', '判定要求'],
    ].find(([key]) => String(input[key] || '').trim() !== String(frozen[key] || '').trim());
    if (changedField) {
      throw requestError(409, `巡检项目“${frozen.name}”的${changedField[1]}已偏离冻结标准，请刷新后重试。`);
    }
    return {
      ...frozen,
      result: input.result,
      actual: input.actual,
      note: input.note,
    };
  });
}

function normalizeEquipmentInspectionStandard(input, existing, data, actor) {
  const equipment = ensureEquipmentManagement(data);
  const name = String(input.name || '').trim();
  const equipmentModel = String(input.equipmentModel || '').trim();
  const acceptance = String(input.acceptance || '').trim();
  if (!name) throw requestError(400, '巡检标准名称不能为空。');
  if (!equipmentModel) throw requestError(400, '适用设备型号不能为空。');
  if (!ensureMasterRows(data, 'equipment').some((row) => String(row.model || '').trim() === equipmentModel)) {
    throw requestError(400, '适用设备型号必须来自设备主档。');
  }
  const duplicate = equipment.standards.find((row) => row.code !== existing?.code && String(row.name || '').trim() === name);
  if (duplicate) throw requestError(400, '已存在同名巡检标准。');
  const status = ['草稿', '启用', '停用'].includes(input.status) ? input.status : existing?.status || '草稿';
  if (status === '启用' && !acceptance) throw requestError(400, '启用巡检标准前必须填写整体合格条件。');
  if (existing) {
    const activePlan = equipment.plans.find((plan) => plan.standardCode === existing.code && plan.status === '启用');
    if (activePlan && status !== '启用') {
      throw requestError(400, `巡检标准正被启用计划 ${activePlan.code} 引用，请先停用或调整该计划。`);
    }
    if (activePlan && equipmentModel !== String(existing.equipmentModel || '').trim()) {
      throw requestError(400, `巡检标准正被启用计划 ${activePlan.code} 引用，不能修改适用设备型号；请先停用或调整该计划。`);
    }
  }
  const normalized = {
    ...(existing || {}),
    code: existing?.code || nextDocumentCode(data, 'equipment-inspection-standards', equipment.standards, 'EIS'),
    name,
    equipmentModel,
    acceptance,
    status,
    revision: Number(existing?.revision || 0) + 1,
    items: normalizeEquipmentInspectionItems(input.items, { allowIncomplete: status !== '启用' }),
    note: String(input.note || '').trim(),
    updatedAt: shanghaiDateTime(),
    updatedBy: actor,
  };
  delete normalized.inspectionMethod;
  delete normalized.owner;
  delete normalized.equipmentScope;
  return normalized;
}

function equipmentInspectionDueAt(dateText, executionWindow) {
  const end = String(executionWindow || '').match(/(\d{2}:\d{2})\s*$/)?.[1] || '23:59';
  return `${dateText} ${end}`;
}

function normalizeEquipmentInspectionWindow(value) {
  const match = String(value || '').trim().match(/^([01]\d|2[0-3]):([0-5]\d)-([01]\d|2[0-3]):([0-5]\d)$/);
  if (!match) throw requestError(400, '执行时间窗必须按 HH:mm-HH:mm 填写。');
  const startMinutes = Number(match[1]) * 60 + Number(match[2]);
  const endMinutes = Number(match[3]) * 60 + Number(match[4]);
  if (endMinutes <= startMinutes) throw requestError(400, '执行时间窗的结束时间必须晚于开始时间。');
  return `${match[1]}:${match[2]}-${match[3]}:${match[4]}`;
}

function normalizeEquipmentInspectionPlan(input, existing, data, actor) {
  const equipment = ensureEquipmentManagement(data);
  const name = String(input.name || '').trim();
  if (!name) throw requestError(400, '巡检计划名称不能为空。');
  const equipmentRecord = ensureMasterRows(data, 'equipment').find((row) => row.code === input.equipmentCode && row.status !== '停用');
  if (!equipmentRecord) throw requestError(400, '请选择有效且启用的设备。');
  const standard = equipment.standards.find((row) => row.code === input.standardCode && row.status === '启用');
  if (!standard) throw requestError(400, '请选择已启用的巡检标准。');
  if (standard.equipmentModel !== String(equipmentRecord.model || '').trim()) {
    throw requestError(400, `巡检标准 ${standard.code} 适用于 ${standard.equipmentModel || '未维护'} 型号，不能用于设备 ${equipmentRecord.code}（${equipmentRecord.model || '型号未维护'}）。`);
  }
  const frequency = ['每日', '每周', '每月', '每季度'].includes(input.frequency) ? input.frequency : '每日';
  const firstDueDate = String(existing?.firstDueDate || input.firstDueDate || shanghaiDate()).trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(firstDueDate)) throw requestError(400, '首次计划日期格式不正确。');
  if (!existing && firstDueDate < shanghaiDate()) throw requestError(400, '首次计划日期不能早于今天。');
  const executionWindow = normalizeEquipmentInspectionWindow(input.executionWindow || existing?.executionWindow || '08:00-17:00');
  const employees = ensureMasterRows(data, 'employees');
  const requestedOwnerEmployeeCode = String(input.ownerEmployeeCode || existing?.ownerEmployeeCode || '').trim();
  const requestedOwnerName = String(input.owner || existing?.owner || '').trim();
  const ownerEmployee = employees.find((row) => (
    row.status !== '停用'
    && ((requestedOwnerEmployeeCode && row.code === requestedOwnerEmployeeCode)
      || (!requestedOwnerEmployeeCode && requestedOwnerName && row.name === requestedOwnerName))
    && employeeHasActivePermission(data, row, 'PERM-EQUIPMENT-OPERATE')
  ));
  if (!ownerEmployee) throw requestError(400, '请选择拥有设备巡检操作权限的启用员工。');
  const status = input.status === '停用' ? '停用' : '启用';
  const duplicate = equipment.plans.find((row) => (
    row.code !== existing?.code
    && row.status === '启用'
    && status === '启用'
    && row.equipmentCode === equipmentRecord.code
    && row.standardCode === standard.code
    && row.frequency === frequency
  ));
  if (duplicate) throw requestError(400, `设备已有相同标准和频次的启用计划 ${duplicate.code}。`);
  return {
    ...(existing || {}),
    code: existing?.code || nextDocumentCode(data, 'equipment-inspection-plans', equipment.plans, 'EIP'),
    name,
    equipmentCode: equipmentRecord.code,
    equipmentName: equipmentRecord.name,
    equipmentModel: equipmentRecord.model || '',
    location: equipmentRecord.primary || '',
    standardCode: standard.code,
    standardName: standard.name,
    standardRevision: Number(standard.revision || 1),
    frequency,
    executionWindow,
    firstDueDate,
    nextDueDate: existing?.nextDueDate || firstDueDate,
    owner: ownerEmployee.name,
    ownerEmployeeCode: ownerEmployee.code,
    status,
    revision: Number(existing?.revision || 0) + 1,
    note: String(input.note || '').trim(),
    updatedAt: shanghaiDateTime(),
    updatedBy: actor,
  };
}

function createEquipmentInspectionTaskFromPlan(data, plan, scheduledDate, actor = '系统') {
  const equipment = ensureEquipmentManagement(data);
  if (plan.status !== '启用') return null;
  const repeated = equipment.tasks.find((row) => row.planCode === plan.code && row.scheduledDate === scheduledDate);
  if (repeated) return repeated;
  const standard = equipment.standards.find((row) => row.code === plan.standardCode && row.status === '启用');
  if (!standard) return null;
  const task = {
    code: nextDocumentCode(data, 'equipment-inspection-tasks', equipment.tasks, 'EIT'),
    planCode: plan.code,
    planName: plan.name,
    equipmentCode: plan.equipmentCode,
    equipmentName: plan.equipmentName,
    equipmentModel: plan.equipmentModel,
    location: plan.location,
    standardCode: standard.code,
    standardName: standard.name,
    standardRevision: Number(standard.revision || 1),
    scheduledDate,
    dueAt: equipmentInspectionDueAt(scheduledDate, plan.executionWindow),
    assignee: plan.owner,
    assigneeEmployeeCode: plan.ownerEmployeeCode,
    status: '待巡检',
    result: '待执行',
    revision: 1,
    items: normalizeEquipmentInspectionItems(standard.items, { task: true }),
    startedAt: '',
    completedAt: '',
    cancelledAt: '',
    cancelReason: '',
    exceptionSummary: '',
    resolution: '',
    updatedAt: shanghaiDateTime(),
    updatedBy: actor,
  };
  equipment.tasks.unshift(task);
  appendEquipmentInspectionFlow(data, task.code, '生成巡检任务', `由计划 ${plan.code} 自动生成，计划日期 ${scheduledDate}。`, actor);
  return task;
}

function generateNextEquipmentInspectionTask(data, task, actor) {
  const equipment = ensureEquipmentManagement(data);
  const plan = equipment.plans.find((row) => row.code === task.planCode);
  if (!plan) return null;
  const scheduledDate = nextEquipmentInspectionDate(task.scheduledDate, plan.frequency);
  plan.nextDueDate = scheduledDate;
  plan.updatedAt = shanghaiDateTime();
  plan.updatedBy = actor;
  plan.revision = Number(plan.revision || 0) + 1;
  if (plan.status !== '启用') return null;
  const generatedTask = createEquipmentInspectionTaskFromPlan(data, plan, scheduledDate, actor);
  plan.nextDueDate = generatedTask?.scheduledDate || scheduledDate;
  return generatedTask;
}

function equipmentInspectionEditableSignature(page, record) {
  if (page === 'inspection-standards') {
    return JSON.stringify({
      name: String(record.name || '').trim(),
      equipmentModel: String(record.equipmentModel || '').trim(),
      acceptance: String(record.acceptance || '').trim(),
      status: record.status,
      items: record.items || [],
      note: String(record.note || '').trim(),
    });
  }
  return JSON.stringify({
    name: String(record.name || '').trim(),
    equipmentCode: record.equipmentCode,
    standardCode: record.standardCode,
    frequency: record.frequency,
    executionWindow: record.executionWindow,
    firstDueDate: record.firstDueDate,
    ownerEmployeeCode: record.ownerEmployeeCode,
    status: record.status,
    note: String(record.note || '').trim(),
  });
}

function assertEquipmentInspectionRevision(body, record) {
  const revision = Number(body.revision ?? body.record?.revision);
  if (Number.isFinite(revision) && revision !== Number(record.revision || 0)) {
    throw requestError(409, '记录已被其他操作更新，请刷新后重试。');
  }
}

async function handleRequest(req, res) {
  if (req.method === 'OPTIONS') return sendJson(res, 204, {});

  const url = new URL(req.url || '/', `http://${req.headers.host}`);
  const parts = url.pathname.split('/').filter(Boolean);

  try {
    if (parts[0] !== 'api') return sendError(res, 404, '接口不存在');
    if (parts[1] === 'health') return sendJson(res, 200, { ok: true, dataFile, updatedAt: new Date().toISOString() });

    const data = enrichBusinessData(await readData());
    if (parts[1] === 'finance') {
      return sendError(res, 410, '独立财务模块已移除；开票、收票、回款和付款进度请在销售或采购订单中登记。');
    }
    await requireReadPermissionAudited(req, data, parts);
    await requireWritePermissionAudited(req, data, parts);
    await requireOperationPermissionAudited(req, data, parts);
    await requireEnabledMenuPathAudited(req, data, parts);

    if (parts[1] === 'session') {
      if (req.method === 'GET' && parts[2] === 'current') {
        return sendJson(res, 200, sessionContext(req, data));
      }

      if (req.method === 'POST' && parts[2] === 'login') {
        const body = await readBody(req);
        const identifier = String(body.username || body.account || body.code || '').trim();
        const password = String(body.password || '');
        const system = ensureSystem(data);
        const account = system.accounts.find(
          (row) =>
            row.status !== '停用' &&
            accountIdentityMatches(row, identifier),
        );

        if (!identifier || !password) return sendError(res, 400, '请输入账号和密码。');
        if (!account) return sendError(res, 401, '账号或密码不正确。');
        if (!hasAccountPassword(account)) return sendError(res, 400, '该账号尚未设置登录密码，请先在账号管理中设置。');
        if (!verifyPassword(password, account)) return sendError(res, 401, '账号或密码不正确。');

        const token = createAccountSession(data, account);
        appendSystemLog(system, '登录成功', account.code, `${accountAuditName(account)} 已登录系统。`, {
          owner: accountAuditName(account),
          sourceAccount: account.code,
          sourceIp: requestSourceIp(req),
        });
        await writeData(data);
        return sendJson(res, 200, { token, ...sessionContext(req, data, account) });
      }

      if (req.method === 'POST' && parts[2] === 'logout') {
        const account = activeAccountForRequest(req, data);
        clearAccountSession(req, data);
        if (account) {
          const system = ensureSystem(data);
          appendSystemLog(system, '退出登录', account.code, `${accountAuditName(account)} 已退出系统。`, {
            owner: accountAuditName(account),
            sourceAccount: account.code,
            sourceIp: requestSourceIp(req),
          });
        }
        await writeData(data);
        return sendJson(res, 200, { ok: true });
      }

      if (req.method === 'POST' && parts[2] === 'password') {
        const account = activeAccountForRequest(req, data);
        const system = ensureSystem(data);
        if (!account) return sendError(res, passwordLoginRequired(data) ? 401 : 403, '请先登录后再修改密码。');

        const body = await readBody(req);
        const accountIndex = system.accounts.findIndex((row) => row.code === account.code);
        if (accountIndex < 0) return sendError(res, 404, '账号不存在或已停用。');
        const accountRecord = system.accounts[accountIndex];
        const currentPassword = String(body.currentPassword || '');
        if (hasAccountPassword(accountRecord) && !verifyPassword(currentPassword, accountRecord)) {
          return sendError(res, 400, '当前密码不正确。');
        }

        const passwordUpdate = accountPasswordUpdate(body);
        if (!passwordUpdate) return sendError(res, 400, '请输入新密码。');
        const proposedAccounts = system.accounts.map((row) =>
          row.code === accountRecord.code ? { ...row, ...passwordUpdate } : row,
        );
        assertPasswordLoginHasSystemManager(data, proposedAccounts);
        const currentAccountIndex = system.accounts.findIndex((row) => row.code === accountRecord.code);
        if (currentAccountIndex < 0) return sendError(res, 404, '账号不存在或已停用。');
        const updatedAccount = { ...system.accounts[currentAccountIndex], ...passwordUpdate };
        system.accounts[currentAccountIndex] = updatedAccount;
        const sessionsCleared = clearSessionsForAccount(data, updatedAccount.code);
        appendSystemLog(system, '修改登录密码', updatedAccount.code, `${accountAuditName(updatedAccount)} 已修改自己的登录密码。`, {
          owner: accountAuditName(updatedAccount),
          sourceAccount: updatedAccount.code,
          sourceIp: requestSourceIp(req),
        });
        await writeData(data);
        return sendJson(res, 200, { ok: true, sessionsCleared });
      }

      if (req.method === 'POST' && parts[2] === 'impersonate') {
        const currentAccount = activeAccountForRequest(req, data);
        if (!currentAccount) return sendError(res, passwordLoginRequired(data) ? 401 : 403, '请先登录。');
        if (!accountPermissionCodesForAccount(data, currentAccount).has(systemPermissionCode)) {
          return sendError(res, 403, '当前账号没有系统配置维护权限，不能切换账号。');
        }

        const body = await readBody(req);
        const accountCode = String(body.accountCode || '').trim();
        const system = ensureSystem(data);
        const targetAccount = system.accounts.find((row) => row.status !== '停用' && row.code === accountCode);
        if (!targetAccount) return sendError(res, 404, '目标账号不存在或已停用。');
        if (passwordLoginRequired(data) && !hasAccountPassword(targetAccount)) {
          return sendError(res, 400, '目标账号尚未设置登录密码，不能在密码登录模式下切换。');
        }

        const token = createAccountSession(data, targetAccount);
        appendSystemLog(system, '切换账号', targetAccount.code, `${accountAuditName(currentAccount)} 切换到 ${accountAuditName(targetAccount)}。`, {
          owner: accountAuditName(currentAccount),
          sourceAccount: currentAccount.code,
          sourceIp: requestSourceIp(req),
        });
        await writeData(data);
        return sendJson(res, 200, { token, ...sessionContext(req, data, targetAccount) });
      }

      return sendError(res, 404, '会话接口不存在');
    }

    if (parts[1] === 'notifications') {
      const account = activeAccountForRequest(req, data);
      if (!account) {
        return sendError(
          res,
          passwordLoginRequired(data) ? 401 : 403,
          passwordLoginRequired(data) ? '请先登录后再读取通知。' : '当前账号不存在或已停用。',
        );
      }

      if (req.method === 'GET' && parts.length === 2) {
        const limit = Math.min(Math.max(Number(url.searchParams.get('limit') || 20), 1), 100);
        return sendJson(res, 200, notificationResponse(req, data, limit));
      }

      if (req.method === 'POST' && parts[2] === 'read-all') {
        const system = ensureSystem(data);
        const visibleCodes = new Set(system.notificationInbox
          .filter((row) => notificationVisibleToAccount(data, row, account))
          .map((row) => row.code));
        data.system.notificationInbox
          .filter((row) => visibleCodes.has(row.code))
          .forEach((row) => {
            const readBy = new Set(listFromText(row.readBy));
            readBy.add(account.code);
            row.readBy = Array.from(readBy).join(',');
          });
        await writeData(data);
        return sendJson(res, 200, notificationResponse(req, data));
      }

      if (req.method === 'POST' && parts[3] === 'read') {
        markNotificationRead(data, decodeURIComponent(parts[2] || ''), account);
        await writeData(data);
        return sendJson(res, 200, notificationResponse(req, data));
      }

      return sendError(res, 404, '通知接口不存在');
    }

    if (req.method === 'GET' && parts[1] === 'reference') {
      const account = activeAccountForRequest(req, data);
      if (!account) return sendError(res, passwordLoginRequired(data) ? 401 : 403, '请先登录后再读取候选列表。');

      const type = masterType(parts[2]) || parts[2];
      await requireReferencePermissionAudited(req, data, type, account);
      const keyword = (url.searchParams.get('q') || '').trim();
      const onlyActive = url.searchParams.get('activeOnly') !== 'false';
      const limit = Math.min(Number(url.searchParams.get('limit') || 20), 50);

      if (type === 'customers') {
        const rows = ensureMasterRows(data, 'customers')
          .filter((row) => activeOnly(row, onlyActive))
          .filter((row) => includesKeyword(row, keyword, ['code', 'name', 'contact', 'phone', 'address', 'defaultShipContact', 'defaultShipPhone', 'defaultShipAddress']))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      if (type === 'suppliers') {
        const rows = ensureMasterRows(data, 'suppliers')
          .filter((row) => activeOnly(row, onlyActive))
          .filter((row) => includesKeyword(row, keyword, ['code', 'name', 'contact', 'phone', 'address']))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      if (type === 'materials') {
        const kind = url.searchParams.get('kind');
        const rows = data.masterData.materials
          .filter((row) => activeOnly(row, onlyActive))
          .filter((row) => {
            if (!kind) return true;
            if (kind === '成品') return isSaleableMaterial(row);
            if (kind === '生产产出') return isProductionOutputMaterial(row);
            if (kind === '非成品') return !isSaleableMaterial(row);
            if (kind === '销售') return isSaleableMaterial(row);
            if (kind === '采购') return isPurchasableMaterial(row);
            if (kind === '生产') return isProducibleMaterial(row);
            return row.type === kind || row.category === kind;
          })
          .filter((row) => includesKeyword(row, keyword, ['code', 'name', 'model', 'spec', 'uom', 'englishName', 'englishModel', 'englishSpec', 'category']))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      if (type === 'warehouses') {
        const company = String(url.searchParams.get('company') || '').trim();
        const kind = String(url.searchParams.get('kind') || '').trim();
        const rows = ensureMasterRows(data, 'warehouses')
          .filter((row) => activeOnly(row, onlyActive))
          .filter((row) => !company || row.company === company)
          .filter((row) => kind !== '采购收货' || row.allowPurchaseStaging === true)
          .filter((row) => kind !== '销售退货暂存' || row.allowSalesReturnStaging === true)
          .filter((row) => kind !== '采购正式入库' || row.allowPurchaseReceipt === true)
          .filter((row) => kind !== '销售出库' || row.allowSalesIssue === true)
          .filter((row) => kind !== '生产领料' || row.allowProductionIssue === true)
          .filter((row) => kind !== '生产入库' || row.allowProductionReceipt === true)
          .filter((row) => kind !== '不合格隔离' || row.allowQuarantine === true)
          .filter((row) => (
            includesKeyword(row, keyword, ['code', 'name', 'englishName', 'type', 'company', 'address', 'englishAddress', 'note'])
            || (row.warehouseFunctions || []).some((item) => normalizedMasterText(item).includes(normalizedMasterText(keyword)))
          ))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows.map((row) => ({
          ...row,
          locationOptions: warehouseLocationOptions(data, row),
        }))));
      }

      if (['uom', 'currencies', 'departments', 'employees', 'company', 'equipment', 'productionLines'].includes(type)) {
        const company = String(url.searchParams.get('company') || '').trim();
        const kind = String(url.searchParams.get('kind') || '').trim();
        const employeeRole = ['sales-document-owner', 'sales-after-sales-owner'].includes(kind)
          ? 'ROLE-SALES'
          : kind === 'purchase-after-sales-owner'
            ? 'ROLE-PURCHASE'
            : kind === 'production-document-owner'
              ? 'ROLE-PRODUCTION'
            : kind === 'warehouse-stocktake-owner'
              ? 'ROLE-WAREHOUSE'
              : '';
        const employeePermission = kind === 'equipment-inspection-owner'
          ? 'PERM-EQUIPMENT-OPERATE'
          : '';
        const rows = ensureMasterRows(data, type)
          .filter((row) => activeOnly(row, onlyActive))
          .filter((row) => type !== 'departments' || !company || row.company === company || row.owner === company)
          .filter((row) => type !== 'employees' || !employeeRole || employeeHasActiveRole(data, row, employeeRole))
          .filter((row) => type !== 'employees' || !employeePermission || employeeHasActivePermission(data, row, employeePermission))
          .filter((row) =>
            includesKeyword(row, keyword, [
              'code',
              'name',
              'type',
              'owner',
              'primary',
              'secondary',
              'contact',
              'phone',
              'email',
              'website',
              'address',
              'registeredAddress',
              'invoicePhone',
              'englishAbbreviation',
              'englishName',
              'symbol',
              'parentDepartment',
              'position',
              'brand',
              'model',
              'serialNumber',
              'workshop',
              'processScope',
              'capacityUnit',
              'status',
              'note',
            ]),
          )
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      if (type === 'purchase-orders') {
        const purchase = ensurePurchase(data);
        const kind = String(url.searchParams.get('kind') || '').trim();
        const warehouse = ensureWarehouse(data);
        const rows = purchase.orders
          .filter((row) => activeOnly(row, onlyActive))
          .filter((row) => kind !== 'after-sales' || (
            row.purchaseType === '物料采购'
            && !['草稿', '已作废', '已取消'].includes(String(row.status || ''))
            && hasRemainingAfterSalesQuantity(purchase.afterSales, row.code, row.products)
          ))
          .filter((row) => kind !== 'warehouse-receipt' || (
            row.purchaseType === '物料采购'
            && row.status === '已确认'
          ))
          .map((row) => {
            if (kind !== 'warehouse-receipt') return row;
            const activeReceipts = warehouse.purchaseReceipts.filter((receipt) => (
              receipt.sourceDoc === row.code
              && !receipt.reversalCode
              && !['已作废', '已取消'].includes(String(receipt.status || ''))
            ));
            const products = (row.products || []).flatMap((product, productIndex) => {
              const sourceLineId = product.lineId || `L${productIndex + 1}`;
              const allocatedQty = activeReceipts.reduce((sum, receipt) => sum + (receipt.products || []).reduce((lineSum, receiptLine, receiptLineIndex) => {
                const receiptSourceLineId = receiptLine.sourceLineId || receiptLine.lineId || `L${receiptLineIndex + 1}`;
                const representedQty = ['草稿', '待收货'].includes(String(receipt.status || ''))
                  ? parseQty(receiptLine.plannedQty || receiptLine.qty)
                  : parseQty(receiptLine.acceptedQty ?? receiptLine.qty) + parseQty(receiptLine.exceptionHeldQty);
                return receiptSourceLineId === sourceLineId ? lineSum + representedQty : lineSum;
              }, 0), 0);
              const remainingQty = Math.max(0, parseQty(product.qty) - allocatedQty);
              return remainingQty > 0.0001
                ? [{ ...product, qty: formatQty(remainingQty, product.uom || qtyUnit(product.qty) || '') }]
                : [];
            });
            return { ...row, products };
          })
          .filter((row) => kind !== 'warehouse-receipt' || row.products.length > 0)
          .filter((row) => includesKeyword(row, keyword, ['code', 'supplier', 'contact', 'owner', 'status', 'purchaseType', 'remark']))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      if (type === 'purchase-requisitions') {
        const purchase = ensurePurchase(data);
        const kind = String(url.searchParams.get('kind') || '').trim();
        const rows = purchase.requisitions
          .map((row) => withPurchaseRequisitionFacts(data, row))
          .filter((row) => row.status === '待采购受理')
          .filter((row) => row.conversionFacts.status !== '已转单')
          .filter((row) => !kind || row.purchaseType === kind)
          .filter((row) => includesKeyword(row, keyword, ['code', 'department', 'requester', 'reason', 'status', 'purchaseType']))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      if (type === 'purchase-receipts') {
        const warehouse = ensureWarehouse(data);
        const rows = warehouse.purchaseReceipts
          .filter((row) => row.status === '已入库' && !row.reversalCode)
          .filter((row) => includesKeyword(row, keyword, ['code', 'sourceDoc', 'supplier', 'contact', 'warehouse', 'location', 'status']))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      if (type === 'purchase-invoices') {
        const finance = ensureFinance(data);
        const rows = finance.purchaseInvoices
          .filter((row) => activeOnly(row, onlyActive))
          .filter((row) => includesKeyword(row, keyword, ['code', 'sourceDoc', 'party', 'contact', 'owner', 'status']))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      if (type === 'sales-orders') {
        const kind = String(url.searchParams.get('kind') || '').trim();
        const rows = data.sales.orders
          .filter((row) => row.testOnly !== true)
          .filter((row) => activeOnly(row, onlyActive))
          .filter((row) => kind !== 'after-sales' || !['草稿', '已作废', '已取消'].includes(String(row.documentStatus || row.status || '')))
          .map((row) => withSalesAfterSalesEligibility(data, row))
          .filter((row) => kind !== 'after-sales' || (
            row.afterSalesEligibleProducts.length > 0
            && hasRemainingAfterSalesQuantity(data.sales.afterSales, row.code, row.afterSalesEligibleProducts)
          ))
          .filter((row) => includesKeyword(row, keyword, ['code', 'customer', 'contact', 'owner', 'status']))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      if (type === 'outbound-requests') {
        const sales = ensureSales(data);
        const kind = String(url.searchParams.get('kind') || '').trim();
        const warehouse = ensureWarehouse(data);
        const rows = sales.outboundRequests
          .filter((row) => !['草稿', '已作废', '已出库'].includes(row.status))
          .map((row) => {
            if (kind !== 'warehouse-sales-issue') return row;
            const order = sales.orders.find((candidate) => candidate.code === row.sourceOrder);
            const sourceLines = salesTrackingLines(row, order);
            const activeIssues = warehouse.salesIssues.filter((issue) => (
              !issue.reversalCode
              && !['已作废', '已取消'].includes(String(issue.status || ''))
              && (issue.sourceDoc === row.code || (row.sourceOrder && issue.sourceOrder === row.sourceOrder))
            ));
            const products = sourceLines.flatMap((product, productIndex) => {
              const sourceLineId = businessLineId(product, productIndex);
              const allocatedQty = activeIssues.reduce((sum, issue) => sum + (issue.products || []).reduce((lineSum, issueLine, issueLineIndex) => {
                const matchedLine = salesIssueSourceLine(sourceLines, issueLine, issueLineIndex);
                const issueSourceLineId = issueLine.sourceLineId || (matchedLine
                  ? businessLineId(matchedLine, sourceLines.indexOf(matchedLine))
                  : '');
                return issueSourceLineId === sourceLineId ? lineSum + parseQty(issueLine.qty) : lineSum;
              }, 0), 0);
              const plannedQty = parseQty(product.requestQty || product.qty);
              const remainingQty = Math.max(0, plannedQty - allocatedQty);
              const unit = product.uom || qtyUnit(product.requestQty || product.qty) || '';
              return remainingQty > 0.0001
                ? [{ ...product, sourceLineId, requestQty: formatQty(remainingQty, unit) }]
                : [];
            });
            return { ...row, products };
          })
          .filter((row) => kind !== 'warehouse-sales-issue' || row.products.length > 0)
          .filter((row) => includesKeyword(row, keyword, ['code', 'sourceOrder', 'customer', 'contact', 'applicant', 'status', 'deliveryDate']))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      if (type === 'sales-invoices') {
        const finance = ensureFinance(data);
        const rows = finance.salesInvoices
          .filter((row) => activeOnly(row, onlyActive))
          .filter((row) => includesKeyword(row, keyword, ['code', 'sourceDoc', 'party', 'contact', 'owner', 'status']))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      if (type === 'sales-quotes') {
        const sales = ensureSales(data);
        const rows = sales.quotes
          .filter((row) => row.status === '已确认')
          .filter((row) => !salesQuoteIsExpired(row))
          .filter((row) => includesKeyword(row, keyword, ['code', 'customer', 'contact', 'owner', 'status']))
          .slice(0, limit);
        return sendJson(res, 200, referenceResponse(type, rows));
      }

      return sendError(res, 404, '未知候选列表');
    }

    if (parts[1] === 'master-data' && parts[2] === 'relations') {
      const relations = ensureMasterRelations(data);
      const relationType = parts[3];
      const materialCode = String(url.searchParams.get('materialCode') || '').trim();
      const supplierCode = String(url.searchParams.get('supplierCode') || '').trim();
      const warehouseCode = String(url.searchParams.get('warehouseCode') || '').trim();

      if (relationType === 'material-suppliers') {
        const supplierNameByCode = new Map(
          ensureMasterRows(data, 'suppliers').map((row) => [row.code, row.name || '']),
        );
        const materialNameByCode = new Map(
          ensureMasterRows(data, 'materials').map((row) => [row.code, row.name || '']),
        );
        const materialUomByCode = new Map(
          ensureMasterRows(data, 'materials').map((row) => [row.code, row.uom || '']),
        );
        if (req.method === 'GET') {
          const items = relations.materialSuppliers
            .filter((row) => !materialCode || row.materialCode === materialCode)
            .filter((row) => !supplierCode || row.supplierCode === supplierCode)
            .map((row) => ({
              ...row,
              supplierName: supplierNameByCode.get(row.supplierCode) || row.supplierName,
              materialName: materialNameByCode.get(row.materialCode) || row.materialName,
              baseUom: materialUomByCode.get(row.materialCode) || '',
            }))
            .sort((a, b) => `${a.materialName || ''}${a.supplierName || ''}`.localeCompare(`${b.materialName || ''}${b.supplierName || ''}`, 'zh-CN'));
          return sendJson(res, 200, { items });
        }

        if (req.method === 'PUT' && parts[4]) {
          const targetSupplierCode = decodeURIComponent(parts[4]);
          const supplier = ensureMasterRows(data, 'suppliers').find((row) => row.code === targetSupplierCode);
          if (!supplier) return sendError(res, 404, '供应商不存在');

          const body = await readBody(req);
          const inputItems = Array.isArray(body.items) ? body.items : [];
          const materials = ensureMasterRows(data, 'materials');
          const materialByCode = new Map(materials.map((row) => [row.code, row]));
          const existingByMaterial = new Map(
            relations.materialSuppliers
              .filter((row) => row.supplierCode === targetSupplierCode)
              .map((row) => [row.materialCode, row]),
          );
          const seenMaterials = new Set();
          let nextSequence = relations.materialSuppliers.reduce((max, row) => {
            const match = /^MSR-(\d+)$/.exec(String(row.code || ''));
            return Math.max(max, Number(match?.[1]) || 0);
          }, 0);

          const normalizedItems = [];
          for (const input of inputItems) {
            const relationMaterialCode = String(input.materialCode || '').trim();
            if (!relationMaterialCode) return sendError(res, 400, '可供物料不能为空');
            if (seenMaterials.has(relationMaterialCode)) return sendError(res, 400, '同一供应商不能重复维护同一物料');
            seenMaterials.add(relationMaterialCode);

            const existing = existingByMaterial.get(relationMaterialCode);
            const material = materialByCode.get(relationMaterialCode);
            if (!material) return sendError(res, 400, `物料 ${relationMaterialCode} 不存在`);
            const relationStatus = input.status === '停用' ? '停用' : input.status === '启用' ? '启用' : '';
            if (!relationStatus) return sendError(res, 400, `${material.name}的供货关系状态无效`);
            if (supplier.status === '停用' && relationStatus !== '停用') {
              return sendError(res, 400, `供应商 ${supplier.name} 已停用，只能保留为停用关系`);
            }
            if (!supplierSupportsMaterialRelations(supplier.type) && relationStatus !== '停用') {
              return sendError(res, 400, `供应商类型“${supplier.type}”不适用可供物料，只能保留为停用关系`);
            }
            if (material.status === '停用' && (!existing || relationStatus !== '停用')) {
              return sendError(res, 400, `物料 ${relationMaterialCode} 已停用，只能保留为停用关系`);
            }
            if (!isPurchasableMaterial(material) && (!existing || relationStatus !== '停用')) {
              return sendError(res, 400, `物料 ${relationMaterialCode} 未启用可采购属性，只能保留为停用关系`);
            }

            const minOrderQty = Number(input.minOrderQty);
            const leadTimeDays = Number(input.leadTimeDays);
            if (!Number.isFinite(minOrderQty) || minOrderQty <= 0) return sendError(res, 400, `${material.name}的起订量必须大于 0`);
            if (!Number.isInteger(leadTimeDays) || leadTimeDays < 0) return sendError(res, 400, `${material.name}的供货周期必须是大于或等于 0 的整数天`);

            normalizedItems.push({
              ...(existing || {}),
              code: existing?.code || `MSR-${String(++nextSequence).padStart(5, '0')}`,
              supplierCode: targetSupplierCode,
              supplierName: supplier.name,
              materialCode: relationMaterialCode,
              materialName: material.name,
              supplierMaterialCode: String(input.supplierMaterialCode || '').trim(),
              minOrderQty,
              leadTimeDays,
              isDefault: Boolean(input.isDefault),
              status: relationStatus,
              note: String(input.note || existing?.note || '').trim(),
            });
          }
          const omittedExisting = [...existingByMaterial.keys()].filter((existingMaterialCode) => !seenMaterials.has(existingMaterialCode));
          if (omittedExisting.length) {
            return sendError(res, 400, `已有供货关系不能直接删除，请将 ${omittedExisting.join('、')} 改为停用`);
          }

          normalizedItems
            .filter((row) => row.isDefault && row.status === '启用')
            .forEach((row) => {
              relations.materialSuppliers
                .filter((other) => other.materialCode === row.materialCode && other.supplierCode !== targetSupplierCode)
                .forEach((other) => { other.isDefault = false; });
            });

          relations.materialSuppliers = [
            ...relations.materialSuppliers.filter((row) => row.supplierCode !== targetSupplierCode),
            ...normalizedItems,
          ];
          await writeData(data);
          return sendJson(res, 200, {
            items: normalizedItems.map((row) => ({
              ...row,
              baseUom: materialUomByCode.get(row.materialCode) || '',
            })),
          });
        }

        return sendError(res, 405, '不支持的物料—供应商关系操作');
      }

      if (relationType === 'warehouse-materials') {
        const warehouseNameByCode = new Map(
          ensureMasterRows(data, 'warehouses').map((row) => [row.code, row.name || '']),
        );
        const materialByCodeForProjection = new Map(
          ensureMasterRows(data, 'materials').map((row) => [row.code, row]),
        );
        if (req.method === 'GET') {
          const items = relations.warehouseMaterials
            .filter((row) => !materialCode || row.materialCode === materialCode)
            .filter((row) => !warehouseCode || row.warehouseCode === warehouseCode)
            .map((row) => ({
              ...row,
              warehouseName: warehouseNameByCode.get(row.warehouseCode) || row.warehouseName,
              materialName: materialByCodeForProjection.get(row.materialCode)?.name || row.materialName,
              uom: materialByCodeForProjection.get(row.materialCode)?.uom || row.uom,
            }))
            .sort((a, b) => `${a.materialName || ''}${a.warehouseName || ''}`.localeCompare(`${b.materialName || ''}${b.warehouseName || ''}`, 'zh-CN'));
          return sendJson(res, 200, { items });
        }

        if (req.method === 'PUT' && parts[4]) {
          const targetWarehouseCode = decodeURIComponent(parts[4]);
          const warehouse = ensureMasterRows(data, 'warehouses').find((row) => row.code === targetWarehouseCode);
          if (!warehouse) return sendError(res, 404, '仓库不存在');

          const body = await readBody(req);
          const inputItems = Array.isArray(body.items) ? body.items : [];
          const materials = ensureMasterRows(data, 'materials');
          const materialByCode = new Map(materials.map((row) => [row.code, row]));
          const existingByMaterial = new Map(
            relations.warehouseMaterials
              .filter((row) => row.warehouseCode === targetWarehouseCode)
              .map((row) => [row.materialCode, row]),
          );
          const seenMaterials = new Set();
          let nextSequence = relations.warehouseMaterials.reduce((max, row) => {
            const match = /^WMR-(\d+)$/.exec(String(row.code || ''));
            return Math.max(max, Number(match?.[1]) || 0);
          }, 0);

          const normalizedItems = [];
          for (const input of inputItems) {
            const relationMaterialCode = String(input.materialCode || '').trim();
            if (!relationMaterialCode) return sendError(res, 400, '补货物料不能为空');
            if (seenMaterials.has(relationMaterialCode)) return sendError(res, 400, '同一仓库不能重复维护同一物料');
            seenMaterials.add(relationMaterialCode);

            const existing = existingByMaterial.get(relationMaterialCode);
            const material = materialByCode.get(relationMaterialCode);
            if (!material) return sendError(res, 400, `物料 ${relationMaterialCode} 不存在`);
            const relationStatus = input.status === '停用' ? '停用' : input.status === '启用' ? '启用' : '';
            if (!relationStatus) return sendError(res, 400, `${material.name}的补货关系状态无效`);
            if (warehouse.status === '停用' && relationStatus !== '停用') {
              return sendError(res, 400, `仓库 ${warehouse.name} 已停用，只能保留为停用关系`);
            }
            if (!warehouseSupportsReplenishment(warehouse) && relationStatus !== '停用') {
              return sendError(res, 400, `仓库“${warehouse.name}”的业务职能不适用库存补货，只能保留为停用关系`);
            }
            if (material.status === '停用' && (!existing || relationStatus !== '停用')) {
              return sendError(res, 400, `物料 ${relationMaterialCode} 已停用，只能保留为停用关系`);
            }

            const safetyStock = Number(input.safetyStock);
            const reorderPoint = Number(input.reorderPoint);
            const maxStock = Number(input.maxStock);
            const replenishmentLot = Number(input.replenishmentLot);
            if (![safetyStock, reorderPoint, maxStock].every((value) => Number.isFinite(value) && value >= 0)) {
              return sendError(res, 400, `${material.name}的库存参数不能小于 0`);
            }
            if (!Number.isFinite(replenishmentLot) || replenishmentLot <= 0) {
              return sendError(res, 400, `${material.name}的补货批量必须大于 0`);
            }
            if (safetyStock > reorderPoint || reorderPoint > maxStock) {
              return sendError(res, 400, `${material.name}需满足安全库存 ≤ 补货点 ≤ 最高库存`);
            }

            normalizedItems.push({
              ...(existing || {}),
              code: existing?.code || `WMR-${String(++nextSequence).padStart(5, '0')}`,
              warehouseCode: targetWarehouseCode,
              warehouseName: warehouse.name,
              materialCode: relationMaterialCode,
              materialName: material.name,
              uom: material.uom || '',
              safetyStock,
              reorderPoint,
              maxStock,
              replenishmentLot,
              status: relationStatus,
              note: String(input.note || existing?.note || '').trim(),
            });
          }
          const omittedExisting = [...existingByMaterial.keys()].filter((existingMaterialCode) => !seenMaterials.has(existingMaterialCode));
          if (omittedExisting.length) {
            return sendError(res, 400, `已有补货关系不能直接删除，请将 ${omittedExisting.join('、')} 改为停用`);
          }

          relations.warehouseMaterials = [
            ...relations.warehouseMaterials.filter((row) => row.warehouseCode !== targetWarehouseCode),
            ...normalizedItems,
          ];
          await writeData(data);
          return sendJson(res, 200, { items: normalizedItems });
        }

        return sendError(res, 405, '不支持的仓库补货设置操作');
      }

      return sendError(res, 404, '未知基础资料关联类型');
    }

    if (parts[1] === 'equipment') {
      const equipment = ensureEquipmentManagement(data);
      const page = parts[2];
      const pageConfig = {
        'inspection-tasks': { rows: equipment.tasks, label: '巡检任务' },
        'inspection-plans': { rows: equipment.plans, label: '巡检计划' },
        'inspection-standards': { rows: equipment.standards, label: '巡检标准' },
      }[page];
      if (!pageConfig) return sendError(res, 404, '未知设备巡检页面');

      const code = decodeURIComponent(parts[3] || '');
      const record = pageConfig.rows.find((row) => row.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        const items = [...pageConfig.rows].sort((left, right) => (
          String(right.scheduledDate || right.updatedAt || '').localeCompare(String(left.scheduledDate || left.updatedAt || ''))
        ));
        return sendJson(res, 200, { items });
      }

      if (req.method === 'GET' && parts.length === 4) {
        if (!record) return sendError(res, 404, `${pageConfig.label}不存在`);
        return sendJson(res, 200, equipmentInspectionResponse(data, record));
      }

      if (page === 'inspection-tasks') {
        if (req.method !== 'POST' || parts.length !== 5) return sendError(res, 405, '巡检任务由巡检计划自动生成，不能手工新增或编辑。');
        if (!record) return sendError(res, 404, '巡检任务不存在');

        const action = parts[4];
        if (!['start', 'complete', 'resolve', 'cancel'].includes(action)) return sendError(res, 404, '未知巡检任务操作');
        const body = await readBody(req);
        const idempotencyKey = String(body.idempotencyKey || '').trim();
        if (!idempotencyKey) return sendError(res, 400, '执行巡检任务必须提供幂等键。');
        const repeated = equipment.commands.find((command) => command.idempotencyKey === idempotencyKey);
        if (repeated) {
          const latest = equipment.tasks.find((row) => row.code === code) || record;
          return sendJson(res, 200, equipmentInspectionResponse(data, latest));
        }
        assertEquipmentInspectionRevision(body, record);

        const actor = businessActorName(req, data);
        let actionLabel = '';
        let actionRemark = '';
        let generatedTask = null;

        if (action === 'start') {
          if (record.status !== '待巡检') return sendError(res, 400, '只有待巡检任务可以开始。');
          if (record.scheduledDate > shanghaiDate()) {
            return sendError(res, 400, `任务计划日期为 ${record.scheduledDate}，计划日期到达后才能开始巡检。`);
          }
          record.status = '巡检中';
          record.startedAt = shanghaiDateTime();
          record.updatedAt = record.startedAt;
          record.updatedBy = actor;
          record.revision = Number(record.revision || 0) + 1;
          actionLabel = '开始巡检';
          actionRemark = `${record.equipmentName} 已进入现场巡检。`;
        }

        if (action === 'complete') {
          if (record.status !== '巡检中') return sendError(res, 400, '只有巡检中的任务可以提交结果。');
          const inputRecord = body.record || {};
          const items = normalizeEquipmentInspectionTaskResults(inputRecord.items, record.items);
          if (items.some((item) => item.result === '待检查')) return sendError(res, 400, '请完成全部巡检项目的判定。');
          const abnormalItems = items.filter((item) => item.result === '异常');
          if (abnormalItems.some((item) => !item.actual && !item.note)) {
            return sendError(res, 400, '异常巡检项目必须填写实测情况或备注。');
          }
          const exceptionSummary = String(inputRecord.exceptionSummary || '').trim();
          if (abnormalItems.length && !exceptionSummary) return sendError(res, 400, '存在异常项目时必须填写异常概述。');

          record.items = items;
          record.exceptionSummary = abnormalItems.length ? exceptionSummary : '';
          delete record.note;
          record.result = abnormalItems.length ? '异常' : '正常';
          record.status = abnormalItems.length ? '异常处理中' : '已完成';
          record.completedAt = abnormalItems.length ? '' : shanghaiDateTime();
          record.updatedAt = shanghaiDateTime();
          record.updatedBy = actor;
          record.revision = Number(record.revision || 0) + 1;
          actionLabel = abnormalItems.length ? '提交巡检异常' : '完成巡检';
          actionRemark = abnormalItems.length
            ? `${abnormalItems.length} 项异常，已进入异常处理。`
            : '全部巡检项目正常，任务已完成。';
          if (!abnormalItems.length) generatedTask = generateNextEquipmentInspectionTask(data, record, actor);
        }

        if (action === 'resolve') {
          if (record.status !== '异常处理中') return sendError(res, 400, '只有异常处理中的任务可以关闭异常。');
          const resolution = String(body.record?.resolution || '').trim();
          if (!resolution) return sendError(res, 400, '关闭异常前必须填写处理结果。');
          record.resolution = resolution;
          record.status = '已完成';
          record.completedAt = shanghaiDateTime();
          record.updatedAt = record.completedAt;
          record.updatedBy = actor;
          record.revision = Number(record.revision || 0) + 1;
          actionLabel = '关闭巡检异常';
          actionRemark = resolution;
          generatedTask = generateNextEquipmentInspectionTask(data, record, actor);
        }

        if (action === 'cancel') {
          if (record.status !== '待巡检') return sendError(res, 400, '只有尚未开始的待巡检任务可以取消。');
          const cancelReason = String(body.record?.cancelReason || '').trim();
          if (!cancelReason) return sendError(res, 400, '取消巡检任务前必须填写取消原因。');
          record.cancelReason = cancelReason;
          record.cancelledAt = shanghaiDateTime();
          record.status = '已取消';
          record.result = '未执行';
          record.updatedAt = record.cancelledAt;
          record.updatedBy = actor;
          record.revision = Number(record.revision || 0) + 1;
          actionLabel = '取消巡检任务';
          actionRemark = cancelReason;
          generatedTask = generateNextEquipmentInspectionTask(data, record, actor);
        }

        appendEquipmentInspectionFlow(data, record.code, actionLabel, actionRemark, actor);
        equipment.commands.push({ idempotencyKey, code: record.code, action, revision: record.revision, updatedAt: shanghaiDateTime() });
        appendBusinessAuditLog(req, data, actionLabel, record.code, actionRemark);
        await writeData(data);
        return sendJson(res, 200, equipmentInspectionResponse(data, record, generatedTask));
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const actor = businessActorName(req, data);
        const input = body.record || body;
        let created;
        let generatedTask = null;
        if (page === 'inspection-standards') {
          created = normalizeEquipmentInspectionStandard(input, null, data, actor);
        } else {
          created = normalizeEquipmentInspectionPlan(input, null, data, actor);
        }
        pageConfig.rows.unshift(created);
        if (page === 'inspection-plans' && created.status === '启用') {
          generatedTask = createEquipmentInspectionTaskFromPlan(data, created, created.firstDueDate, actor);
          created.nextDueDate = generatedTask?.scheduledDate || created.firstDueDate;
        }
        appendEquipmentInspectionFlow(data, created.code, `新建${pageConfig.label}`, `${created.name}，状态 ${created.status}。`, actor);
        appendBusinessAuditLog(req, data, `新建${pageConfig.label}`, created.code, `${created.name}，状态 ${created.status}。`);
        await writeData(data);
        return sendJson(res, 201, equipmentInspectionResponse(data, created, generatedTask));
      }

      if (req.method === 'PUT' && parts.length === 4) {
        if (!record) return sendError(res, 404, `${pageConfig.label}不存在`);
        const body = await readBody(req);
        assertEquipmentInspectionRevision(body, record);
        const actor = businessActorName(req, data);
        const input = body.record || body;
        const wasEnabled = record.status === '启用';
        const previousPlan = page === 'inspection-plans'
          ? { owner: record.owner, ownerEmployeeCode: record.ownerEmployeeCode }
          : null;
        const updated = page === 'inspection-standards'
          ? normalizeEquipmentInspectionStandard(input, record, data, actor)
          : normalizeEquipmentInspectionPlan(input, record, data, actor);
        if (equipmentInspectionEditableSignature(page, updated) === equipmentInspectionEditableSignature(page, record)) {
          return sendJson(res, 200, equipmentInspectionResponse(data, record, null, { unchanged: true }));
        }
        const index = pageConfig.rows.findIndex((row) => row.code === record.code);
        pageConfig.rows[index] = updated;
        if (page === 'inspection-standards') {
          equipment.plans
            .filter((plan) => plan.standardCode === updated.code)
            .forEach((plan) => {
              plan.standardName = updated.name;
              plan.standardRevision = Number(updated.revision || 1);
            });
        }
        const reassignedTaskCount = page === 'inspection-plans'
          ? reassignPendingEquipmentInspectionTasks(data, previousPlan, updated, actor)
          : 0;
        let generatedTask = null;
        let retainedTask = null;
        if (page === 'inspection-plans' && !wasEnabled && updated.status === '启用') {
          retainedTask = equipment.tasks
            .filter((task) => task.planCode === updated.code && equipmentInspectionTaskIsOpen(task))
            .sort((left, right) => String(left.scheduledDate || '').localeCompare(String(right.scheduledDate || '')))[0] || null;
          if (retainedTask) {
            updated.nextDueDate = retainedTask.scheduledDate;
          } else {
            const plannedDate = updated.nextDueDate || updated.firstDueDate;
            const scheduledDate = plannedDate < shanghaiDate() ? shanghaiDate() : plannedDate;
            generatedTask = createEquipmentInspectionTaskFromPlan(data, updated, scheduledDate, actor);
            if (generatedTask) updated.nextDueDate = generatedTask.scheduledDate;
          }
        }
        appendEquipmentInspectionFlow(
          data,
          updated.code,
          `更新${pageConfig.label}`,
          `${updated.name} 已更新。${page === 'inspection-standards' ? `当前修订 R${updated.revision}，之后生成的任务采用该修订。` : ''}${reassignedTaskCount ? `已同步改派 ${reassignedTaskCount} 个待巡检任务。` : ''}${retainedTask ? `继续承接未完成任务 ${retainedTask.code}，未重复生成。` : ''}`,
          actor,
        );
        appendBusinessAuditLog(req, data, `更新${pageConfig.label}`, updated.code, `${updated.name}，状态 ${updated.status}。`);
        await writeData(data);
        return sendJson(res, 200, equipmentInspectionResponse(data, updated, generatedTask, { reassignedTaskCount, retainedTask }));
      }

      return sendError(res, 405, `不支持的${pageConfig.label}操作`);
    }

    if (parts[1] === 'master-data') {
      const type = masterType(parts[2]);
      if (!type) return sendError(res, 404, '未知基础资料类型');

      const rows = ensureMasterRows(data, type);
      const code = decodeURIComponent(parts[3] || '');
      const index = rows.findIndex((row) => row.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        const responseRows = type === 'departments'
            ? rows.map((row) => ({
                ...row,
                employeeCount: ensureMasterRows(data, 'employees').filter(
                  (employee) => employee.status !== '停用' && [row.name, row.code].includes(employee.owner),
                ).length,
              }))
            : type === 'employees'
              ? rows.map((row) => {
                  const account = ensureSystem(data).accounts.find((candidate) => (
                    String(candidate.employeeCode || '').trim() === row.code
                    || (!candidate.employeeCode && String(candidate.name || '').trim() === String(row.name || '').trim())
                  ));
                  return {
                    ...row,
                    linkedAccount: account?.username || account?.code || '',
                    linkedAccountStatus: account?.status || '未分配',
                  };
                })
            : rows;
        return sendJson(res, 200, {
          items: [...responseRows].sort(compareUpdatedRows),
        });
      }

      if (req.method === 'GET' && code) {
        if (index < 0) return sendError(res, 404, '基础资料不存在');
        const record = type === 'departments'
            ? {
                ...rows[index],
                employeeCount: ensureMasterRows(data, 'employees').filter(
                  (employee) => employee.status !== '停用' && [rows[index].name, rows[index].code].includes(employee.owner),
                ).length,
              }
            : type === 'employees'
              ? (() => {
                  const employee = rows[index];
                  const account = ensureSystem(data).accounts.find((candidate) => (
                    String(candidate.employeeCode || '').trim() === employee.code
                    || (!candidate.employeeCode && String(candidate.name || '').trim() === String(employee.name || '').trim())
                  ));
                  return {
                    ...employee,
                    linkedAccount: account?.username || account?.code || '',
                    linkedAccountStatus: account?.status || '未分配',
                  };
                })()
            : rows[index];
        return sendJson(res, 200, { record });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        if (type === 'currencies' && rows.some((row) => row.code === String(body.code || '').trim().toUpperCase())) {
          return sendError(res, 400, `币种代码 ${String(body.code || '').trim().toUpperCase()} 已存在。`);
        }
        const normalizedInput =
          body.code && rows.some((row) => row.code === body.code)
            ? { ...body, code: nextMasterCode(type, rows, body) }
            : body;
        const record = normalizeMasterRecord(type, normalizedInput, undefined, rows, data);
        rows.unshift(record);
        await writeData(data);
        return sendJson(res, 201, { record });
      }

      if (req.method === 'PUT' && code) {
        if (index < 0) return sendError(res, 404, '基础资料不存在');
        const body = await readBody(req);
        const previousRecord = rows[index];
        const expectedRevision = Number(body.revision);
        const currentRevision = Number(previousRecord.revision || 1);
        if (!Number.isInteger(expectedRevision) || expectedRevision !== currentRevision) {
          return sendError(res, 409, '资料已被其他用户更新，请刷新页面后重新修改。');
        }
        const record = normalizeMasterRecord(type, { ...body, code }, previousRecord, rows, data);
        rows[index] = record;
        syncMasterReferenceProjections(data, type, previousRecord, record);
        await writeData(data);
        return sendJson(res, 200, { record });
      }
    }

    const afterSalesExecutionModule = {
      warehouse: '仓库',
      quality: '质检',
      production: '生产',
    }[parts[1]];
    if (afterSalesExecutionModule && parts[2] === 'after-sales-tasks') {
      ensureSales(data);
      ensurePurchase(data);
      const store = afterSalesTaskStore(data, afterSalesExecutionModule);
      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: [...store]
            .filter((task) => task.status !== '已取消')
            .sort((a, b) => `${b.createdAt || ''}${b.code}`.localeCompare(`${a.createdAt || ''}${a.code}`))
            .map((task) => afterSalesExecutionTaskResponse(data, task)),
        });
      }
      const code = decodeURIComponent(parts[3] || '');
      const task = store.find((record) => record.code === code);
      if (req.method === 'GET' && code) {
        if (!task) return sendError(res, 404, `${afterSalesExecutionModule}售后任务不存在`);
        return sendJson(res, 200, {
          task: {
            ...afterSalesExecutionTaskResponse(data, task),
            companyCode: task.companyCode || '',
            company: task.company || '',
            partyCode: task.partyCode || '',
            warehouseCode: task.warehouseCode || '',
            warehouse: task.warehouse || '',
            location: task.location || '',
            stockFacts: cloneJson(task.stockFacts || [], []),
            adjustmentCode: task.adjustmentCode || '',
          },
          afterSale: cloneJson(afterSalesCase(data, task.afterSaleKind, task.afterSaleCode), null),
        });
      }
      if (req.method === 'POST' && code && parts[4] === 'start') {
        const body = await readBody(req);
        const actor = businessActorName(req, data);
        const result = startAfterSalesExecutionTask(data, afterSalesExecutionModule, code, body, actor);
        appendBusinessAuditLog(req, data, `开始${afterSalesExecutionModule}售后任务`, code, result.task.kind);
        await writeData(data);
        return sendJson(res, 200, { task: afterSalesExecutionTaskResponse(data, result.task), repeated: result.repeated });
      }
      if (req.method === 'POST' && code && parts[4] === 'complete') {
        const body = await readBody(req);
        const actor = businessActorName(req, data);
        const result = completeAfterSalesExecutionTask(data, afterSalesExecutionModule, code, body, actor);
        appendBusinessAuditLog(req, data, `完成${afterSalesExecutionModule}售后任务`, code, `${result.task.kind}：${result.task.evidence}`);
        await writeData(data);
        return sendJson(res, 200, {
          task: afterSalesExecutionTaskResponse(data, result.task),
          afterSale: result.caseRecord,
          repeated: result.repeated,
        });
      }
    }

    if (parts[1] === 'production' && parts[2] === 'tasks') {
      const production = ensureProduction(data);
      const code = decodeURIComponent(parts[3] || '');
      const index = production.tasks.findIndex((record) => record.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: [...production.tasks].sort((a, b) => `${b.updatedAt || b.createdAt || ''}${b.code}`.localeCompare(`${a.updatedAt || a.createdAt || ''}${a.code}`)),
        });
      }

      if (req.method === 'GET' && code && parts.length === 4) {
        if (index < 0) return sendError(res, 404, '生产任务不存在。');
        return sendJson(res, 200, {
          record: production.tasks[index],
          flowRecords: production.taskFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const command = String(body.command || 'save').trim();
        if (!['save', 'submit'].includes(command)) return sendError(res, 400, '生产任务动作无效。');
        const replay = productionPlanningCommandReplay(production, 'tasks', command, body.idempotencyKey);
        if (replay) {
          return sendJson(res, replay.statusCode, {
            ...cloneJson(replay.response, {}),
            repeated: true,
          });
        }
        const actorAccount = activeAccountForRequest(req, data);
        const actor = businessActorName(req, data);
        const record = normalizeProductionTask(body, undefined, data, actorAccount);
        if (production.tasks.some((item) => item.code === record.code)) {
          return sendError(res, 409, `生产任务 ${record.code} 已存在。`);
        }
        production.tasks.unshift(record);
        const submitted = record.documentStatus === '已确认';
        appendProductionTaskFlow(data, record.code, submitted ? '提交生产任务' : '保存生产任务', submitted ? '任务已确认，可按成品明细创建生产工单。' : '任务已保存为草稿。', actor);
        appendBusinessAuditLog(req, data, submitted ? '提交生产任务' : '保存生产任务', record.code, `${record.products.length} 项成品，计划 ${record.demandQty}${record.unit}。`);
        const responseBody = {
          record,
          items: production.tasks,
          flowRecords: production.taskFlowRecords[record.code] || [],
        };
        rememberProductionPlanningCommand(production, 'tasks', command, body.idempotencyKey, 201, responseBody);
        await writeData(data);
        return sendJson(res, 201, responseBody);
      }

      if (req.method === 'PUT' && code && parts.length === 4) {
        const body = await readBody(req);
        const command = String(body.command || 'save').trim();
        if (!['save', 'submit'].includes(command)) return sendError(res, 400, '生产任务动作无效。');
        const replay = productionPlanningCommandReplay(production, 'tasks', command, body.idempotencyKey);
        if (replay) {
          return sendJson(res, replay.statusCode, {
            ...cloneJson(replay.response, {}),
            repeated: true,
          });
        }
        if (index < 0) return sendError(res, 404, '生产任务不存在。');
        const expectedRevision = Number(body.revision);
        const currentRevision = Number(production.tasks[index].revision || 0);
        if (!Number.isInteger(expectedRevision) || expectedRevision !== currentRevision) {
          return sendError(res, 409, '生产任务已被其他用户更新，请刷新后重新修改。');
        }
        const actorAccount = activeAccountForRequest(req, data);
        const actor = businessActorName(req, data);
        const record = normalizeProductionTask({ ...body, code }, production.tasks[index], data, actorAccount);
        production.tasks[index] = record;
        const submitted = record.documentStatus === '已确认';
        appendProductionTaskFlow(data, record.code, submitted ? '提交任务变更' : '保存任务变更', `任务修订为第 ${record.revision} 版。`, actor);
        appendBusinessAuditLog(req, data, '更新生产任务', record.code, `任务修订为第 ${record.revision} 版。`);
        const responseBody = {
          record,
          items: production.tasks,
          flowRecords: production.taskFlowRecords[record.code] || [],
        };
        rememberProductionPlanningCommand(production, 'tasks', command, body.idempotencyKey, 200, responseBody);
        await writeData(data);
        return sendJson(res, 200, responseBody);
      }
    }

    if (parts[1] === 'production' && parts[2] === 'material-requests') {
      const production = ensureProduction(data);
      const code = decodeURIComponent(parts[3] || '');
      const index = production.materialRequests.findIndex((record) => record.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: [...production.materialRequests].sort((a, b) => `${b.updatedAt || b.requestDate || ''}${b.code}`.localeCompare(`${a.updatedAt || a.requestDate || ''}${a.code}`)),
        });
      }

      if (req.method === 'GET' && code && parts.length === 4) {
        if (index < 0) return sendError(res, 404, '备料申请不存在。');
        return sendJson(res, 200, {
          record: production.materialRequests[index],
          flowRecords: production.materialRequestFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'accept') {
        return sendError(res, 410, '仓库受理备料申请已取消；生产提交时由系统自动评估库存并分流采购缺口。');
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const command = String(body.command || 'save').trim();
        if (!['save', 'submit'].includes(command)) return sendError(res, 400, '备料申请动作无效。');
        const replay = productionPlanningCommandReplay(production, 'material-requests', command, body.idempotencyKey);
        if (replay) {
          return sendJson(res, replay.statusCode, {
            ...cloneJson(replay.response, {}),
            repeated: true,
          });
        }
        const actorAccount = activeAccountForRequest(req, data);
        const actor = businessActorName(req, data);
        const normalized = normalizeProductionMaterialRequest(body, undefined, data, actorAccount);
        if (production.materialRequests.some((item) => item.code === normalized.code)) {
          return sendError(res, 409, `备料申请 ${normalized.code} 已存在。`);
        }
        const submitted = normalized.documentStatus === '已确认';
        const evaluated = submitted
          ? evaluateProductionMaterialRequestCoverage(data, normalized)
          : { record: normalized, requisition: null };
        const record = evaluated.record;
        production.materialRequests.unshift(record);
        appendProductionMaterialRequestFlow(
          data,
          record.code,
          submitted ? '提交并自动分流' : '保存备料申请',
          submitted
            ? evaluated.requisition
              ? `系统按可用库存快照完成评估，缺口已生成采购申请 ${evaluated.requisition.code}。`
              : '系统按可用库存快照完成评估，当前库存可覆盖；不提前占用库存。'
            : '申请已保存为草稿。',
          submitted ? '系统' : actor,
        );
        appendBusinessAuditLog(
          req,
          data,
          submitted ? '提交并评估备料申请' : '保存备料申请',
          record.code,
          submitted
            ? `${record.lines.length} 项物料明细；${evaluated.requisition ? `生成采购申请 ${evaluated.requisition.code}` : '当前库存可覆盖'}。`
            : `${record.lines.length} 项物料明细。`,
        );
        const responseBody = {
          record,
          purchaseRequisition: evaluated.requisition,
          items: production.materialRequests,
          flowRecords: production.materialRequestFlowRecords[record.code] || [],
        };
        rememberProductionPlanningCommand(production, 'material-requests', command, body.idempotencyKey, 201, responseBody);
        await writeData(data);
        return sendJson(res, 201, responseBody);
      }

      if (req.method === 'PUT' && code && parts.length === 4) {
        const body = await readBody(req);
        const command = String(body.command || 'save').trim();
        if (!['save', 'submit'].includes(command)) return sendError(res, 400, '备料申请动作无效。');
        const replay = productionPlanningCommandReplay(production, 'material-requests', command, body.idempotencyKey);
        if (replay) {
          return sendJson(res, replay.statusCode, {
            ...cloneJson(replay.response, {}),
            repeated: true,
          });
        }
        if (index < 0) return sendError(res, 404, '备料申请不存在。');
        const expectedRevision = Number(body.revision);
        const currentRevision = Number(production.materialRequests[index].revision || 0);
        if (!Number.isInteger(expectedRevision) || expectedRevision !== currentRevision) {
          return sendError(res, 409, '备料申请已被其他用户更新，请刷新后重新修改。');
        }
        const actorAccount = activeAccountForRequest(req, data);
        const actor = businessActorName(req, data);
        const normalized = normalizeProductionMaterialRequest({ ...body, code }, production.materialRequests[index], data, actorAccount);
        const submitted = normalized.documentStatus === '已确认';
        const evaluated = submitted
          ? evaluateProductionMaterialRequestCoverage(data, normalized)
          : { record: normalized, requisition: null };
        const record = evaluated.record;
        production.materialRequests[index] = record;
        appendProductionMaterialRequestFlow(
          data,
          record.code,
          submitted ? '提交并自动分流' : '保存申请变更',
          submitted
            ? evaluated.requisition
              ? `第 ${record.revision} 版已按可用库存快照评估，缺口生成采购申请 ${evaluated.requisition.code}。`
              : `第 ${record.revision} 版已按可用库存快照评估，当前库存可覆盖；不提前占用库存。`
            : `申请修订为第 ${record.revision} 版。`,
          submitted ? '系统' : actor,
        );
        appendBusinessAuditLog(
          req,
          data,
          submitted ? '提交并评估备料申请' : '更新备料申请',
          record.code,
          submitted
            ? `${record.lines.length} 项物料明细；${evaluated.requisition ? `生成采购申请 ${evaluated.requisition.code}` : '当前库存可覆盖'}。`
            : `申请修订为第 ${record.revision} 版。`,
        );
        const responseBody = {
          record,
          purchaseRequisition: evaluated.requisition,
          items: production.materialRequests,
          flowRecords: production.materialRequestFlowRecords[record.code] || [],
        };
        rememberProductionPlanningCommand(production, 'material-requests', command, body.idempotencyKey, 200, responseBody);
        await writeData(data);
        return sendJson(res, 200, responseBody);
      }
    }

    if (parts[1] === 'production' && parts[2] === 'recipes') {
      const production = ensureProduction(data);
      const code = decodeURIComponent(parts[3] || '');
      const index = production.recipes.findIndex((record) => record.code === code);
      const effectiveRecord = effectiveProductionRecipes(data).find((record) => record.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: effectiveProductionRecipes(data)
            .sort((a, b) => `${b.updatedAt || ''}${b.code}`.localeCompare(`${a.updatedAt || ''}${a.code}`)),
        });
      }

      if (req.method === 'GET' && code && parts.length === 4) {
        if (!effectiveRecord) return sendError(res, 404, '生产配方不存在');
        return sendJson(res, 200, {
          record: effectiveRecord,
          flowRecords: production.recipeFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const actor = businessActorName(req, data);
        const record = normalizeProductionRecipe(data, { ...body, status: '草稿' }, undefined, '', actor);
        if (effectiveProductionRecipes(data).some((item) => item.code === record.code)) {
          return sendError(res, 409, `生产配方 ${record.code} 已存在。`);
        }
        production.recipes.unshift(record);
        appendProductionRecipeFlow(data, record.code, '创建配方', `${record.productName} ${record.version} 已保存为${record.status}。`, record.owner);
        appendBusinessAuditLog(req, data, '创建生产配方', record.code, `${record.productName} ${record.version}，状态 ${record.status}。`);
        await writeData(data);
        return sendJson(res, 201, {
          record,
          items: production.recipes,
          flowRecords: production.recipeFlowRecords[record.code] || [],
        });
      }

      if (req.method === 'PUT' && code && parts.length === 4) {
        if (!effectiveRecord) return sendError(res, 404, '生产配方不存在');
        const body = await readBody(req);
        const command = String(body.command || 'save').trim();
        if (!['save', 'activate', 'disable'].includes(command)) return sendError(res, 400, '生产配方版本动作无效。');
        if (command === 'save' && effectiveRecord.status !== '草稿') {
          return sendError(res, 409, '已启用或已停用的配方不能直接编辑，请创建新版本。');
        }
        if (command === 'activate' && effectiveRecord.status !== '草稿') {
          return sendError(res, 409, '只有草稿配方可以启用。');
        }
        if (command === 'disable' && effectiveRecord.status !== '启用') {
          return sendError(res, 409, '只有当前启用的配方可以停用。');
        }
        const nextStatus = command === 'activate' ? '启用' : command === 'disable' ? '停用' : '草稿';
        const actor = businessActorName(req, data);
        const record = normalizeProductionRecipe(data, { ...body, code, status: nextStatus }, effectiveRecord, code, actor);
        if (index >= 0) production.recipes[index] = record;
        else production.recipes.unshift(record);
        const action = command === 'activate' ? '启用配方' : command === 'disable' ? '停用配方' : '更新配方草稿';
        appendProductionRecipeFlow(data, record.code, action, `修订为第 ${record.revision} 版记录，状态 ${record.status}。`, record.owner);
        appendBusinessAuditLog(req, data, action, record.code, `修订为第 ${record.revision} 版记录，状态 ${record.status}。`);
        await writeData(data);
        return sendJson(res, 200, {
          record,
          items: production.recipes,
          flowRecords: production.recipeFlowRecords[record.code] || [],
        });
      }
    }

    if (parts[1] === 'production' && parts[2] === 'process-templates') {
      const production = ensureProduction(data);
      const code = decodeURIComponent(parts[3] || '');
      const index = production.processTemplates.findIndex((record) => record.code === code);
      const effectiveRecord = effectiveProductionProcessTemplates(data).find((record) => record.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: effectiveProductionProcessTemplates(data)
            .sort((a, b) => `${b.updatedAt || ''}${b.code}`.localeCompare(`${a.updatedAt || ''}${a.code}`)),
        });
      }

      if (req.method === 'GET' && code && parts.length === 4) {
        if (!effectiveRecord) return sendError(res, 404, '生产工艺不存在。');
        return sendJson(res, 200, {
          record: effectiveRecord,
          flowRecords: production.processTemplateFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const actor = businessActorName(req, data);
        const record = normalizeProductionProcessTemplate(data, { ...body, status: '草稿' }, undefined, '', actor);
        if (effectiveProductionProcessTemplates(data).some((item) => item.code === record.code)) {
          return sendError(res, 409, `生产工艺 ${record.code} 已存在。`);
        }
        production.processTemplates.unshift(record);
        appendProductionProcessTemplateFlow(data, record.code, '创建工艺', `${record.name} ${record.version} 已保存为草稿。`, record.owner);
        appendBusinessAuditLog(req, data, '创建生产工艺', record.code, `${record.name} ${record.version}，状态 ${record.status}。`);
        await writeData(data);
        return sendJson(res, 201, {
          record,
          items: production.processTemplates,
          flowRecords: production.processTemplateFlowRecords[record.code] || [],
        });
      }

      if (req.method === 'PUT' && code && parts.length === 4) {
        if (!effectiveRecord) return sendError(res, 404, '生产工艺不存在。');
        const body = await readBody(req);
        const command = String(body.command || 'save').trim();
        if (!['save', 'activate', 'disable'].includes(command)) return sendError(res, 400, '生产工艺版本动作无效。');
        if (command === 'save' && effectiveRecord.status !== '草稿') {
          return sendError(res, 409, '已启用或已停用的工艺不能直接编辑，请创建新版本。');
        }
        if (command === 'activate' && effectiveRecord.status !== '草稿') {
          return sendError(res, 409, '只有草稿工艺可以启用。');
        }
        if (command === 'disable' && effectiveRecord.status !== '启用') {
          return sendError(res, 409, '只有当前启用的工艺可以停用。');
        }
        const nextStatus = command === 'activate' ? '启用' : command === 'disable' ? '停用' : '草稿';
        const actor = businessActorName(req, data);
        const record = normalizeProductionProcessTemplate(data, { ...body, code, status: nextStatus }, effectiveRecord, code, actor);
        if (index >= 0) production.processTemplates[index] = record;
        else production.processTemplates.unshift(record);
        const action = command === 'activate' ? '启用工艺' : command === 'disable' ? '停用工艺' : '更新工艺草稿';
        appendProductionProcessTemplateFlow(data, record.code, action, `修订为第 ${record.revision} 版记录，状态 ${record.status}。`, record.owner);
        appendBusinessAuditLog(req, data, action, record.code, `修订为第 ${record.revision} 版记录，状态 ${record.status}。`);
        await writeData(data);
        return sendJson(res, 200, {
          record,
          items: production.processTemplates,
          flowRecords: production.processTemplateFlowRecords[record.code] || [],
        });
      }
    }

    if (parts[1] === 'production' && parts[2] === 'work-orders') {
      const production = ensureProduction(data);
      const code = decodeURIComponent(parts[3] || '');
      const index = production.workOrders.findIndex((record) => record.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: [...production.workOrders].sort((a, b) => `${b.updatedAt || ''}${b.code}`.localeCompare(`${a.updatedAt || ''}${a.code}`)),
          tasks: production.tasks,
          materialRequests: production.materialRequests,
          executionCards: refreshExecutionCards(data, production.executionCards),
          releaseBatches: production.workOrders.flatMap((order) => activeWorkOrderReleases(production, order.code)),
          qualityTasks: production.qualityTasks,
          productionLines: ensureMasterRows(data, 'productionLines'),
        });
      }

      if (req.method === 'GET' && code && parts[4] === 'releases') {
        if (index < 0) return sendError(res, 404, '生产工单不存在');
        return sendJson(res, 200, {
          workOrder: production.workOrders[index],
          items: activeWorkOrderReleases(production, code),
        });
      }

      if (req.method === 'GET' && code && parts.length === 4) {
        if (index < 0) return sendError(res, 404, '生产工单不存在');
        const executionCards = refreshExecutionCards(
          data,
          production.executionCards.filter((item) => item.workOrderCode === code),
        );
        return sendJson(res, 200, {
          record: production.workOrders[index],
          releaseBatches: activeWorkOrderReleases(production, code),
          executionCards,
          qualityTasks: production.qualityTasks.filter((item) => item.workOrderCode === code),
          flowRecords: production.workOrderFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const command = String(body.command || 'save').trim();
        if (!['save', 'submit'].includes(command)) return sendError(res, 400, '生产工单动作无效。');
        const replay = productionPlanningCommandReplay(production, 'work-orders', command, body.idempotencyKey);
        if (replay) {
          return sendJson(res, replay.statusCode, {
            ...cloneJson(replay.response, {}),
            repeated: true,
          });
        }
        const actorAccount = activeAccountForRequest(req, data);
        const actor = businessActorName(req, data);
        const record = normalizeWorkOrder(body, undefined, data, actorAccount);
        if (production.workOrders.some((item) => item.code === record.code)) {
          return sendError(res, 409, `生产工单 ${record.code} 已存在，请刷新后继续编辑。`);
        }
        production.workOrders.unshift(record);
        if (record.sourceDocument) recomputeSalesOrderProgress(data, record.sourceDocument);
        appendWorkOrderFlow(
          data,
          record.code,
          record.documentStatus === '已确认' ? '提交生产工单' : '保存生产工单',
          record.documentStatus === '已确认'
            ? `工单已确认，来源 ${record.sourceTask ? `${record.sourceTask} / ${record.sourceLineId}` : '手工新建'}，等待按物料条件释放。`
            : `工单草稿已保存，来源 ${record.sourceTask ? `${record.sourceTask} / ${record.sourceLineId}` : '手工新建'}。`,
          actor,
        );
        appendBusinessAuditLog(req, data, '创建生产工单', record.code, `来源 ${record.sourceTask ? `${record.sourceTask} / ${record.sourceLineId}` : '手工新建'}，计划 ${record.planQty}${record.unit}。`);
        const responseBody = {
          record,
          items: production.workOrders,
          flowRecords: production.workOrderFlowRecords[record.code] || [],
        };
        rememberProductionPlanningCommand(production, 'work-orders', command, body.idempotencyKey, 201, responseBody);
        await writeData(data);
        return sendJson(res, 201, responseBody);
      }

      if (req.method === 'POST' && code && parts[4] === 'release') {
        if (index < 0) return sendError(res, 404, '生产工单不存在');
        const body = await readBody(req);
        const {
          release,
          productionIssue,
          taskCreated,
          repeated,
        } = createWorkOrderRelease(data, production.workOrders[index], body, businessActorName(req, data));
        if (!repeated) {
          appendWorkOrderReleaseFlow(
            data,
            release.code,
            '释放到现场',
            `${release.workOrderCode} 本次释放 ${release.releasedQty}${release.unit}，物料已按来源行形成生产分配。`,
            release.releasedBy,
          );
          appendWorkOrderFlow(
            data,
            release.workOrderCode,
            '释放到现场',
            `释放批次 ${release.code} 已释放 ${release.releasedQty}${release.unit}，等待仓库领料。`,
            release.releasedBy,
          );
          appendBusinessAuditLog(
            req,
            data,
            '释放生产工单',
            release.workOrderCode,
            `释放批次 ${release.code}，数量 ${release.releasedQty}${release.unit}。`,
          );
        }
        if (!repeated || taskCreated) await writeData(data);
        return sendJson(res, repeated ? 200 : 201, {
          record: production.workOrders[index],
          release,
          productionIssue,
          repeated,
          releaseBatches: activeWorkOrderReleases(production, code),
          flowRecords: production.workOrderFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'close') {
        if (index < 0) return sendError(res, 404, '生产工单不存在。');
        const body = await readBody(req);
        const replay = productionPlanningCommandReplay(production, 'work-orders', 'close', body.idempotencyKey);
        if (replay) {
          return sendJson(res, replay.statusCode, {
            ...cloneJson(replay.response, {}),
            repeated: true,
          });
        }
        const record = production.workOrders[index];
        if (String(record.documentStatus || '') === '已关闭') {
          return sendError(res, 409, `生产工单 ${code} 已关闭；如为重试，请沿用首次关闭请求的幂等键。`);
        }
        const expectedRevision = Number(body.revision);
        if (!Number.isInteger(expectedRevision) || expectedRevision !== Number(record.revision || 0)) {
          return sendError(res, 409, `生产工单 ${code} 已更新，请刷新后再关闭。`);
        }
        if (!['已确认', 'submitted', 'confirmed'].includes(String(record.documentStatus || ''))) {
          return sendError(res, 409, '生产工单必须先确认，才能关闭。');
        }
        const cards = production.executionCards.filter((card) => String(card.workOrderCode || '') === code);
        const inboundQty = cards.reduce((sum, card) => sum + Number(card.inboundQty || 0), 0);
        const effectivePlanQty = workOrderEffectivePlanQty(record, cards);
        if (Number(record.planQty || 0) <= 0 || inboundQty + 0.0001 < effectivePlanQty) {
          return sendError(
            res,
            409,
            `生产工单尚未达到有效入库目标 ${formatQty(effectivePlanQty, record.unit)}，当前入库 ${formatQty(inboundQty, record.unit)}。`,
          );
        }
        const cardCodes = new Set(cards.map((card) => String(card.code || '')));
        const activeException = production.productionExceptions.find((exception) => (
          String(exception.status || '') !== '已关闭'
          && (
            String(exception.relatedWorkOrder || exception.workOrderCode || '') === code
            || cardCodes.has(String(exception.executionCardCode || exception.relatedBatch || ''))
          )
        ));
        if (activeException) {
          return sendError(res, 409, `生产异常 ${activeException.code} 尚未关闭，不能关闭工单。`);
        }
        const pendingQuality = production.qualityTasks.find((task) => {
          if (String(task.workOrderCode || '') !== code) return false;
          const progress = syncProductionQualityDispositionProgress(production, task);
          return ['待检', '检验中', '待判定'].includes(String(task.status || ''))
            || progress.remainingQty > 0
            || ['待处置', '返工中', '待复检'].includes(String(task.dispositionStatus || ''));
        });
        if (pendingQuality) {
          return sendError(res, 409, `质检任务 ${pendingQuality.code} 尚未完成处置，不能关闭工单。`);
        }
        const now = shanghaiDateTime();
        const actor = businessActorName(req, data);
        record.documentStatus = '已关闭';
        record.status = '已完成';
        record.currentNode = '已入库';
        record.inboundQty = inboundQty;
        record.acceptedShortageQty = Math.max(0, Number(record.planQty || 0) - effectivePlanQty);
        record.nextStep = '工单已关闭，可查看生产批次和完工入库记录';
        record.nextAction = record.nextStep;
        record.closedAt = now;
        record.closedBy = actor;
        record.revision = Number(record.revision || 0) + 1;
        record.updatedAt = now;
        const shortageSummary = record.acceptedShortageQty > 0
          ? `，接受短缺 ${formatQty(record.acceptedShortageQty, record.unit)}`
          : '';
        appendWorkOrderFlow(
          data,
          code,
          '关闭生产工单',
          `原计划 ${formatQty(record.planQty, record.unit)}，有效入库目标 ${formatQty(effectivePlanQty, record.unit)}${shortageSummary}，已完成核对。`,
          actor,
        );
        appendBusinessAuditLog(
          req,
          data,
          '关闭生产工单',
          code,
          `有效入库目标 ${formatQty(effectivePlanQty, record.unit)}${shortageSummary}。`,
        );
        const responseBody = {
          record,
          repeated: false,
          flowRecords: production.workOrderFlowRecords[code] || [],
        };
        rememberProductionPlanningCommand(production, 'work-orders', 'close', body.idempotencyKey, 200, responseBody);
        await writeData(data);
        return sendJson(res, 200, responseBody);
      }

      if (req.method === 'PUT' && code) {
        const body = await readBody(req);
        const command = String(body.command || 'save').trim();
        if (!['save', 'submit'].includes(command)) return sendError(res, 400, '生产工单动作无效。');
        const replay = productionPlanningCommandReplay(production, 'work-orders', command, body.idempotencyKey);
        if (replay) {
          return sendJson(res, replay.statusCode, {
            ...cloneJson(replay.response, {}),
            repeated: true,
          });
        }
        if (index < 0) return sendError(res, 404, '生产工单不存在');
        const expectedRevision = Number(body.revision);
        if (!Number.isInteger(expectedRevision) || expectedRevision !== Number(production.workOrders[index].revision || 0)) {
          return sendError(res, 409, `生产工单 ${code} 已更新，请刷新后重新修改。`);
        }
        const actorAccount = activeAccountForRequest(req, data);
        const actor = businessActorName(req, data);
        const record = normalizeWorkOrder({ ...body, code }, production.workOrders[index], data, actorAccount);
        production.workOrders[index] = record;
        if (record.sourceDocument) recomputeSalesOrderProgress(data, record.sourceDocument);
        appendWorkOrderFlow(
          data,
          record.code,
          record.documentStatus === '已确认' ? '提交工单变更' : '保存工单变更',
          `工单修订为第 ${record.revision} 版，来源保持为 ${record.sourceTask ? `${record.sourceTask} / ${record.sourceLineId}` : '手工新建'}。`,
          actor,
        );
        appendBusinessAuditLog(req, data, '更新生产工单', record.code, `工单修订为第 ${record.revision} 版。`);
        const responseBody = {
          record,
          items: production.workOrders,
          flowRecords: production.workOrderFlowRecords[record.code] || [],
        };
        rememberProductionPlanningCommand(production, 'work-orders', command, body.idempotencyKey, 200, responseBody);
        await writeData(data);
        return sendJson(res, 200, responseBody);
      }
    }

    if (parts[1] === 'production' && parts[2] === 'execution-cards') {
      const production = ensureProduction(data);
      const warehouse = ensureWarehouse(data);
      const code = decodeURIComponent(parts[3] || '');
      const index = production.executionCards.findIndex((record) => record.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: refreshExecutionCards(data, [...production.executionCards])
            .sort((a, b) => `${b.updatedAt || b.createdAt || ''}${b.code}`.localeCompare(`${a.updatedAt || a.createdAt || ''}${a.code}`)),
        });
      }

      if (req.method === 'GET' && code && parts.length === 4) {
        if (index < 0) return sendError(res, 404, '生产流转批次不存在');
        const card = refreshExecutionCardProcessInstances(data, production.executionCards[index]);
        return sendJson(res, 200, {
          record: card,
          release: productionReleaseForExecutionCard(production, card) || null,
          workOrder: production.workOrders.find((item) => item.code === card.workOrderCode) || null,
          reports: production.productionReports.filter((item) => item.executionCardCode === code),
          wipBatches: production.wipBatches.filter((item) => item.executionCardCode === code),
          lineageRecords: production.batchLineageRecords.filter((item) => item.executionCardCode === code),
          executionEvents: production.executionEvents.filter((item) => item.executionCardCode === code),
          exceptions: production.productionExceptions.filter((item) => item.executionCardCode === code),
          shiftHandovers: production.shiftHandovers.filter((item) => item.activeCards.some((card) => card.executionCardCode === code)),
          qualityTasks: production.qualityTasks.filter((item) => item.sourceCard === code),
          packagingRecords: production.packagingRecords.filter((item) => item.executionCardCode === code),
          productionIssues: warehouse.productionIssues.filter((item) => item.executionCard === code || item.releaseBatch === card.releaseBatchCode),
          productionReturns: warehouse.productionReturns.filter((item) => item.executionCard === code || item.releaseBatch === card.releaseBatchCode),
          productionReceipts: warehouse.productionReceipts.filter((item) => item.executionCard === code),
          flowRecords: production.executionCardFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'operation-jobs' && parts[6] === 'start') {
        if (index < 0) return sendError(res, 404, '生产批次不存在。');
        const jobCode = decodeURIComponent(parts[5] || '');
        const body = await readBody(req);
        const actor = String(body.actor || body.operator || production.executionCards[index].leader || '生产班长');
        const result = startExecutionCardOperationJob(data, production.executionCards[index], jobCode, body);
        if (!result.repeated) {
          const operationLabel = result.operationJob.operationType === '复绕生产' ? '复绕开工' : '补产开工';
          const sourceText = result.wipBatch?.code ? `，来源大盘 ${result.wipBatch.code}` : '';
          appendExecutionCardFlow(data, code, operationLabel, `${result.operationJob.operationType} ${jobCode} 已在 ${result.operationJob.assignedLine} 开工${sourceText}${result.qualityTask ? `，生成开机首检 ${result.qualityTask.code}` : ''}。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, operationLabel, `生产批次 ${code} 已开始${result.operationJob.operationType}。`, actor);
          appendBusinessAuditLog(req, data, `${result.operationJob.operationType}开工`, jobCode, `生产批次 ${code}，产线 ${result.operationJob.assignedLine}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.card,
          flowRecords: production.executionCardFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'short-close-resolution') {
        if (index < 0) return sendError(res, 404, '生产流转批次不存在');
        const body = await readBody(req);
        const actor = String(body.actor || production.executionCards[index].leader || '生产主管');
        const result = resolveExecutionCardShortClose(data, production.executionCards[index], body);
        if (!result.repeated) {
          const jobText = result.operationJob ? `，补充设备作业 ${result.operationJob.code}` : '';
          appendExecutionCardFlow(data, code, '处理短关剩余', `${result.decision.action} ${formatQty(result.decision.remainingQty, result.decision.unit)}${jobText}；原因：${result.decision.reason}。`, actor);
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '处理短关剩余', `生产批次 ${code} 已${result.decision.action}${jobText}。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, '处理短关剩余', `生产批次 ${code} 短关剩余已选择${result.decision.action}。`, actor);
          appendBusinessAuditLog(req, data, '生产短关剩余处理', result.decision.code, `生产批次 ${code}，${result.decision.action} ${result.decision.remainingQty}${result.decision.unit}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.card,
          flowRecords: production.executionCardFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'start') {
        if (index < 0) return sendError(res, 404, '生产流转批次不存在');
        const body = await readBody(req);
        const actor = String(body.actor || body.leader || '生产班长');
        const result = startExecutionCard(data, production.executionCards[index], body);
        if (!result.repeated) {
          appendExecutionCardFlow(data, code, '现场开工', `已指定负责人 ${result.card.leader}、操作人 ${result.card.operator}，生成开机首检 ${result.qualityTask.code}。`, actor);
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '现场开工', `流转批次 ${code} 已开工，等待开机首检 ${result.qualityTask.code}。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, '现场开工', `流转批次 ${code} 已开工，等待首检放行。`, actor);
          appendBusinessAuditLog(req, data, '生产流转批次开工', code, `生成开机首检 ${result.qualityTask.code}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.card,
          flowRecords: production.executionCardFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'report') {
        if (index < 0) return sendError(res, 404, '生产流转批次不存在');
        const body = await readBody(req);
        const actor = String(body.actor || production.executionCards[index].leader || '生产班长');
        const result = reportExecutionCard(data, production.executionCards[index], body);
        if (!result.repeated) {
          appendExecutionCardFlow(
            data,
            code,
            result.shortClosed ? '生产报工并短关' : '生产报工',
            `报工 ${result.report.code}：良品 ${formatQty(result.report.goodQty, result.report.unit)}，不良 ${formatQty(result.report.defectQty, result.report.unit)}${result.qualityTask ? `，生成报工全检 ${result.qualityTask.code}` : ''}${result.shortClosed ? `；设备作业短关，剩余 ${formatQty(result.card.shortCloseRemainingQty, result.card.unit)}，原因：${result.card.shortCloseReason}` : ''}。`,
            actor,
          );
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '生产报工', `流转批次 ${code} 已登记报工 ${result.report.code}。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, '生产报工', `流转批次 ${code} 已登记报工 ${result.report.code}。`, actor);
          appendBusinessAuditLog(req, data, result.shortClosed ? '生产报工并短关' : '生产报工', result.report.code, `生产批次 ${code}，良品 ${result.report.goodQty}${result.report.unit}，不良 ${result.report.defectQty}${result.report.unit}${result.shortClosed ? `，短关剩余 ${result.card.shortCloseRemainingQty}${result.card.unit}，原因：${result.card.shortCloseReason}` : ''}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.card,
          flowRecords: production.executionCardFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'wip-report') {
        if (index < 0) return sendError(res, 404, '生产流转批次不存在');
        const body = await readBody(req);
        const actor = String(body.actor || production.executionCards[index].leader || '生产班长');
        const result = reportExecutionCardWip(data, production.executionCards[index], body);
        if (!result.repeated) {
          appendExecutionCardFlow(
            data,
            code,
            '大盘半成品报工',
            `登记大盘 ${result.wipBatch.code}，净重 ${formatQty(result.wipBatch.netWeightKg, 'kg')}，生成半成品质检 ${result.qualityTask.code}。`,
            actor,
          );
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '大盘半成品报工', `流转批次 ${code} 已登记大盘 ${result.wipBatch.code}。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, '大盘半成品报工', `流转批次 ${code} 已登记大盘 ${result.wipBatch.code}。`, actor);
          appendBusinessAuditLog(req, data, '大盘半成品报工', result.report.code, `流转批次 ${code}，大盘 ${result.wipBatch.code}，净重 ${result.wipBatch.netWeightKg}kg。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.card,
          flowRecords: production.executionCardFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'pause') {
        if (index < 0) return sendError(res, 404, '生产流转批次不存在');
        const body = await readBody(req);
        const actor = String(body.actor || production.executionCards[index].leader || '生产班长');
        const result = pauseExecutionCard(data, production.executionCards[index], body);
        if (!result.repeated) {
          appendExecutionCardFlow(data, code, '暂停生产', `${result.event.code}：${result.event.reason}。原执行节点保持为 ${result.card.node}。`, actor);
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '暂停生产', `流转批次 ${code} 已暂停，等待原因解除。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, '暂停生产', `流转批次 ${code} 已暂停。`, actor);
          appendBusinessAuditLog(req, data, '生产暂停', code, `${result.event.code}：${result.event.reason}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.card,
          flowRecords: production.executionCardFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'resume') {
        if (index < 0) return sendError(res, 404, '生产流转批次不存在');
        const body = await readBody(req);
        const actor = String(body.actor || production.executionCards[index].leader || '生产班长');
        const result = resumeExecutionCard(data, production.executionCards[index], body);
        if (!result.repeated) {
          appendExecutionCardFlow(data, code, '恢复生产', `${result.event.code}：${result.event.reason}，返回 ${result.card.node}。`, actor);
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '恢复生产', `流转批次 ${code} 已恢复到 ${result.card.node}。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, '恢复生产', `流转批次 ${code} 已恢复现场执行。`, actor);
          appendBusinessAuditLog(req, data, '生产恢复', code, `${result.event.code}：${result.event.reason}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.card,
          flowRecords: production.executionCardFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'pack') {
        if (index < 0) return sendError(res, 404, '生产流转批次不存在');
        const body = await readBody(req);
        const actor = String(body.actor || production.executionCards[index].leader || '生产班长');
        const result = packExecutionCard(data, production.executionCards[index], body);
        if (!result.repeated) {
          appendExecutionCardFlow(data, code, '包装确认', `已确认包装并生成入库抽检 ${result.qualityTask.code}。`, actor);
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '包装确认', `流转批次 ${code} 已生成入库抽检 ${result.qualityTask.code}。`, actor);
          appendBusinessAuditLog(req, data, '生产包装确认', code, `生成入库抽检 ${result.qualityTask.code}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.card,
          flowRecords: production.executionCardFlowRecords[code] || [],
        });
      }
    }

    if (parts[1] === 'production' && parts[2] === 'loss-records') {
      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, { items: projectProductionLossRecords(data) });
      }
    }

    if (parts[1] === 'production' && parts[2] === 'exceptions') {
      const production = ensureProduction(data);
      const code = decodeURIComponent(parts[3] || '');
      const index = production.productionExceptions.findIndex((record) => record.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: [...production.productionExceptions].sort((a, b) => `${b.createdAt || ''}${b.code}`.localeCompare(`${a.createdAt || ''}${a.code}`)),
        });
      }

      if (req.method === 'GET' && code && parts.length === 4) {
        if (index < 0) return sendError(res, 404, '生产异常不存在');
        const exception = production.productionExceptions[index];
        const workOrder = production.workOrders.find((item) => item.code === exception.relatedWorkOrder) || null;
        return sendJson(res, 200, {
          record: exception,
          qualityTask: production.qualityTasks.find((item) => item.code === exception.source) || null,
          executionCard: production.executionCards.find((item) => item.code === exception.executionCardCode) || null,
          release: production.workOrderReleases.find((item) => item.code === exception.releaseBatchCode) || null,
          workOrder,
          task: productionExceptionSourceTask(production, exception),
          tasks: productionExceptionSourceTasks(production, exception),
          flowRecords: production.productionExceptionFlowRecords[exception.code] || [],
        });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const cardCode = String(body.executionCardCode || '').trim();
        const card = production.executionCards.find((item) => item.code === cardCode);
        if (!card) return sendError(res, 409, `生产流转批次 ${cardCode || '-'} 不存在`);
        const actor = String(body.actor || card.leader || '生产班长');
        const result = createProductionException(data, card, body);
        if (!result.repeated) {
          appendExecutionCardFlow(data, card.code, '登记生产异常', `${result.exception.code}：${result.exception.cause}；现场结论 ${result.exception.outcome}。`, actor);
          appendWorkOrderReleaseFlow(data, card.releaseBatchCode, '登记生产异常', `流转批次 ${card.code} 生成异常 ${result.exception.code}。`, actor);
          appendWorkOrderFlow(data, card.workOrderCode, '登记生产异常', `流转批次 ${card.code} 生成异常 ${result.exception.code}。`, actor);
          appendBusinessAuditLog(req, data, '登记生产异常', result.exception.code, `${card.code}：${result.exception.cause}；${result.exception.outcome}。`, {
            status: result.exception.outcome === '异常停机' ? '异常' : '正常',
          });
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.exception,
          executionCard: result.card,
          flowRecords: production.productionExceptionFlowRecords[result.exception.code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'resolve') {
        if (index < 0) return sendError(res, 404, '生产异常不存在');
        const body = await readBody(req);
        const actor = String(body.actor || production.productionExceptions[index].owner || '生产主管');
        const result = resolveProductionException(data, production.productionExceptions[index], body);
        if (!result.repeated) {
          appendExecutionCardFlow(data, result.card.code, '关闭生产异常', `${result.exception.code}：${result.exception.resolution}，恢复到 ${result.card.node}。`, actor);
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '关闭生产异常', `${result.exception.code} 已关闭，流转批次 ${result.card.code} 恢复执行。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, '关闭生产异常', `${result.exception.code} 已关闭。`, actor);
          appendBusinessAuditLog(req, data, '关闭生产异常', result.exception.code, `${result.exception.resolution}；流转批次 ${result.card.code} 恢复到 ${result.card.node}。`);
          await writeData(data);
        }
        return sendJson(res, 200, {
          ...result,
          record: result.exception,
          executionCard: result.card,
          flowRecords: production.productionExceptionFlowRecords[result.exception.code] || [],
        });
      }
    }

    if (parts[1] === 'production' && parts[2] === 'shifts') {
      const production = ensureProduction(data);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, { items: production.shiftHandovers });
      }

      if (req.method === 'POST' && parts[3] === 'handover') {
        const body = await readBody(req);
        const actor = String(body.actor || body.leader || '生产班长');
        const result = createShiftHandover(data, body);
        if (!result.repeated) {
          result.cards.forEach((card) => {
            appendExecutionCardFlow(data, card.code, '生产交班', `${result.handover.code}：${result.handover.fromShiftName}已交班，业务节点保持为 ${card.node}/${card.status}。`, actor);
          });
          appendBusinessAuditLog(req, data, '生产交班', result.handover.code, `${result.handover.fromShiftName}交班，承接 ${result.handover.activeCards.length} 个流转批次。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, result);
      }

      const code = decodeURIComponent(parts[3] || '');
      const index = production.shiftHandovers.findIndex((record) => record.code === code);
      if (req.method === 'POST' && code && parts[4] === 'receive') {
        if (index < 0) return sendError(res, 404, '交接班记录不存在');
        const body = await readBody(req);
        const actor = String(body.actor || body.leader || '生产班长');
        const result = receiveShiftHandover(data, production.shiftHandovers[index], body);
        if (!result.repeated) {
          result.cards.forEach((card) => {
            appendExecutionCardFlow(data, card.code, '生产接班', `${result.handover.code}：${result.handover.toShiftName}班长 ${result.handover.toLeader} 已接班，继续 ${card.node}/${card.status}。`, actor);
          });
          appendBusinessAuditLog(req, data, '生产接班', result.handover.code, `${result.handover.toShiftName}接班，承接 ${result.cards.length} 个流转批次。`);
          await writeData(data);
        }
        return sendJson(res, 200, result);
      }
    }

    if (parts[1] === 'quality' && parts[2] === 'production') {
      const production = ensureProduction(data);
      const code = decodeURIComponent(parts[3] || '');
      const index = production.qualityTasks.findIndex((record) => record.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, { items: production.qualityTasks });
      }

      if (req.method === 'GET' && code && parts.length === 4) {
        if (index < 0) return sendError(res, 404, '生产质检任务不存在');
        const task = production.qualityTasks[index];
        const executionCard = production.executionCards.find((item) => item.code === task.sourceCard) || null;
        return sendJson(res, 200, {
          record: task,
          decision: production.qualityDecisions[code] || null,
          dispositions: production.qualityDispositions[code] || [],
          reworkTasks: productionQualityReworkTasks(production, code),
          reinspectionTasks: productionQualityReinspectionTasks(production, code),
          executionCard: executionCard
            ? refreshExecutionCardProcessInstances(data, executionCard)
            : null,
          report: production.productionReports.find((item) => item.code === task.sourceReportCode) || null,
          wipBatch: production.wipBatches.find((item) => item.code === task.sourceWipBatchCode || item.sourceReportCode === task.sourceReportCode) || null,
          productionException: executionCard ? findProductionQualityException(production, task, executionCard) || null : null,
          flowRecords: production.executionCardFlowRecords[task.sourceCard] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'decision') {
        if (index < 0) return sendError(res, 404, '生产质检任务不存在');
        const body = await readBody(req);
        const actor = String(body.actor || production.qualityTasks[index].inspector || '质检员');
        const result = decideProductionQualityTask(data, production.qualityTasks[index], body);
        if (!result.repeated) {
          appendExecutionCardFlow(data, result.card.code, `${result.task.kind}判定`, `${result.task.code} 判定为${result.decision.result}；${result.card.nextAction}。`, actor);
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, `${result.task.kind}判定`, `质检任务 ${result.task.code} 判定为${result.decision.result}。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, `${result.task.kind}判定`, `流转批次 ${result.card.code}：${result.card.nextAction}。`, actor);
          appendBusinessAuditLog(req, data, '生产质检判定', code, `${result.task.kind}判定为${result.decision.result}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.task,
          executionCard: result.card,
          flowRecords: production.executionCardFlowRecords[result.card.code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'dispose') {
        if (index < 0) return sendError(res, 404, '生产质检任务不存在');
        const body = await readBody(req);
        const actor = String(body.actor || production.qualityTasks[index].inspector || '质检员');
        const result = createProductionQualityDisposition(data, production.qualityTasks[index], body);
        if (!result.repeated) {
          const actionLabel = result.disposition.action === 'rework_pass'
            ? '返工复检合格'
            : result.disposition.action === 'approve_concession'
              ? '让步审批放行'
              : '报废';
          appendExecutionCardFlow(data, result.card.code, '生产不合格处置', `${result.task.code}：${actionLabel} ${formatQty(result.disposition.quantity, result.disposition.unit)}；${result.card.nextAction}。`, actor);
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '生产不合格处置', `${result.task.code} 完成${actionLabel}，剩余待处置 ${formatQty(result.task.remainingDispositionQty, result.disposition.unit)}。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, '生产不合格处置', `流转批次 ${result.card.code}：${result.card.nextAction}。`, actor);
          appendBusinessAuditLog(req, data, '生产不合格处置', code, `${actionLabel} ${formatQty(result.disposition.quantity, result.disposition.unit)}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.task,
          executionCard: result.card,
          flowRecords: production.executionCardFlowRecords[result.card.code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'rework' && parts.length === 5) {
        if (index < 0) return sendError(res, 404, '生产质检任务不存在');
        const body = await readBody(req);
        const actor = String(body.actor || production.qualityTasks[index].inspector || '质检员');
        const result = createProductionReworkTask(data, production.qualityTasks[index], body);
        if (!result.repeated) {
          appendExecutionCardFlow(data, result.card.code, '创建返工任务', `${result.reworkTask.code} · ${formatQty(result.reworkTask.quantity, result.reworkTask.unit)} · 负责人 ${result.reworkTask.assignee}。`, actor);
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '创建返工任务', `${result.task.code} 已转返工 ${result.reworkTask.code}。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, '创建返工任务', `${result.card.code} 已安排返工，后续批次保持阻断。`, actor);
          appendBusinessAuditLog(req, data, '生产返工任务', result.reworkTask.code, `来源 ${code}，数量 ${formatQty(result.reworkTask.quantity, result.reworkTask.unit)}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.task,
          executionCard: result.card,
          dispositions: production.qualityDispositions[code] || [],
          reworkTasks: productionQualityReworkTasks(production, code),
          reinspectionTasks: productionQualityReinspectionTasks(production, code),
          flowRecords: production.executionCardFlowRecords[result.card.code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'rework' && parts[6] === 'complete') {
        if (index < 0) return sendError(res, 404, '生产质检任务不存在');
        const reworkCode = decodeURIComponent(parts[5] || '');
        const reworkTask = production.reworkTasks.find((item) => item.code === reworkCode && item.qualityTaskCode === code);
        if (!reworkTask) return sendError(res, 404, '返工任务不存在');
        const body = await readBody(req);
        const actor = String(body.actor || reworkTask.assignee || '生产人员');
        const result = completeProductionReworkTask(data, production.qualityTasks[index], reworkTask, body);
        if (!result.repeated) {
          appendExecutionCardFlow(data, result.card.code, '返工完成待复检', `${reworkTask.code} 已完成，生成复检任务 ${result.reinspectionTask.code}。`, actor);
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '返工完成待复检', `${reworkTask.code} 已转 ${result.reinspectionTask.code}。`, actor);
          appendBusinessAuditLog(req, data, '生产返工完成', reworkTask.code, `已生成复检任务 ${result.reinspectionTask.code}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.task,
          executionCard: result.card,
          dispositions: production.qualityDispositions[code] || [],
          reworkTasks: productionQualityReworkTasks(production, code),
          reinspectionTasks: productionQualityReinspectionTasks(production, code),
          flowRecords: production.executionCardFlowRecords[result.card.code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'reinspection' && parts[6] === 'decision') {
        if (index < 0) return sendError(res, 404, '生产质检任务不存在');
        const reinspectionCode = decodeURIComponent(parts[5] || '');
        const reinspectionTask = production.reinspectionTasks.find((item) => item.code === reinspectionCode && item.qualityTaskCode === code);
        if (!reinspectionTask) return sendError(res, 404, '返工复检任务不存在');
        const reworkTask = production.reworkTasks.find((item) => item.code === reinspectionTask.reworkTaskCode);
        if (!reworkTask) return sendError(res, 409, '复检任务关联的返工任务不存在');
        const body = await readBody(req);
        const actor = String(body.actor || reinspectionTask.inspector || '质检员');
        const result = decideProductionReinspectionTask(data, production.qualityTasks[index], reworkTask, reinspectionTask, body);
        if (!result.repeated) {
          appendExecutionCardFlow(data, result.card.code, '返工复检判定', `${reinspectionTask.code} 判定 ${reinspectionTask.result}；合格 ${formatQty(reinspectionTask.acceptedQty, reinspectionTask.unit)}，不合格 ${formatQty(reinspectionTask.rejectedQty, reinspectionTask.unit)}。`, actor);
          appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '返工复检判定', `${reinspectionTask.code} 已完成，${result.card.nextAction}。`, actor);
          appendWorkOrderFlow(data, result.card.workOrderCode, '返工复检判定', `${result.card.code} · ${result.card.nextAction}。`, actor);
          appendBusinessAuditLog(req, data, '生产返工复检', reinspectionTask.code, `结果 ${reinspectionTask.result}。`);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          record: result.task,
          executionCard: result.card,
          dispositions: production.qualityDispositions[code] || [],
          reworkTasks: productionQualityReworkTasks(production, code),
          reinspectionTasks: productionQualityReinspectionTasks(production, code),
          flowRecords: production.executionCardFlowRecords[result.card.code] || [],
        });
      }
    }

    if (parts[1] === 'quality' && parts[2] === 'standards') {
      const quality = ensureQuality(data);
      const code = decodeURIComponent(parts[3] || '');
      const index = quality.standards.findIndex((record) => record.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        const items = [...quality.standards].sort((left, right) => {
          if (left.status === '启用' && right.status !== '启用') return -1;
          if (right.status === '启用' && left.status !== '启用') return 1;
          return String(right.updatedAt || '').localeCompare(String(left.updatedAt || ''));
        });
        return sendJson(res, 200, { items });
      }

      if (req.method === 'GET' && code && parts.length === 4) {
        if (index < 0) return sendError(res, 404, '质检标准不存在');
        return sendJson(res, 200, { record: quality.standards[index] });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const idempotencyKey = String(body.idempotencyKey || '').trim();
        const repeated = idempotencyKey && quality.standardCommands.find((command) => command.idempotencyKey === idempotencyKey);
        if (repeated) {
          const record = quality.standards.find((item) => item.code === repeated.code);
          if (record) return sendJson(res, 200, { record, repeated: true });
        }
        const normalized = normalizeQualityStandardDraft(body);
        const familyCode = nextQualityStandardFamilyCode(quality);
        const { code: nextCode, version } = nextQualityStandardVersionCode(quality, familyCode);
        const actor = String(body.actor || normalized.owner || '质量部');
        const record = {
          ...normalized,
          code: nextCode,
          familyCode,
          version,
          revision: 1,
          status: '草稿',
          updatedAt: shanghaiDate(),
          updatedBy: actor,
          createdAt: shanghaiDateTime(),
        };
        quality.standards.unshift(record);
        if (idempotencyKey) quality.standardCommands.push({ idempotencyKey, action: 'create', code: record.code });
        appendBusinessAuditLog(req, data, '新建质检标准草稿', record.code, `${record.name} · V${record.version}`);
        await writeData(data);
        return sendJson(res, 201, { record, repeated: false });
      }

      if (req.method === 'PUT' && code && parts.length === 4) {
        if (index < 0) return sendError(res, 404, '质检标准不存在');
        const body = await readBody(req);
        const source = quality.standards[index];
        if (body.revision != null && Number(body.revision) !== Number(source.revision || 0)) {
          return sendError(res, 409, `质检标准 ${code} 已更新，请刷新后重新保存。`);
        }
        const normalized = normalizeQualityStandardDraft(body, source);
        const actor = String(body.actor || normalized.owner || '质量部');
        let record;
        let createdVersion = false;
        if (source.status === '草稿') {
          record = {
            ...source,
            ...normalized,
            status: '草稿',
            revision: Number(source.revision || 0) + 1,
            updatedAt: shanghaiDate(),
            updatedBy: actor,
          };
          quality.standards[index] = record;
        } else {
          const familyCode = source.familyCode || qualityStandardFamilyCode(source.code);
          const next = nextQualityStandardVersionCode(quality, familyCode);
          record = {
            ...source,
            ...normalized,
            code: next.code,
            familyCode,
            version: next.version,
            revision: 1,
            status: '草稿',
            createdAt: shanghaiDateTime(),
            updatedAt: shanghaiDate(),
            updatedBy: actor,
          };
          quality.standards.unshift(record);
          createdVersion = true;
        }
        appendBusinessAuditLog(req, data, createdVersion ? '建立质检标准新版本' : '保存质检标准草稿', record.code, `${record.name} · V${record.version}`);
        await writeData(data);
        return sendJson(res, createdVersion ? 201 : 200, { record, createdVersion });
      }

      if (req.method === 'POST' && code && ['activate', 'deactivate'].includes(parts[4])) {
        if (index < 0) return sendError(res, 404, '质检标准不存在');
        const body = await readBody(req);
        const record = quality.standards[index];
        if (body.revision != null && Number(body.revision) !== Number(record.revision || 0)) {
          return sendError(res, 409, `质检标准 ${code} 已更新，请刷新后重新操作。`);
        }
        const actor = String(body.actor || record.owner || '质量部');
        if (parts[4] === 'activate') {
          if (record.status === '启用') return sendJson(res, 200, { record, repeated: true });
          const familyCode = record.familyCode || qualityStandardFamilyCode(record.code);
          quality.standards.forEach((item) => {
            if (item.code !== record.code && (item.familyCode || qualityStandardFamilyCode(item.code)) === familyCode && item.status === '启用') {
              item.status = '停用';
              item.revision = Number(item.revision || 0) + 1;
              item.updatedAt = shanghaiDate();
              item.updatedBy = actor;
            }
          });
          record.status = '启用';
        } else {
          if (record.status !== '启用') return sendJson(res, 200, { record, repeated: true });
          record.status = '停用';
        }
        record.revision = Number(record.revision || 0) + 1;
        record.updatedAt = shanghaiDate();
        record.updatedBy = actor;
        appendBusinessAuditLog(req, data, parts[4] === 'activate' ? '启用质检标准' : '停用质检标准', record.code, `${record.name} · V${record.version}`);
        await writeData(data);
        return sendJson(res, 200, { record, repeated: false });
      }
    }

    if (parts[1] === 'quality' && qualityClosureConfig(parts[2])) {
      const kind = parts[2];
      const config = qualityClosureConfig(kind);
      const quality = ensureQuality(data);
      const rows = quality[config.collection];
      const code = decodeURIComponent(parts[3] || '');
      const index = rows.findIndex((record) => record.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, { items: rows });
      }

      if (req.method === 'GET' && code && parts.length === 4) {
        if (index < 0) return sendError(res, 404, `${config.label}不存在`);
        return sendJson(res, 200, qualityClosureResponse(data, rows[index]));
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const idempotencyKey = String(body.idempotencyKey || '').trim();
        if (!idempotencyKey) return sendError(res, 400, `新建${config.label}必须提供幂等键。`);
        const repeated = quality.closureCommands.find((command) => command.idempotencyKey === idempotencyKey);
        if (repeated) {
          if (repeated.kind !== kind || repeated.action !== 'create') {
            return sendError(res, 409, '该质量闭环幂等键已被其他动作使用。');
          }
          const repeatedRecord = rows.find((record) => record.code === repeated.code);
          if (repeatedRecord) return sendJson(res, 200, qualityClosureResponse(data, repeatedRecord));
        }
        const draft = cloneJson(body.draft, {});
        const nextCode = nextDocumentCode(data, config.ruleKey, rows, config.prefix);
        const actor = String(body.actor || draft.inspector || '质量负责人');
        const standardSnapshot = kind === 'patrol'
          ? frozenQualityStandardSnapshot(data, '质量巡检', draft.qualityStandardCode)
          : null;
        if (kind === 'patrol' && draft.qualityStandardCode && !standardSnapshot) {
          return sendError(res, 409, `巡检标准 ${draft.qualityStandardCode} 不存在或不属于质量巡检，请刷新后重试。`);
        }
        if (standardSnapshot) {
          draft.qualityStandardCode = standardSnapshot.code;
          draft.qualityStandardName = standardSnapshot.name;
          draft.standardVersionId = standardSnapshot.code;
          draft.qualityStandardSnapshot = standardSnapshot;
        }
        const record = {
          code: nextCode,
          kind,
          status: config.initialStatus,
          revision: 1,
          draft: { ...draft, code: nextCode, kind, status: config.initialStatus },
          attachments: Array.isArray(body.attachments) ? cloneJson(body.attachments, []) : [],
          updatedAt: shanghaiDateTime(),
          updatedBy: actor,
        };
        rows.unshift(record);
        quality.closureCommands.push({ idempotencyKey, kind, code: nextCode, action: 'create', revision: record.revision });
        appendQualityClosureFlow(data, nextCode, `新建${config.label}`, `${config.label}已建立，当前阶段为${record.status}。`, actor);
        appendBusinessAuditLog(req, data, `新建${config.label}`, nextCode, `${config.label}已建立。`);
        await writeData(data);
        return sendJson(res, 201, qualityClosureResponse(data, record));
      }

      if (req.method === 'PUT' && code && parts.length === 4) {
        if (index < 0) return sendError(res, 404, `${config.label}不存在`);
        const body = await readBody(req);
        const record = rows[index];
        const idempotencyKey = String(body.idempotencyKey || '').trim();
        if (!idempotencyKey) return sendError(res, 400, `保存${config.label}必须提供幂等键。`);
        const repeated = quality.closureCommands.find((command) => command.idempotencyKey === idempotencyKey);
        if (repeated) {
          if (repeated.kind !== kind || repeated.code !== code || repeated.action !== 'save') {
            return sendError(res, 409, '该质量闭环幂等键已被其他动作使用。');
          }
          return sendJson(res, 200, qualityClosureResponse(data, record));
        }
        if (Number(body.revision) !== Number(record.revision || 0)) {
          return sendError(res, 409, `${config.label} ${code} 已更新，请刷新后重新保存。`);
        }
        const actor = String(body.actor || body.draft?.inspector || '质量负责人');
        const draft = qualityClosureStageDraft(kind, record, body.draft);
        const updated = {
          ...record,
          draft: { ...draft, code, kind, status: record.status },
          attachments: Array.isArray(body.attachments) ? cloneJson(body.attachments, []) : record.attachments || [],
          revision: Number(record.revision || 0) + 1,
          updatedAt: shanghaiDateTime(),
          updatedBy: actor,
        };
        rows[index] = updated;
        quality.closureCommands.push({ idempotencyKey, kind, code, action: 'save', revision: updated.revision });
        appendQualityClosureFlow(data, code, `保存${config.label}`, '已保存当前说明、责任信息和附件元数据。', actor);
        appendBusinessAuditLog(req, data, `保存${config.label}`, code, '已保存闭环草稿。');
        await writeData(data);
        return sendJson(res, 200, qualityClosureResponse(data, updated));
      }

      if (req.method === 'POST' && code && parts[4] === 'transition') {
        if (index < 0) return sendError(res, 404, `${config.label}不存在`);
        const body = await readBody(req);
        const record = rows[index];
        const idempotencyKey = String(body.idempotencyKey || '').trim();
        if (!idempotencyKey) return sendError(res, 400, `推进${config.label}必须提供幂等键。`);
        const repeated = quality.closureCommands.find((command) => command.idempotencyKey === idempotencyKey);
        if (repeated) {
          if (repeated.kind !== kind || repeated.code !== code || repeated.action !== 'transition') {
            return sendError(res, 409, '该质量闭环幂等键已被其他动作使用。');
          }
          return sendJson(res, 200, qualityClosureResponse(data, record));
        }
        if (Number(body.revision) !== Number(record.revision || 0)) {
          return sendError(res, 409, `${config.label} ${code} 已更新，请刷新后重新提交。`);
        }
        const nextStatus = String(body.nextStatus || '').trim();
        const draft = qualityClosureStageDraft(kind, record, body.draft || record.draft || {});
        const action = String(body.action || `进入${nextStatus}`);
        validateQualityClosureTransition(kind, record, nextStatus, draft, action);
        const remark = String(body.remark || `${config.label}由${record.status}进入${nextStatus}。`);
        const actor = String(body.actor || draft.inspector || '质量负责人');
        const derivedDraft = { ...draft };
        if (kind === 'patrol' && record.status === '待巡检') {
          derivedDraft.qualityOutcome = nextStatus === '已关闭' ? '正常' : '异常';
          derivedDraft.disposition = nextStatus === '已关闭' ? '无异常关闭' : '现场整改';
        }
        if (kind === 'patrol' && record.status === '待复查') {
          derivedDraft.verificationResult = action === '升级不良' ? '未通过' : '通过';
          derivedDraft.closureResult = action === '升级不良' ? '已升级不良' : '整改通过';
        }
        if (kind === 'defects' && nextStatus === '待验证') derivedDraft.verificationResult = '待验证';
        if (kind === 'defects' && record.status === '待验证' && nextStatus === '处置中') {
          derivedDraft.verificationResult = '未通过';
        }
        if (kind === 'defects' && record.status === '待验证' && nextStatus === '已关闭') {
          derivedDraft.verificationResult = '通过';
          derivedDraft.closureResult = '验证通过';
        }
        const updated = {
          ...record,
          status: nextStatus,
          draft: { ...derivedDraft, code, kind, status: nextStatus },
          attachments: Array.isArray(body.attachments) ? cloneJson(body.attachments, []) : record.attachments || [],
          revision: Number(record.revision || 0) + 1,
          updatedAt: shanghaiDateTime(),
          updatedBy: actor,
        };
        if (kind === 'patrol' && record.status === '待复查' && action === '升级不良') {
          const linkedDefect = createDefectFromPatrol(data, record, derivedDraft, actor);
          if (!linkedDefect) return sendError(res, 409, '巡检异常无法建立关联不良记录，请刷新后重试。');
          updated.linkedDefectCode = linkedDefect.code;
          updated.draft.linkedDefectCode = linkedDefect.code;
        }
        rows[index] = updated;
        quality.closureCommands.push({ idempotencyKey, kind, code, action: 'transition', revision: updated.revision });
        appendQualityClosureFlow(data, code, action, remark, actor);
        appendBusinessAuditLog(req, data, `${config.label}${action}`, code, remark);
        await writeData(data);
        return sendJson(res, 200, qualityClosureResponse(data, updated));
      }
    }

    if (parts[1] === 'quality' && parts[2] === 'incoming') {
      const quality = ensureQuality(data);
      const warehouse = ensureWarehouse(data);
      const code = decodeURIComponent(parts[3] || '');
      const index = quality.incomingDocuments.findIndex((record) => record.code === code);

      if (req.method === 'GET' && parts.length === 3) {
        const sourceRows = [...quality.incomingDocuments];
        Object.values(quality.incomingDecisions).forEach((decision) => {
          if (!sourceRows.some((record) => record.code === decision.code)) sourceRows.push(decision);
        });
        return sendJson(res, 200, { items: sourceRows.map((record) => incomingQualityReadModel(data, record)) });
      }

      if (req.method === 'GET' && code) {
        const record = quality.incomingDocuments[index] || quality.incomingDecisions[code];
        if (!record) return sendError(res, 404, '来料质检单不存在');
        const receipt = warehouse.purchaseReceipts.find((row) => row.code === record.sourceDoc);
        const decision = quality.incomingDecisions[code] || null;
        (quality.incomingReinspections[code] || []).forEach((task) => {
          ensureIncomingReinspectionTaskUnit(receipt, task);
          ensureIncomingReinspectionTaskEvidence(data, decision, task);
        });
        return sendJson(res, 200, {
          record: incomingQualityReadModel(data, record),
          receipt,
          decision,
          dispositions: quality.incomingDispositions[code] || [],
          reinspections: quality.incomingReinspections[code] || [],
          returnDocuments: quality.incomingReturnDocuments.filter((item) => item.qualityCode === code),
          flowRecords: quality.incomingFlowRecords[code] || [],
        });
      }

      if (req.method === 'PUT' && code && parts.length === 4) {
        const body = await readBody(req);
        const existing = index >= 0 ? quality.incomingDocuments[index] : undefined;
        if (!existing) return sendError(res, 404, '来料质检任务必须由采购收货到货触发，不能脱离来源新建。');
        ensureIncomingQualityTaskSnapshot(data, existing);
        if (quality.incomingDecisions[code]) return sendError(res, 409, '来料质检单已形成正式数量决定，不能再覆盖草稿。');
        if (body.sourceDoc && String(body.sourceDoc) !== existing.sourceDoc) {
          return sendError(res, 409, '来料质检任务的来源收货单已冻结，不能替换。');
        }
        const record = {
          ...existing,
          code,
          sourceDoc: existing.sourceDoc,
          sourceType: existing.sourceType,
          qualityStandardCode: existing.qualityStandardCode,
          qualityStandardName: existing.qualityStandardName,
          standardVersionId: existing.standardVersionId,
          qualityStandardSnapshot: cloneJson(existing.qualityStandardSnapshot),
          products: normalizeIncomingQualityDraftProducts(existing, body.products),
          inspector: String(body.inspector || existing.inspector || '待分配'),
          conclusion: String(body.conclusion ?? existing.conclusion ?? ''),
          note: String(body.note ?? existing.note ?? ''),
          status: String(existing.status || '待检验'),
          version: Number(existing.version || 0),
          updatedAt: shanghaiDateTime(),
        };
        quality.incomingDocuments[index] = record;
        appendIncomingQualityFlow(data, code, '保存质检草稿', `已保存来源采购收货单 ${record.sourceDoc} 的质检草稿。`, body.actor);
        await writeData(data);
        return sendJson(res, 200, { record, flowRecords: quality.incomingFlowRecords[code] || [] });
      }

      if (req.method === 'POST' && code && parts[4] === 'decision') {
        const body = await readBody(req);
        const authenticatedActor = businessActorName(req, data);
        const commandBody = { ...body, actor: authenticatedActor };
        const existingDecision = quality.incomingDecisions[code];
        const idempotencyKey = String(commandBody.idempotencyKey || '');
        if (existingDecision) {
          if (idempotencyKey && existingDecision.idempotencyKey === idempotencyKey) {
            const receipt = warehouse.purchaseReceipts.find((row) => row.code === existingDecision.sourceDoc);
            return sendJson(res, 200, {
              record: quality.incomingDocuments.find((row) => row.code === code) || existingDecision,
              receipt,
              decision: existingDecision,
              inventory: warehouse.inventory,
              flowRecords: quality.incomingFlowRecords[code] || [],
            });
          }
          if (Number(existingDecision.totals?.pending || 0) <= 0) {
            return sendError(res, 409, '该来料质检单已完成全部数量判定，不能重复放行或重复隔离库存。');
          }
        }

        const draft = index >= 0 ? quality.incomingDocuments[index] : undefined;
        if (!draft) return sendError(res, 404, '来料质检任务必须由采购收货到货触发，不能脱离来源提交判定。');
        ensureIncomingQualityTaskSnapshot(data, draft);
        if (commandBody.sourceDoc && String(commandBody.sourceDoc) !== draft.sourceDoc) {
          return sendError(res, 409, '来料质检任务的来源收货单已冻结，不能替换。');
        }
        const sourceDoc = String(draft.sourceDoc || '').trim();
        const receiptIndex = warehouse.purchaseReceipts.findIndex((row) => row.code === sourceDoc);
        if (receiptIndex < 0) return sendError(res, 404, '关联采购收货单不存在');
        const receipt = warehouse.purchaseReceipts[receiptIndex];
        if (receipt.status !== '待质检' && receipt.stockStage !== 'qc_hold') {
          return sendError(res, 409, `采购收货单 ${sourceDoc} 当前状态为${receipt.status || '-'}，不能提交来料质检决定。`);
        }

        const decision = normalizeIncomingQualityDecision(data, code, receipt, commandBody, existingDecision, draft);
        applyIncomingQualityDecisionToInventory(data, receipt, decision, existingDecision);
        quality.incomingDecisionHistory[code] = [
          ...(quality.incomingDecisionHistory[code] || []),
          cloneJson(decision),
        ];
        quality.incomingDecisions[code] = decision;
        const record = {
          ...(draft || {}),
          code,
          sourceDoc,
          status: decision.status,
          conclusion: decision.conclusion,
          inspector: decision.actor,
          date: String(decision.decidedAt || '').slice(0, 10),
          standardVersionId: decision.standardVersionId,
          qualityStandardSnapshot: cloneJson(decision.qualityStandardSnapshot),
          qualityDecision: cloneJson(decision),
          products: (draft.products || []).map((product, productIndex) => {
            const lineId = incomingQualityLineIdentity(product, productIndex);
            const decisionLine = decision.lines.find((line) => line.receiptLineId === lineId);
            return decisionLine
              ? {
                  ...product,
                  sampleQty: decisionLine.sampleQty || product.sampleQty || '',
                  failedQty: decisionLine.sampleIssueQty || product.failedQty || '',
                  result: decisionLine.result,
                  inspectionItems: cloneJson(decisionLine.inspectionItems, []),
                }
              : product;
          }),
          version: decision.version,
          updatedAt: decision.decidedAt,
        };
        if (index >= 0) quality.incomingDocuments[index] = record;
        else quality.incomingDocuments.unshift(record);
        appendIncomingQualityFlow(
          data,
          code,
          '提交数量决定',
          `实收 ${decision.totals.received}，放行 ${decision.totals.released}，不合格 ${decision.totals.rejected}，待判 ${decision.totals.pending}。`,
          decision.actor,
        );
        appendReceiptFlow(data, receipt.code, '来料质检决定', `${code}：${decision.status}，放行 ${decision.totals.released}，不合格 ${decision.totals.rejected}。`, decision.actor);
        appendBusinessAuditLog(req, data, '提交来料质检决定', code, `关联 ${receipt.code}，版本 ${decision.version}。`);
        await writeData(data);
        return sendJson(res, 200, {
          record,
          receipt,
          decision,
          inventory: warehouse.inventory,
          flowRecords: quality.incomingFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'reinspections' && parts.length === 5) {
        const decision = quality.incomingDecisions[code];
        if (!decision) return sendError(res, 409, '来料质检尚未形成数量判定，不能建立复检任务。');
        const receipt = warehouse.purchaseReceipts.find((row) => row.code === decision.sourceDoc);
        if (!receipt) return sendError(res, 404, '关联采购收货单不存在');
        const body = await readBody(req);
        const authenticatedActor = businessActorName(req, data);
        const { task, repeated } = createIncomingQualityReinspection(
          data,
          code,
          receipt,
          decision,
          { ...body, actor: authenticatedActor },
        );
        if (!repeated) {
          appendIncomingQualityFlow(
            data,
            code,
            '建立来料复检',
            `${task.receiptLineId} 安排复检 ${task.quantity}${task.unit}，复检人 ${task.inspector}。`,
            task.actor,
          );
          appendReceiptFlow(data, receipt.code, '建立来料复检', `来料质检 ${code} 建立复检任务 ${task.code}。`, task.actor);
          appendBusinessAuditLog(req, data, '建立来料复检任务', task.code, `来源 ${code} / ${task.receiptLineId}。`);
          await writeData(data);
        }
        return sendJson(res, repeated ? 200 : 201, {
          record: quality.incomingDocuments.find((row) => row.code === code) || decision,
          receipt,
          decision,
          task,
          reinspections: quality.incomingReinspections[code] || [],
          dispositions: quality.incomingDispositions[code] || [],
          returnDocuments: quality.incomingReturnDocuments.filter((item) => item.qualityCode === code),
          inventory: warehouse.inventory,
          repeated,
          flowRecords: quality.incomingFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'reinspections' && parts[6] === 'decide') {
        const decision = quality.incomingDecisions[code];
        if (!decision) return sendError(res, 409, '来料质检尚未形成数量判定，不能提交复检结果。');
        const receipt = warehouse.purchaseReceipts.find((row) => row.code === decision.sourceDoc);
        if (!receipt) return sendError(res, 404, '关联采购收货单不存在');
        const taskCode = decodeURIComponent(parts[5] || '');
        const body = await readBody(req);
        const authenticatedActor = businessActorName(req, data);
        const { task, repeated } = completeIncomingQualityReinspection(
          data,
          code,
          receipt,
          decision,
          taskCode,
          { ...body, actor: authenticatedActor },
        );
        if (!repeated) {
          appendIncomingQualityFlow(
            data,
            code,
            '提交来料复检结果',
            `${task.code}：合格 ${task.acceptedQty}${task.unit}，不合格 ${task.rejectedQty}${task.unit}。`,
            task.decidedBy,
          );
          appendReceiptFlow(data, receipt.code, '来料复检结果', `${task.code} 结果为${task.result}。`, task.decidedBy);
          appendBusinessAuditLog(req, data, '提交来料复检结果', task.code, `结果 ${task.result}，来源 ${code}。`);
          await writeData(data);
        }
        return sendJson(res, 200, {
          record: quality.incomingDocuments.find((row) => row.code === code) || decision,
          receipt,
          decision,
          task,
          reinspections: quality.incomingReinspections[code] || [],
          dispositions: quality.incomingDispositions[code] || [],
          returnDocuments: quality.incomingReturnDocuments.filter((item) => item.qualityCode === code),
          inventory: warehouse.inventory,
          repeated,
          flowRecords: quality.incomingFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'dispose') {
        const decision = quality.incomingDecisions[code];
        if (!decision) return sendError(res, 409, '来料质检尚未形成数量判定，不能执行不合格处置。');
        const receipt = warehouse.purchaseReceipts.find((row) => row.code === decision.sourceDoc);
        if (!receipt) return sendError(res, 404, '关联采购收货单不存在');
        const body = await readBody(req);
        const authenticatedActor = businessActorName(req, data);
        const { disposition, returnDocument, repeated } = createIncomingQualityDisposition(
          data,
          code,
          receipt,
          decision,
          { ...body, actor: authenticatedActor },
        );
        if (!repeated) {
          const actionLabel = disposition.action === 'return_to_supplier' ? '转采购处理' : '让步审批放行';
          appendIncomingQualityFlow(
            data,
            code,
            actionLabel,
            `${disposition.receiptLineId} 处置 ${disposition.quantity}${disposition.unit}：${disposition.reason}`,
            disposition.actor,
          );
          appendReceiptFlow(
            data,
            receipt.code,
            actionLabel,
            `来料质检 ${code} 已处置 ${disposition.quantity}${disposition.unit}。`,
            disposition.actor,
          );
          appendBusinessAuditLog(
            req,
            data,
            '提交来料质检处置',
            code,
            `${actionLabel} ${disposition.quantity}${disposition.unit}，来源 ${receipt.code} / ${disposition.receiptLineId}。`,
          );
          await writeData(data);
        }
        return sendJson(res, repeated ? 200 : 201, {
          record: quality.incomingDocuments.find((row) => row.code === code) || decision,
          receipt,
          decision,
          disposition,
          dispositions: quality.incomingDispositions[code] || [],
          returnDocument: returnDocument || null,
          returnDocuments: quality.incomingReturnDocuments.filter((item) => item.qualityCode === code),
          reinspections: quality.incomingReinspections[code] || [],
          inventory: warehouse.inventory,
          repeated,
          flowRecords: quality.incomingFlowRecords[code] || [],
        });
      }
    }

    if (parts[1] === 'finance') {
      const finance = ensureFinance(data);
      const financeActor = accountAuditName(activeAccountForRequest(req, data));
      const financeStatusTarget =
        parts[2] === 'payables'
          ? { rows: finance.payables, group: 'payables', title: '应付账款' }
          : undefined;

      if (financeStatusTarget && req.method === 'POST' && parts[4] === 'status') {
        const code = decodeURIComponent(parts[3] || '');
        const index = financeStatusTarget.rows.findIndex((record) => record.code === code);
        if (index < 0) return sendError(res, 404, `${financeStatusTarget.title}不存在`);

        const body = await readBody(req);
        const actor = businessActorName(req, data);
        const status = String(body.status || '').trim();
        if (!status) return sendError(res, 400, '请提供目标状态');

        const action = String(body.action || '状态更新').trim();
        const remark = String(body.remark || body.reason || `${financeStatusTarget.title}状态更新为${status}`).trim();
        const existing = financeStatusTarget.rows[index];
        const currentStatus = financeStatusTarget.group === 'payables' ? existing.holdStatus || '正常' : existing.status;
        assertFinanceStatusTransition(financeStatusTarget.group, currentStatus, status);
        const record = {
          ...existing,
          ...(financeStatusTarget.group === 'payables'
            ? {
                holdStatus: status,
                holdReason: status === '已暂缓' ? remark : '',
                heldAt: status === '已暂缓' ? shanghaiDateTime() : '',
                heldBy: status === '已暂缓' ? financeActor : '',
              }
            : { status }),
        };
        financeStatusTarget.rows[index] = record;
        appendFinanceFlow(data, financeStatusTarget.group, code, action, remark, financeActor);
        appendBusinessAuditLog(req, data, `更新${financeStatusTarget.title}状态`, code, remark);
        if (financeStatusTarget.group === 'sales-invoices' || financeStatusTarget.group === 'receivables') {
          recomputeSalesOrderProgress(data, record.sourceOrder || record.sourceDoc);
        }
        await writeData(data);
        return sendJson(res, 200, {
          record,
          flowRecords:
            financeStatusTarget.group === 'payables'
              ? finance.payableFlowRecords[code] || []
              : financeStatusTarget.group === 'receivables'
                ? finance.receivableFlowRecords[code] || []
                : financeStatusTarget.group === 'sales-invoices'
                  ? finance.salesInvoiceFlowRecords[code] || []
                  : finance.invoiceFlowRecords[code] || [],
        });
      }

      if (parts[2] === 'sales-invoices') {
        if (req.method === 'GET' && parts[3] === 'availability') {
          const sourceOrder = String(url.searchParams.get('sourceOrder') || '').trim();
          const excludeInvoiceCode = String(url.searchParams.get('excludeInvoiceCode') || '').trim();
          if (!sourceOrder) return sendError(res, 400, '查询开票余量必须提供销售订单号。');
          const availability = salesInvoiceAllocationSummary(data, sourceOrder, excludeInvoiceCode);
          if (!availability.order) return sendError(res, 404, '销售订单不存在');
          return sendJson(res, 200, {
            sourceOrder,
            lines: availability.lines,
          });
        }

        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...finance.salesInvoices].sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`)),
          });
        }

        const code = decodeURIComponent(parts[3] || '');
        const index = finance.salesInvoices.findIndex((invoice) => invoice.code === code);

        if (req.method === 'GET' && code) {
          if (index < 0) return sendError(res, 404, '销售发票不存在');
          const reversal = finance.salesInvoiceReversals.find((item) => item.sourceInvoice === code) || null;
          return sendJson(res, 200, {
            record: finance.salesInvoices[index],
            reversal,
            redInvoice: reversal ? finance.salesRedInvoices.find((item) => item.code === reversal.redInvoiceCode) || null : null,
            refunds: finance.salesRefunds.filter((item) => item.sourceInvoice === code),
            flowRecords: finance.salesInvoiceFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts.length === 3) {
          const body = await readBody(req);
          const record = normalizeSalesInvoice(body, undefined, data);
          finance.salesInvoices.unshift(record);
          appendFinanceFlow(data, 'sales-invoices', record.code, '保存销售发票', '销售发票已保存为待开票。', financeActor);
          await writeData(data);
          return sendJson(res, 201, { record, flowRecords: finance.salesInvoiceFlowRecords[record.code] || [] });
        }

        if (req.method === 'PUT' && code) {
          if (index < 0) return sendError(res, 404, '销售发票不存在');
          const existing = finance.salesInvoices[index];
          assertDocumentEditable('销售发票', code, existing.status, salesInvoiceLockedStatuses);
          const body = await readBody(req);
          const record = normalizeSalesInvoice({ ...body, code }, existing, data);
          finance.salesInvoices[index] = record;
          appendFinanceFlow(data, 'sales-invoices', record.code, '保存销售发票', '销售发票内容已更新。', financeActor);
          await writeData(data);
          return sendJson(res, 200, { record, flowRecords: finance.salesInvoiceFlowRecords[record.code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'confirm') {
          if (index < 0) return sendError(res, 404, '销售发票不存在');
          const existing = finance.salesInvoices[index];
          if (financeInvoiceDocumentStatus(existing, 'sales') !== '待开票') {
            return sendError(res, 400, `销售发票 ${code} 当前单据状态为${financeInvoiceDocumentStatus(existing, 'sales') || '-'}，不能重复确认开票。`);
          }
          assertSalesInvoiceWithinOrder(data, existing);
          const record = { ...existing, status: '已开票', documentStatus: '已开票', settlementStatus: '未收款' };
          finance.salesInvoices[index] = record;
          appendFinanceFlow(data, 'sales-invoices', code, '确认开票', '销售发票已确认开具，系统生成应收账款。', financeActor);
          appendBusinessAuditLog(req, data, '确认销售发票', code, '销售发票已确认开具，系统生成应收账款。');
          appendBusinessNotification(data, {
            module: '财务',
            action: '发票确认',
            title: '销售发票已确认',
            message: `${code} 已确认开票，系统已生成应收账款。`,
            sourceDoc: code,
            sourcePath: `/finance/sales-invoices/${encodeURIComponent(code)}`,
            actor: financeActor,
          });

          const receivableIndex = finance.receivables.findIndex((receivable) => receivable.sourceDoc === code);
          const receivable = normalizeReceivableFromInvoice(
            record,
            receivableIndex >= 0 ? finance.receivables[receivableIndex] : undefined,
            data,
          );
          if (receivableIndex >= 0) {
            finance.receivables[receivableIndex] = receivable;
          } else {
            finance.receivables.unshift(receivable);
          }
          appendFinanceFlow(data, 'receivables', receivable.code, '生成应收账款', `由销售发票 ${code} 自动生成应收账款。`, financeActor);
          syncSalesOrderFromFinance(
            data,
            receivable.sourceOrder || record.sourceDoc || record.sourceOrder,
            '待收款',
            '财务确认开票',
            `${code} 已确认开票并生成应收账款 ${receivable.code}，销售订单进入待收款。`,
            financeActor,
          );

          await writeData(data);
          return sendJson(res, 200, {
            record,
            receivable,
            flowRecords: finance.salesInvoiceFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts[4] === 'reverse') {
          if (index < 0) return sendError(res, 404, '销售发票不存在');
          const body = await readBody(req);
          const record = finance.salesInvoices[index];
          const { reversal, redInvoice, refund, repeated } = reverseSalesInvoiceFact(data, record, body, financeActor);
          if (!repeated) {
            appendFinanceFlow(
              data,
              'sales-invoices',
              code,
              '销售发票红冲',
              `红字凭证 ${redInvoice.code} 已生效${refund ? `，生成退款义务 ${refund.code}` : ''}。`,
              reversal.actor,
            );
            appendBusinessAuditLog(
              req,
              data,
              '红冲销售发票',
              code,
              `红字凭证 ${redInvoice.code}${refund ? `，退款义务 ${refund.code}` : ''}。`,
            );
            recomputeSalesOrderProgress(data, record.sourceOrder || record.sourceDoc);
            await writeData(data);
          }
          return sendJson(res, repeated ? 200 : 201, {
            record,
            reversal,
            redInvoice,
            refund: refund || null,
            refunds: finance.salesRefunds.filter((item) => item.sourceInvoice === code),
            flowRecords: finance.salesInvoiceFlowRecords[code] || [],
            repeated,
          });
        }
      }

      if (parts[2] === 'sales-refunds') {
        const code = decodeURIComponent(parts[3] || '');
        const index = finance.salesRefunds.findIndex((item) => item.code === code);
        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, { items: finance.salesRefunds });
        }
        if (req.method === 'GET' && code && parts.length === 4) {
          if (index < 0) return sendError(res, 404, '销售退款义务不存在');
          return sendJson(res, 200, {
            refund: finance.salesRefunds[index],
            flowRecords: finance.salesRefundFlowRecords[code] || [],
          });
        }
        if (req.method === 'POST' && code && parts[4] === 'complete') {
          if (index < 0) return sendError(res, 404, '销售退款义务不存在');
          const body = await readBody(req);
          const { refund, repeated } = completeSalesRefundFact(data, finance.salesRefunds[index], body, financeActor);
          if (!repeated) {
            appendFinanceFlow(data, 'sales-invoices', refund.sourceInvoice, '完成销售退款', `${refund.code} 已退款 ${refund.amount}。`, refund.completedBy);
            appendBusinessAuditLog(req, data, '完成销售退款', refund.code, `来源销售发票 ${refund.sourceInvoice}，金额 ${refund.amount}。`);
            await writeData(data);
          }
          return sendJson(res, 200, {
            refund,
            flowRecords: finance.salesRefundFlowRecords[code] || [],
            repeated,
          });
        }
      }

      if (parts[2] === 'purchase-invoices') {
        if (req.method === 'GET' && parts[3] === 'matching') {
          const receiptCode = String(url.searchParams.get('sourceReceipt') || '').trim();
          const excludeInvoiceCode = String(url.searchParams.get('excludeInvoiceCode') || '').trim();
          return sendJson(res, 200, purchaseInvoiceMatchingSummary(data, receiptCode, excludeInvoiceCode));
        }

        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...finance.purchaseInvoices].sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`)),
          });
        }

        const code = decodeURIComponent(parts[3] || '');
        const index = finance.purchaseInvoices.findIndex((invoice) => invoice.code === code);

        if (req.method === 'GET' && code) {
          if (index < 0) return sendError(res, 404, '采购发票不存在');
          return sendJson(res, 200, {
            record: finance.purchaseInvoices[index],
            matching: purchaseInvoiceMatchingSummary(data, finance.purchaseInvoices[index].sourceDoc, code),
            flowRecords: finance.invoiceFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts.length === 3) {
          const body = await readBody(req);
          const record = normalizePurchaseInvoice(body, undefined, data);
          finance.purchaseInvoices.unshift(record);
          appendFinanceFlow(data, 'purchase-invoices', record.code, '保存采购发票', '采购发票已保存为待收票。', financeActor);
          await writeData(data);
          return sendJson(res, 201, {
            record,
            matching: purchaseInvoiceMatchingSummary(data, record.sourceDoc, record.code),
            flowRecords: finance.invoiceFlowRecords[record.code] || [],
          });
        }

        if (req.method === 'PUT' && code) {
          if (index < 0) return sendError(res, 404, '采购发票不存在');
          const existing = finance.purchaseInvoices[index];
          assertDocumentEditable('采购发票', code, existing.status, purchaseInvoiceLockedStatuses);
          const body = await readBody(req);
          const record = normalizePurchaseInvoice({ ...body, code }, existing, data);
          finance.purchaseInvoices[index] = record;
          appendFinanceFlow(data, 'purchase-invoices', record.code, '保存采购发票', '采购发票内容已更新。', financeActor);
          await writeData(data);
          return sendJson(res, 200, {
            record,
            matching: purchaseInvoiceMatchingSummary(data, record.sourceDoc, record.code),
            flowRecords: finance.invoiceFlowRecords[record.code] || [],
          });
        }

        if (req.method === 'POST' && parts[4] === 'confirm') {
          if (index < 0) return sendError(res, 404, '采购发票不存在');
          const existing = finance.purchaseInvoices[index];
          if (financeInvoiceDocumentStatus(existing, 'purchase') !== '待收票') {
            return sendError(res, 400, `采购发票 ${code} 当前单据状态为${financeInvoiceDocumentStatus(existing, 'purchase') || '-'}，不能重复确认收票。`);
          }
          const matching = assertPurchaseInvoiceMatch(data, existing);
          const record = { ...existing, status: '已收票', documentStatus: '已收票', settlementStatus: '未付款' };
          finance.purchaseInvoices[index] = record;
          appendFinanceFlow(data, 'purchase-invoices', code, '确认收票', '采购发票已确认，系统生成应付款。', financeActor);
          appendBusinessAuditLog(req, data, '确认采购发票', code, '采购发票已确认，系统生成应付款。');
          appendBusinessNotification(data, {
            module: '财务',
            action: '发票确认',
            title: '采购发票已确认',
            message: `${code} 已确认收票，系统已生成应付账款。`,
            sourceDoc: code,
            sourcePath: `/finance/purchase-invoices/${encodeURIComponent(code)}`,
            actor: financeActor,
          });

          const payableIndex = finance.payables.findIndex((payable) => payable.sourceDoc === code);
          const payable = normalizePayableFromInvoice(
            record,
            payableIndex >= 0 ? finance.payables[payableIndex] : undefined,
            data,
          );
          if (payableIndex >= 0) {
            finance.payables[payableIndex] = payable;
          } else {
            finance.payables.unshift(payable);
          }
          appendFinanceFlow(data, 'payables', payable.code, '生成应付款', `由采购发票 ${code} 自动生成应付账款。`, financeActor);

          await writeData(data);
          return sendJson(res, 200, {
            record,
            payable,
            matching,
            flowRecords: finance.invoiceFlowRecords[code] || [],
          });
        }
      }

      if (parts[2] === 'receivables') {
        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...finance.receivables].sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`)),
          });
        }

        const code = decodeURIComponent(parts[3] || '');
        const index = finance.receivables.findIndex((receivable) => receivable.code === code);

        if (req.method === 'GET' && code) {
          if (index < 0) return sendError(res, 404, '应收款不存在');
          const paymentRecords = finance.receivablePayments[code] || [];
          return sendJson(res, 200, {
            record: finance.receivables[index],
            payments: paymentRecords.map((payment, paymentIndex) => financeSettlementEventView(payment, '收款', code, paymentIndex)),
            flowRecords: finance.receivableFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts[4] === 'receive') {
          if (index < 0) return sendError(res, 404, '应收款不存在');
          const existing = finance.receivables[index];
          const body = await readBody(req);
          const idempotencyKey = String(body.idempotencyKey || '').trim();
          if (!idempotencyKey) {
            return sendError(res, 400, '登记收款必须提供幂等键，避免网络重试造成重复收款。');
          }
          const paymentRecords = finance.receivablePayments[code] || [];
          const existingPayment = paymentRecords.find((payment) => payment.idempotencyKey === idempotencyKey);
          if (existingPayment) {
            return sendJson(res, 200, {
              record: existing,
              payment: financeSettlementEventView(existingPayment, '收款', code, paymentRecords.indexOf(existingPayment)),
              payments: paymentRecords.map((payment, paymentIndex) => financeSettlementEventView(payment, '收款', code, paymentIndex)),
              idempotentReplay: true,
              flowRecords: finance.receivableFlowRecords[code] || [],
            });
          }
          if (!['待收款', '部分收款'].includes(existing.status)) {
            return sendError(res, 400, `应收款 ${code} 当前状态为${existing.status || '-'}，不能重复登记收款。`);
          }
          const settlement = financeSettlementPayload(body, '收款');
          const totalAmount = financeEffectiveTotal(existing);
          const currentSettled = parseMoney(existing.settledAmount);
          const remainingAmount = Math.max(0, totalAmount - currentSettled);
          const receivedAmount = body.amount == null || body.amount === '' ? remainingAmount : parseMoney(body.amount);
          if (!Number.isFinite(receivedAmount) || receivedAmount <= 0) {
            return sendError(res, 400, '本次收款金额必须大于 0。');
          }
          if (receivedAmount > remainingAmount + 0.01) {
            return sendError(res, 409, `本次收款金额超过剩余应收金额 ${money(remainingAmount)}。`);
          }
          const nextSettled = Math.min(totalAmount, currentSettled + receivedAmount);
          const receivable = {
            ...existing,
            status: nextSettled + 0.01 >= totalAmount ? '已收款' : '部分收款',
            settledAmount: money(nextSettled),
          };
          finance.receivables[index] = receivable;
          const createdAt = shanghaiDateTime();
          const payment = {
            code: nextDocumentCode(data, 'finance-receipts', Object.values(finance.receivablePayments).flat(), 'RCV2'),
            receivableCode: code,
            sourceInvoice: receivable.sourceDoc || '',
            sourceOrder: receivable.sourceOrder || '',
            idempotencyKey,
            direction: '收款',
            amount: money(receivedAmount),
            ...settlement,
            actor: financeActor,
            createdAt,
          };
          finance.receivablePayments[code] = [...paymentRecords, payment];
          appendFinanceFlow(data, 'receivables', code, '登记收款', `本次收款 ${money(receivedAmount)}，累计 ${money(nextSettled)}。`, financeActor);
          appendBusinessAuditLog(req, data, '登记收款', code, `本次收款 ${money(receivedAmount)}，累计 ${money(nextSettled)}，幂等键 ${idempotencyKey}。`);
          appendBusinessNotification(data, {
            module: '财务',
            action: '收付款登记',
            title: receivable.status === '已收款' ? '应收账款已收清' : '应收账款部分收款',
            message: `${code} 已登记收款 ${money(receivedAmount)}，当前状态为${receivable.status}。`,
            sourceDoc: code,
            sourcePath: `/finance/receivables/${encodeURIComponent(code)}`,
            actor: financeActor,
          });

          const invoiceIndex = finance.salesInvoices.findIndex((invoice) => invoice.code === receivable.sourceDoc);
          if (invoiceIndex >= 0) {
            const invoiceCode = finance.salesInvoices[invoiceIndex].code;
            const invoiceReceivables = finance.receivables.filter((record) => record.sourceDoc === invoiceCode && record.status !== '已作废');
            const invoiceSettled = invoiceReceivables.reduce((sum, record) => sum + parseMoney(record.settledAmount), 0);
            const invoiceTotal = parseMoney(finance.salesInvoices[invoiceIndex].totalAmount);
            finance.salesInvoices[invoiceIndex] = {
              ...finance.salesInvoices[invoiceIndex],
              status: financeInvoiceDocumentStatus(finance.salesInvoices[invoiceIndex], 'sales'),
              documentStatus: financeInvoiceDocumentStatus(finance.salesInvoices[invoiceIndex], 'sales'),
              settlementStatus: invoiceSettled + 0.01 >= invoiceTotal ? '已收款' : invoiceSettled > 0 ? '部分收款' : '未收款',
              settledAmount: money(Math.min(invoiceSettled, invoiceTotal)),
            };
            appendFinanceFlow(data, 'sales-invoices', receivable.sourceDoc, '收款进度更新', `${code} 本次收款 ${money(receivedAmount)}，发票累计收款 ${money(invoiceSettled)}。`);
          }
          syncSalesOrderFromFinance(
            data,
            receivable.sourceOrder || finance.salesInvoices[invoiceIndex]?.sourceOrder || finance.salesInvoices[invoiceIndex]?.sourceDoc,
            receivable.status,
            '收款进度更新',
            `${code} 本次收款 ${money(receivedAmount)}；销售订单仅更新收款进度，不自动关闭。`,
            financeActor,
          );

          await writeData(data);
          return sendJson(res, 200, {
            record: receivable,
            payment: financeSettlementEventView(payment, '收款', code, paymentRecords.length),
            payments: finance.receivablePayments[code].map((item, paymentIndex) => financeSettlementEventView(item, '收款', code, paymentIndex)),
            flowRecords: finance.receivableFlowRecords[code] || [],
          });
        }
      }

      if (parts[2] === 'payables') {
        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...finance.payables].sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`)),
          });
        }

        const code = decodeURIComponent(parts[3] || '');
        const index = finance.payables.findIndex((payable) => payable.code === code);

        if (req.method === 'GET' && code) {
          if (index < 0) return sendError(res, 404, '应付款不存在');
          const paymentRecords = finance.payablePayments[code] || [];
          return sendJson(res, 200, {
            record: finance.payables[index],
            payments: paymentRecords.map((payment, paymentIndex) => financeSettlementEventView(payment, '付款', code, paymentIndex)),
            flowRecords: finance.payableFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts[4] === 'pay') {
          if (index < 0) return sendError(res, 404, '应付款不存在');
          const existing = finance.payables[index];
          const body = await readBody(req);
          const idempotencyKey = String(body.idempotencyKey || '').trim();
          if (!idempotencyKey) {
            return sendError(res, 400, '登记付款必须提供幂等键，避免网络重试造成重复付款。');
          }
          const paymentRecords = finance.payablePayments[code] || [];
          const existingPayment = paymentRecords.find((payment) => payment.idempotencyKey === idempotencyKey);
          if (existingPayment) {
            return sendJson(res, 200, {
              record: existing,
              payment: financeSettlementEventView(existingPayment, '付款', code, paymentRecords.indexOf(existingPayment)),
              payments: paymentRecords.map((payment, paymentIndex) => financeSettlementEventView(payment, '付款', code, paymentIndex)),
              idempotentReplay: true,
              flowRecords: finance.payableFlowRecords[code] || [],
            });
          }
          if (!['待付款', '部分付款'].includes(existing.status)) {
            return sendError(res, 400, `应付款 ${code} 当前状态为${existing.status || '-'}，不能登记付款。`);
          }
          if (existing.holdStatus === '已暂缓') {
            return sendError(res, 409, `应付款 ${code} 已暂缓，需先处理暂缓原因并恢复付款。`);
          }
          const settlement = financeSettlementPayload(body, '付款');
          const totalAmount = financeEffectiveTotal(existing);
          const currentSettled = parseMoney(existing.settledAmount);
          const remainingAmount = Math.max(0, totalAmount - currentSettled);
          const paidAmount = body.amount == null || body.amount === '' ? remainingAmount : parseMoney(body.amount);
          if (!Number.isFinite(paidAmount) || paidAmount <= 0) return sendError(res, 400, '本次付款金额必须大于 0。');
          if (paidAmount > remainingAmount + 0.01) {
            return sendError(res, 409, `本次付款金额超过剩余应付金额 ${money(remainingAmount)}。`);
          }
          const nextSettled = Math.min(totalAmount, currentSettled + paidAmount);
          const payable = {
            ...existing,
            status: nextSettled + 0.01 >= totalAmount ? '已付款' : '部分付款',
            settledAmount: money(nextSettled),
          };
          finance.payables[index] = payable;
          const createdAt = shanghaiDateTime();
          const payment = {
            code: nextDocumentCode(data, 'finance-payments', Object.values(finance.payablePayments).flat(), 'PAY2'),
            payableCode: code,
            sourceInvoice: payable.sourceDoc || '',
            sourceOrder: payable.sourceOrder || '',
            direction: '付款',
            amount: money(paidAmount),
            ...settlement,
            actor: financeActor,
            idempotencyKey,
            createdAt,
          };
          finance.payablePayments[code] = [...paymentRecords, payment];
          appendFinanceFlow(data, 'payables', code, '登记付款', `本次付款 ${money(paidAmount)}，累计 ${money(nextSettled)}。`, financeActor);
          appendBusinessAuditLog(req, data, '登记付款', code, `本次付款 ${money(paidAmount)}，累计 ${money(nextSettled)}，幂等键 ${idempotencyKey}。`);
          appendBusinessNotification(data, {
            module: '财务',
            action: '收付款登记',
            title: payable.status === '已付款' ? '应付账款已付清' : '应付账款部分付款',
            message: `${code} 已登记付款 ${money(paidAmount)}，当前状态为${payable.status}。`,
            sourceDoc: code,
            sourcePath: `/finance/payables/${encodeURIComponent(code)}`,
            actor: financeActor,
          });

          const invoiceIndex = finance.purchaseInvoices.findIndex((invoice) => invoice.code === payable.sourceDoc);
          if (invoiceIndex >= 0) {
            const invoiceCode = finance.purchaseInvoices[invoiceIndex].code;
            const invoicePayables = finance.payables.filter((record) => record.sourceDoc === invoiceCode && record.status !== '已作废');
            const invoiceSettled = invoicePayables.reduce((sum, record) => sum + parseMoney(record.settledAmount), 0);
            const invoiceTotal = parseMoney(finance.purchaseInvoices[invoiceIndex].totalAmount);
            finance.purchaseInvoices[invoiceIndex] = {
              ...finance.purchaseInvoices[invoiceIndex],
              status: financeInvoiceDocumentStatus(finance.purchaseInvoices[invoiceIndex], 'purchase'),
              documentStatus: financeInvoiceDocumentStatus(finance.purchaseInvoices[invoiceIndex], 'purchase'),
              settlementStatus: invoiceSettled + 0.01 >= invoiceTotal ? '已付款' : invoiceSettled > 0 ? '部分付款' : '未付款',
              settledAmount: money(Math.min(invoiceSettled, invoiceTotal)),
            };
            appendFinanceFlow(data, 'purchase-invoices', payable.sourceDoc, '付款进度更新', `${code} 本次付款 ${money(paidAmount)}，发票累计付款 ${money(invoiceSettled)}。`);
          }

          await writeData(data);
          return sendJson(res, 200, {
            record: payable,
            payment: financeSettlementEventView(payment, '付款', code, paymentRecords.length),
            payments: finance.payablePayments[code].map((item, paymentIndex) => financeSettlementEventView(item, '付款', code, paymentIndex)),
            flowRecords: finance.payableFlowRecords[code] || [],
          });
        }
      }
    }

    if (parts[1] === 'system') {
      const system = ensureSystem(data);
      const actor = activeAccountForRequest(req, data);
      const page = parts[2];
      if (!systemApiPages.has(page)) return sendError(res, 404, '系统配置页不存在');
      const rows = system[page];
      if (!Array.isArray(rows)) return sendError(res, 404, '系统配置页不存在');

      if (req.method === 'GET' && parts.length === 3) {
        if (page === 'menus') {
          const visibleRows = menuRowsForRequest(data, rows, actor);
          return sendJson(res, 200, {
            items: sanitizeSystemRows(page, [...visibleRows].sort((a, b) => Number(a.sortOrder || 0) - Number(b.sortOrder || 0))),
          });
        }
        return sendJson(res, 200, {
          items: sanitizeSystemRows(
            page,
            [...rows].sort(compareUpdatedRows),
          ),
        });
      }

      if (readOnlySystemPages.has(page) && req.method !== 'GET') {
        return sendError(res, 405, '系统日志只读，不能手动新建或修改。');
      }

      if (req.method === 'POST' && parts.length === 3 && !readOnlySystemPages.has(page)) {
        if (nonCreatableSystemPages.has(page)) {
          return sendError(
            res,
            405,
            systemCreateBlockedMessages[page] || `${systemPageLogLabel(page)}由当前系统生成，不能手动新建。`,
          );
        }
        const body = await readBody(req);
        const record = normalizeSystemRecord(page, body, undefined, rows, data);
        const liveRows = Array.isArray(system[page]) ? system[page] : rows;
        if (liveRows.some((row) => row.code === record.code)) {
          return sendError(res, 400, `${systemPageLogLabel(page)}编码 ${record.code} 已存在，不能重复新建。`);
        }
        liveRows.unshift(record);
        appendSystemLog(system, `新建${systemPageLogLabel(page)}`, record.code, `${record.name} 已创建。`, {
          owner: accountAuditName(actor),
          sourceAccount: actor?.code || '',
          sourceIp: requestSourceIp(req),
        });
        await writeData(data);
        return sendJson(res, 201, { record: sanitizeSystemRecord(page, record), items: sanitizeSystemRows(page, liveRows) });
      }

      const code = decodeURIComponent(parts[3] || '');
      const index = rows.findIndex((record) => record.code === code);

      if (page === 'apps' && req.method === 'POST' && code && parts[4] === 'check-health') {
        if (index < 0) return sendError(res, 404, '应用不存在');
        const existingRecord = rows[index];
        if (existingRecord.status === '停用') return sendError(res, 400, '停用应用不能执行健康检查。');
        const missingFields = appRequiredMissingFields(existingRecord);
        if (missingFields.length) {
          return sendError(res, 400, `应用配置不完整，不能执行健康检查：缺少${missingFields.join('、')}。`);
        }
        const result = await checkAppHealth(existingRecord, req);
        const record = {
          ...existingRecord,
          ...result,
          lastVerifiedAt: result.healthCheckedAt,
          updatedAt: shanghaiDateTime(),
        };
        rows[index] = record;
        appendSystemLog(system, '应用健康检查', record.code, `${record.name}：${result.healthStatus}，${result.healthMessage}`, {
          owner: accountAuditName(actor),
          sourceAccount: actor?.code || '',
          sourceIp: requestSourceIp(req),
        });
        await writeData(data);
        return sendJson(res, 200, {
          record: sanitizeSystemRecord(page, record),
          result,
        });
      }

      if (page === 'mcp-tools' && req.method === 'POST' && code && parts[4] === 'verify') {
        if (index < 0) return sendError(res, 404, 'MCP 工具不存在');
        const existingRecord = rows[index];
        if (existingRecord.status === '停用') {
          return sendError(res, 400, '停用工具不能记录验证。');
        }
        const missingFields = mcpToolRequiredMissingFields(existingRecord);
        if (missingFields.length) {
          return sendError(res, 400, `工具配置不完整，不能记录验证：缺少${missingFields.join('、')}。`);
        }
        const body = await readBody(req);
        const verificationRemark = String(body.verificationRemark || '').trim().slice(0, 500);
        if (existingRecord.riskLevel === '高' && !verificationRemark) {
          return sendError(res, 400, '高风险工具记录验证时必须填写本次验证备注。');
        }
        const verifiedAt = shanghaiDateTime();
        const record = {
          ...existingRecord,
          lastVerifiedAt: verifiedAt,
          lastVerificationRemark: verificationRemark,
          updatedAt: shanghaiDateTime(),
        };
        rows[index] = record;
        appendSystemLog(system, 'MCP 工具验证', record.code, `${record.name} 已按验证方式记录为已验证。${verificationRemark ? `备注：${verificationRemark}` : ''}`, {
          owner: accountAuditName(actor),
          sourceAccount: actor?.code || '',
          sourceIp: requestSourceIp(req),
        });
        await writeData(data);
        return sendJson(res, 200, { record: sanitizeSystemRecord(page, record) });
      }

      if (req.method === 'PUT' && code && page !== 'logs') {
        if (index < 0) return sendError(res, 404, '系统配置记录不存在');
        const body = await readBody(req);
        const existingRecord = rows[index];
        const record = normalizeSystemRecord(page, { ...body, code }, rows[index], rows, data);
        const isPasswordUpdate = page === 'accounts' && Boolean(body.passwordInput || body.passwordConfirm);
        assertActorKeepsSystemConfig(data, page, record, index, actor);
        if (['accounts', 'roles', 'permissions'].includes(page)) {
          assertEquipmentInspectionResponsibilityContinuity(
            data,
            dataWithProposedSystemRecord(data, page, record, index),
          );
        }
        const liveRows = Array.isArray(system[page]) ? system[page] : rows;
        const liveIndex = liveRows.findIndex((row) => row.code === record.code);
        if (liveIndex < 0) return sendError(res, 404, '系统配置记录不存在');
        liveRows[liveIndex] = record;
        const accountSessionsCleared =
          page === 'accounts' && (isPasswordUpdate || (existingRecord.status !== '停用' && record.status === '停用'))
            ? clearSessionsForAccount(data, record.code)
            : 0;
        const changeSummary = systemConfigChangeSummary(page, existingRecord, record);
        appendSystemLog(
          system,
          isPasswordUpdate ? '更新账号密码' : `更新${systemPageLogLabel(page)}`,
          record.code,
          `${record.name} 已更新为 ${record.status}。${changeSummary}。${isPasswordUpdate ? '密码已更新。' : ''}${accountSessionsCleared ? `已清理 ${accountSessionsCleared} 个旧会话。` : ''}`,
          {
            owner: accountAuditName(actor),
            sourceAccount: actor?.code || '',
            sourceIp: requestSourceIp(req),
          },
        );
        await writeData(data);
        return sendJson(res, 200, { record: sanitizeSystemRecord(page, record), items: sanitizeSystemRows(page, liveRows) });
      }
    }

    if (parts[1] === 'warehouse') {
      const warehouse = ensureWarehouse(data);

      if (req.method === 'GET' && parts[2] === 'inventory') {
        return sendJson(res, 200, {
          items: warehouse.inventory
            .filter(inventoryFactHasOutstandingQuantity)
            .map((row) => {
              const eligibility = productionIssueInventoryEligibility(data, row);
              return {
                ...row,
                warehouseStatus: eligibility.warehouse.status || '',
                allowProductionIssue: eligibility.warehouse.allowProductionIssue === true,
                stocktakeFrozen: eligibility.reason === '盘点冻结',
                stocktakeCode: eligibility.stocktake?.sourceDoc || '',
              };
            })
            .sort((a, b) => `${b.updatedAt || ''}${b.item || ''}`.localeCompare(`${a.updatedAt || ''}${a.item || ''}`)),
        });
      }

      if (req.method === 'GET' && parts[2] === 'replenishments') {
        const signals = warehouseReplenishmentSignals(data);
        const notificationCountBefore = ensureSystem(data).notificationInbox.length;
        signals.filter((signal) => signal.actionRequired).forEach((signal) => {
          appendBusinessNotification(data, {
            module: '仓库',
            action: '库存预警',
            title: `${signal.warehouseName} · ${signal.materialName}${signal.thresholdStatus}`,
            message: `${signal.message}，建议补货 ${formatQty(signal.suggestedQty, signal.uom)}。`,
            sourceDoc: `${signal.code}:${signal.thresholdStatus}`,
            sourcePath: signal.sourcePath,
            actor: '库存预警',
          });
        });
        if (ensureSystem(data).notificationInbox.length !== notificationCountBefore) await writeData(data);
        return sendJson(res, 200, { items: signals });
      }

      if (req.method === 'POST' && parts[2] === 'replenishments' && parts[4] === 'replenish') {
        const relationCode = decodeURIComponent(parts[3] || '');
        const body = await readBody(req);
        const actor = businessActorName(req, data);
        const result = startWarehouseReplenishment(data, relationCode, String(body.routeType || '').trim(), actor);
        if (!result.repeated) {
          appendBusinessAuditLog(
            req,
            data,
            '发起库存补货',
            relationCode,
            `${result.document.type} ${result.document.code} 已由库存预警生成。`,
          );
          appendBusinessNotification(data, {
            module: result.document.type === '采购申请' ? '采购' : '生产',
            action: result.document.type === '采购申请' ? '采购申请生成' : '补货任务生成',
            title: result.document.type === '采购申请' ? '仓库补货采购申请待受理' : '安全库存生产任务待确认',
            message: `${result.document.code} 已由 ${result.signal.warehouseName} / ${result.signal.materialName} 库存预警生成，建议补货 ${formatQty(result.signal.suggestedQty, result.signal.uom)}。`,
            sourceDoc: result.document.code,
            sourcePath: result.document.path,
            actor,
          });
          await writeData(data);
        }
        const updatedSignal = warehouseReplenishmentSignals(data).find((row) => row.code === relationCode) || result.signal;
        return sendJson(res, result.repeated ? 200 : 201, {
          signal: updatedSignal,
          document: result.document,
          repeated: result.repeated,
        });
      }

      if (req.method === 'GET' && parts[2] === 'stock-ledger') {
        return sendJson(res, 200, {
          items: [...warehouse.stockLedger].sort((a, b) => `${b.time || ''}${b.sourceDoc || ''}`.localeCompare(`${a.time || ''}${a.sourceDoc || ''}`)),
        });
      }

      if (req.method === 'GET' && parts[2] === 'reversals') {
        return sendJson(res, 200, {
          items: [...warehouse.reversals].sort((a, b) => `${b.createdAt || ''}${b.code}`.localeCompare(`${a.createdAt || ''}${a.code}`)),
        });
      }

      const reversibleWarehouseResources = new Set([
        'purchase-receipts',
        'sales-issues',
        'other-moves',
        'transfers',
        'stocktakes',
      ]);
      if (req.method === 'POST' && parts[4] === 'reverse' && reversibleWarehouseResources.has(parts[2])) {
        const code = decodeURIComponent(parts[3] || '');
        const body = await readBody(req);
        const result = applyWarehouseReversal(data, parts[2], code, body, businessActorName(req, data));
        if (!result.repeated) {
          appendBusinessAuditLog(req, data, '库存冲销', code, `${result.reversal.code}：${result.reversal.reason}`);
          const notificationSource = parts[2] === 'purchase-receipts' && result.record.sourceDoc
            ? {
                sourceDoc: result.record.sourceDoc,
                sourcePath: `/purchase/orders/${encodeURIComponent(result.record.sourceDoc)}/follow-up`,
              }
            : parts[2] === 'sales-issues' && result.record.sourceOrder
              ? {
                  sourceDoc: result.record.sourceOrder,
                  sourcePath: `/sales/orders/${encodeURIComponent(result.record.sourceOrder)}/delivery`,
                }
              : {
                  sourceDoc: code,
                  sourcePath: result.reversal.sourcePath,
                };
          appendBusinessNotification(data, {
            module: '仓库',
            action: '库存冲销',
            targetRoles: parts[2] === 'purchase-receipts'
              ? 'ROLE-PURCHASE'
              : parts[2] === 'sales-issues'
                ? 'ROLE-SALES'
                : 'ROLE-WAREHOUSE',
            title: '库存冲销已完成',
            message: `${result.reversal.code} 已冲销 ${code} 的库存影响，原单和原流水保持不变。`,
            ...notificationSource,
            actor: result.reversal.actor,
          });
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          inventory: warehouse.inventory,
          stockLedger: warehouse.stockLedger,
        });
      }

      if (parts[2] === 'production-issues') {
        const production = ensureProduction(data);
        const code = decodeURIComponent(parts[3] || '');
        const index = warehouse.productionIssues.findIndex((record) => record.code === code);

        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...warehouse.productionIssues].sort((a, b) => `${b.updatedAt || ''}${b.code}`.localeCompare(`${a.updatedAt || ''}${a.code}`)),
          });
        }

        if (req.method === 'GET' && code === 'source' && parts.length === 4) {
          const releaseCode = String(url.searchParams.get('releaseBatch') || '').trim();
          const release = productionReleaseForIssue(data, releaseCode);
          if (!release) return sendError(res, 404, `释放批次 ${releaseCode || '-'} 不存在。`);
          const persistedIssue = warehouse.productionIssues.find((item) => (
            item.releaseBatch === release.code
            && !['已作废', '已取消'].includes(String(item.status || ''))
          ));
          if (persistedIssue) {
            return sendJson(res, 200, {
              issue: persistedIssue,
              release,
              workOrder: production.workOrders.find((item) => item.code === release.workOrderCode) || null,
              autoGenerated: true,
            });
          }
          const preview = normalizeProductionIssue(data, { releaseBatch: release.code }, undefined);
          return sendJson(res, 200, {
            issue: {
              ...preview,
              code: '系统自动生成',
              owner: '',
              note: '',
              revision: 0,
              createdAt: '',
              updatedAt: '',
            },
            release,
            workOrder: production.workOrders.find((item) => item.code === release.workOrderCode) || null,
          });
        }

        if (req.method === 'GET' && code && parts.length === 4) {
          if (index < 0) return sendError(res, 404, '生产领料单不存在');
          const issue = warehouse.productionIssues[index];
          return sendJson(res, 200, {
            issue,
            release: productionReleaseForIssue(data, issue.releaseBatch),
            executionCard: production.executionCards.find((item) => item.code === issue.executionCard) || null,
            flowRecords: warehouse.productionIssueFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts.length === 3) {
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const issue = normalizeProductionIssue(data, body, undefined);
          warehouse.productionIssues.unshift(issue);
          appendProductionIssueFlow(data, issue.code, '创建领料草稿', `承接释放批次 ${issue.releaseBatch}，等待提交出库。`, actor);
          appendBusinessAuditLog(req, data, '创建生产领料单', issue.code, `来源释放批次 ${issue.releaseBatch}。`);
          await writeData(data);
          return sendJson(res, 201, {
            issue,
            release: productionReleaseForIssue(data, issue.releaseBatch),
            flowRecords: warehouse.productionIssueFlowRecords[issue.code] || [],
          });
        }

        if (req.method === 'PUT' && code && parts.length === 4) {
          if (index < 0) return sendError(res, 404, '生产领料单不存在');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const issue = normalizeProductionIssue(data, { ...body, code }, warehouse.productionIssues[index]);
          warehouse.productionIssues[index] = issue;
          appendProductionIssueFlow(data, issue.code, '保存领料草稿', `领料单修订为第 ${issue.revision} 版。`, actor);
          appendBusinessAuditLog(req, data, '更新生产领料单', issue.code, `修订 ${issue.revision}。`);
          await writeData(data);
          return sendJson(res, 200, {
            issue,
            release: productionReleaseForIssue(data, issue.releaseBatch),
            flowRecords: warehouse.productionIssueFlowRecords[issue.code] || [],
          });
        }

        if (req.method === 'POST' && code && parts[4] === 'submit') {
          if (index < 0) return sendError(res, 404, '生产领料单不存在');
          const actor = businessActorName(req, data);
          const issue = warehouse.productionIssues[index];
          if (issue.status !== '草稿') return sendError(res, 409, `生产领料单 ${code} 当前状态为${issue.status}，不能重复提交。`);
          const release = productionReleaseForIssue(data, issue.releaseBatch);
          if (!release || release.releaseStatus !== '已释放' || release.materialStatus === '已领料') {
            return sendError(res, 409, `释放批次 ${issue.releaseBatch} 当前不能办理领料。`);
          }
          issue.status = '待出库';
          issue.submittedBy = actor;
          issue.revision = Number(issue.revision || 0) + 1;
          issue.updatedAt = shanghaiDateTime();
          appendProductionIssueFlow(data, code, '提交领料出库', `释放批次 ${issue.releaseBatch} 等待仓库过账。`, actor);
          appendWorkOrderReleaseFlow(data, release.code, '领料单已提交', `生产领料单 ${issue.code} 等待仓库出库。`, actor);
          appendBusinessAuditLog(req, data, '提交生产领料单', code, `来源释放批次 ${issue.releaseBatch}。`);
          await writeData(data);
          return sendJson(res, 200, {
            issue,
            release,
            flowRecords: warehouse.productionIssueFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && code && parts[4] === 'post') {
          if (index < 0) return sendError(res, 404, '生产领料单不存在');
          const issue = warehouse.productionIssues[index];
          const release = productionReleaseForIssue(data, issue.releaseBatch);
          if (!release) return sendError(res, 404, '关联释放批次不存在');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const { executionCard, repeated } = postProductionIssueToStock(
            data,
            issue,
            release,
            String(body.idempotencyKey || ''),
            actor,
          );
          if (!repeated) {
            appendProductionIssueFlow(data, code, '生产领料过账', `物料分配已消耗，生成流转批次 ${executionCard.code}。`, actor);
            appendWorkOrderReleaseFlow(data, release.code, '生产领料完成', `领料单 ${issue.code} 已过账，生成流转批次 ${executionCard.code}。`, actor);
            appendWorkOrderFlow(data, release.workOrderCode, '生产领料完成', `释放批次 ${release.code} 已生成流转批次 ${executionCard.code}。`, actor);
            appendBusinessAuditLog(req, data, '生产领料过账', issue.code, `释放批次 ${release.code}，流转批次 ${executionCard.code}。`);
            await writeData(data);
          }
          return sendJson(res, repeated ? 200 : 201, {
            issue,
            release,
            workOrder: production.workOrders.find((item) => item.code === release.workOrderCode),
            executionCard,
            inventory: warehouse.inventory,
            flowRecords: warehouse.productionIssueFlowRecords[code] || [],
            repeated,
          });
        }
      }

      if (parts[2] === 'production-returns') {
        const production = ensureProduction(data);
        const code = decodeURIComponent(parts[3] || '');
        const index = warehouse.productionReturns.findIndex((record) => record.code === code);

        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...warehouse.productionReturns].sort((a, b) => `${b.updatedAt || ''}${b.code}`.localeCompare(`${a.updatedAt || ''}${a.code}`)),
          });
        }

        if (req.method === 'GET' && code && parts.length === 4) {
          if (index < 0) return sendError(res, 404, '生产退料单不存在');
          const record = warehouse.productionReturns[index];
          return sendJson(res, 200, {
            record,
            materialIssue: warehouse.productionIssues.find((item) => item.code === record.materialIssue) || null,
            executionCard: production.executionCards.find((item) => item.code === record.executionCard) || null,
            flowRecords: warehouse.productionReturnFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts.length === 3) {
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const record = normalizeProductionReturn(data, body, undefined);
          warehouse.productionReturns.unshift(record);
          appendProductionReturnFlow(data, record.code, '创建退料草稿', `引用原领料单 ${record.materialIssue}，等待提交入库。`, actor);
          appendBusinessAuditLog(req, data, '创建生产退料单', record.code, `原领料单 ${record.materialIssue}。`);
          await writeData(data);
          return sendJson(res, 201, {
            record,
            materialIssue: warehouse.productionIssues.find((item) => item.code === record.materialIssue) || null,
            flowRecords: warehouse.productionReturnFlowRecords[record.code] || [],
          });
        }

        if (req.method === 'PUT' && code && parts.length === 4) {
          if (index < 0) return sendError(res, 404, '生产退料单不存在');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const record = normalizeProductionReturn(data, { ...body, code }, warehouse.productionReturns[index]);
          warehouse.productionReturns[index] = record;
          appendProductionReturnFlow(data, code, '保存退料草稿', `退料单修订为第 ${record.revision} 版。`, actor);
          appendBusinessAuditLog(req, data, '更新生产退料单', code, `修订 ${record.revision}。`);
          await writeData(data);
          return sendJson(res, 200, {
            record,
            materialIssue: warehouse.productionIssues.find((item) => item.code === record.materialIssue) || null,
            flowRecords: warehouse.productionReturnFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && code && parts[4] === 'submit') {
          if (index < 0) return sendError(res, 404, '生产退料单不存在');
          const actor = businessActorName(req, data);
          const record = warehouse.productionReturns[index];
          if (record.status !== '草稿') return sendError(res, 409, `生产退料单 ${code} 当前为${record.status}，不能重复提交。`);
          productionIssueForReturn(data, record, record);
          record.status = '待入库';
          record.submittedAt = shanghaiDateTime();
          record.submittedBy = actor;
          record.revision = Number(record.revision || 0) + 1;
          record.updatedAt = record.submittedAt;
          appendProductionReturnFlow(data, code, '提交退料入库', `原领料单 ${record.materialIssue} 的余料等待仓库确认入库。`, actor);
          appendBusinessAuditLog(req, data, '提交生产退料单', code, `原领料单 ${record.materialIssue}。`);
          await writeData(data);
          return sendJson(res, 200, {
            record,
            materialIssue: warehouse.productionIssues.find((item) => item.code === record.materialIssue) || null,
            flowRecords: warehouse.productionReturnFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && code && parts[4] === 'post') {
          if (index < 0) return sendError(res, 404, '生产退料单不存在');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const result = postProductionReturnToStock(
            data,
            warehouse.productionReturns[index],
            String(body.idempotencyKey || ''),
            actor,
          );
          if (!result.repeated) {
            appendProductionReturnFlow(data, code, '生产退料过账', `余料已退回 ${result.record.targetWarehouse}，库存与流水已更新。`, actor);
            if (result.executionCard) {
              appendExecutionCardFlow(data, result.executionCard.code, '生产退料过账', `退料单 ${code} 已完成，不改变已领料主状态。`, actor);
            }
            appendBusinessAuditLog(req, data, '生产退料过账', code, `原领料单 ${result.record.materialIssue}。`);
            await writeData(data);
          }
          return sendJson(res, result.repeated ? 200 : 201, {
            ...result,
            inventory: warehouse.inventory,
            stockLedger: warehouse.stockLedger,
            flowRecords: warehouse.productionReturnFlowRecords[code] || [],
          });
        }
      }

      if (parts[2] === 'production-receipts') {
        const production = ensureProduction(data);
        const code = decodeURIComponent(parts[3] || '');
        const index = warehouse.productionReceipts.findIndex((record) => record.code === code);

        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...warehouse.productionReceipts].sort((a, b) => `${b.updatedAt || ''}${b.code}`.localeCompare(`${a.updatedAt || ''}${a.code}`)),
          });
        }

        if (req.method === 'GET' && code && parts.length === 4) {
          if (index < 0) return sendError(res, 404, '完工入库单不存在');
          const receipt = warehouse.productionReceipts[index];
          const card = production.executionCards.find((item) => item.code === receipt.executionCard);
          return sendJson(res, 200, {
            receipt,
            executionCard: card || null,
            release: card ? productionReleaseForExecutionCard(production, card) || null : null,
            workOrder: production.workOrders.find((item) => item.code === receipt.workOrder) || null,
            flowRecords: warehouse.productionReceiptFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts.length === 3) {
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const receipt = normalizeProductionReceipt(data, body, undefined);
          warehouse.productionReceipts.unshift(receipt);
          appendProductionReceiptFlow(data, receipt.code, '创建完工入库草稿', `承接流转批次 ${receipt.executionCard}，数量 ${formatQty(receipt.quantity, receipt.unit)}。`, actor);
          appendBusinessAuditLog(req, data, '创建完工入库单', receipt.code, `来源流转批次 ${receipt.executionCard}。`);
          await writeData(data);
          return sendJson(res, 201, {
            receipt,
            executionCard: production.executionCards.find((item) => item.code === receipt.executionCard),
            flowRecords: warehouse.productionReceiptFlowRecords[receipt.code] || [],
          });
        }

        if (req.method === 'PUT' && code && parts.length === 4) {
          if (index < 0) return sendError(res, 404, '完工入库单不存在');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const existing = warehouse.productionReceipts[index];
          const receipt = existing.status === '待入库'
            ? updatePendingProductionReceiptDestination(data, body, existing)
            : normalizeProductionReceipt(data, { ...body, code }, existing);
          warehouse.productionReceipts[index] = receipt;
          const action = existing.status === '待入库' ? '确认完工入库去向' : '保存完工入库草稿';
          const remark = existing.status === '待入库'
            ? `已选择 ${receipt.targetWarehouse} / ${receipt.targetLocation}，等待仓库过账。`
            : `修订为第 ${receipt.revision} 版。`;
          appendProductionReceiptFlow(data, code, action, remark, actor);
          appendBusinessAuditLog(req, data, '更新完工入库单', code, `修订 ${receipt.revision}。`);
          await writeData(data);
          return sendJson(res, 200, {
            receipt,
            executionCard: production.executionCards.find((item) => item.code === receipt.executionCard),
            flowRecords: warehouse.productionReceiptFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && code && parts[4] === 'submit') {
          if (index < 0) return sendError(res, 404, '完工入库单不存在');
          const actor = businessActorName(req, data);
          const receipt = warehouse.productionReceipts[index];
          if (receipt.status !== '草稿') return sendError(res, 409, `完工入库单 ${code} 当前为${receipt.status}，不能重复提交。`);
          const card = production.executionCards.find((item) => item.code === receipt.executionCard);
          if (!card || card.node !== '待入库' || card.status !== '待仓库') {
            return sendError(res, 409, `流转批次 ${receipt.executionCard} 当前不能办理完工入库。`);
          }
          assertProductionReceiptDestination(data, receipt);
          receipt.status = '待入库';
          receipt.submittedBy = actor;
          receipt.revision = Number(receipt.revision || 0) + 1;
          receipt.updatedAt = shanghaiDateTime();
          appendProductionReceiptFlow(data, code, '提交完工入库', `流转批次 ${receipt.executionCard} 等待仓库过账。`, actor);
          appendExecutionCardFlow(data, receipt.executionCard, '完工入库已提交', `入库单 ${code} 等待仓库过账。`, actor);
          appendBusinessAuditLog(req, data, '提交完工入库单', code, `来源流转批次 ${receipt.executionCard}。`);
          await writeData(data);
          return sendJson(res, 200, {
            receipt,
            executionCard: card,
            flowRecords: warehouse.productionReceiptFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && code && parts[4] === 'post') {
          if (index < 0) return sendError(res, 404, '完工入库单不存在');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const result = postProductionReceiptToStock(
            data,
            warehouse.productionReceipts[index],
            String(body.idempotencyKey || ''),
            actor,
          );
          if (!result.repeated) {
            appendProductionReceiptFlow(data, code, '完工入库过账', `成品 ${formatQty(result.receipt.quantity, result.receipt.unit)} 已进入 ${result.receipt.targetWarehouse}。`, actor);
            appendExecutionCardFlow(data, result.card.code, '完工入库过账', `入库单 ${code} 已完成，累计入库 ${formatQty(result.card.inboundQty, result.card.unit)}。`, actor);
            appendWorkOrderReleaseFlow(data, result.card.releaseBatchCode, '完工入库过账', `流转批次 ${result.card.code} 已完成入库 ${formatQty(result.receipt.quantity, result.receipt.unit)}。`, actor);
            appendWorkOrderFlow(data, result.card.workOrderCode, '完工入库过账', `流转批次 ${result.card.code} 累计入库 ${formatQty(result.card.inboundQty, result.card.unit)}。`, actor);
            appendBusinessAuditLog(req, data, '完工入库过账', code, `流转批次 ${result.card.code}，数量 ${result.receipt.quantity}${result.receipt.unit}。`);
            await writeData(data);
          }
          return sendJson(res, result.repeated ? 200 : 201, {
            ...result,
            inventory: warehouse.inventory,
            flowRecords: warehouse.productionReceiptFlowRecords[code] || [],
          });
        }
      }

      const warehouseStatusTarget =
        parts[2] === 'purchase-receipts'
          ? {
              rows: warehouse.purchaseReceipts,
              flowKey: 'receiptFlowRecords',
              append: appendReceiptFlow,
              title: '采购入库单',
            }
          : parts[2] === 'sales-issues'
            ? {
                rows: warehouse.salesIssues,
                flowKey: 'salesIssueFlowRecords',
                append: appendSalesIssueFlow,
                title: '销售出库单',
              }
            : parts[2] === 'other-moves'
              ? {
                  rows: warehouse.otherMoves,
                  flowKey: 'otherMoveFlowRecords',
                  append: appendOtherMoveFlow,
                  title: '其他出入库单',
                }
              : parts[2] === 'transfers'
                ? {
                    rows: warehouse.transfers,
                    flowKey: 'transferFlowRecords',
                    append: appendTransferFlow,
                    title: '库存调拨单',
                  }
                : parts[2] === 'stocktakes'
                  ? {
                      rows: warehouse.stocktakes,
                      flowKey: 'stocktakeFlowRecords',
                      append: appendStocktakeFlow,
                      title: '库存盘点单',
                    }
                  : undefined;

      if (warehouseStatusTarget && req.method === 'POST' && parts[4] === 'status') {
        const code = decodeURIComponent(parts[3] || '');
        const index = warehouseStatusTarget.rows.findIndex((record) => record.code === code);
        if (index < 0) return sendError(res, 404, `${warehouseStatusTarget.title}不存在`);

        const body = await readBody(req);
        const actor = businessActorName(req, data);
        const status = String(body.status || '').trim();
        if (!status) return sendError(res, 400, '请提供目标状态');

        const action = String(body.action || '状态更新').trim();
        const remark = String(body.remark || body.reason || `${warehouseStatusTarget.title}状态更新为${status}`).trim();
        const existing = warehouseStatusTarget.rows[index];
        if (String(existing.status || '') === status) {
          return sendJson(res, 200, {
            record: existing,
            qualityTask: null,
            flowRecords: warehouse[warehouseStatusTarget.flowKey][code] || [],
            idempotentReplay: true,
          });
        }
        if (
          parts[2] === 'purchase-receipts'
          && ['草稿', '待收货'].includes(String(existing.status || ''))
          && ['待质检', '待入库'].includes(status)
        ) {
          return sendError(
            res,
            409,
            '采购入库任务不能用通用状态接口确认到货；请保存实际到货明细后，使用“提交到货结果”。',
          );
        }
        if (
          parts[2] === 'purchase-receipts'
          && status === '待入库'
          && (
            existing.status === '待质检'
            || ['qc_hold', 'quality_partial'].includes(existing.stockStage)
            || (
              purchaseReceiptRequiresIncomingQuality(existing)
              && (!purchaseReceiptQualityDecisionComplete(existing) || existing.stockStage !== 'pending_inbound')
            )
          )
        ) {
          return sendError(res, 409, '待质检收货单必须由质检模块提交逐行数量决定；仓库不能直接整批放行。');
        }
        if (
          parts[2] === 'sales-issues'
          && existing.status === '待拣货'
          && status === '待复核'
        ) {
          return sendError(
            res,
            409,
            '销售出库任务不能用通用状态接口提交复核；请使用“登记拣货”原子提交本次库存分配。',
          );
        }
        if (
          parts[2] === 'transfers'
          && ['已取消', '已作废', '已中断'].includes(status)
        ) {
          return sendError(
            res,
            409,
            '库存调拨不能用通用状态接口终止；尚未调出请使用“取消调拨”，调出后必须确认调入，完成后如需纠错再办理库存冲销。',
          );
        }
        assertWarehouseStatusTransition(parts[2], existing.status, status);
        let statusSource = existing;
        let generatedQualityTask = null;
        let generatedQualityTaskCreated = false;
        if (parts[2] === 'sales-issues') {
          const milestoneTime = shanghaiDateTime();
          if (existing.status === '待复核' && status === '待拣货') {
            statusSource = {
              ...existing,
              actualWarehouses: [],
              reviewSubmittedAt: '',
              reviewSubmittedBy: '',
              pickingResult: null,
              reviewReturnedAt: milestoneTime,
              reviewReturnedBy: actor,
            };
          }
        }
        if (parts[2] === 'other-moves' && ['待审核', '待过账'].includes(status)) {
          assertOtherMoveReady(data, existing);
        }
        if (parts[2] === 'stocktakes' && status === '待复核') {
          assertStocktakeCounted(existing);
        }
        if (parts[2] === 'transfers' && status === '调拨中') {
          statusSource = {
            ...existing,
            products: (existing.products || []).map((product) => ({ ...product })),
            transitLines: [],
          };
          dispatchTransferToTransit(data, statusSource, actor);
        }
        if (parts[2] === 'purchase-receipts') {
          if (['待质检', '待入库'].includes(status)) {
            const stagingWarehouse = warehouseMeta(data, existing.warehouseCode, existing.warehouse);
            if (!stagingWarehouse.code || stagingWarehouse.status !== '启用' || stagingWarehouse.allowPurchaseStaging !== true) {
              return sendError(res, 409, `采购暂存仓“${existing.warehouse || existing.warehouseCode || '-'}”当前不可用，不能登记到货。`);
            }
            if (!String(existing.location || '').trim()) {
              return sendError(res, 400, '登记到货前请选择采购暂存库位。');
            }
            const stagingLocations = warehouseLocationOptions(data, stagingWarehouse);
            if (stagingLocations.length && !stagingLocations.includes(String(existing.location).trim())) {
              return sendError(res, 400, `采购暂存库位“${existing.location}”不属于仓库“${stagingWarehouse.name}”，请从库位列表选择。`);
            }
            if (!/^\d{4}-\d{2}-\d{2}$/.test(String(existing.date || '').trim())) {
              return sendError(res, 400, '确认到货前请填写真实的实际到货日期。');
            }
            existing.products = (existing.products || []).map((product) => ({
              ...product,
              batch: '',
            }));
          }
          if (status === '待质检') {
            if (!purchaseReceiptRequiresIncomingQuality(existing)) {
              return sendError(res, 409, '该收货单全部物料均为免检，不需要进入来料质检。');
            }
            recordPurchaseReceiptArrival(data, existing, 'qc_hold', actor);
            const generated = createIncomingQualityTaskForReceipt(data, existing, actor);
            generatedQualityTask = generated.task;
            generatedQualityTaskCreated = generated.created;
          }
          if (status === '待入库') {
            recordPurchaseReceiptArrival(data, existing, 'pending_inbound', actor);
          }
        }
        const warehouseMilestone = parts[2] === 'other-moves'
          ? status === '待审核'
            ? { submittedAt: shanghaiDateTime(), submittedBy: actor }
            : status === '待过账'
              ? { approvedAt: shanghaiDateTime(), approvedBy: actor }
              : {}
          : parts[2] === 'transfers' && status === '调拨中'
            ? { dispatchedAt: shanghaiDateTime(), dispatchedBy: actor }
            : {};
        const record = { ...statusSource, status, ...warehouseMilestone };
        warehouseStatusTarget.rows[index] = record;
        const generatedNextReceipt = parts[2] === 'purchase-receipts' && ['待质检', '待入库'].includes(status)
          ? ensurePendingPurchaseReceiptTask(
              data,
              ensurePurchase(data).orders.find((order) => order.code === record.sourceDoc),
              { actor },
            )
          : { task: null, created: false };
        const qualityFlowRemark = generatedQualityTaskCreated
          ? `${remark}已自动生成来料质检任务 ${generatedQualityTask.code}。`
          : remark;
        const flowRemark = generatedNextReceipt.created
          ? `${qualityFlowRemark} 未到齐数量已自动生成后续待收货任务 ${generatedNextReceipt.task.code}。`
          : qualityFlowRemark;
        warehouseStatusTarget.append(data, code, action, flowRemark, actor);
        appendBusinessAuditLog(req, data, `更新${warehouseStatusTarget.title}状态`, code, flowRemark);
        await writeData(data);
        return sendJson(res, 200, {
          record,
          qualityTask: generatedQualityTask ? incomingQualityReadModel(data, generatedQualityTask) : null,
          nextReceiptTask: generatedNextReceipt.task,
          flowRecords: warehouse[warehouseStatusTarget.flowKey][code] || [],
        });
      }

      if (parts[2] === 'purchase-receipts') {
        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...warehouse.purchaseReceipts].sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`)),
          });
        }

        const code = decodeURIComponent(parts[3] || '');
        const index = warehouse.purchaseReceipts.findIndex((receipt) => receipt.code === code);

        if (req.method === 'GET' && code) {
          if (index < 0) return sendError(res, 404, '采购入库单不存在');
          return sendJson(res, 200, {
            receipt: warehouse.purchaseReceipts[index],
            flowRecords: warehouse.receiptFlowRecords[code] || [],
            detailProjection: purchaseInboundDetailProjection(data, warehouse.purchaseReceipts[index]),
          });
        }

        if (req.method === 'POST' && parts.length === 3) {
          await readBody(req);
          return sendError(
            res,
            405,
            '采购收货任务由已确认采购订单自动生成，仓库不能新建空白采购收货单。',
          );
        }

        if (req.method === 'PUT' && code) {
          if (index < 0) return sendError(res, 404, '采购入库单不存在');
          const existing = warehouse.purchaseReceipts[index];
          assertDocumentEditable('采购入库单', code, existing.status, warehouseLockedStatuses);
          if (existing.stockStage || !['草稿', '待收货'].includes(existing.status)) {
            const body = await readBody(req);
            const actor = businessActorName(req, data);
            const frozenFields = [
              'sourceDoc',
              'supplierCode',
              'supplier',
              'contact',
              'contactPhone',
              'warehouseCode',
              'warehouse',
              'location',
              'owner',
              'status',
              'date',
              'expectedDate',
            ];
            const changedFrozenField = frozenFields.find((field) => (
              body[field] !== undefined
              && JSON.stringify(body[field]) !== JSON.stringify(existing[field])
            ));
            const coreProductFacts = (products) => (products || []).map((product) => {
              const {
                destinationWarehouseCode,
                destinationWarehouse,
                destinationLocation,
                ...core
              } = product;
              return core;
            });
            const changedProducts = body.products !== undefined
              && JSON.stringify(coreProductFacts(body.products)) !== JSON.stringify(coreProductFacts(existing.products));
            if (changedFrozenField) {
              return sendError(res, 409, `采购收货单 ${code} 已形成到货或库存事实，不能改写来源、数量、批次、仓库或日期；请使用冲销、退货或差异处理单。`);
            }
            if (changedProducts) {
              return sendError(res, 409, `采购收货单 ${code} 已形成到货事实，只能补充每行正式入库仓库和库位，不能改写到货物料、数量或批次。`);
            }
            const destinationByLine = new Map((body.products || []).map((product, lineIndex) => [
              product.lineId || `L${lineIndex + 1}`,
              product,
            ]));
            const products = (existing.products || []).map((product, lineIndex) => {
              const requested = destinationByLine.get(product.lineId || `L${lineIndex + 1}`);
              return requested
                ? {
                    ...product,
                    destinationWarehouseCode: String(requested.destinationWarehouseCode || ''),
                    destinationWarehouse: String(requested.destinationWarehouse || ''),
                    destinationLocation: String(requested.destinationLocation || ''),
                  }
                : product;
            });
            const inboundAllocations = Array.isArray(body.inboundAllocations)
              ? body.inboundAllocations.map((allocation, allocationIndex) => ({
                  id: String(allocation.id || `A${allocationIndex + 1}`),
                  receiptLineId: String(allocation.receiptLineId || ''),
                  quantity: String(allocation.quantity ?? allocation.qty ?? ''),
                  warehouseCode: String(allocation.warehouseCode || ''),
                  warehouse: String(allocation.warehouse || ''),
                  location: String(allocation.location || ''),
                }))
              : existing.inboundAllocations || [];
            const receipt = {
              ...existing,
              products,
              inboundAllocations,
              note: String(body.note ?? existing.note ?? ''),
              attachments: Array.isArray(body.attachments) ? body.attachments : existing.attachments || [],
            };
            if (
              existing.status === '待入库'
              && body.products !== undefined
              && body.inboundAllocations === undefined
            ) {
              assertPurchaseReceiptDestinations(data, receipt);
            }
            warehouse.purchaseReceipts[index] = receipt;
            appendReceiptFlow(data, receipt.code, '补充收货记录', '已补充采购收货备注或附件，原到货与库存事实保持不变。', actor);
            await writeData(data);
            return sendJson(res, 200, { receipt, flowRecords: warehouse.receiptFlowRecords[receipt.code] || [] });
          }
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const receipt = normalizeReceipt({ ...body, code }, existing, data);
          if (['草稿', '待收货'].includes(String(receipt.status || ''))) {
            receipt.arrivalDraftSavedAt = shanghaiDateTime();
            receipt.arrivalDraftSavedBy = actor;
          }
          warehouse.purchaseReceipts[index] = receipt;
          appendReceiptFlow(data, receipt.code, '保存采购入库单', '采购入库单内容已更新。', actor);
          await writeData(data);
          return sendJson(res, 200, { receipt, flowRecords: warehouse.receiptFlowRecords[receipt.code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'arrival-result') {
          if (index < 0) return sendError(res, 404, '采购入库任务不存在');
          const body = await readBody(req);
          const originalReceipt = warehouse.purchaseReceipts[index];
          const submittedReceipt = purchaseReceiptArrivalSubmission(
            originalReceipt,
            body,
          );
          // The remaining-quantity projection must see this submitted snapshot.
          // Otherwise the old pending task is reused as its own follow-up task.
          warehouse.purchaseReceipts[index] = submittedReceipt;
          let result;
          try {
            result = submitPurchaseReceiptArrivalResult(
              data,
              submittedReceipt,
              req,
              body,
            );
          } catch (error) {
            warehouse.purchaseReceipts[index] = originalReceipt;
            throw error;
          }
          const persistedIndex = warehouse.purchaseReceipts.findIndex((receipt) => receipt.code === code);
          if (persistedIndex >= 0) warehouse.purchaseReceipts[persistedIndex] = result.receipt;
          await writeData(data);
          return sendJson(res, result.repeated ? 200 : 201, {
            ...result,
            flowRecords: warehouse.receiptFlowRecords[code] || [],
            inventory: warehouse.inventory,
            stockLedger: warehouse.stockLedger,
          });
        }

        if (req.method === 'POST' && parts[4] === 'post') {
          if (index < 0) return sendError(res, 404, '采购入库单不存在');
          const existing = warehouse.purchaseReceipts[index];
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const idempotencyKey = String(body.idempotencyKey || '').trim();
          const repeatedPosting = idempotencyKey
            ? (existing.inboundPostings || []).find((posting) => posting.idempotencyKey === idempotencyKey)
            : null;
          if (repeatedPosting) {
            return sendJson(res, 200, {
              receipt: existing,
              posting: repeatedPosting,
              repeated: true,
              flowRecords: warehouse.receiptFlowRecords[code] || [],
              inventory: warehouse.inventory,
              stockLedger: warehouse.stockLedger,
            });
          }
          assertActionStatus('采购入库任务', code, existing.status, ['待入库', '待质检', '部分入库'], '登记入库');
          const receipt = existing;
          assertPurchaseReceiptWithinOrder(data, receipt);
          const postingResult = applyPurchaseReceiptToStock(
            data,
            receipt,
            body.allocations,
            idempotencyKey,
            actor,
          );
          warehouse.purchaseReceipts[index] = receipt;
          if (!postingResult.repeated) {
            const postedSummary = postingResult.posting.lines
              .map((line) => `${line.materialCode || line.receiptLineId} ${formatQty(line.postedQty, line.unit)} → ${line.warehouse}/${line.location}`)
              .join('；');
            appendReceiptFlow(data, code, '登记入库', `${postingResult.posting.code}：${postedSummary}。`, actor);
            appendBusinessAuditLog(req, data, '确认采购入库', code, `${postingResult.posting.code}：${postedSummary}。`);
            appendBusinessNotification(data, {
              module: '仓库',
              action: '库存过账',
              targetRoles: 'ROLE-PURCHASE',
              title: receipt.status === '已入库' ? '采购入库已完成' : '采购入库已部分过账',
              message: `${code} 已生成 ${postingResult.posting.code}，库存余额和流水已更新。`,
              sourceDoc: receipt.sourceDoc || code,
              sourcePath: receipt.sourceDoc
                ? `/purchase/orders/${encodeURIComponent(receipt.sourceDoc)}/follow-up`
                : '/purchase/orders',
              actor,
            });

            const purchase = ensurePurchase(data);
            const orderIndex = purchase.orders.findIndex((order) => order.code === receipt.sourceDoc);
            if (orderIndex >= 0) {
              const inboundProgress = purchaseOrderReceiptStatus(data, receipt.sourceDoc) || '已入库';
              appendPurchaseFlow(
                data,
                receipt.sourceDoc,
                inboundProgress === '已完成' ? '采购入库完成' : '部分入库',
                `${receipt.code} 已生成入库记录 ${postingResult.posting.code}；采购订单主状态保持不变，入库进度独立更新。`,
                actor,
              );
            }
          }

          await writeData(data);
          return sendJson(res, 200, {
            receipt: warehouse.purchaseReceipts[index],
            posting: postingResult.posting,
            repeated: postingResult.repeated,
            flowRecords: warehouse.receiptFlowRecords[code] || [],
            inventory: warehouse.inventory,
            stockLedger: warehouse.stockLedger,
          });
        }
      }

      if (parts[2] === 'sales-issues') {
        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...warehouse.salesIssues].sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`)),
          });
        }

        const code = decodeURIComponent(parts[3] || '');
        const index = warehouse.salesIssues.findIndex((issue) => issue.code === code);

        if (req.method === 'GET' && code) {
          if (index < 0) return sendError(res, 404, '销售出库单不存在');
          return sendJson(res, 200, {
            issue: warehouse.salesIssues[index],
            flowRecords: warehouse.salesIssueFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts.length === 3) {
          return sendError(
            res,
            405,
            '销售出库任务只能由已确认的销售交付事实自动生成，仓库不能手工新建任务。',
          );
        }

        if (req.method === 'PUT' && code) {
          if (index < 0) return sendError(res, 404, '销售出库单不存在');
          return sendError(
            res,
            405,
            `销售出库任务 ${code} 不支持普通保存；请使用“登记拣货”、退回复拣或正式过账命令。`,
          );
        }

        if (req.method === 'POST' && parts[4] === 'picking-result') {
          if (index < 0) return sendError(res, 404, '销售出库任务不存在');
          const body = await readBody(req);
          const result = submitSalesIssuePickingResult(
            data,
            warehouse.salesIssues[index],
            req,
            body,
          );
          warehouse.salesIssues[index] = result.issue;
          await writeData(data);
          return sendJson(res, result.repeated ? 200 : 201, {
            ...result,
            flowRecords: warehouse.salesIssueFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts[4] === 'post') {
          if (index < 0) return sendError(res, 404, '销售出库单不存在');
          const existing = warehouse.salesIssues[index];
          assertActionStatus('销售出库单', code, existing.status, ['待复核'], '确认出库');

          if (existing.status !== '已出库') {
            const actor = businessActorName(req, data);
            const issue = {
              ...existing,
              products: (existing.products || []).map((product) => ({ ...product })),
              status: '已出库',
              postedBy: actor,
              postedAt: shanghaiDateTime(),
            };
            assertSalesIssueReadyForReview(data, issue, '确认销售出库');
            applySalesIssueToStock(data, issue, actor);
            warehouse.salesIssues[index] = issue;
            appendSalesIssueFlow(data, code, '确认出库', '销售出库复核完成，库存余额和库存流水已更新。', actor);
            appendBusinessAuditLog(req, data, '确认销售出库', code, '销售出库复核完成，库存余额和库存流水已更新。');
            appendBusinessNotification(data, {
              module: '仓库',
              action: '库存过账',
              targetRoles: 'ROLE-SALES',
              title: '销售出库已过账',
              message: `${code} 已完成销售出库，库存余额和流水已更新。`,
              sourceDoc: issue.sourceOrder || code,
              sourcePath: issue.sourceOrder
                ? `/sales/orders/${encodeURIComponent(issue.sourceOrder)}/delivery`
                : '/sales/orders',
              actor,
            });

            const sales = ensureSales(data);
            const fulfillment = syncShipmentTrackingFulfillment(data, issue);
            const tracking = sales.outboundRequests.find((requestDoc) => requestDoc.code === issue.sourceDoc);
            if (tracking && !fulfillment.isComplete) {
              ensureSalesIssueTaskForTracking(data, tracking, actor);
            }

            const orderIndex = sales.orders.findIndex((order) => order.code === issue.sourceOrder);
            if (orderIndex >= 0) {
              if (fulfillment.isComplete) {
                sales.orders[orderIndex] = { ...sales.orders[orderIndex], status: '待签收' };
                appendFlow(data, issue.sourceOrder, '销售出库完成', `${issue.code} 已完成出库，销售订单同步为待签收，等待销售确认客户签收。`, actor);
              } else {
                sales.orders[orderIndex] = { ...sales.orders[orderIndex], status: '部分发货' };
                appendFlow(data, issue.sourceOrder, '部分发货', `${issue.code} 已完成本批出库，销售订单仍有未发货数量。`, actor);
              }
            }
          }

          await writeData(data);
          return sendJson(res, 200, {
            issue: warehouse.salesIssues.find((record) => record.code === code),
            flowRecords: warehouse.salesIssueFlowRecords[code] || [],
            inventory: warehouse.inventory,
            stockLedger: warehouse.stockLedger,
          });
        }
      }

      if (parts[2] === 'other-moves') {
        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...warehouse.otherMoves].sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`)),
          });
        }

        const code = decodeURIComponent(parts[3] || '');
        const index = warehouse.otherMoves.findIndex((move) => move.code === code);

        if (req.method === 'GET' && code) {
          if (index < 0) return sendError(res, 404, '其他出入库单不存在');
          return sendJson(res, 200, {
            move: warehouse.otherMoves[index],
            flowRecords: warehouse.otherMoveFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts.length === 3) {
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const move = normalizeOtherMove(body, undefined, data);
          warehouse.otherMoves.unshift(move);
          appendOtherMoveFlow(data, move.code, '保存其他出入库单', '其他出入库单已保存为草稿。', actor);
          await writeData(data);
          return sendJson(res, 201, { move, flowRecords: warehouse.otherMoveFlowRecords[move.code] || [] });
        }

        if (req.method === 'PUT' && code) {
          if (index < 0) return sendError(res, 404, '其他出入库单不存在');
          const existing = warehouse.otherMoves[index];
          assertActionStatus('其他出入库单', code, existing.status, ['草稿'], '编辑');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const move = normalizeOtherMove({ ...body, code }, existing, data);
          warehouse.otherMoves[index] = move;
          appendOtherMoveFlow(data, move.code, '保存其他出入库单', '其他出入库单内容已更新。', actor);
          await writeData(data);
          return sendJson(res, 200, { move, flowRecords: warehouse.otherMoveFlowRecords[move.code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'submit') {
          if (index < 0) return sendError(res, 404, '其他出入库单不存在');
          if (warehouse.otherMoves[index].status === '待过账') {
            return sendJson(res, 200, {
              move: warehouse.otherMoves[index],
              repeated: true,
              flowRecords: warehouse.otherMoveFlowRecords[code] || [],
            });
          }
          const actor = businessActorName(req, data);
          assertActionStatus('其他出入库单', code, warehouse.otherMoves[index].status, ['待审核'], '审核通过');
          assertOtherMoveReady(data, warehouse.otherMoves[index]);
          const move = {
            ...warehouse.otherMoves[index],
            status: '待过账',
            approvedAt: shanghaiDateTime(),
            approvedBy: actor,
          };
          warehouse.otherMoves[index] = move;
          appendOtherMoveFlow(data, code, '审核通过', '其他出入库单已审核通过，等待库存过账。', actor);
          appendBusinessAuditLog(req, data, '审核其他出入库', code, '其他出入库单已审核通过，等待库存过账。');
          await writeData(data);
          return sendJson(res, 200, { move, flowRecords: warehouse.otherMoveFlowRecords[code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'post') {
          if (index < 0) return sendError(res, 404, '其他出入库单不存在');
          const existing = warehouse.otherMoves[index];
          if (existing.status === '已过账') {
            return sendJson(res, 200, {
              move: existing,
              repeated: true,
              flowRecords: warehouse.otherMoveFlowRecords[code] || [],
              inventory: warehouse.inventory,
              stockLedger: warehouse.stockLedger,
            });
          }
          const actor = businessActorName(req, data);
          assertActionStatus('其他出入库单', code, existing.status, ['待过账'], '确认过账');
          assertOtherMoveReady(data, existing);

          if (existing.status !== '已过账') {
            const move = {
              ...existing,
              products: [...existing.products],
              status: '已过账',
              postedAt: shanghaiDateTime(),
              postedBy: actor,
            };
            applyOtherMoveToStock(data, move, actor);
            warehouse.otherMoves[index] = move;
            appendOtherMoveFlow(data, code, '确认过账', '其他出入库已完成库存过账，库存余额和库存流水已更新。', actor);
            appendBusinessAuditLog(req, data, '确认其他出入库过账', code, '其他出入库已完成库存过账，库存余额和库存流水已更新。');
            appendBusinessNotification(data, {
              module: '仓库',
              action: '库存过账',
              targetRoles: 'ROLE-WAREHOUSE',
              title: '其他出入库已过账',
              message: `${code} 已完成库存过账，库存余额和流水已更新。`,
              sourceDoc: code,
              sourcePath: `/warehouse/other-moves/${encodeURIComponent(code)}`,
              actor,
            });
          }

          await writeData(data);
          return sendJson(res, 200, {
            move: warehouse.otherMoves[index],
            flowRecords: warehouse.otherMoveFlowRecords[code] || [],
            inventory: warehouse.inventory,
            stockLedger: warehouse.stockLedger,
          });
        }
      }

      if (parts[2] === 'transfers') {
        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...warehouse.transfers].sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`)),
          });
        }

        const code = decodeURIComponent(parts[3] || '');
        const index = warehouse.transfers.findIndex((transfer) => transfer.code === code);

        if (req.method === 'GET' && code) {
          if (index < 0) return sendError(res, 404, '库存调拨单不存在');
          return sendJson(res, 200, {
            transfer: warehouse.transfers[index],
            flowRecords: warehouse.transferFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts.length === 3) {
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const transfer = normalizeTransfer(body, undefined, data, actor);
          warehouse.transfers.unshift(transfer);
          appendTransferFlow(data, transfer.code, '保存调拨单', '库存调拨单已保存为草稿。', actor);
          await writeData(data);
          return sendJson(res, 201, { transfer, flowRecords: warehouse.transferFlowRecords[transfer.code] || [] });
        }

        if (req.method === 'PUT' && code) {
          if (index < 0) return sendError(res, 404, '库存调拨单不存在');
          const existing = warehouse.transfers[index];
          assertActionStatus('库存调拨单', code, existing.status, ['草稿'], '编辑');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const transfer = normalizeTransfer({ ...body, code }, existing, data, actor);
          warehouse.transfers[index] = transfer;
          appendTransferFlow(data, transfer.code, '保存调拨单', '库存调拨单内容已更新。', actor);
          await writeData(data);
          return sendJson(res, 200, { transfer, flowRecords: warehouse.transferFlowRecords[transfer.code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'submit') {
          if (index < 0) return sendError(res, 404, '库存调拨单不存在');
          const actor = businessActorName(req, data);
          assertActionStatus('库存调拨单', code, warehouse.transfers[index].status, ['草稿'], '提交调拨');
          assertTransferReady(data, warehouse.transfers[index]);
          const transfer = {
            ...warehouse.transfers[index],
            status: '待出库',
            submittedAt: shanghaiDateTime(),
            submittedBy: actor,
          };
          warehouse.transfers[index] = transfer;
          appendTransferFlow(data, code, '提交调拨', '库存调拨单已提交，等待出库和入库确认。', actor);
          appendBusinessAuditLog(req, data, '提交库存调拨', code, '库存调拨单已提交，等待出库和入库确认。');
          await writeData(data);
          return sendJson(res, 200, { transfer, flowRecords: warehouse.transferFlowRecords[code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'cancel') {
          if (index < 0) return sendError(res, 404, '库存调拨单不存在');
          const existing = warehouse.transfers[index];
          assertActionStatus('库存调拨单', code, existing.status, ['草稿', '待出库'], '取消调拨');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const reason = String(body.reason || '').trim();
          if (!reason) throw requestError(400, '请填写取消调拨原因。');
          const transfer = {
            ...existing,
            status: '已取消',
            cancelledAt: shanghaiDateTime(),
            cancellationReason: reason,
            cancelledBy: actor,
          };
          warehouse.transfers[index] = transfer;
          appendTransferFlow(data, code, '取消调拨', reason, actor);
          appendBusinessAuditLog(req, data, '取消库存调拨', code, reason);
          await writeData(data);
          return sendJson(res, 200, { transfer, flowRecords: warehouse.transferFlowRecords[code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'post') {
          if (index < 0) return sendError(res, 404, '库存调拨单不存在');
          const existing = warehouse.transfers[index];
          if (existing.status === '已完成') {
            return sendJson(res, 200, {
              transfer: existing,
              flowRecords: warehouse.transferFlowRecords[code] || [],
              inventory: warehouse.inventory,
              stockLedger: warehouse.stockLedger,
              idempotentReplay: true,
            });
          }
          const actor = businessActorName(req, data);
          assertActionStatus('库存调拨单', code, existing.status, ['调拨中', '待入库'], '确认调入');

          if (existing.status !== '已完成') {
            const transfer = {
              ...existing,
              products: [...existing.products],
              transitLines: (existing.transitLines || []).map((line) => ({ ...line })),
              status: '已完成',
              receivedAt: shanghaiDateTime(),
              receivedBy: actor,
            };
            receiveTransferFromTransit(data, transfer, actor);
            warehouse.transfers[index] = transfer;
            appendTransferFlow(data, code, '确认调拨完成', '库存调拨已完成，调出仓和调入仓库存流水已更新。', actor);
            appendBusinessAuditLog(req, data, '确认库存调拨完成', code, '库存调拨已完成，调出仓和调入仓库存流水已更新。');
            appendBusinessNotification(data, {
              module: '仓库',
              action: '库存过账',
              targetRoles: 'ROLE-WAREHOUSE',
              title: '库存调拨已完成',
              message: `${code} 已完成调拨过账，调出仓和调入仓库存流水已更新。`,
              sourceDoc: code,
              sourcePath: `/warehouse/transfers/${encodeURIComponent(code)}`,
              actor,
            });
          }

          await writeData(data);
          return sendJson(res, 200, {
            transfer: warehouse.transfers[index],
            flowRecords: warehouse.transferFlowRecords[code] || [],
            inventory: warehouse.inventory,
            stockLedger: warehouse.stockLedger,
          });
        }
      }

      if (parts[2] === 'stocktakes') {
        if (req.method === 'GET' && parts.length === 3) {
          return sendJson(res, 200, {
            items: [...warehouse.stocktakes].sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`)),
          });
        }

        const code = decodeURIComponent(parts[3] || '');
        const index = warehouse.stocktakes.findIndex((stocktake) => stocktake.code === code);

        if (req.method === 'GET' && code) {
          if (index < 0) return sendError(res, 404, '库存盘点单不存在');
          return sendJson(res, 200, {
            stocktake: stocktakeMaterialIdentityProjection(data, warehouse.stocktakes[index]),
            flowRecords: warehouse.stocktakeFlowRecords[code] || [],
          });
        }

        if (req.method === 'POST' && parts.length === 3) {
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const stocktake = normalizeStocktake(body, undefined, data, actor);
          warehouse.stocktakes.unshift(stocktake);
          appendStocktakeFlow(data, stocktake.code, '保存盘点单', '库存盘点单已保存。', actor);
          await writeData(data);
          return sendJson(res, 201, { stocktake, flowRecords: warehouse.stocktakeFlowRecords[stocktake.code] || [] });
        }

        if (req.method === 'PUT' && code) {
          if (index < 0) return sendError(res, 404, '库存盘点单不存在');
          const existing = warehouse.stocktakes[index];
          assertActionStatus('库存盘点单', code, existing.status, ['待盘点', '盘点中'], '编辑');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const stocktake = normalizeStocktake({ ...body, code }, existing, data, actor);
          warehouse.stocktakes[index] = stocktake;
          appendStocktakeFlow(data, stocktake.code, '保存盘点单', '库存盘点单内容已更新。', actor);
          await writeData(data);
          return sendJson(res, 200, { stocktake, flowRecords: warehouse.stocktakeFlowRecords[stocktake.code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'start') {
          if (index < 0) return sendError(res, 404, '库存盘点单不存在');
          const actor = businessActorName(req, data);
          assertActionStatus('库存盘点单', code, warehouse.stocktakes[index].status, ['待盘点'], '开始盘点');
          const stocktake = {
            ...warehouse.stocktakes[index],
            lines: (warehouse.stocktakes[index].lines || []).map((line) => ({ ...line })),
            status: '盘点中',
            startedAt: shanghaiDateTime(),
            startedBy: actor,
          };
          startStocktakeSnapshot(data, stocktake);
          warehouse.stocktakes[index] = stocktake;
          appendStocktakeFlow(data, code, '开始盘点', `已形成 ${stocktake.plannedCount} 条账面快照并冻结盘点范围。`, actor);
          appendBusinessAuditLog(req, data, '开始库存盘点', code, `已形成 ${stocktake.plannedCount} 条账面快照并冻结盘点范围。`);
          await writeData(data);
          return sendJson(res, 200, { stocktake, flowRecords: warehouse.stocktakeFlowRecords[code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'submit') {
          if (index < 0) return sendError(res, 404, '库存盘点单不存在');
          const actor = businessActorName(req, data);
          assertActionStatus('库存盘点单', code, warehouse.stocktakes[index].status, ['盘点中'], '提交复核');
          assertStocktakeCounted(warehouse.stocktakes[index]);
          const stocktake = {
            ...warehouse.stocktakes[index],
            status: '待复核',
            submittedAt: shanghaiDateTime(),
            submittedBy: actor,
          };
          warehouse.stocktakes[index] = stocktake;
          (stocktake.lines || []).forEach((line) => {
            const inventoryRow = warehouse.inventory.find((row) => row.key === line.inventoryKey);
            const freezeSource = (inventoryRow?.freezeSources || []).find((source) => source.sourceDoc === code);
            if (freezeSource) freezeSource.status = '待复核';
          });
          appendStocktakeFlow(data, code, '提交复核', '盘点结果已提交，等待复核差异。', actor);
          appendBusinessAuditLog(req, data, '提交库存盘点复核', code, '盘点结果已提交，等待复核差异。');
          await writeData(data);
          return sendJson(res, 200, { stocktake, flowRecords: warehouse.stocktakeFlowRecords[code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'return') {
          if (index < 0) return sendError(res, 404, '库存盘点单不存在');
          assertActionStatus('库存盘点单', code, warehouse.stocktakes[index].status, ['待复核'], '退回实盘');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const reason = String(body.reason || '').trim();
          if (!reason) throw requestError(400, '请填写退回实盘原因。');
          const stocktake = {
            ...warehouse.stocktakes[index],
            status: '盘点中',
            reviewReturnedAt: shanghaiDateTime(),
            reviewReturnReason: reason,
            reviewReturnedBy: actor,
          };
          warehouse.stocktakes[index] = stocktake;
          (stocktake.lines || []).forEach((line) => {
            const inventoryRow = warehouse.inventory.find((row) => row.key === line.inventoryKey);
            const freezeSource = (inventoryRow?.freezeSources || []).find((source) => source.sourceDoc === code);
            if (freezeSource) freezeSource.status = '盘点中';
          });
          appendStocktakeFlow(data, code, '退回实盘', reason, stocktake.reviewReturnedBy);
          appendBusinessAuditLog(req, data, '退回库存盘点实盘', code, reason);
          await writeData(data);
          return sendJson(res, 200, { stocktake, flowRecords: warehouse.stocktakeFlowRecords[code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'cancel') {
          if (index < 0) return sendError(res, 404, '库存盘点单不存在');
          assertActionStatus('库存盘点单', code, warehouse.stocktakes[index].status, ['待盘点', '盘点中'], '取消盘点');
          const body = await readBody(req);
          const actor = businessActorName(req, data);
          const reason = String(body.reason || '').trim();
          if (!reason) throw requestError(400, '请填写取消盘点原因。');
          const existing = warehouse.stocktakes[index];
          if (existing.status === '盘点中') releaseStocktakeFreeze(data, existing);
          const stocktake = {
            ...existing,
            status: '已取消',
            cancelledAt: shanghaiDateTime(),
            cancellationReason: reason,
            cancelledBy: actor,
          };
          warehouse.stocktakes[index] = stocktake;
          appendStocktakeFlow(data, code, '取消盘点', reason, stocktake.cancelledBy);
          appendBusinessAuditLog(req, data, '取消库存盘点', code, reason);
          await writeData(data);
          return sendJson(res, 200, { stocktake, flowRecords: warehouse.stocktakeFlowRecords[code] || [] });
        }

        if (req.method === 'POST' && parts[4] === 'complete') {
          if (index < 0) return sendError(res, 404, '库存盘点单不存在');
          const actor = businessActorName(req, data);
          assertActionStatus('库存盘点单', code, warehouse.stocktakes[index].status, ['待复核'], '完成盘点');
          assertStocktakeCounted(warehouse.stocktakes[index]);
          const stocktake = {
            ...warehouse.stocktakes[index],
            lines: (warehouse.stocktakes[index].lines || []).map((line) => ({ ...line })),
            status: '已完成',
            completedAt: shanghaiDateTime(),
            completedBy: actor,
          };
          completeStocktakeToStock(data, stocktake, actor);
          warehouse.stocktakes[index] = stocktake;
          appendStocktakeFlow(data, code, '完成盘点', '盘点差异已过账，盘点冻结已解除。', actor);
          appendBusinessAuditLog(req, data, '完成库存盘点', code, '盘点差异已过账，盘点冻结已解除。');
          appendBusinessNotification(data, {
            module: '仓库',
            action: '盘点过账',
            title: '库存盘点已完成',
            message: `${code} 已完成差异过账并解除盘点冻结。`,
            sourceDoc: code,
            sourcePath: `/warehouse/stocktakes/${encodeURIComponent(code)}`,
            actor,
          });
          await writeData(data);
          return sendJson(res, 200, { stocktake, flowRecords: warehouse.stocktakeFlowRecords[code] || [] });
        }
      }
    }

    if (parts[1] === 'purchase') {
      const purchase = ensurePurchase(data);
      const target =
        parts[2] === 'requisitions'
          ? { rows: purchase.requisitions, flowKey: 'requisitionFlowRecords', append: appendPurchaseRequisitionFlow, title: '请购' }
          : parts[2] === 'orders'
            ? { rows: purchase.orders, flowKey: 'orderFlowRecords', append: appendPurchaseFlow, title: '采购订单' }
            : undefined;

      if (target && req.method === 'POST' && parts[4] === 'status') {
        const code = decodeURIComponent(parts[3] || '');
        const index = target.rows.findIndex((record) => record.code === code);
        if (index < 0) return sendError(res, 404, `${target.title}不存在`);

        const body = await readBody(req);
        const status = String(body.status || '').trim();
        if (!status) return sendError(res, 400, '请提供目标状态');

        const action = String(body.action || '状态更新').trim();
        const remark = String(body.remark || body.reason || `${target.title}状态更新为${status}`).trim();
        const existing = target.rows[index];
        const actor = businessActorName(req, data);
        assertPurchaseStatusTransition(parts[2], existing.status, status);
        const record = { ...existing, status };
        target.rows[index] = record;
        if (parts[2] === 'orders' && ['已关闭', '已作废'].includes(status)) {
          cancelPendingPurchaseReceiptTasks(data, code, actor, `采购订单 ${code} 已${status === '已关闭' ? '关闭' : '作废'}`);
        }
        target.append(data, code, action, remark, actor);
        appendBusinessAuditLog(req, data, `更新${target.title}状态`, code, remark);
        await writeData(data);
        return sendJson(res, 200, { record, flowRecords: purchase[target.flowKey][code] || [] });
      }
    }

    if (parts[1] === 'purchase' && parts[2] === 'after-sales') {
      const purchase = ensurePurchase(data);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: [...purchase.afterSales]
            .sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`))
            .map((record) => withPurchaseAfterSaleFacts(data, record)),
        });
      }

      const code = decodeURIComponent(parts[3] || '');
      const index = purchase.afterSales.findIndex((record) => record.code === code);

      if (req.method === 'GET' && code) {
        if (index < 0) return sendError(res, 404, '采购售后不存在');
        return sendJson(res, 200, {
          record: withPurchaseAfterSaleFacts(data, purchase.afterSales[index]),
          flowRecords: purchase.afterSalesFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const record = normalizePurchaseAfterSale(body, undefined, data);
        purchase.afterSales.unshift(record);
        appendPurchaseAfterSaleFlow(data, record.code, '登记采购售后', `${record.issueType}已登记，等待受理。`, record.owner);
        appendBusinessAuditLog(req, data, '登记采购售后', record.code, `来源采购订单 ${record.sourceOrder}。`);
        await writeData(data);
        return sendJson(res, 201, { record: withPurchaseAfterSaleFacts(data, record), flowRecords: purchase.afterSalesFlowRecords[record.code] || [] });
      }

      if (req.method === 'PUT' && code) {
        if (index < 0) return sendError(res, 404, '采购售后不存在');
        if (purchase.afterSales[index].status === '已关闭') throw requestError(409, `采购售后 ${code} 已关闭，不能再变更。`);
        const body = await readBody(req);
        assertRecordRevision(body, purchase.afterSales[index], `采购售后 ${code}`);
        const record = normalizePurchaseAfterSale({ ...body, code }, purchase.afterSales[index], data);
        purchase.afterSales[index] = record;
        appendPurchaseAfterSaleFlow(data, code, '保存售后变更', '处理动作、责任协同和金额影响已更新。', record.owner);
        await writeData(data);
        return sendJson(res, 200, { record: withPurchaseAfterSaleFacts(data, record), flowRecords: purchase.afterSalesFlowRecords[code] || [] });
      }

      if (req.method === 'POST' && code && parts[4] === 'advance') {
        if (index < 0) return sendError(res, 404, '采购售后不存在');
        const body = await readBody(req);
        assertRecordRevision(body, purchase.afterSales[index], `采购售后 ${code}`);
        const transitions = {
          '待受理': { action: '受理售后', status: '处理中', nextStep: '执行处理动作' },
          '处理中': { action: '提交结果', status: '待确认', nextStep: '确认处理结果' },
          '待确认': { action: '关闭售后', status: '已关闭', nextStep: '归档完成' },
        };
        const current = hydratePurchaseAfterSaleRecord(purchase.afterSales[index], data);
        if (current.status === '待受理') {
          if (!String(current.action || '').trim()) throw requestError(409, `采购售后 ${code} 必须先填写对方补救方案，才能受理。`);
          if (current.amountImpactType === '待评估') throw requestError(409, `采购售后 ${code} 的金额影响仍为待评估，请明确后再受理。`);
          if (!['无金额影响', '待评估'].includes(current.amountImpactType) && parseMoney(current.estimatedAmount) <= 0) {
            throw requestError(409, `采购售后 ${code} 必须先填写预计金额，才能受理。`);
          }
        }
        const tasks = current.status === '待受理'
          ? ensureAfterSalesExecutionTasks(data, 'purchase', { ...current, status: '处理中' })
          : refreshAfterSalesExecution(data, 'purchase', current);
        if (current.status === '处理中' && tasks.some((task) => task.status !== '已完成')) {
          throw requestError(
            409,
            `采购售后 ${code} 还有未完成的协同任务：${tasks.filter((task) => task.status !== '已完成').map((task) => `${task.module}·${task.kind}`).join('、')}。`,
          );
        }
        const remedyReceipt = current.status === '处理中'
          ? purchaseAfterSaleRemedyReceipt(data, current)
          : null;
        if (remedyReceipt && !purchaseAfterSaleRemedyReceiptComplete(remedyReceipt)) {
          throw requestError(
            409,
            `采购售后 ${code} 的统一采购入库任务 ${remedyReceipt.code} 当前为“${remedyReceipt.status || '未记录'}”，完成到货、质检和正式入库后才能提交处理结果。`,
          );
        }
        if (current.status === '处理中' && !String(current.processingResult || '').trim()) {
          throw requestError(409, `采购售后 ${code} 必须先填写处理结果，才能提交确认。`);
        }
        if (current.status === '处理中' && !['无金额影响', '待评估'].includes(current.amountImpactType) && parseMoney(current.confirmedAmount) <= 0) {
          throw requestError(409, `采购售后 ${code} 必须填写确认金额，才能提交供应商确认。`);
        }
        if (current.status === '待确认' && !String(current.confirmationNote || '').trim()) {
          throw requestError(409, `采购售后 ${code} 必须先填写供应商确认依据，才能关闭。`);
        }
        const transition = transitions[current.status];
        if (!transition) throw requestError(409, `采购售后 ${code} 当前为“${current.status}”，没有可执行的状态动作。`);
        const record = hydratePurchaseAfterSaleRecord({
          ...current,
          status: transition.status,
          nextStep: transition.nextStep,
          revision: Number(current.revision || 1) + 1,
        }, data);
        let generatedInboundTask = null;
        if (transition.status === '处理中') {
          refreshAfterSalesExecution(data, 'purchase', record);
          generatedInboundTask = ensurePurchaseAfterSaleInboundTask(data, record, { actor: record.owner }).task;
        }
        purchase.afterSales[index] = record;
        appendPurchaseAfterSaleFlow(
          data,
          code,
          transition.action,
          `采购售后已更新为${transition.status}。${generatedInboundTask ? ` 已生成统一采购入库任务 ${generatedInboundTask.code}。` : ''}`,
          record.owner,
        );
        appendBusinessAuditLog(req, data, transition.action, code, `采购售后已更新为${transition.status}。`);
        await writeData(data);
        return sendJson(res, 200, { record: withPurchaseAfterSaleFacts(data, record), flowRecords: purchase.afterSalesFlowRecords[code] || [] });
      }

      if (req.method === 'POST' && code && parts[4] === 'void') {
        if (index < 0) return sendError(res, 404, '采购售后不存在');
        const body = await readBody(req);
        assertRecordRevision(body, purchase.afterSales[index], `采购售后 ${code}`);
        const current = hydratePurchaseAfterSaleRecord(purchase.afterSales[index], data);
        if (['已关闭', '已作废'].includes(current.status)) throw requestError(409, `采购售后 ${code} 当前为${current.status}，不能作废。`);
        const tasks = refreshAfterSalesExecution(data, 'purchase', current);
        if (tasks.some((task) => task.status === '已完成')) throw requestError(409, `采购售后 ${code} 已有完成的执行事实，不能直接作废。`);
        tasks.forEach((projection) => {
          const task = allAfterSalesExecutionTasks(data).find((item) => item.code === projection.code);
          if (task) task.status = '已取消';
        });
        const record = hydratePurchaseAfterSaleRecord({
          ...current,
          status: '已作废',
          nextStep: '已作废',
          revision: Number(current.revision || 1) + 1,
        }, data);
        purchase.afterSales[index] = record;
        appendPurchaseAfterSaleFlow(data, code, '作废售后', '未形成完成执行事实，采购售后已作废。', current.owner);
        await writeData(data);
        return sendJson(res, 200, { record: withPurchaseAfterSaleFacts(data, record), flowRecords: purchase.afterSalesFlowRecords[code] || [] });
      }
    }

    if (parts[1] === 'sales') {
      const sales = ensureSales(data);
      const target =
        parts[2] === 'quotes'
          ? { rows: sales.quotes, flowKey: 'quoteFlowRecords', append: appendQuoteFlow, title: '报价单' }
          : parts[2] === 'orders'
            ? { rows: sales.orders, flowKey: 'orderFlowRecords', append: appendFlow, title: '销售订单' }
            : parts[2] === 'outbound-requests'
              ? { rows: sales.outboundRequests, flowKey: 'outboundRequestFlowRecords', append: appendOutboundFlow, title: '交付追踪' }
              : undefined;

      if (target && req.method === 'POST' && parts[4] === 'status') {
        const code = decodeURIComponent(parts[3] || '');
        const index = target.rows.findIndex((record) => record.code === code);
        if (index < 0) return sendError(res, 404, `${target.title}不存在`);

        const body = await readBody(req);
        const status = String(body.status || '').trim();
        if (!status) return sendError(res, 400, '请提供目标状态');

        const action = String(body.action || '状态更新').trim();
        const remark = String(body.remark || body.reason || `${target.title}状态更新为${status}`).trim();
        const existing = target.rows[index];
        const actor = businessActorName(req, data);
        if (['quotes', 'orders'].includes(parts[2])) {
          assertRecordRevision(body, existing, `${target.title} ${code}`);
        }
        assertSalesStatusTransition(parts[2], existing.status, status);
        const record = {
          ...existing,
          status,
          revision: ['quotes', 'orders'].includes(parts[2])
            ? Number(existing.revision || 1) + 1
            : existing.revision,
        };
        target.rows[index] = record;
        target.append(data, code, action, remark, actor);
        appendBusinessAuditLog(req, data, `更新${target.title}状态`, code, remark);
        await writeData(data);
        return sendJson(res, 200, { record, flowRecords: sales[target.flowKey][code] || [] });
      }
    }

    if (parts[1] === 'purchase' && parts[2] === 'suggestions') {
      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, { items: purchaseSuggestionMaterials(data) });
      }
      if (req.method === 'POST' && parts[3] === 'create-order') {
        return sendError(res, 410, '采购建议仅提供只读参考；请从采购订单新建页选择供应商并承接开放采购需求。');
      }
    }

    if (parts[1] === 'purchase' && parts[2] === 'requisitions') {
      const purchase = ensurePurchase(data);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: [...purchase.requisitions]
            .sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`))
            .map((requisition) => withPurchaseRequisitionFacts(data, requisition)),
        });
      }

      const code = decodeURIComponent(parts[3] || '');
      const index = purchase.requisitions.findIndex((requisition) => requisition.code === code);

      if (req.method === 'GET' && code) {
        if (index < 0) return sendError(res, 404, '请购单不存在');
        return sendJson(res, 200, {
          requisition: withPurchaseRequisitionFacts(data, purchase.requisitions[index]),
          flowRecords: purchase.requisitionFlowRecords[code] || [],
        });
      }

      if (req.method === 'DELETE' && code) {
        if (index < 0) return sendError(res, 404, '请购单不存在');
        const requisition = purchase.requisitions[index];
        assertActionStatus('请购单', code, requisition.status, ['草稿'], '删除采购申请草稿');
        purchase.requisitions.splice(index, 1);
        delete purchase.requisitionFlowRecords[code];
        appendBusinessAuditLog(req, data, '删除采购申请草稿', code, '采购申请草稿已删除。');
        await writeData(data);
        return sendJson(res, 200, { deletedCode: code });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const requisition = normalizePurchaseRequisition(body, undefined, data);
        purchase.requisitions.unshift(requisition);
        appendPurchaseRequisitionFlow(data, requisition.code, '保存请购', '请购单已保存为草稿。', requisition.requester);
        await writeData(data);
        return sendJson(res, 201, {
          requisition: withPurchaseRequisitionFacts(data, requisition),
          flowRecords: purchase.requisitionFlowRecords[requisition.code] || [],
        });
      }

      if (req.method === 'PUT' && code) {
        if (index < 0) return sendError(res, 404, '请购单不存在');
        assertActionStatus('请购单', code, purchase.requisitions[index].status, ['草稿'], '修改采购申请');
        const body = await readBody(req);
        const requisition = normalizePurchaseRequisition({ ...body, code }, purchase.requisitions[index], data);
        purchase.requisitions[index] = requisition;
        appendPurchaseRequisitionFlow(data, requisition.code, '保存请购', '请购单内容已更新。', requisition.requester);
        await writeData(data);
        return sendJson(res, 200, {
          requisition: withPurchaseRequisitionFacts(data, requisition),
          flowRecords: purchase.requisitionFlowRecords[requisition.code] || [],
        });
      }

      if (req.method === 'POST' && parts[4] === 'submit') {
        if (index < 0) return sendError(res, 404, '请购单不存在');
        assertActionStatus('请购单', code, purchase.requisitions[index].status, ['草稿'], '提交采购受理');
        assertPurchaseRequisitionReady(data, purchase.requisitions[index]);
        const requisition = {
          ...purchase.requisitions[index],
          status: '待采购受理',
        };
        purchase.requisitions[index] = requisition;
        appendPurchaseRequisitionFlow(data, code, '提交采购受理', '请购已提交给采购，等待生成采购订单。', requisition.requester);
        appendBusinessAuditLog(req, data, '提交请购受理', code, '请购已提交给采购，等待生成采购订单。');
        await writeData(data);
        return sendJson(res, 200, {
          requisition: withPurchaseRequisitionFacts(data, requisition),
          flowRecords: purchase.requisitionFlowRecords[code] || [],
        });
      }
    }

    if (parts[1] === 'purchase' && parts[2] === 'orders') {
      const purchase = ensurePurchase(data);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: [...purchase.orders]
            .sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`))
            .map((order) => withPurchaseOrderFacts(data, order)),
        });
      }

      const code = decodeURIComponent(parts[3] || '');
      const index = purchase.orders.findIndex((order) => order.code === code);

      if (req.method === 'POST' && code && parts[4] === 'commercial-follow-ups') {
        if (index < 0) return sendError(res, 404, '采购订单不存在');
        const body = await readBody(req);
        const actor = businessActorName(req, data);
        const result = createCommercialFollowUp(data, 'purchase', purchase.orders[index], body, actor);
        if (!result.repeated) {
          const action = result.event.kind === 'purchase_invoice' ? '登记收票' : '登记付款';
          appendPurchaseFlow(
            data,
            code,
            action,
            commercialFollowUpEventSummary(result.event),
            actor,
          );
          appendBusinessAuditLog(req, data, action, code, commercialFollowUpEventSummary(result.event));
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          order: withPurchaseOrderFacts(data, purchase.orders[index]),
        });
      }

      if (req.method === 'DELETE' && code && parts[4] === 'commercial-follow-ups' && parts[5]) {
        if (index < 0) return sendError(res, 404, '采购订单不存在');
        const actor = businessActorName(req, data);
        const eventId = decodeURIComponent(parts[5]);
        const result = removeCommercialFollowUp(data, 'purchase', purchase.orders[index], eventId, actor);
        if (!result.repeated) {
          const subject = result.event.kind === 'purchase_invoice' ? '收票' : '付款';
          const action = `删除${subject}登记`;
          const remark = `${result.event.occurredOn} 的 ${money(result.event.amount)} ${subject}登记已删除，采购商务进度已重新计算。`;
          appendPurchaseFlow(data, code, action, remark, actor);
          appendBusinessAuditLog(req, data, action, code, remark);
          await writeData(data);
        }
        return sendJson(res, 200, {
          ...result,
          order: withPurchaseOrderFacts(data, purchase.orders[index]),
        });
      }

      if (req.method === 'GET' && code) {
        if (index < 0) return sendError(res, 404, '采购订单不存在');
        return sendJson(res, 200, {
          order: withPurchaseOrderFacts(data, purchase.orders[index]),
          flowRecords: purchase.orderFlowRecords[code] || [],
        });
      }

      if (req.method === 'DELETE' && code) {
        if (index < 0) return sendError(res, 404, '采购订单不存在');
        const order = purchase.orders[index];
        assertActionStatus('采购订单', code, order.status, ['草稿'], '删除采购订单草稿');
        purchase.orders.splice(index, 1);
        delete purchase.orderFlowRecords[code];
        const sourceRequisitions = order.sourceRequisitions?.length ? order.sourceRequisitions : [order.sourceRequisition].filter(Boolean);
        sourceRequisitions.forEach((requisitionCode) => releaseRequisitionConversion(data, requisitionCode, code, order.owner));
        appendBusinessAuditLog(req, data, '删除采购订单草稿', code, '采购订单草稿已删除。');
        await writeData(data);
        return sendJson(res, 200, { deletedCode: code });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const order = normalizePurchaseOrder(body, undefined, data);
        purchase.orders.unshift(order);
        appendPurchaseFlow(data, order.code, '创建采购订单', '采购订单已保存为草稿。');
        const sourceRequisitions = order.sourceRequisitions?.length ? order.sourceRequisitions : [order.sourceRequisition].filter(Boolean);
        sourceRequisitions.forEach((requisitionCode) => markRequisitionConverted(data, requisitionCode, order.code, order.owner));
        await writeData(data);
        return sendJson(res, 201, { order: withPurchaseOrderFacts(data, order), flowRecords: purchase.orderFlowRecords[order.code] || [] });
      }

      if (req.method === 'PUT' && code) {
        if (index < 0) return sendError(res, 404, '采购订单不存在');
        const body = await readBody(req);
        const existingOrder = purchase.orders[index];
        assertDocumentEditable('采购订单', code, existingOrder.status, purchaseOrderLockedStatuses);
        const isControlledChange = body?._operation === 'change';
        if (purchaseOrderControlledChangeStatuses.has(existingOrder.status) && !isControlledChange) {
          throw requestError(409, `采购订单 ${code} 已进入履约流程，请从变更入口提交修改。`);
        }
        if (
          purchaseOrderControlledChangeStatuses.has(existingOrder.status)
          && purchaseOrderHasExecutedDownstreamFacts(data, existingOrder)
        ) {
          throw requestError(409, `采购订单 ${code} 已形成收货、质检、售后或结算单据，采购内容已冻结。`);
        }
        if (purchaseOrderControlledChangeStatuses.has(existingOrder.status) && !accountPermissionCodes(req, data).has(purchaseApprovePermissionCode)) {
          const permissionLabel = permissionDisplayLabel(data, purchaseApprovePermissionCode);
          const message = `当前账号没有 ${permissionLabel} 操作权限，不能变更已确认或流程中的采购订单。`;
          await auditPermissionDenied(req, data, permissionLabel, message);
          return sendError(res, 403, message);
        }
        const order = normalizePurchaseOrder({ ...body, code }, purchase.orders[index], data);
        purchase.orders[index] = order;
        const synchronizedReceipt = order.status === '已确认'
          ? ensurePendingPurchaseReceiptTask(data, order, { notify: false, actor: order.owner })
          : { task: null, changed: false };
        const previousSources = new Set(existingOrder.sourceRequisitions?.length ? existingOrder.sourceRequisitions : [existingOrder.sourceRequisition].filter(Boolean));
        const nextSources = new Set(order.sourceRequisitions?.length ? order.sourceRequisitions : [order.sourceRequisition].filter(Boolean));
        nextSources.forEach((requisitionCode) => {
          if (!previousSources.has(requisitionCode)) markRequisitionConverted(data, requisitionCode, order.code, order.owner);
        });
        previousSources.forEach((requisitionCode) => {
          if (!nextSources.has(requisitionCode)) releaseRequisitionConversion(data, requisitionCode, order.code, order.owner);
        });
        appendPurchaseFlow(
          data,
          order.code,
          '保存采购订单',
          synchronizedReceipt.changed
            ? `采购订单内容已更新，待收货任务 ${synchronizedReceipt.task?.code || ''} 已同步。`
            : '采购订单内容已更新。',
        );
        await writeData(data);
        return sendJson(res, 200, {
          order: withPurchaseOrderFacts(data, order),
          receiptTask: synchronizedReceipt.task,
          flowRecords: purchase.orderFlowRecords[order.code] || [],
        });
      }

      if (req.method === 'POST' && parts[4] === 'confirm') {
        if (index < 0) return sendError(res, 404, '采购订单不存在');
        assertActionStatus('采购订单', code, purchase.orders[index].status, ['草稿'], '确认采购订单');
        assertPurchaseOrderReady(data, purchase.orders[index]);
        const order = {
          ...purchase.orders[index],
          status: '已确认',
        };
        purchase.orders[index] = order;
        const generatedReceipt = ensurePendingPurchaseReceiptTask(data, order, { actor: order.owner });
        const confirmRemark = generatedReceipt.task
          ? `采购订单已确认，已为仓库生成待收货任务 ${generatedReceipt.task.code}。`
          : '采购订单已确认，等待仓库登记到货。';
        appendPurchaseFlow(data, code, '确认采购订单', confirmRemark);
        appendBusinessAuditLog(req, data, '确认采购订单', code, confirmRemark);
        await writeData(data);
        return sendJson(res, 200, {
          order: withPurchaseOrderFacts(data, order),
          receiptTask: generatedReceipt.task,
          flowRecords: purchase.orderFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && parts[4] === 'close-remainder') {
        if (index < 0) return sendError(res, 404, '采购订单不存在');
        if (!accountPermissionCodes(req, data).has(purchaseApprovePermissionCode)) {
          const permissionLabel = permissionDisplayLabel(data, purchaseApprovePermissionCode);
          const message = `当前账号没有 ${permissionLabel} 操作权限，不能关闭待收余量。`;
          await auditPermissionDenied(req, data, permissionLabel, message);
          return sendError(res, 403, message);
        }
        const body = await readBody(req);
        const actor = accountAuditName(activeAccountForRequest(req, data));
        const result = closePurchaseOrderReceiptRemainder(data, purchase.orders[index], body, actor);
        appendBusinessAuditLog(
          req,
          data,
          '关闭采购待收余量',
          code,
          result.closures.map((line) => `${line.name} ${formatQty(line.closedQty, line.uom)}`).join('；'),
        );
        await writeData(data);
        return sendJson(res, 200, {
          order: withPurchaseOrderFacts(data, result.order),
          closures: result.closures,
          flowRecords: purchase.orderFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && parts[4] === 'close') {
        if (index < 0) return sendError(res, 404, '采购订单不存在');
        if (!accountPermissionCodes(req, data).has(purchaseApprovePermissionCode)) {
          const permissionLabel = permissionDisplayLabel(data, purchaseApprovePermissionCode);
          const message = `当前账号没有 ${permissionLabel} 操作权限，不能关闭采购订单。`;
          await auditPermissionDenied(req, data, permissionLabel, message);
          return sendError(res, 403, message);
        }
        const current = purchase.orders[index];
        if (current.status === '已关闭') {
          return sendJson(res, 200, {
            order: withPurchaseOrderFacts(data, current),
            flowRecords: purchase.orderFlowRecords[code] || [],
          });
        }
        if (current.status === '草稿' || current.status === '已作废') {
          throw requestError(409, `采购订单 ${code} 当前为${current.status}，不能关闭。`);
        }
        assertPurchaseOrderClosable(data, current);
        const order = { ...current, status: '已关闭' };
        purchase.orders[index] = order;
        cancelPendingPurchaseReceiptTasks(data, code, order.owner || '采购', `采购订单 ${code} 已关闭`);
        appendPurchaseFlow(data, code, '关闭采购订单', '到货、质量、入库、收票和付款已闭环，采购订单已关闭。', order.owner);
        appendBusinessAuditLog(req, data, '关闭采购订单', code, '采购履约与结算已完成。');
        await writeData(data);
        return sendJson(res, 200, {
          order: withPurchaseOrderFacts(data, order),
          flowRecords: purchase.orderFlowRecords[code] || [],
        });
      }

    }

    if (parts[1] === 'sales' && parts[2] === 'after-sales') {
      const sales = ensureSales(data);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: [...sales.afterSales].sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`)),
        });
      }

      const code = decodeURIComponent(parts[3] || '');
      const index = sales.afterSales.findIndex((record) => record.code === code);

      if (req.method === 'GET' && code) {
        if (index < 0) return sendError(res, 404, '销售售后不存在');
        return sendJson(res, 200, {
          record: withSalesAfterSaleFacts(data, sales.afterSales[index]),
          flowRecords: sales.afterSalesFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const record = normalizeSalesAfterSale(body, undefined, data);
        sales.afterSales.unshift(record);
        appendSalesAfterSaleFlow(data, record.code, '登记销售售后', `${record.issueType}已登记，等待受理。`, record.owner);
        appendBusinessAuditLog(req, data, '登记销售售后', record.code, `来源销售订单 ${record.sourceOrder}。`);
        await writeData(data);
        return sendJson(res, 201, {
          record: withSalesAfterSaleFacts(data, record),
          flowRecords: sales.afterSalesFlowRecords[record.code] || [],
        });
      }

      if (req.method === 'PUT' && code) {
        if (index < 0) return sendError(res, 404, '销售售后不存在');
        if (sales.afterSales[index].status === '已关闭') throw requestError(409, `销售售后 ${code} 已关闭，不能再变更。`);
        const body = await readBody(req);
        assertRecordRevision(body, sales.afterSales[index], `销售售后 ${code}`);
        const record = normalizeSalesAfterSale({ ...body, code }, sales.afterSales[index], data);
        sales.afterSales[index] = record;
        const completedTasks = (record.executionTasks || []).filter((task) => task.status === '已完成').length;
        const taskSummary = record.executionTasks?.length
          ? `执行任务 ${completedTasks}/${record.executionTasks.length} 项已完成。`
          : '问题登记信息已更新。';
        appendSalesAfterSaleFlow(data, code, '保存售后变更', taskSummary, record.owner);
        await writeData(data);
        return sendJson(res, 200, {
          record: withSalesAfterSaleFacts(data, record),
          flowRecords: sales.afterSalesFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'advance') {
        if (index < 0) return sendError(res, 404, '销售售后不存在');
        const body = await readBody(req);
        assertRecordRevision(body, sales.afterSales[index], `销售售后 ${code}`);
        const transitions = {
          '待受理': { action: '受理售后', status: '处理中' },
          '处理中': { action: '提交结果', status: '待确认' },
          '待确认': { action: '关闭售后', status: '已关闭' },
        };
        const current = hydrateSalesAfterSaleRecord(sales.afterSales[index], data);
        if (current.status === '待受理') {
          const missingPlan = [
            ['处理方案', current.action],
            ['金额影响类型', current.amountImpactType],
          ].find(([, value]) => !String(value || '').trim());
          if (missingPlan) {
            throw requestError(409, `销售售后 ${code} 必须先填写${missingPlan[0]}，才能受理。`);
          }
          if (current.amountImpactType === '待评估') {
            throw requestError(409, `销售售后 ${code} 的金额影响仍为待评估，请明确后再受理。`);
          }
          if (!['无金额影响', '待评估'].includes(current.amountImpactType) && parseMoney(current.estimatedAmount) <= 0) {
            throw requestError(409, `销售售后 ${code} 必须先填写预计金额，才能受理。`);
          }
        }
        if (current.status === '处理中') {
          const incompleteTasks = refreshAfterSalesExecution(data, 'sales', current).filter((task) => task.status !== '已完成');
          if (incompleteTasks.length) {
            throw requestError(
              409,
              `销售售后 ${code} 还有 ${incompleteTasks.length} 项执行任务未完成：${incompleteTasks.map((task) => task.kind).join('、')}。`,
            );
          }
          if (!String(current.processingResult || '').trim()) {
            throw requestError(409, `销售售后 ${code} 必须先填写处理结果，才能提交确认。`);
          }
          if (!['无金额影响', '待评估'].includes(current.amountImpactType) && parseMoney(current.confirmedAmount) <= 0) {
            throw requestError(409, `销售售后 ${code} 必须填写确认金额，才能提交客户确认。`);
          }
        }
        if (current.status === '待确认' && !String(current.confirmationNote || '').trim()) {
          throw requestError(409, `销售售后 ${code} 必须先填写客户确认依据，才能关闭。`);
        }
        const transition = transitions[current.status];
        if (!transition) throw requestError(409, `销售售后 ${code} 当前为“${current.status}”，没有可执行的状态动作。`);
        if (current.status === '待受理') {
          ensureAfterSalesExecutionTasks(data, 'sales', { ...current, status: '处理中' });
        }
        const executionTasks = current.status === '待受理'
          ? ensureAfterSalesExecutionTasks(data, 'sales', { ...current, status: '处理中' })
          : refreshAfterSalesExecution(data, 'sales', current);
        const firstPendingTask = executionTasks.find((task) => task.status !== '已完成');
        const nextStep = transition.status === '处理中'
          ? firstPendingTask
            ? `等待${firstPendingTask.module}完成${firstPendingTask.kind}`
            : '记录处理结果'
          : transition.status === '待确认'
            ? '等待客户确认处理结果'
            : '已归档';
        const record = hydrateSalesAfterSaleRecord({
          ...current,
          executionTasks,
          status: transition.status,
          nextStep,
          revision: Number(current.revision || 1) + 1,
        }, data);
        sales.afterSales[index] = record;
        const taskRemark = current.status === '待受理'
          ? `已生成 ${executionTasks.length} 项执行任务：${executionTasks.map((task) => `${task.module}·${task.kind}`).join('、')}。`
          : `销售售后已更新为${transition.status}。`;
        appendSalesAfterSaleFlow(data, code, transition.action, taskRemark, record.owner);
        appendBusinessAuditLog(req, data, transition.action, code, `销售售后已更新为${transition.status}。`);
        await writeData(data);
        return sendJson(res, 200, {
          record: withSalesAfterSaleFacts(data, record),
          flowRecords: sales.afterSalesFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'void') {
        if (index < 0) return sendError(res, 404, '销售售后不存在');
        const body = await readBody(req);
        assertRecordRevision(body, sales.afterSales[index], `销售售后 ${code}`);
        const current = hydrateSalesAfterSaleRecord(sales.afterSales[index], data);
        if (['已关闭', '已作废'].includes(current.status)) throw requestError(409, `销售售后 ${code} 当前为${current.status}，不能作废。`);
        const tasks = refreshAfterSalesExecution(data, 'sales', current);
        if (tasks.some((task) => task.status === '已完成')) throw requestError(409, `销售售后 ${code} 已有完成的执行事实，不能直接作废。`);
        tasks.forEach((projection) => {
          const task = allAfterSalesExecutionTasks(data).find((item) => item.code === projection.code);
          if (task) task.status = '已取消';
        });
        const record = hydrateSalesAfterSaleRecord({
          ...current,
          status: '已作废',
          nextStep: '已作废',
          revision: Number(current.revision || 1) + 1,
        }, data);
        sales.afterSales[index] = record;
        appendSalesAfterSaleFlow(data, code, '作废售后', '未形成完成执行事实，销售售后已作废。', current.owner);
        await writeData(data);
        return sendJson(res, 200, {
          record: withSalesAfterSaleFacts(data, record),
          flowRecords: sales.afterSalesFlowRecords[code] || [],
        });
      }
    }

    if (parts[1] === 'sales' && parts[2] === 'outbound-requests') {
      const sales = ensureSales(data);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: [...sales.outboundRequests].sort((a, b) =>
            `${b.requestDate}${b.code}`.localeCompare(`${a.requestDate}${a.code}`),
          ),
        });
      }

      const code = decodeURIComponent(parts[3] || '');
      const index = sales.outboundRequests.findIndex((requestDoc) => requestDoc.code === code);

      if (req.method === 'GET' && code) {
        if (index < 0) return sendError(res, 404, '交付追踪不存在');
        return sendJson(res, 200, {
          request: sales.outboundRequests[index],
          flowRecords: sales.outboundRequestFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const requestDoc = normalizeSalesOutboundRequest(body, undefined, data);
        sales.outboundRequests.unshift(requestDoc);
        appendOutboundFlow(data, requestDoc.code, '保存交付追踪', '交付追踪已保存。', requestDoc.applicant);
        await writeData(data);
        return sendJson(res, 201, {
          request: requestDoc,
          flowRecords: sales.outboundRequestFlowRecords[requestDoc.code] || [],
        });
      }

      if (req.method === 'PUT' && code) {
        if (index < 0) return sendError(res, 404, '交付追踪不存在');
        assertActionStatus(
          '交付追踪',
          code,
          sales.outboundRequests[index].status,
          ['草稿', '待发货', '已提交', '仓库已受理', '部分出库', '部分发货', '已退回'],
          '变更交付信息',
        );
        const body = await readBody(req);
        const requestDoc = normalizeSalesOutboundRequest({ ...body, code }, sales.outboundRequests[index], data);
        sales.outboundRequests[index] = requestDoc;
        appendOutboundFlow(data, requestDoc.code, '保存交付追踪', '交付追踪内容已更新。', requestDoc.applicant);
        await writeData(data);
        return sendJson(res, 200, {
          request: requestDoc,
          flowRecords: sales.outboundRequestFlowRecords[requestDoc.code] || [],
        });
      }

      if (req.method === 'POST' && parts[4] === 'submit') {
        if (index < 0) return sendError(res, 404, '交付追踪不存在');
        assertActionStatus('交付追踪', code, sales.outboundRequests[index].status, ['草稿'], '同步交付追踪');
        const requestDoc = {
          ...sales.outboundRequests[index],
          status: '待发货',
        };
        sales.outboundRequests[index] = requestDoc;
        appendOutboundFlow(data, code, '同步交付追踪', '交付追踪已同步，仓库任务进入待拣货。', requestDoc.applicant);
        appendBusinessAuditLog(req, data, '同步交付追踪', code, '交付追踪已同步，仓库任务进入待拣货。');

        const orderIndex = sales.orders.findIndex((order) => order.code === requestDoc.sourceOrder);
        if (orderIndex >= 0 && !['待签收', '已发货', '待开票', '待收款', '部分收款', '已完成', '已作废'].includes(sales.orders[orderIndex].status)) {
          sales.orders[orderIndex] = { ...sales.orders[orderIndex], status: '待发货' };
          appendFlow(data, requestDoc.sourceOrder, '同步交付追踪', `${requestDoc.code} 已同步给仓库，等待确认出库。`, requestDoc.applicant);
        }

        const generatedIssue = ensureSalesIssueTaskForTracking(data, requestDoc, requestDoc.applicant);
        await writeData(data);
        return sendJson(res, 200, {
          request: requestDoc,
          salesIssue: generatedIssue.task,
          flowRecords: sales.outboundRequestFlowRecords[code] || [],
        });
      }
    }

    if (parts[1] === 'sales' && parts[2] === 'quotes') {
      const sales = ensureSales(data);

      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: sales.quotes.map((quote) => withSalesQuoteFacts(data, quote))
            .sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`)),
        });
      }

      const code = decodeURIComponent(parts[3] || '');
      const index = sales.quotes.findIndex((quote) => quote.code === code);

      if (req.method === 'GET' && code) {
        if (index < 0) return sendError(res, 404, '报价单不存在');
        return sendJson(res, 200, {
          quote: withSalesQuoteFacts(data, sales.quotes[index]),
          flowRecords: sales.quoteFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const account = activeAccountForRequest(req, data);
        const actor = businessActorName(req, data);
        const quote = normalizeSalesQuote(body, undefined, data, {
          name: actor,
          code: account?.code || '',
          employeeCode: account?.employeeCode || '',
        });
        sales.quotes.unshift(quote);
        appendQuoteFlow(data, quote.code, '保存报价', '报价单已保存为草稿。', actor);
        await writeData(data);
        return sendJson(res, 201, { quote: withSalesQuoteFacts(data, quote), flowRecords: sales.quoteFlowRecords[quote.code] || [] });
      }

      if (req.method === 'PUT' && code) {
        if (index < 0) return sendError(res, 404, '报价单不存在');
        if (['已转订单', '已作废'].includes(sales.quotes[index].status)) {
          throw requestError(409, `报价单 ${code} 已锁定，不能修改。`);
        }
        const body = await readBody(req);
        assertRecordRevision(body, sales.quotes[index], `报价单 ${code}`);
        const wasConfirmed = sales.quotes[index].status === '已确认';
        const actor = businessActorName(req, data);
        const quote = normalizeSalesQuote({ ...body, code }, sales.quotes[index], data);
        if (wasConfirmed) quote.status = '草稿';
        sales.quotes[index] = quote;
        appendQuoteFlow(
          data,
          quote.code,
          wasConfirmed ? '变更报价' : '保存报价',
          wasConfirmed ? '已确认报价发生变更，退回草稿并等待重新确认。' : '报价单内容已更新。',
          actor,
        );
        await writeData(data);
        return sendJson(res, 200, { quote: withSalesQuoteFacts(data, quote), flowRecords: sales.quoteFlowRecords[quote.code] || [] });
      }

      if (req.method === 'POST' && parts[4] === 'confirm') {
        if (index < 0) return sendError(res, 404, '报价单不存在');
        const body = await readBody(req);
        assertRecordRevision(body, sales.quotes[index], `报价单 ${code}`);
        assertActionStatus('报价单', code, sales.quotes[index].status, ['草稿'], '确认报价');
        assertSalesQuoteConfirmable(data, sales.quotes[index]);
        if (salesQuoteIsExpired(sales.quotes[index])) {
          throw requestError(409, `报价单 ${code} 的有效期 ${sales.quotes[index].validUntil} 已过，请更新后再确认。`);
        }
        const quote = {
          ...sales.quotes[index],
          status: '已确认',
          revision: Number(sales.quotes[index].revision || 1) + 1,
        };
        sales.quotes[index] = quote;
        appendQuoteFlow(data, code, '确认报价', '报价单已确认，可转销售订单。', businessActorName(req, data));
        appendBusinessAuditLog(req, data, '确认报价', code, '报价单已确认，可转销售订单。');
        await writeData(data);
        return sendJson(res, 200, { quote: withSalesQuoteFacts(data, quote), flowRecords: sales.quoteFlowRecords[code] || [] });
      }

      if (req.method === 'POST' && parts[4] === 'void') {
        if (index < 0) return sendError(res, 404, '报价单不存在');
        const body = await readBody(req);
        assertRecordRevision(body, sales.quotes[index], `报价单 ${code}`);
        assertActionStatus('报价单', code, sales.quotes[index].status, ['草稿', '已确认'], '作废报价');
        const quote = {
          ...sales.quotes[index],
          status: '已作废',
          revision: Number(sales.quotes[index].revision || 1) + 1,
        };
        sales.quotes[index] = quote;
        appendQuoteFlow(data, code, '作废报价', '报价单已作废。', businessActorName(req, data));
        appendBusinessAuditLog(req, data, '作废报价', code, '报价单已作废。');
        await writeData(data);
        return sendJson(res, 200, { quote: withSalesQuoteFacts(data, quote), flowRecords: sales.quoteFlowRecords[code] || [] });
      }
    }

    if (parts[1] === 'sales' && parts[2] === 'inventory' && req.method === 'GET' && parts.length === 3) {
      return sendJson(res, 200, { items: salesInventoryProjection(data) });
    }

    if (parts[1] === 'sales' && parts[2] === 'delivery-records' && req.method === 'GET' && parts.length === 3) {
      const sourceOrder = String(url.searchParams.get('sourceOrder') || '').trim();
      const warehouse = ensureWarehouse(data);
      const testOnlyOrderCodes = new Set(
        data.sales.orders.filter((order) => order.testOnly === true).map((order) => order.code),
      );
      const items = warehouse.salesIssues
        .filter((record) => !testOnlyOrderCodes.has(record.sourceOrder))
        .filter((record) => !sourceOrder || record.sourceOrder === sourceOrder)
        .map((record) => {
          const actualWarehouses = Array.isArray(record.actualWarehouses) && record.actualWarehouses.length
            ? record.actualWarehouses
            : [...new Map(
                (record.products || [])
                  .flatMap((product) => product.allocations || [])
                  .filter((allocation) => parseQty(allocation.qty) > 0)
                  .map((allocation) => [
                    allocation.warehouseCode || allocation.warehouse,
                    { code: allocation.warehouseCode || '', name: allocation.warehouse || '' },
                  ]),
              ).values()];
          return {
            code: record.code,
            sourceOrder: record.sourceOrder,
            status: record.status,
            date: record.date,
            warehouse: actualWarehouses.map((item) => item.name).filter(Boolean).join('、') || record.warehouse || '',
            actualWarehouses,
            deliveryMethod: record.deliveryMethod,
            owner: record.owner || '',
            reversalCode: record.reversalCode || '',
            products: (record.products || []).map((product) => ({
              lineId: product.lineId,
              sourceLineId: product.sourceLineId,
              materialCode: product.materialCode,
              name: product.name,
              model: product.model,
              spec: product.spec,
              qty: product.qty,
              uom: product.uom,
            })),
          };
        });
      return sendJson(res, 200, { items });
    }

    if (parts[1] === 'sales' && parts[2] === 'orders') {
      if (req.method === 'GET' && parts.length === 3) {
        return sendJson(res, 200, {
          items: data.sales.orders
            .filter((order) => order.testOnly !== true)
            .sort((a, b) => `${b.date}${b.code}`.localeCompare(`${a.date}${a.code}`))
            .map((order) => withSalesAfterSalesEligibility(data, order)),
        });
      }

      const code = decodeURIComponent(parts[3] || '');
      const index = data.sales.orders.findIndex((order) => order.code === code);

      if (req.method === 'POST' && code && parts[4] === 'commercial-follow-ups') {
        if (index < 0) return sendError(res, 404, '销售订单不存在');
        const body = await readBody(req);
        const actor = businessActorName(req, data);
        const result = createCommercialFollowUp(data, 'sales', data.sales.orders[index], body, actor);
        if (!result.repeated) {
          const action = result.event.kind === 'sales_invoice' ? '登记开票' : '登记回款';
          appendFlow(
            data,
            code,
            action,
            commercialFollowUpEventSummary(result.event),
            actor,
          );
          appendBusinessAuditLog(req, data, action, code, commercialFollowUpEventSummary(result.event));
          recomputeSalesOrderProgress(data, code);
          await writeData(data);
        }
        return sendJson(res, result.repeated ? 200 : 201, {
          ...result,
          order: withSalesAfterSalesEligibility(data, data.sales.orders[index]),
        });
      }

      if (req.method === 'DELETE' && code && parts[4] === 'commercial-follow-ups' && parts[5]) {
        if (index < 0) return sendError(res, 404, '销售订单不存在');
        const actor = businessActorName(req, data);
        const eventId = decodeURIComponent(parts[5]);
        const result = removeCommercialFollowUp(data, 'sales', data.sales.orders[index], eventId, actor);
        if (!result.repeated) {
          const subject = result.event.kind === 'sales_invoice' ? '开票' : '回款';
          const action = `删除${subject}登记`;
          const remark = `${result.event.occurredOn} 的 ${money(result.event.amount)} ${subject}登记已删除，销售商务进度已重新计算。`;
          appendFlow(data, code, action, remark, actor);
          appendBusinessAuditLog(req, data, action, code, remark);
          recomputeSalesOrderProgress(data, code);
          await writeData(data);
        }
        return sendJson(res, 200, {
          ...result,
          order: withSalesAfterSalesEligibility(data, data.sales.orders[index]),
        });
      }

      if (req.method === 'GET' && code) {
        if (index < 0) return sendError(res, 404, '销售订单不存在');
        return sendJson(res, 200, {
          order: withSalesAfterSalesEligibility(data, data.sales.orders[index]),
          flowRecords: data.sales.orderFlowRecords[code] || [],
        });
      }

      if (req.method === 'DELETE' && code) {
        if (index < 0) return sendError(res, 404, '销售订单不存在');
        const order = data.sales.orders[index];
        assertActionStatus('销售订单', code, order.status, ['草稿'], '删除销售订单草稿');
        data.sales.orders.splice(index, 1);
        delete data.sales.orderFlowRecords[code];
        releaseQuoteConversion(data, order.sourceQuote, code, businessActorName(req, data));
        appendBusinessAuditLog(req, data, '删除销售订单草稿', code, '销售订单草稿已删除。');
        await writeData(data);
        return sendJson(res, 200, { deletedCode: code });
      }

      if (req.method === 'POST' && parts.length === 3) {
        const body = await readBody(req);
        const actor = businessActorName(req, data);
        assertSalesQuoteConvertible(data, body.sourceQuote);
        const order = normalizeOrder(body, undefined, data, actor);
        data.sales.orders.unshift(order);
        appendFlow(data, order.code, '保存草稿', '新建销售订单草稿。', actor);
        markQuoteConverted(data, order.sourceQuote, order.code, actor);
        await writeData(data);
        return sendJson(res, 201, { order, flowRecords: data.sales.orderFlowRecords[order.code] || [] });
      }

        if (req.method === 'PUT' && code) {
          if (index < 0) return sendError(res, 404, '销售订单不存在');
          const body = await readBody(req);
          const existingOrder = data.sales.orders[index];
          assertRecordRevision(body, existingOrder, `销售订单 ${code}`);
          const actor = businessActorName(req, data);
          const isControlledChange = body?._operation === 'change';
          if (!isControlledChange) assertDocumentEditable('销售订单', code, existingOrder.status, salesOrderLockedStatuses);
        if (
          isControlledChange
          && !['已确认', '待申请出库', '待发货'].includes(existingOrder.status)
        ) {
          throw requestError(
            409,
            `销售订单 ${code} 已进入生产、出库或后续履约，不能直接变更原单；请通过售后、冲销或补充单据处理。`,
          );
        }
        if (existingOrder.status !== '草稿' && !isControlledChange) {
          throw requestError(409, `销售订单 ${code} 已确认，请从变更入口提交修改。`);
        }
        if ([
          '已确认',
          '待申请出库',
          '待发货',
          '生产中',
          '发货中',
          '已申请出库',
          '部分发货',
          '已出库',
          '待签收',
          '已发货',
          '待开票',
          '待收款',
          '部分收款',
          '已完成',
        ].includes(existingOrder.status) && !accountPermissionCodes(req, data).has(salesApprovePermissionCode)) {
          const permissionLabel = permissionDisplayLabel(data, salesApprovePermissionCode);
          const message = `当前账号没有 ${permissionLabel} 操作权限，不能变更已确认或流程中的销售订单。`;
          await auditPermissionDenied(req, data, permissionLabel, message);
          return sendError(res, 403, message);
        }
        const nextSourceQuote = Object.prototype.hasOwnProperty.call(body, 'sourceQuote')
          ? String(body.sourceQuote || '')
          : existingOrder.sourceQuote || '';
        assertSalesQuoteConvertible(data, nextSourceQuote, code);
        const order = normalizeOrder({ ...body, code, sourceQuote: nextSourceQuote }, existingOrder, data, actor);
        data.sales.orders[index] = order;
        if (existingOrder.sourceQuote !== order.sourceQuote) {
          releaseQuoteConversion(data, existingOrder.sourceQuote, code, actor, '变更来源报价');
          markQuoteConverted(data, order.sourceQuote, code, actor);
        }
        appendFlow(data, order.code, '保存草稿', '更新销售订单内容。', actor);
        if (['待发货', '待申请出库', '发货中', '已申请出库', '部分发货', '待签收', '已发货'].includes(order.status)) {
          upsertShipmentTrackingFromOrder(data, order, actor);
        }
        await writeData(data);
        return sendJson(res, 200, { order, flowRecords: data.sales.orderFlowRecords[order.code] || [] });
      }

      if (req.method === 'POST' && code && parts[4] === 'confirm') {
        if (index < 0) return sendError(res, 404, '销售订单不存在');
        const body = await readBody(req);
        assertRecordRevision(body, data.sales.orders[index], `销售订单 ${code}`);
        assertActionStatus('销售订单', code, data.sales.orders[index].status, ['草稿'], '确认订单');
        assertSalesOrderConfirmable(data, data.sales.orders[index]);
        const actor = businessActorName(req, data);
        data.sales.orders[index] = {
          ...data.sales.orders[index],
          documentStatus: '已确认',
          revision: Number(data.sales.orders[index].revision || 1) + 1,
        };
        const supply = commitSalesOrderSupply(data, data.sales.orders[index], actor);
        data.sales.orders[index].status = supply.productionTask ? '生产中' : '待发货';
        const tracking = upsertShipmentTrackingFromOrder(data, data.sales.orders[index], actor);
        const remark = supply.productionTask
          ? `销售订单确认；已生成交付追踪 ${tracking.code}，其中 ${supply.reservedLineCount} 项形成库存预留、${supply.shortageLineCount} 项缺口由生产任务 ${supply.productionTask.code} 承接。`
          : `销售订单确认；已生成交付追踪 ${tracking.code}，${supply.reservedLineCount} 项形成库存预留。`;
        appendFlow(data, code, '确认订单', remark, actor);
        appendBusinessAuditLog(req, data, '确认销售订单', code, remark);
        if (supply.productionTask) {
          appendBusinessNotification(data, {
            module: '生产',
            action: '生产任务',
            title: '销售缺口待建工单',
            message: `${code} 的库存缺口已形成生产任务 ${supply.productionTask.code}，请按成品明细建立生产工单。`,
            sourceDoc: supply.productionTask.code,
            sourcePath: `/production/tasks/${encodeURIComponent(supply.productionTask.code)}`,
            actor,
          });
        }
        const projectedOrder = recomputeSalesOrderProgress(data, code) || data.sales.orders[index];
        await writeData(data);
        return sendJson(res, 200, {
          order: projectedOrder,
          outboundRequest: tracking,
          productionTask: supply.productionTask,
          flowRecords: data.sales.orderFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'confirm-receipt') {
        if (index < 0) return sendError(res, 404, '销售订单不存在');
        const body = await readBody(req);
        assertRecordRevision(body, data.sales.orders[index], `销售订单 ${code}`);
        const previousRevision = Number(data.sales.orders[index].revision || 1);
        const order = recomputeSalesOrderProgress(data, code);
        if (salesDocumentStatus(order) !== '已确认') {
          throw requestError(409, `销售订单 ${code} 当前单据状态为${salesDocumentStatus(order)}，不能确认客户签收。`);
        }
        if (order.progressFacts?.delivery?.status !== '待签收') {
          throw requestError(409, `销售订单 ${code} 当前交付进度为${order.progressFacts?.delivery?.status || '未确认'}，只有全部出库后才能确认客户签收。`);
        }

        const relatedTracking = data.sales.outboundRequests.filter((requestDoc) => (
          requestDoc.sourceOrder === code && !['已作废', '已取消'].includes(requestDoc.status)
        ));
        if (!relatedTracking.length) {
          throw requestError(409, `销售订单 ${code} 没有关联交付追踪，不能确认客户签收。`);
        }
        const incompleteTracking = relatedTracking.find((requestDoc) => !shipmentTrackingFulfillment(data, requestDoc).isComplete);
        if (incompleteTracking) {
          throw requestError(409, `交付追踪 ${incompleteTracking.code} 尚未全部出库，不能确认整单签收。`);
        }

        const actor = businessActorName(req, data);
        const signedAt = shanghaiDateTime();
        relatedTracking.forEach((requestDoc) => {
          requestDoc.status = '已签收';
          requestDoc.signedAt = signedAt;
          requestDoc.signedBy = actor;
          appendOutboundFlow(data, requestDoc.code, '确认客户签收', `${code} 已确认客户签收。`, actor);
        });
        const updatedOrder = recomputeSalesOrderProgress(data, code);
        updatedOrder.revision = previousRevision + 1;
        appendFlow(data, code, '确认客户签收', `关联交付追踪已确认签收，交付进度更新为${updatedOrder.progressFacts.delivery.status}。`, actor);
        appendBusinessAuditLog(req, data, '确认销售订单签收', code, '客户签收已记录到关联交付追踪。');
        await writeData(data);
        return sendJson(res, 200, {
          order: updatedOrder,
          flowRecords: data.sales.orderFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'close-remainder') {
        if (index < 0) return sendError(res, 404, '销售订单不存在');
        if (!accountPermissionCodes(req, data).has(salesApprovePermissionCode)) {
          const permissionLabel = permissionDisplayLabel(data, salesApprovePermissionCode);
          const message = `当前账号没有 ${permissionLabel} 操作权限，不能关闭待发余量。`;
          await auditPermissionDenied(req, data, permissionLabel, message);
          return sendError(res, 403, message);
        }
        const body = await readBody(req);
        assertRecordRevision(body, data.sales.orders[index], `销售订单 ${code}`);
        const actor = accountAuditName(activeAccountForRequest(req, data));
        const result = closeSalesOrderDeliveryRemainder(data, data.sales.orders[index], body, actor);
        appendBusinessAuditLog(
          req,
          data,
          '关闭销售待发余量',
          code,
          result.closures.map((line) => `${line.name} ${formatQty(line.closedQty, line.uom)}`).join('；'),
        );
        await writeData(data);
        return sendJson(res, 200, {
          order: withSalesAfterSalesEligibility(data, result.order),
          closures: result.closures,
          flowRecords: data.sales.orderFlowRecords[code] || [],
        });
      }

      if (req.method === 'POST' && code && parts[4] === 'void') {
        if (index < 0) return sendError(res, 404, '销售订单不存在');
        const body = await readBody(req);
        assertRecordRevision(body, data.sales.orders[index], `销售订单 ${code}`);
        assertActionStatus('销售订单', code, data.sales.orders[index].status, ['草稿', '已确认', '待申请出库', '待发货'], '作废销售订单');
        const actor = businessActorName(req, data);
        data.sales.orders[index] = {
          ...data.sales.orders[index],
          documentStatus: '已作废',
          status: '已作废',
          revision: Number(data.sales.orders[index].revision || 1) + 1,
        };
        appendFlow(data, code, '作废销售订单', '销售订单已作废。', actor);
        appendBusinessAuditLog(req, data, '作废销售订单', code, '销售订单已作废。');
        await writeData(data);
        return sendJson(res, 200, {
          order: data.sales.orders[index],
          flowRecords: data.sales.orderFlowRecords[code] || [],
        });
      }
    }

    sendError(res, 404, '接口不存在');
  } catch (error) {
    sendError(res, error.statusCode || 500, error.message || '服务异常');
  }
}

let mutationQueue = Promise.resolve();

function enqueueMutation(req, res) {
  const operation = mutationQueue.then(() => handleRequest(req, res));
  mutationQueue = operation.catch(() => undefined);
  return operation;
}

const server = http.createServer((req, res) => {
  if (req.method === 'GET' || req.method === 'OPTIONS') {
    void handleRequest(req, res);
    return;
  }
  void enqueueMutation(req, res);
});

server.listen(port, host, () => {
  console.log(`filatrix ERP API listening on http://${host}:${port}`);
});
